local P = LoreForeverPacks.Begin("LoreForever_Voice_Female_MorePeople")
P.transportVersion = 1
P.transport = {}
P.transport["npc:aelthalyste"] = {
  hash = "e3b49c",
  fullHash = "e3b49c",
  text = "Aelthalyste. In the Undercity's War Quarter, Aelthalyste trains Forsaken priests in the power of Shadow. She guides their spiritual discipline and sends troll acolytes to their own elders in Orgrimmar. Aelthalyste trains Forsaken priests in the power of Shadow. While many priests across Azeroth revere the Holy Light, her students have turned from it. She rose as an incorporeal banshee and shares the spectral agony and relentless resolve of Sylvanas Windrunner's followers. From her chamber in the Undercity's War Quarter, she calls aspiring priests from distant outposts to master their darker arts. She teaches them to harness suffering as a weapon. Aelthalyste respects the spiritual traditions of other Horde practitioners. She sends troll initiates away from her shadow teachings, directing them across the sea to Ur'kyo in Orgrimmar, where they can learn Darkspear spiritualism. Her deference lets Horde spellcasters develop within their own traditions and strengthens ties between Kalimdor and Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_aelthalyste-16d81a7cf43abe9951ce/1-0000.mp3", duration = 61.3616327, start = 0},
  },
}
P.transport["npc:ahanu"] = {
  hash = "55a912",
  fullHash = "55a912",
  text = "Ahanu. Ahanu is a tauren merchant operating within Hewa's Armory on the lower rise of Thunder Bluff. He crafts and trades leather armor to travelers and young braves setting out across Mulgore and the wider plains. He also helps newly arrived couriers navigate the bluffs when delivering messages from nearby settlements. Situated amidst the leatherworking stalls and armories of Thunder Bluff's lower rise, Ahanu provides vital equipment to those who make their living across Kalimdor's grasslands. Working hides sent by his friend Jahan Hawkwing at the Crossroads, he represents the everyday tradesfolk who keep the tauren capital supplied with durable cured and tanned hide gear. For travelers fresh off a wind rider from the Crossroads, Ahanu frequently serves as a first point of contact in the grand city, receiving deliveries and directing messengers toward the local flight roosts.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ahanu-f880875e23a0d5b8116a/1-0000.mp3", duration = 49.3453061, start = 0},
  },
}
P.transport["npc:alamar-grimm"] = {
  hash = "d652a6",
  fullHash = "d652a6",
  text = "Alamar Grimm. Alamar Grimm is a gnome warlock trainer stationed in Coldridge Valley at Anvilmar. Bitter over the tragic loss of Gnomeregan, he distrusts outsiders and focuses on teaching fledgling warlocks how to harness dark arts and summon their first demonic minions. While most gnomes in Coldridge Valley channel their energies into recovery and tinkering, Alamar Grimm harbors a deep resentment over the fall of Gnomeregan. He holds a cynical view of standard adventurers and even the host dwarves of Ironforge, grumbling that their allies care more about diplomacy with humans than reclaiming the fallen techno-city. Operating from Anvilmar, he seeks kindred spirits who understand that ruthless power may be what his people truly need. To young gnomes walking the path of fel magic, Grimm serves as an initial guide. When presented with a tainted memorandum, he offers a rare warm reception and begins tutoring recruits in fundamental spells. Before granting a novice the dangerous knowledge required to bind a demonic imp, however, he demands proof of their magical and physical endurance by sending them to retrieve the strange feather charms carried by local Frostmane troll novices.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_alamar-grimm-1f375cd14b8315b9ef87/1-0000.mp3", duration = 70.8440816, start = 0},
  },
}
P.transport["npc:altsoba-ragetotem"] = {
  hash = "7a3fd1",
  fullHash = "7a3fd1",
  text = "Altsoba Ragetotem. Altsoba Ragetotem is a tauren weaponsmith stationed at Bloodvenom Post in Felwood. From this remote Horde outpost, he keeps passing champions armed with reliable maces, staves, and axes to face the blighted horrors of the forest. Bloodvenom Post is a treacherous outpost, situated in the heart of Felwood amidst demonic corruption and tainted wildlife. Maintaining a supply line out here is a grim necessity, and Altsoba Ragetotem does his part by outfitting Horde scouts and travelers. Whether someone requires a sturdy crescent axe or a heavy war maul, Altsoba ensures warriors heading into the corrupted timberlands do not enter the fray unarmed.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_altsoba-ragetotem-6d88b35da65cb275701c/1-0000.mp3", duration = 40.6465306, start = 0},
  },
}
P.transport["npc:alyissia"] = {
  hash = "236ee6",
  fullHash = "236ee6",
  text = "Alyissia. In Aldrassil, Alyissia trains young night elves to fight with strength and discipline. She teaches warriors how to defend the young world tree. Alyissia trains young night elves inside Aldrassil, where they learn to fight with steel and shield instead of nature magic or the priesthood. Kaldorei forces are known for their Sentinels and stealthy archers, but danger across Kalimdor also calls for fighters who can hold the front line. Alyissia teaches the first techniques: how to direct battle fury, master a stance, and withstand the wild creatures and corrupted grells that press into Shadowglen.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_alyissia-07aa6eb7f71ea4e5c185/1-0000.mp3", duration = 36.1795918, start = 0},
  },
}
P.transport["npc:amber-kearnen"] = {
  hash = "972163",
  fullHash = "972163",
  text = "Amber Kearnen. In Westfall, Amber Kearnen watches the Defias Brotherhood for SI:7. From a hidden vantage point, she tracks their unlawful activity for Master Mathias Shaw. Amber Kearnen scouts for SI:7 in Westfall, far from the halls of Stormwind Keep. She watches an abandoned tower the Defias Brotherhood has taken over. Master Mathias Shaw leads her work directly. Kearnen briefs covert operatives sent to stop Defias threats and gather intelligence across the contested countryside.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_amber-kearnen-8d5d9e928895a0e38a53/1-0000.mp3", duration = 30.5893878, start = 0},
  },
}
P.transport["npc:andron-gant"] = {
  hash = "5b65cb",
  fullHash = "5b65cb",
  text = "Andron Gant. Andron Gant is a reclusive, frequently intoxicated Forsaken residing in the murky depths of the Apothecarium in the Undercity. He handles occasional research commissions for local mages. Lounging amidst the noxious fumes of the Apothecarium, Andron Gant rarely ventures beyond the safety of the Undercity's stone walls. To the casual observer, he appears to be little more than a drunken scholar, occasionally hiring adventurous couriers to retrieve obscure relics like the Tablet of Markri from distant shores on behalf of local mages.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_andron-gant-10e2d918df2044f195f4/1-0000.mp3", duration = 33.4889796, start = 0},
  },
}
P.transport["npc:anduin-wrynn"] = {
  hash = "bfab8f",
  fullHash = "bfab8f",
  text = "Anduin Wrynn. Anduin Llane Wrynn is the ten-year-old crowned King of Stormwind, reigning in the absence of his missing father, King Varian Wrynn. Due to his young age, the true administration of the kingdom rests in the hands of Highlord Bolvar Fordragon and the royal court. Born in the peaceful interlude following the Second War, Prince Anduin was named in honor of both his grandfather King Llane and the legendary knight Sir Anduin Lothar. Following the mysterious disappearance of his father en route to a diplomatic summit in Theramore, the child was abruptly crowned to maintain stability throughout the kingdom. Though intelligent and empathetic beyond his years, the ten-year-old monarch has little actual say in state affairs, leaving rule of the realm divided between Highlord Bolvar Fordragon and royal councilor Lady Katrana Prestor. Within the gilded walls of Stormwind Keep, young Anduin is surrounded by escalating political tension. While Highlord Bolvar manages military defenses and strives to maintain the integrity of the kingdom, the noblewoman Katrana Prestor constantly whispers counsel into the court's ear, actively undermining troop deployments to outlying human settlements. Anduin senses the precarious nature of his court and misses his father dearly, yet for now, he remains a figurehead surrounded by scheming nobles and watchful guardians.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_anduin-wrynn-d082ef2531e406a2bd51/1-0000.mp3", duration = 87.1444898, start = 0},
  },
}
P.transport["npc:apothecary-helbrim"] = {
  hash = "f43465",
  fullHash = "f43465",
  text = "Apothecary Helbrim. At the Crossroads, Apothecary Helbrim studies the Barrens for the Royal Apothecary Society. Sent to Kalimdor, he gathers unfamiliar reagents for the Forsaken. Apothecary Helbrim works beneath the harsh sun at the Crossroads, far from the Royal Apothecary Society's quarters in the damp undercity of Undercity. Sent across the Great Sea to Kalimdor, he searches the Barrens for useful plants, fungi, and other natural specimens. He depends on travelers to bring him samples, including local fungal spores, and works with Apothecary Zamah in Thunder Bluff. Through Helbrim, the Forsaken's alchemists reach beyond the ruined borders of Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_apothecary-helbrim-e534b4c634457513178d/1-0000.mp3", duration = 41.8481633, start = 0},
  },
}
P.transport["npc:apothecary-zinge"] = {
  hash = "0f0700",
  fullHash = "0f0700",
  text = "Apothecary Zinge. Beneath the ruins of Lordaeron, Apothecary Zinge works for the Forsaken. She studies biological specimens and arranges research shipments across Horde lands. Apothecary Zinge works in the Apothecarium beneath the Undercity. Under Master Apothecary Faranell, she searches for chemical and biological compounds that can advance the Forsaken's aims. Her work connects her with field researchers and scouts far beyond Tirisfal Glades, including at distant outposts in Kalimdor. Apothecary Zinge depends on couriers and adventurers to carry test materials across the sea. She regularly writes to Apothecary Helbrim at the Crossroads in the Barrens. She sends him toxic wolf heart samples from Silverpine Forest so he can study how Lordaeron's toxins affect Kalimdor's beasts.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_apothecary-zinge-85a93a20d0dc88d1b1f4/1-0000.mp3", duration = 50.7036735, start = 0},
  },
}
P.transport["npc:archaeologist-flagongut"] = {
  hash = "0c2059",
  fullHash = "0c2059",
  text = "Archaeologist Flagongut. At Menethil Harbor, Archaeologist Flagongut keeps in touch with field researchers across the Great Sea. The dwarven scholar of the Explorers' League is staying at the Deepwater Tavern while bound for the Whelgar Excavation Site. Archaeologist Flagongut rests with a mug at the Deepwater Tavern in Menethil Harbor. Like many members of Ironforge's Explorers' League, he traveled west across Khaz Modan to help with discoveries near the Whelgar Excavation Site in the Wetlands. Though far from the high halls of the library, he keeps ties with field researchers, processing lost relics and reports carried across the Great Sea from distant expeditions. Dwarven curiosity reaches beyond one continent. Chief Archaeologist Greywhisker in Darnassus sends Flagongut the mysterious fossil unearthed in Darkshore by the absent-minded Prospector Remtravel. Flagongut is amazed: he once brought a similar fossil to the Explorers' League's annual conference in Ironforge, convinced it held a power that could somehow be unlocked.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_archaeologist-flagongut-f6a8cd85b100e5b5cd68/1-0000.mp3", duration = 62.0408163, start = 0},
  },
}
P.transport["npc:archaeologist-hollee"] = {
  hash = "1941fb",
  fullHash = "1941fb",
  text = "Archaeologist Hollee. In Auberdine, Archaeologist Hollee tracks dwarven research across Darkshore. The ancient ruins draw Ironforge scholars to the coast, where she keeps in touch with prospectors searching for relics and unusual geological formations. Archaeologist Hollee works from Auberdine, among the night elves who guard and settle Darkshore. The dwarven scholar is a regional contact for surveyors and expedition teams crossing the wilderness. The Explorers' League sends its people across the sea to uncover traces of ancient history, and Darkshore's ruins give them ground to study.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_archaeologist-hollee-ff6c9540be2128c3ae8f/1-0000.mp3", duration = 35.7877551, start = 0},
  },
}
P.transport["npc:archbishop-benedictus"] = {
  hash = "d3d378",
  fullHash = "d3d378",
  text = "Archbishop Benedictus. In Stormwind City, Archbishop Benedictus leads the Church of the Holy Light from the Cathedral of Light. He guides the faithful and the Alliance through uncertain times. Archbishop Benedictus took the Church’s leadership after his mentor, Archbishop Alonsus Faol, died. He had seen the First and Second Wars devastate the kingdoms and helped oversee the building of the Cathedral of Light in Stormwind City. He vowed to uphold the virtues of the faith. After Lordaeron fell and the Scourge rose during the Third War, the human kingdoms looked to him for spiritual guidance. From the Cathedral, he counsels the royal court, trains newly initiated priests, and directs holy crusades against the undead and demonic forces threatening Azeroth. Across the Alliance, people regard Archbishop Benedictus as a gentle, wise, and benevolent patriarch. He offers the public hope and rallies heroes against dark threats, including Amnennar the Coldbringer in Kalimdor. He also helps purify cursed relics brought by faithful adventurers.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_archbishop-benedictus-cb7bffca013d957fdf95/1-0000.mp3", duration = 63.1902041, start = 0},
  },
}
P.transport["npc:archmage-ansirem-runeweaver"] = {
  hash = "c5c4d8",
  fullHash = "c5c4d8",
  text = "Archmage Ansirem Runeweaver. Archmage Ansirem Runeweaver is a senior human wizard and a ruling member of Dalaran's Council of Six. Having survived the Scourge's destruction of Dalaran in the Third War, he oversees Kirin Tor operations from the Violet Citadel as Dalaran is rebuilt. Though dedicated to the rebuilding of his city, he also maintains discreet interests abroad—including a willful daughter who ran off to Booty Bay to become a pirate. A veteran mage who helped defend Dalaran across decades, Ansirem Runeweaver sits on the Council of Six, the ruling magocracy of the Kirin Tor. He survived the devastation when Arthas Menethil and the Scourge marched upon the city and Archimonde was summoned. In the wake of Dalaran's fall, Ansirem has aided the efforts to rebuild the arcane city, whose protective shield was lifted early, and now works from the Violet Citadel. Despite his scholarly duties and stern wizardly demeanor, Ansirem possesses personal ties far beyond the Alterac Mountains. His willful daughter, Catelyn, ran off to Booty Bay to become a pirate, taking with her an ancient troll dagger he had found while researching in Stranglethorn. He has also dealt with Baron Revilgaz there. He has also engaged in arcane studies involving troll antiquities and maintains diplomatic conduits across distant realms.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_archmage-ansirem-runeweaver-158284e5a575bbd7aafb/1-0000.mp3", duration = 78.6808163, start = 0},
  },
}
P.transport["npc:archmage-malin"] = {
  hash = "e4e1b5",
  fullHash = "e4e1b5",
  text = "Archmage Malin. Outside the Wizard's Sanctum in Stormwind City, Archmage Malin directs arcane affairs. A former pupil of Archmage Trelane, he coordinates field agents seeking magical artifacts and rare reagents across the Eastern Kingdoms. Archmage Malin is the central contact for Stormwind's arcane practitioners, stationed beneath the Wizard's Sanctum in the Mage Quarter. He learned magic under Archmage Trelane, and now works to protect the scattered legacy of his former master. While acolytes study inside the tower, Malin watches over matters across the realm that need magical oversight. Archmage Malin directs much of his attention north, to the perilous ruins of the Arathi Highlands. He sent his trusted associates, Skuerto and Apprentice Kryten, to recover Archmage Trelane's lost possessions and secure delicate spell components. From the capital, Malin coordinates their work and relies on capable Alliance travelers to carry instructions, supplies, and intelligence to his agents in hostile territory.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_archmage-malin-6238f3c22e0196222aa7/1-0000.mp3", duration = 64, start = 0},
  },
}
P.transport["npc:archmage-xylem"] = {
  hash = "582f5e",
  fullHash = "582f5e",
  text = "Archmage Xylem. Archmage Xylem is an eccentric and reclusive human wizard dwelling in an isolated tower atop the cliffs of northern Azshara. Known for his volatile temperament and dangerous experiments, he has withdrawn from worldly affairs to pursue esoteric arcane research. Reaching him requires magical teleportation, and he only entertains adventurers who can assist in his peculiar studies or aid his personal vendettas. Perched high upon the jagged cliffs of northern Azshara, Archmage Xylem makes his home in a secluded spire overlooking the ruined elven coastline. Rather than building a road or trail, the wizard isolated his sanctuary entirely, relying on his servant Sanath Lim-yo to magically transport approved visitors up the cliff face. Observers across Kalimdor consider him profoundly eccentric and perilous to deal with; even fellow scholars treat him with deep caution, noting that he behaves unlike almost any other human mage.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_archmage-xylem-795c422093e2f600b72e/1-0000.mp3", duration = 59.7942857, start = 0},
  },
}
P.transport["npc:argent-guard-manados"] = {
  hash = "da8273",
  fullHash = "da8273",
  text = "Argent Guard Manados. Argent Guard Manados is a night elf sentry stationed in Darnassus on behalf of the Argent Dawn. Resting at the Craftsmen's Terrace, he keeps watch over Kalimdor's growing corruption and directs adventurers toward the sinister forces lurking in Blackfathom Deeps. While most of the Argent Dawn focuses its vigilance on the blighted lands of Lordaeron and the Scourge, Argent Guard Manados represents their watchful eyes in the night elf capital of Darnassus. Standing among the artisans and tradefolk of the Craftsmen's Terrace, Manados monitors emerging threats that menace the balance of northern Kalimdor. When rumors reach him of the Twilight's Hammer cult establishing a foul foothold beneath the waves of Ashenvale, Manados enlists capable heroes to strike at Blackfathom Deeps and recover artifacts of their dark devotion.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_argent-guard-manados-a31163df6cf05a4c4ec0/1-0000.mp3", duration = 48.0653061, start = 0},
  },
}
P.transport["npc:argos-nightwhisper"] = {
  hash = "11711a",
  fullHash = "11711a",
  text = "Argos Nightwhisper. In Stormwind's Park, Argos Nightwhisper guides Alliance travelers toward Darkshore. His brother Gershala studies the corruption spreading there. Argos Nightwhisper lives among the night elves gathering in Stormwind's Park. The district's quiet groves recall the kaldorei's ancestral woodlands. Like others of his kin stationed in the human kingdom, Argos connects the new allies across the Great Sea. Reports from across the ocean trouble him. He urges capable Alliance champions to travel to Auberdine in Darkshore, where his brother Gershala needs help against the spreading corruption.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_argos-nightwhisper-7a7daf4163b4613f156a/1-0000.mp3", duration = 36.9632653, start = 0},
  },
}
P.transport["npc:ashlan-stonesmirk"] = {
  hash = "d3deaa",
  fullHash = "d3deaa",
  text = "Ashlan Stonesmirk. Ashlan Stonesmirk is a dwarven explosives expert assigned to the regiment guarding Dun Modr and the Thandol Span in the northern Wetlands. From there, he keeps a vigilant eye on regional dangers threatening the realm of Ironforge. Positioned at Dun Modr in the northern Wetlands, Ashlan Stonesmirk serves the regiment guarding the Thandol Span. His expertise with explosives makes him a useful contact when suspicious materials threaten dwarven defenses.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ashlan-stonesmirk-f46657304784aebe485f/1-0000.mp3", duration = 25.0253061, start = 0},
  },
}
P.transport["npc:austil-de-mon"] = {
  hash = "78c80c",
  fullHash = "78c80c",
  text = "Austil de Mon. Austil de Mon is a Forsaken warrior trainer stationed in Brill within Tirisfal Glades. Based out of the Gallows' End Tavern, he instructs newly risen warriors looking to hone their martial prowess in service of the Dark Lady. Found inside the Gallows' End Tavern in Brill, Austil de Mon serves as one of the earliest instructors for Forsaken warriors venturing out of Deathknell. While the living once populated the inn to drink and rest, Austil now uses the gloomy refuge to teach newly liberated undead how to channel raw martial discipline and ruthless combat techniques against the kingdom's surrounding foes.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_austil-de-mon-2a331fd5932d38ca6953/1-0000.mp3", duration = 37.0677551, start = 0},
  },
}
P.transport["npc:ayanna-everstride"] = {
  hash = "b48e9b",
  fullHash = "b48e9b",
  text = "Ayanna Everstride. In Shadowglen, Ayanna Everstride trains young kaldorei in the hunter’s way. Stationed in Aldrassil, she teaches marksmanship, tracking, and survival beneath the World Tree. Ayanna Everstride trains newly awakened kaldorei hunters inside Aldrassil, in the heart of Shadowglen. To the night elves, hunters are indispensable guardians of the sacred forests, not merely trappers or sharpshooters. Ayanna teaches novices early martial skills, ranged combat, and how to survive Teldrassil’s perilous woods.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ayanna-everstride-7f3015636dd823f1bfb9/1-0000.mp3", duration = 33.6979592, start = 0},
  },
}
P.transport["npc:ayessa-dawnsinger"] = {
  hash = "f4014d",
  fullHash = "f4014d",
  text = "Ayessa Dawnsinger. Ayessa Dawnsinger is a Skyborne leader found in Valanaar on Zephras Isle. She leads the Windshapers, guiding the Skyborne aligned with the Horde through their trials and politics. Standing within the settlement of Valanaar on Zephras Isle, Ayessa Dawnsinger serves as the paramount guide for the Windshapers—the faction of Skyborne aligned with the Horde. From this vantage, she directs critical efforts across the island, managing external threats, internal fractures, and the overarching survival of her people as they navigate alliances in Kalimdor and beyond.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ayessa-dawnsinger-82f99df08a4eb31e5ba7/1-0000.mp3", duration = 35.0040816, start = 0},
  },
}
P.transport["npc:azar-stronghammer"] = {
  hash = "995b4d",
  fullHash = "995b4d",
  text = "Azar Stronghammer. Azar Stronghammer is a dwarven paladin stationed at the Thunderbrew Distillery in Kharanos. Having completed his own training in the holy arts, he guides newly awakened dwarven champions of the Holy Light and directs promising recruits toward higher instruction in Ironforge. While paladins are more commonly associated with the great cathedrals of humanity, the dwarves of Khaz Modan have fully embraced the virtues of the Holy Light. Stationed at the Thunderbrew Distillery in Kharanos, Azar Stronghammer watches over newly inducted dwarven paladins finding their footing amidst Dun Morogh's freezing slopes. Having mastered his own martial and spiritual vows, he serves as an approachable mentor. When a novice shows enough dedication and spiritual maturity, Azar directs them up the mountain path to Ironforge to study under veteran champions such as Tiza Battleforge.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_azar-stronghammer-1da8fdbc751aafb78c86/1-0000.mp3", duration = 49.397551, start = 0},
  },
}
P.transport["npc:azuregos"] = {
  hash = "9df747",
  fullHash = "9df747",
  text = "Azuregos. Azuregos is an eccentric blue dragon stationed along the coast of Azshara to protect ancient Highborne relics. Entrusted with safeguarding immense magical power by the Spell-Weaver Malygos, he prefers quiet study over violence, but he will readily swat aside any adventurer foolish enough to disturb his vigil. Drawn to the magic-soaked shores of Azshara, Azuregos chose the ancient ruins of Eldarath as his sanctuary. Countless relics survived the Great Sundering along these shattered coasts, and Azuregos considers it his sacred duty as a servant of Malygos to keep such powerful artifacts away from careless mortals. Rather than lurking in a dark cave, he freely roams the crags and beaches, proudly dubbing himself the lord of all magic in the region. Though blessed with a sardonic sense of humor, he fiercely defends Azshara's treasures against the endless stream of adventurers seeking fame or plunder.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_azuregos-7e45d8a8b87d3cfc6b32/1-0000.mp3", duration = 56.1632653, start = 0},
  },
}
P.transport["npc:bailiff-conacher"] = {
  hash = "f2f99d",
  fullHash = "f2f99d",
  text = "Bailiff Conacher. Bailiff Conacher serves in the Lakeshire Town Hall as the chief enforcement officer under Magistrate Solomon. Tasked with maintaining civil order and administering local decrees, he turns to independent champions to enforce the laws of Stormwind across the embattled Redridge Mountains. Within the Lakeshire Town Hall, Bailiff Conacher works closely with Magistrate Solomon to uphold lawful authority in the Redridge Mountains. With the town besieged on all fronts by Blackrock orcs and local gnolls, Conacher cannot rely on standard civic procedures or royal garrisons. Instead, he issues legal decrees that grant passing travelers the authority to administer capital justice on behalf of the realm. When the dark mage Morganth occupied the Tower of Ilgalar and subjugated the local Shadowhide gnolls to his will, the Court of Lakeshire deemed the beasts complicit in high treason. Since aiding a fugitive and criminal of the Kingdom of Stormwind carries a sentence of death, Conacher invokes Solomon's Law. He directs adventurers to scour the ridges for Shadowhide gnolls, demanding their pendants as legal proof that the crown's law has been carried out.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bailiff-conacher-48affd9721db2dd842cf/1-0000.mp3", duration = 68.5191837, start = 0},
  },
}
P.transport["npc:bailor-stonehand"] = {
  hash = "e13d21",
  fullHash = "e13d21",
  text = "Bailor Stonehand. Bailor Stonehand is a skilled dwarven smith residing in Thelsamar within Loch Modan. Renowned for his metallurgical expertise, he once mentored the human weaponsmith Jordan Stilwell and produces a specialized alloy crucial for masterwork armaments. Currently, his forge work faces setbacks after local Mo'grosh ogres ambushed and stole his ore shipments. Operating in the dwarven settlement of Thelsamar, Bailor Stonehand represents the enduring craft of Loch Modan's blacksmiths. Known for his keen eye for raw minerals and his ability to smelt specialized alloys, Bailor's knowledge extends beyond Khaz Modan. He served as a mentor to the renowned human smith Jordan Stilwell, teaching him the foundational arts of metallurgy and sharing formulas that would later prove essential in forging blessed paladin armaments such as Verigan's Fist. Despite his quiet mastery, Bailor's trade is not immune to the rising threats in Loch Modan. Shipments of high-grade ore destined for his forge have fallen prey to the Mo'grosh ogres entrenched in the hills to the northeast. Without raw materials, Bailor finds himself unable to craft his rare alloys, forcing him to rely on passing travelers and allies to reclaim his stolen supplies from the brute encampments.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bailor-stonehand-f8a0632821274f566bbd/1-0000.mp3", duration = 76.8783673, start = 0},
  },
}
P.transport["npc:balir-frosthammer"] = {
  hash = "be1db9",
  fullHash = "be1db9",
  text = "Balir Frosthammer. Balir Frosthammer is a dwarven defender stationed in Coldridge Valley within Dun Morogh. Alarmed by the sudden and aggressive incursions of Rockjaw troggs into dwarven lands, he recruits fledgling adventurers to stem the tide before the valley is overrun. Perched in the snowy enclave of Coldridge Valley, Balir Frosthammer watches the perimeter against encroaching dangers. The valley has long served as a safe haven and training ground for dwarven and gnomish novices, but recent disturbances underground have unleashed violent Rockjaw troggs onto the surface. Balir is among the first to sound the alarm, rallying newly arrived recruits to cull the troggs before they breach deeper into Dun Morogh. Bearing the proud Frosthammer surname, Balir may share a lineage with Tannok Frosthammer of Kharanos. Their family stands resolute in their duty to Ironforge, ensuring that the cold mountain passes remain secure for travelers, miners, and mountaineers even as regional threats multiply.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_balir-frosthammer-2421dc282c3655f7855c/1-0000.mp3", duration = 58.9322449, start = 0},
  },
}
P.transport["npc:barithras-moonshade"] = {
  hash = "a1551b",
  fullHash = "a1551b",
  text = "Barithras Moonshade. In Auberdine, Barithras Moonshade looks to the wilds of Darkshore for rare subterranean plants. The night elf seeks travelers willing to explore the shadowy land and gather them. Barithras Moonshade watches over Auberdine and helps the night elves study and manage Darkshore. He sends travelers into nearby caverns to gather fungi, including death cap mushrooms, for study and use. Barithras also guides capable travelers south to meet Onu. The ancient works to heal Darkshore's tainted soil and soothe its restless natural spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_barithras-moonshade-c4a9b342cbd19d6d380c/1-0000.mp3", duration = 34.6383673, start = 0},
  },
}
P.transport["npc:barkeep-daniels"] = {
  hash = "17b4d7",
  fullHash = "17b4d7",
  text = "Barkeep Daniels. Barkeep Daniels tends the counter at the Lakeshire Inn, serving weary town guards, local fishermen, and visiting travelers. With the Blackrock clan raiding across the Redridge Mountains and cutting off supply routes, keeping the tavern fully stocked has become an uphill battle. Behind the counter of the Lakeshire Inn stands Barkeep Daniels, pouring drinks and greeting whoever wanders in from the bridge. Lakeshire has spent months under constant pressure from gnolls and the Blackrock orcs, and the town's defenders rely on the tavern to unwind after grim patrols. Unfortunately for Daniels, the severed roads and relentless attacks have disrupted trade throughout the region. Finding himself dangerously low on liquor during a time when the town needs good cheer most, he is eager for any passing adventurer willing to fetch shipments from safer settlements.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_barkeep-daniels-17a64cad7b73e24ce9ff/1-0000.mp3", duration = 47.2032653, start = 0},
  },
}
P.transport["npc:baron-revilgaz"] = {
  hash = "ea8e86",
  fullHash = "ea8e86",
  text = "Baron Revilgaz. Baron Revilgaz is the cunning goblin leader of Booty Bay and the Blackwater Raiders, ruling the pirate haven on behalf of the Steamwheedle Cartel. Perched high on the balcony of the Salty Sailor Tavern, he balances fragile trade neutrality with ruthlessly pragmatic opportunism. He hires passing mercenaries to secure his investments, undermine rivals like the Bloodsail Buccaneers, and retrieve ancient relics of the jungle. From his vantage atop the Salty Sailor Tavern, Baron Revilgaz watches the bustling docks of Blackwater Cove through a custom enchanted spyglass. Flanked by his trusted advisor, the tauren Fleet Master Seahorn, Revilgaz exercises firm control over the town's cutpurses, merchants, and privateers. Originally a human settlement overwhelmed by trolls before the First War, the port was claimed and fortified by goblins, eventually evolving into the pirate-leaning commercial nexus of the Blackwater Raiders. Revilgaz ensures the port remains officially open to both Alliance and Horde travelers, strictly enforcing neutrality within harbor limits so that trade continues uninterrupted. Revilgaz's influence extends far past the harbor docks. When business stagnated following recent wars elsewhere in Azeroth, he seized upon the discovery of tastyfish to establish the Stranglethorn Fishing Extravaganza, drawing crowds back to his shores. Across Stranglethorn Vale, he keeps a sharp eye on competitors and potential threats: he commissions sabotage against the Venture Company at Lake Nazferiti, closely monitors Nesingwary's hunting expedition and rogue human military camps in the north, and maintains racing trade ties with Monte Gazlowe and Pozzik at the Mirage Raceway.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_baron-revilgaz-42445966856054508f18/1-0000.mp3", duration = 106.370612, start = 0},
  },
}
P.transport["npc:bartleby"] = {
  hash = "103c00",
  fullHash = "103c00",
  text = "Bartleby. Bartleby drinks and picks fights at the Pig and Whistle Tavern in Stormwind's Old Town. His stubborn hold on his ale makes him a test for aspiring warriors who must face him in a tavern brawl. Bartleby spends his days at the Pig and Whistle Tavern in Stormwind's Old Town. The tavern draws a rougher crowd than the taprooms of Cathedral Square. He clings to his favorite mug, drinks cheap ale, nurses grievances, and picks fights with anyone who disturbs him. Stormwind's warrior trainers see a practical test in Bartleby. Harry Burlguard sends fledgling fighters to find him and take his mug. They must trade bare-knuckle blows with the intoxicated brawler, proving they have the grit to face an unruly opponent at close quarters.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bartleby-9b3b2eb41ea4c2515072/1-0000.mp3", duration = 43.2065306, start = 0},
  },
}
P.transport["npc:bashana-runetotem"] = {
  hash = "8c3bde",
  fullHash = "8c3bde",
  text = "Bashana Runetotem. Bashana Runetotem is an herbalist and druidic researcher residing on the Elder Rise in Thunder Bluff. The daughter of Archdruid Hamuul Runetotem, she aids the Cenarion Circle by overseeing agricultural investigations and guiding Horde adventurers against corrupting forces. Standing atop the breezy heights of the Elder Rise, Bashana Runetotem carries on the druidic legacy of her father, Archdruid Hamuul Runetotem. While her father guides the burgeoning tauren druids and advises Cairne Bloodhoof, Bashana focuses on practical research into botanical anomalies and regional threats. She equips travelers with tools like evergreen pouches to cultivate mysterious flora, notably the enigmatic morrowgrain, while also coordinating Horde efforts to cleanse foul corruption spreading from places like Blackfathom Deeps.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bashana-runetotem-332bb6af3adeb396f115/1-0000.mp3", duration = 49.5542857, start = 0},
  },
}
P.transport["npc:bath-rah-the-windwatcher"] = {
  hash = "fb540b",
  fullHash = "fb540b",
  text = "Bath'rah the Windwatcher. Bath'rah the Windwatcher is a solitary jungle troll shaman and weaponcrafter dwelling amidst the ruins near Chillwind Point. Far from his tropical homelands, he studies the tempestuous elements of the northern mountains, seeking champions powerful enough to help him craft formidable weapons of wind. While most jungle trolls keep to the warm forests and coasts of the south, Bath'rah has embraced the solitary life of a mountain hermit among the cold ruins of the Alterac Mountains. A seasoned shaman and craftsman, he devotes his days to listening to the howling winds and communing with nature spirits. His obsession is not merely philosophical; he seeks to bind the fury of violent elemental storms into tangible armaments for those who possess the strength to wield them.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bath-rah-the-windwatcher-74fba155952cdff29753/1-0000.mp3", duration = 49.5281633, start = 0},
  },
}
P.transport["npc:beldin-steelgrill"] = {
  hash = "9c12a7",
  fullHash = "9c12a7",
  text = "Beldin Steelgrill. Beldin Steelgrill is a renowned dwarven engineer and the master technician operating Steelgrill's Depot in Dun Morogh. Widely regarded as one of the finest siege engine mechanics in Khaz Modan, he oversees the maintenance of the Ironforge military's heavy armor and treaded warmachines. Keeping those massive contraptions running requires an endless supply of high-grade specialized tools. Situated just down the road from Kharanos, Steelgrill's Depot serves as the primary proving ground and service station for dwarven steam tanks and siege engines. Beldin Steelgrill stands as its chief technician, celebrated far and wide for his unmatched expertise in repairing and tuning armored war wagons. Taming heavy metal and rumbling boilers is unforgiving work, and Beldin burns through gear rapidly. His constant demand for heavy wrenches, cutters, and precision instruments frequently pushes local ironworkers to their limits just to keep his workbench supplied.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_beldin-steelgrill-eefec52f186acd5e828c/1-0000.mp3", duration = 60.8653061, start = 0},
  },
}
P.transport["npc:bingles-blastenheimer"] = {
  hash = "32383d",
  fullHash = "32383d",
  text = "Bingles Blastenheimer. Bingles Blastenheimer is an eccentric gnomish aviator stranded on the southeastern shores of the Loch in Loch Modan. Having crash-landed his experimental flying machine, he finds himself marooned amidst local troggs and beasts, desperate to salvage his precious tools and components. Like many ambitious gnomish engineers, Bingles Blastenheimer took to the skies in a customized flying craft, only to discover that coming down safely is far more difficult than lifting off. After his gyrocopter malfunctioned and crashed into the southeastern shores of the Loch, Bingles survived the impact intact, but his machine shattered into scattered parts. Stranded far from Ironforge, he remains huddled near the wreckage, guarded against hungry crocolisks and hostile troggs while pleading with passing travelers to recover the tools and Blastencapper explosives that troggs from a nearby island stole from him.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bingles-blastenheimer-6b4b9812bf05eb16816a/1-0000.mp3", duration = 53.6816327, start = 0},
  },
}
P.transport["npc:bink"] = {
  hash = "521d22",
  fullHash = "521d22",
  text = "Bink. Bink is a gnome mage trainer who resides within the Hall of Mysteries in Ironforge's Mystic Ward. Quick-witted and enthusiastic, she guides aspiring spellcasters through the intricacies of the arcane arts and connects them with prominent wizards across the Alliance. Located in the Mystic Ward of Ironforge, Bink stands among the gathered scholars, priests, and arcanists in the Hall of Mysteries. Like many gnomes driven from Gnomeregan, she has adapted to life within the dwarven mountain stronghold, offering her keen intellect and knowledge of arcane craft to those learning the path of the mage. She is well connected to wizards across the Eastern Kingdoms and Kalimdor, regularly pointing promising apprentices toward greater mentors such as High Sorcerer Andromath in Stormwind or Tabetha in Dustwallow Marsh.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bink-ed01029c000f744940d8/1-0000.mp3", duration = 49.6065306, start = 0},
  },
}
P.transport["npc:bishop-delavey"] = {
  hash = "fd3194",
  fullHash = "fd3194",
  text = "Bishop DeLavey. In Stormwind Keep, Bishop DeLavey hears the court's quiet concerns. He represents the Church of the Holy Light in the Petitioner's Chamber, where matters of faith and state meet. Bishop DeLavey advises Stormwind's court from within the keep. While Archbishop Benedictus tends to the Cathedral of Light, DeLavey lives among the nobility and petitioners. He brings spiritual counsel to the court while reckoning with the kingdom's politics. His place there lets him hear whispered rumors and delicate grievances before they reach Highlord Bolvar Fordragon or the young King Anduin.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bishop-delavey-edeff443201a93fe266b/1-0000.mp3", duration = 36.1012245, start = 0},
  },
}
P.transport["npc:blanchy"] = {
  hash = "bbb48e",
  fullHash = "bbb48e",
  text = "Blanchy. Old Blanchy is the loyal, hard-working mare belonging to Theodore and Verna Furlbrow, currently resting beside their wagon near the Jansen Stead in Westfall. Renowned for her gentle disposition and hefty appetite, she remains a steady companion to her owners amidst the turmoil gripping the countryside. Long before pulling the Furlbrows' wagon through the dust of Westfall, Blanchy worked the Furlbrows' farm in the breadbasket of Stormwind, where she earned a reputation as an exceptionally sweet-tempered, well-behaved mare. Years of heavy labor have worn her down to 'Old Blanchy,' and the arduous journey fleeing troubled homesteads has left her exhausted. Though visibly weary, her appetite remains hearty, and travelers who bring her nourishing handfuls of oats scattered across the surrounding fields are rewarded by Verna with Blanchy's own treasured blanket and feed pouch.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_blanchy-baf89a8cf76d66c9599d/1-0000.mp3", duration = 53.6555102, start = 0},
  },
}
P.transport["npc:bloodmage-drazial"] = {
  hash = "1ceed6",
  fullHash = "1ceed6",
  text = "Bloodmage Drazial. Bloodmage Drazial is a blood elf practitioner of arcane and blood magic camped in the northern reaches of the Blasted Lands. Alongside his sister Lynnore, he studies the native beasts of the red wastes to craft potent alchemical concoctions for traveling adventurers. Perched near the northern pass where the Swamp of Sorrows gives way to the Blasted Lands, Bloodmage Drazial pursues a peculiar brand of magic. While many high elves shun the forbidden arts or despair over Quel'Thalas, Drazial and his sister Lynnore harness blood magic to harvest power from the harsh environment. The blighted fauna of the wastes—scorpoks, snickerfangs, and blasted boars—show strange, unnatural vigor, which Drazial and Lynnore believe came from the energy released when the Dark Portal opened. By harvesting specific organs and tissues from these creatures, Drazial brews volatile concoctions that grant immense bursts of physical strength, agility, and endurance. Unlike many factional agents stationed in the Blasted Lands, Drazial operates with practical detachment. He holds no official allegiance to either the Alliance or the Horde, choosing instead to trade his alchemical expertise to anyone hardy enough to brave the wasteland and gather the raw ingredients he requires. As long as travelers bring him the organs of the local predators, Drazial is content to keep his cauldrons bubbling.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bloodmage-drazial-60b8953d8fc7e626b643/1-0000.mp3", duration = 86.0473469, start = 0},
  },
}
P.transport["npc:bloodmage-lynnore"] = {
  hash = "56291e",
  fullHash = "56291e",
  text = "Bloodmage Lynnore. Bloodmage Lynnore is a blood elf practitioner of forbidden blood magic camped with her brother Drazial near the northern entrance to the Blasted Lands. She assists adventurers by concocting potent alchemical draughts from the organs of local beasts. Camped near the northern entrance to the Blasted Lands alongside her brother Drazial, Bloodmage Lynnore is one of the exceptionally rare elven practitioners of blood magic found in the Eastern Kingdoms. Unperturbed by the harsh and corrupting landscape of the Blasted Lands, she studies the latent arcane and vital energies coursing through native beasts. Travelers who bring her the brains and gizzards of local fauna find that she can distill these gruesome reagents into specialized elixirs granting profound enhancements to intellect and spirit.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bloodmage-lynnore-1d8f8c4b3f1b57120c19/1-0000.mp3", duration = 46.8114286, start = 0},
  },
}
P.transport["npc:bluff-runner-windstrider"] = {
  hash = "4b4aee",
  fullHash = "4b4aee",
  text = "Bluff Runner Windstrider. Bluff Runner Windstrider is a wandering tauren messenger roaming the mesas of Thunder Bluff. He carries urgent dispatches across the city, directing Horde adventurers toward distant frontiers like Ashenvale, Feralas, and the Plaguelands. Thunder Bluff's soaring plateaus require swift feet to keep its leaders and visitors informed, and Bluff Runner Windstrider fills that vital role. Continually jogging the rope bridges and pathways of the tauren capital, he acts as a town crier and dispatch runner. When key outposts across Kalimdor or the Eastern Kingdoms require reinforcements, Windstrider flags down passing champions to carry word and take up the call to arms. Windstrider's dispatches range far beyond Mulgore's serene borders. He directs adventurers northward into Ashenvale to join Senani Thunderheart's great hunt at Splintertree Post, points hardened scouts south toward Camp Mojache in deep Feralas, and relays grave warnings regarding the ongoing undead menace in the Western Plaguelands. Through him, the tribal heart of Mulgore stays bound to the wider conflicts of the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bluff-runner-windstrider-70dd9f55f6956a0789ca/1-0000.mp3", duration = 66.4032653, start = 0},
  },
}
P.transport["npc:braelyn-firehand"] = {
  hash = "96f165",
  fullHash = "96f165",
  text = "Braelyn Firehand. Braelyn Firehand is an elusive elf residing quietly among the Horde at Sun Rock Retreat in the Stonetalon Mountains. While presenting herself as an arcane practitioner seeking to clear mystical obstructions in the highlands, she pursues a deep personal grudge against the grove keepers of Stonetalon Peak. Standing out amidst the tauren lodges and rustic orcish tents of Sun Rock Retreat, Braelyn Firehand is a rare sight: a blood elf dwelling openly within a remote Horde settlement. The shaman and chieftains of the retreat tolerate her presence, seemingly oblivious to her true loyalties. Braelyn presents herself as an observer fascinated by the flow of regional magic, eager to hire passing Horde mercenaries to handle dangerous field assignments across the crags.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_braelyn-firehand-d6847196c768033d0261/1-0000.mp3", duration = 44.3036735, start = 0},
  },
}
P.transport["npc:braenna-flintcrag"] = {
  hash = "4a9c7e",
  fullHash = "4a9c7e",
  text = "Braenna Flintcrag. Braenna Flintcrag is a dwarven priest trainer stationed within the Hall of Mysteries in Ironforge's Mystic Ward. She instructs devout followers of the Holy Light, guiding dwarven acolytes as they develop their spiritual disciplines and healing arts. She also passes word to visiting night elf priests when they are called home to the Temple of the Moon in Darnassus. Residing within the quiet alcoves of the Hall of Mysteries in Ironforge's Mystic Ward, Braenna Flintcrag serves the Alliance as a dedicated priest trainer. While Ironforge is renowned for its roaring forges and martial warriors, devout dwarves like Braenna tend to the spiritual welfare of Khaz Modan. She mentors novices answering the call of the Holy Light, teaching the dual disciplines of restorative mending and defensive warding required to survive in an increasingly dangerous world.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_braenna-flintcrag-54f520423d59a5e92b77/1-0000.mp3", duration = 49.2930612, start = 0},
  },
}
P.transport["npc:brainwashed-noble"] = {
  hash = "fccfc7",
  fullHash = "fccfc7",
  text = "Brainwashed Noble. Deep in the caverns outside the Deadmines, Brainwashed Noble remains captive under Defias control. Magical manipulation has stripped him of his will, and he serves the Brotherhood alongside undead minions instead of walking Stormwind's grand halls.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brainwashed-noble-3e7e6fb7e06573c5fe41/1-0000.mp3", duration = 14.6808163, start = 0},
  },
}
P.transport["npc:brandur-ironhammer"] = {
  hash = "930abb",
  fullHash = "930abb",
  text = "Brandur Ironhammer. Brandur Ironhammer is a dwarven paladin trainer residing in the Hall of Mysteries within Ironforge. He guides aspiring champions of the Holy Light through their early rites, testing their devotion and dispatching them across the Alliance. Stationed within the quiet alcoves of the Hall of Mysteries, Brandur Ironhammer serves the Alliance by instructing novice paladins in the ways of the Holy Light. Alongside his peer, Tiza Battleforge, Brandur keeps a watchful eye on young dwarven champions, guiding them through the trials of the Tome of Divinity. While deeply committed to his holy duties, he has acknowledged personal flaws under Tiza's frank counsel, working diligently to temper his envy and maintain the inner purity demanded of a warrior of the Light. Brandur serves as an essential liaison between Ironforge and the wider Alliance brotherhood. When human initiates find their way into the dwarven mountain, he redirects them back south to Duthorian Rall in the Cathedral of Light. As paladins grow seasoned in the field, Brandur coordinates their deployment to battlegrounds such as Chillwind Camp in the Western Plaguelands, eventually sending veteran crusaders to Lord Grayson Shadowbreaker to undertake the demanding trials of the war charger.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brandur-ironhammer-b6863e205c4d3542e6d0/1-0000.mp3", duration = 75.9902041, start = 0},
  },
}
P.transport["npc:brann-bronzebeard"] = {
  hash = "2316da",
  fullHash = "2316da",
  text = "Brann Bronzebeard. Brann Bronzebeard is the youngest brother of King Magni and Muradin, who is believed dead, renowned throughout Azeroth as a peerless explorer, archaeologist, and founding leader of the Explorers' League. Driven by an insatiable curiosity for titan ruins and ancient history, his wanderlust has led him deep into the deadly wastes of Silithus. His field companions in southern Silithus await news of his latest expedition. While his eldest brother Magni rules Ironforge from the throne and Muradin served on battlefield frontlines, Brann took to the open wilds. He was a veteran warrior of the Second War. Yet peacetime turned his formidable constitution toward uncovering the forgotten past. As a leader of the Explorers' League, Brann charted vast swathes of the Eastern Kingdoms—from Elwynn Forest to the untamed jungles of Zul'Gurub—before turning his gaze across the Great Sea to the mysteries of ancient Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brann-bronzebeard-0208f71589b484a49b03/1-0000.mp3", duration = 59.0367347, start = 0},
  },
}
P.transport["npc:branstock-khalder"] = {
  hash = "de12e9",
  fullHash = "de12e9",
  text = "Branstock Khalder. Branstock Khalder is the priest trainer stationed at Anvilmar in Coldridge Valley. Friendly and grounded, he introduces novice dwarven priests to the Holy Light while keeping a watchful eye on the growing trogg threat outside. Inside the bustling hall of Anvilmar, Branstock Khalder serves as a patient mentor to aspiring priests embarking on their spiritual journey. An easy-going dwarf with a deep devotion to the Light, he helps new acolytes master their early prayers and sacred runes. While his primary duty is spiritual instruction, Branstock is acutely aware of the valley's mounting perils—most notably the aggressive trogg infestation menacing the local mountaineers. Once a novice demonstrates sufficient command of the Light, he directs them through Coldridge Pass to seek further guidance from his superior, Maxan Anvol, in Kharanos.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_branstock-khalder-45599644abd9d68d14ad/1-0000.mp3", duration = 49.1885714, start = 0},
  },
}
P.transport["npc:brave-moonhorn"] = {
  hash = "b29435",
  fullHash = "b29435",
  text = "Brave Moonhorn. Brave Moonhorn is a tauren scout stationed at the top of the Great Lift on the southern border of the Barrens. From this precipice, he keeps watch over the entry to Thousand Needles and alerts travelers to the local dangers ahead. Perched above the sheer drops of Thousand Needles, Brave Moonhorn stands guard where the northern plains meet the canyonlands. His primary role is keeping watchful eyes on regional threats moving through the canyon floor below, particularly the hostile centaur clans. Anyone looking to descend into the needles often crosses paths with him first, receiving crucial warnings before they step onto the massive platforms of the Great Lift. Beyond the constant threat of roving centaur, Moonhorn harbors deep misgivings about his fellow tauren from the Grimtotem tribe. He cautions traveling Horde allies to keep their distance from them, noting their increasingly erratic and suspicious behavior around Thousand Needles. To ensure the defense of the region, he dispatches couriers to Freewind Post to deliver warnings to Cliffwatcher Longhorn.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brave-moonhorn-c908953ca7eac7f4e137/1-0000.mp3", duration = 63.0595918, start = 0},
  },
}
P.transport["npc:brewmeister-bilger"] = {
  hash = "44d50d",
  fullHash = "44d50d",
  text = "Brewmeister Bilger. Brewmeister Bilger is an intoxicated dwarven brewer residing in the cellar of the inn at Southshore in the Hillsbrad Foothills. He whiles away his hours tasting potent spirits and waiting on deliveries from distant lands. Bilger spends his days pacing the cool cellar beneath Southshore's inn, nursing hiccups and seeking out the strongest brews Azeroth can offer. Despite his perpetual stupor, Bilger remains a discerning judge of spirits. He maintains an appetite for heavy dwarven moonshines and potent liquors crafted in the south, eagerly receiving special batches like the moonshine Foggy MacKreel sends him from the Thandol Span.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brewmeister-bilger-73ffeb62d35beac009fc/1-0000.mp3", duration = 39.6277551, start = 0},
  },
}
P.transport["npc:brock-stoneseeker"] = {
  hash = "b051d5",
  fullHash = "b051d5",
  text = "Brock Stoneseeker. Brock Stoneseeker is a dwarven mining instructor based in the settlement of Thelsamar in Loch Modan. As the proprietor of Brock's School of Mining and Surveying, he instructs novice prospectors in the craft of extracting valuable ores and minerals from the earth. Operating out of Thelsamar, Brock Stoneseeker directs Brock's School of Mining and Surveying. In the mineral-rich hills of Loch Modan, seasoned expertise with a pickaxe and an eye for geological veins are indispensable. Brock guides aspiring miners through the foundational techniques of identifying ore nodes, extracting raw metals, and properly surveying subterranean deposits, ensuring Alliance tradesfolk can fuel Ironforge's legendary smithies.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brock-stoneseeker-92efd227f882fb2ef34a/1-0000.mp3", duration = 44.6693878, start = 0},
  },
}
P.transport["npc:bromos-grummner"] = {
  hash = "0fb03f",
  fullHash = "0fb03f",
  text = "Bromos Grummner. Bromos Grummner is a dwarven paladin trainer stationed in Anvilmar within Coldridge Valley. He mentors fledgling dwarven holy warriors, preaching steadfast faith in the Holy Light and the vital bond between dwarves and humans in the Knights of the Silver Hand. Standing within the sturdy stone hall of Anvilmar, Bromos Grummner welcomes dwarven novices drawn to the discipline of the Holy Light. Confident and resolute, he instructs young paladins in martial rites and sacred invocations. Beyond the basic tenets of combat, Bromos emphasizes unity, reminding his pupils that the order of the Knights of the Silver Hand bridges the realms of Ironforge and the human kingdoms of the Alliance in righteous purpose.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bromos-grummner-f69321f2254c6b1b3702/1-0000.mp3", duration = 43.8073469, start = 0},
  },
}
P.transport["npc:brother-joshua"] = {
  hash = "c14cff",
  fullHash = "c14cff",
  text = "Brother Joshua. In Stormwind, Brother Joshua guides those who come to the Cathedral of Light to learn the ways of the Holy Light. He trains novice priests to heal wounds and strengthen their allies. Brother Joshua waits near the main altar in Stormwind's Cathedral of Light, ready to teach new servants of the faith. A priest of the Church of the Holy Light, he instructs them in healing, protective wards, and the focus needed to commune with the Light. Young human priests beginning their service to the Alliance find one of their first guides in him.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brother-joshua-b9523ce90d0497b10a21/1-0000.mp3", duration = 33.1232653, start = 0},
  },
}
P.transport["npc:brother-kristoff"] = {
  hash = "f60437",
  fullHash = "f60437",
  text = "Brother Kristoff. In Stormwind's Cathedral Square, Brother Kristoff preaches beneath Uther's statue. A human priest of the Church of the Holy Light, he stands outdoors near the great statue of Uther the Lightbringer and seeks practical books for sermons on spiritual strength. Brother Kristoff serves the Church of the Holy Light in Cathedral Square, beneath the statue of Uther the Lightbringer. He works among the citizens and pilgrims who pass through the plaza, rather than remaining within the Cathedral of Light. For sermons such as the Fortitude of the Spirit, he turns to worldly comparisons. In The Stresses of Iron, he finds a way to explain how the mortal soul endures pressure, comparing the Holy Light's gift of inner resolve to the tempered strength of worked metal.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brother-kristoff-b8cb60293c9a608f97fd/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["npc:brother-neals"] = {
  hash = "cf7e7c",
  fullHash = "cf7e7c",
  text = "Brother Neals. At Northshire Abbey, Brother Neals keeps watch over the food and drink stores. He oversees shipments and samples wine from the local vineyard. Brother Neals keeps Northshire Abbey supplied with food and drink from his rooms in the upper belfry. He follows the grape manifests from the Northshire vineyards and tastes the wine to check its quality. He also watches the shipments arriving from the fields around the valley.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brother-neals-2465388bf2a07aa5c931/1-0000.mp3", duration = 25.6261224, start = 0},
  },
}
P.transport["npc:brother-sarno"] = {
  hash = "70a49e",
  fullHash = "70a49e",
  text = "Brother Sarno. At the Cathedral of Light in Stormwind City, Brother Sarno welcomes visitors and worshipers. The human cleric also directs Alliance travelers to Ironforge, where Tinkmaster Overspark needs help reclaiming Gnomeregan. Inside the Cathedral of Light in Stormwind, Brother Sarno greets pilgrims and travelers at the entrance. A brother of the Church of the Holy Light, he welcomes those who come seeking prayer, comfort, or guidance. His kind manner puts visitors at ease amid the cathedral’s daily life. Brother Sarno also helps the Alliance beyond the cathedral. When word reached him that Tinkmaster Overspark in Ironforge needed help with his rogue invention, Techbot, in Gnomeregan, Sarno directed capable travelers toward Dun Morogh. His help supports the gnomes displaced from their home.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brother-sarno-e5c3c04d733c30954c20/1-0000.mp3", duration = 48.7183673, start = 0},
  },
}
P.transport["npc:brother-wilhelm"] = {
  hash = "80562e",
  fullHash = "80562e",
  text = "Brother Wilhelm. Behind Goldshire's blacksmith, Brother Wilhelm trains young paladins in the Holy Light. He guides them as they leave Northshire Abbey and take their first steps into Elwynn Forest. Brother Wilhelm trains new paladins behind Goldshire's smithy. Northshire Valley shelters those who begin their path in the Light, but many seek his guidance when they enter the wider forest. He teaches them their sacred duties as they leave the abbey and take up the work of protecting the realm. Brother Wilhelm guides aspiring paladins toward the Tome of Divinity. Its rite teaches initiates the weight of sacrifice and the power of divine redemption. Through it, they test their devotion and learn to wield the Light to resurrect fallen comrades and uphold justice across the Kingdom of Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brother-wilhelm-0da5e0b7b10d430f0ea2/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["npc:cain-firesong"] = {
  hash = "038a36",
  fullHash = "038a36",
  text = "Cain Firesong. Cain Firesong is a Forsaken mage trainer located in the settlement of Brill within Tirisfal Glades. He assists fledgling practitioners of the arcane as they grow in power, guiding them before directing them onward to deeper studies in the Undercity. He can be found on the upstairs landing of the Gallows' End Tavern. While many Forsaken spellcasters delve into shadow or necromancy, Cain Firesong maintains mastery over traditional arcane disciplines. Stationed in Brill, he serves as an early mentor to Forsaken mages venturing forth from Deathknell. The local Deathguards direct visitors to the upstairs landing of the Gallows' End Tavern, joking that he arrived too late to get a room. As novice mages under his tutelage advance beyond their preliminary studies in Tirisfal Glades, Cain ensures they do not stagnate. He directs his most capable students to seek out Anastasia Hartwell, a master sorceress residing in the Magic Quarter of the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_cain-firesong-4c6e130263961caa0c54/1-0000.mp3", duration = 59.0889796, start = 0},
  },
}
P.transport["npc:calvin-montague"] = {
  hash = "ff4a42",
  fullHash = "ff4a42",
  text = "Calvin Montague. Calvin Montague is an opportunistic Forsaken rogue loitering near the exit gate of Deathknell in Tirisfal Glades. Preying on newly awakened undead as they leave the graveyard, he attempts to trick passersby into running errands on his behalf. Positioned just outside the gates leading away from Deathknell, Calvin Montague embodies the ruthless pragmatism common among Lordaeron's restless dead. Rather than handling his own correspondence or paying fair courier rates, he attempts to smooth-talk wandering adventurers into delivering letters under false pretenses. While several other prominent undead bearing the Montague family name manage banking interests within the Undercity, Calvin pursues a decidedly less reputable trade, preferring petty schemes and deception.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_calvin-montague-9611a82987485eeb8b00/1-0000.mp3", duration = 45.322449, start = 0},
  },
}
P.transport["npc:captain-danuvin"] = {
  hash = "d67d45",
  fullHash = "d67d45",
  text = "Captain Danuvin. At Sentinel Hill, Captain Danuvin helps hold Westfall's frontier together. He works with the People's Militia, directing volunteers and recruits to patrol roads and drive back Gnolls and outlaws. His orders protect the supply lines and farmlands from hostile hands. Captain Danuvin coordinates patrols from Sentinel Hill's fortified tower. Stormwind's regular garrison has withdrawn, leaving Westfall's defenses badly weakened. He depends on travelers, farmhands, and volunteer fighters to keep some order across the plains. Captain Danuvin focuses on the roads and open lands around Sentinel Hill. Riverpaw Gnolls raid near the central outposts, so he sends patrols to thin their packs and secure the perimeter. His orders help keep marauders and opportunists from surrounding the camp.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_captain-danuvin-89686cd5089d418bd100/1-0000.mp3", duration = 46.2628571, start = 0},
  },
}
P.transport["npc:captain-rugelfuss"] = {
  hash = "dd2047",
  fullHash = "dd2047",
  text = "Captain Rugelfuss. Captain Rugelfuss is a stern dwarven officer stationed at the southern gate in the Valley of Kings. Tasked with securing the border of Loch Modan, he organizes the defense against a sudden and aggressive trogg uprising. Positioned near the monumental carved arches of the Valley of Kings, Captain Rugelfuss oversees the southern gateway into Loch Modan. With Alliance forces stretched thin across the world, Ironforge relies on veteran officers like him to keep the home territories secure. Rugelfuss dismisses military pomp and formalities, preferring to focus entirely on the grim reality facing the border. The primary crisis demanding Rugelfuss's attention is the swelling trogg threat. Unearthed from ancient caverns and surging into the highlands, these savage brutes have overwhelmed outlying dwarven patrols and established fortified footholds nearby. Under the banner of defending the King's lands, the captain recruits capable travelers to cull their ranks and push the creatures back from the roadway.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_captain-rugelfuss-2d052027f015214a0778/1-0000.mp3", duration = 63.1118367, start = 0},
  },
}
P.transport["npc:captain-shatterskull"] = {
  hash = "44b036",
  fullHash = "44b036",
  text = "Captain Shatterskull. At Mor'shan Base Camp, Captain Shatterskull commands the Horde's northern border defense. A seasoned orc commander, he coordinates efforts to repel night elf forces contesting the border near Warsong Gulch. At Mor'shan Base Camp, Captain Shatterskull guards the Horde's foothold at the edge of Ashenvale. He works beside fellow officers such as Kadrak against night elf sentinels and Silverwing forces seeking to reclaim the borderlands. The struggle over Ashenvale's timber and ancient lands keeps the Barrens frontier under constant threat.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_captain-shatterskull-59e985e65dd8f6fa241f/1-0000.mp3", duration = 33.6195918, start = 0},
  },
}
P.transport["npc:captain-thalo-thas-brightsun"] = {
  hash = "6d5896",
  fullHash = "6d5896",
  text = "Captain Thalo'thas Brightsun. At Ratchet's docks, Captain Thalo'thas Brightsun keeps a cordial face toward Alliance travelers. The privateer serves the Steamwheedle Cartel and resents the Theramore forces at Northwatch Hold for firing on his vessels. Captain Thalo'thas Brightsun leads the Thalo'dan Privateers from Ratchet's docks under the Steamwheedle Cartel's banner. Ratchet welcomes merchants of every flag if they bring coin, but danger shadows trade along the Barrens coast. Northwatch Hold lies just south of the port, where its heavy cannons threaten neutral sea lanes. Brightsun stays cordial toward visiting travelers, yet the garrison's attacks on his fleet have tried his patience. An open assault on Northwatch Hold could endanger Ratchet's neutrality, so Brightsun cannot send his fleet against the fort. He turns instead to capable Horde mercenaries to settle the score. Their strikes aim to silence the cannons and free his captured crew. By using Horde auxiliaries, Brightsun protects his shipping interests without provoking direct Alliance retaliation against the cartel or entering the conflict openly.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_captain-thalo-thas-brightsun-c2000402ea3d8ad968ad/1-0000.mp3", duration = 65.4367347, start = 0},
  },
}
P.transport["npc:captured-mountaineer"] = {
  hash = "e64939",
  fullHash = "e64939",
  text = "Captured Mountaineer. The Captured Mountaineer is an Ironforge dwarf held prisoner in the basement of the Gallows' End Tavern in Brill. Bound and guarded by the Forsaken, he serves as an unwilling subject for the Royal Apothecary Society's grim experiments. Tucked away beneath the floorboards of the Gallows' End Tavern in Brill, this Ironforge Mountaineer sits captive far from the safety of Khaz Modan. While patrons drink above, the Royal Apothecary Society puts him to work as an unwitting test subject for their concoctions. Apothecary Johaan and his peers test the lethal potency of their developing plague against living Alliance physiology, using the prisoner to gauge how well their toxins bring a swift and agonizing end to the living.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_captured-mountaineer-805212ca947df4d2e69f/1-0000.mp3", duration = 44.0163265, start = 0},
  },
}
P.transport["npc:captured-scarlet-zealot"] = {
  hash = "4cd3b5",
  fullHash = "4cd3b5",
  text = "Captured Scarlet Zealot. The Captured Scarlet Zealot is a crusader prisoner held captive in the basement of Gallows' End Tavern in Brill. Watched over by Forsaken apothecaries and townsfolk, he serves as a living test subject for the Royal Apothecary Society's developing concoctions. Confined beneath Gallows' End Tavern, this member of the Scarlet Crusade embodies the unyielding fanaticism of his order. Even in chains, surrounded by the undead he views as an abomination, he offers no remorse, calling on the Light to protect him from the foul and unholy creatures around him. For the Forsaken, capturing a living zealot is not an act of mercy; it provides valuable human test material to evaluate the lethality of experimental plagues and toxins under development by Apothecary Johaan.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_captured-scarlet-zealot-a7b4a3120d31e6a83de0/1-0000.mp3", duration = 48.6138776, start = 0},
  },
}
P.transport["npc:caretaker-folsom"] = {
  hash = "ac2443",
  fullHash = "ac2443",
  text = "Caretaker Folsom. Along Stormwind’s Canals near the Park, Caretaker Folsom tends the remains of a noble household. He once oversaw the Flintridge estate; now he sells what survived its bloody end. Folsom followed his father into a life of service as caretaker of the Flintridge estate. That life ended with the massacre of the household. The manor stood abandoned, and its remaining funds eventually ran out. Left to watch over what remained, Folsom now sends the family's surviving heirlooms and possessions to auction.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_caretaker-folsom-0258b5336a8203f9509e/1-0000.mp3", duration = 32.8097959, start = 0},
  },
}
P.transport["npc:carolai-anise"] = {
  hash = "e5ae5c",
  fullHash = "e5ae5c",
  text = "Carolai Anise. Carolai Anise is an eccentric Forsaken alchemist residing in the village of Brill in Tirisfal Glades. She trains novice alchemists, though her hazardous concoctions have drawn nervous murmurs from local guards. Operating out of Brill, Carolai Anise devotes her unlife to the volatile art of alchemy. While many Forsaken researchers operate under the Royal Apothecary Society's grim mandate, Carolai pursues her own strange brews right inside the settlement. Her unpredictable experiments and smoking retorts are notorious enough that the Deathguards keeping watch over Brill openly grumble that she seems bent on blowing up her own house.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_carolai-anise-2421906d9be0cac0d46c/1-0000.mp3", duration = 38.4783673, start = 0},
  },
}
P.transport["npc:cazul"] = {
  hash = "4968aa",
  fullHash = "4968aa",
  text = "Cazul. In the Cleft of Shadow, Cazul guides young warlocks toward greater command of demons. Blind and ancient, he remains a keeper of old orc warlock traditions. Cazul waits in the Cleft of Shadow beneath Orgrimmar, where rising warlocks seek his counsel. Blind though he is, he senses the currents of the Twisting Nether and hears the whispers of demons. Those who want to master their craft and bind more dangerous servitors are often sent to him. His sight is gone, but his arcane power remains.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_cazul-e9072edec00e29b067aa/1-0000.mp3", duration = 31.9477551, start = 0},
  },
}
P.transport["npc:cerellean-whiteclaw"] = {
  hash = "f6512b",
  fullHash = "f6512b",
  text = "Cerellean Whiteclaw. Near Auberdine’s docks and inn in Darkshore, Cerellean Whiteclaw rests with grief for a lost love. The Sundering’s memory haunts him, and he struggles to bring that restless spirit peace. Before the War of the Ancients, Cerellean Whiteclaw shared his life with Anaya Dawnrunner. Ten thousand years ago, the demonic invasion shattered ancient Kalimdor, and Anaya died in the destruction of her city, Ameth'Aran. Stricken with grief, Cerellean followed Malfurion Stormrage into the long druidic slumber. The Emerald Dream brought little relief from his memories. When he awoke millennia later, he wandered Darkshore in grief and found Anaya's ghost still bound to the stones where she fell.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_cerellean-whiteclaw-0194ef82ffe6e425ff73/1-0000.mp3", duration = 43.0497959, start = 0},
  },
}
P.transport["npc:chef-breanna"] = {
  hash = "16cac0",
  fullHash = "16cac0",
  text = "Chef Breanna. Chef Breanna is the head cook at Lakeshire's local dining house in the Redridge Mountains. Tasked with feeding the garrison of Stormwind soldiers stationed to protect the embattled lakeside town, she relies on hearty, local ingredients to keep the defenders on their feet. Operating out of a restaurant house in northwestern Lakeshire alongside her assistants Crystal Boughman and Gretchen Vogel, Chef Breanna bears the heavy responsibility of provisioning the entire local battalion. With Lakeshire besieged by Blackrock orcs, gnolls, and murlocs, maintaining the strength and morale of Stormwind's understaffed garrison is essential. Her signature dish, Redridge Goulash, relies on the wild game and beasts roaming the surrounding ridges, turning dangerous wilderness predators into fuel for the town's weary guard.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_chef-breanna-e7f679657f495cc6a94b/1-0000.mp3", duration = 46.9942857, start = 0},
  },
}
P.transport["npc:chef-grual"] = {
  hash = "0380f0",
  fullHash = "0380f0",
  text = "Chef Grual. Chef Grual is the resident cook at the Scarlet Raven Tavern in Darkshire. In a secluded town choked by mist and monsters, Grual does his best to keep the Night Watch and weary travelers fed, even if his choice of ingredients raises eyebrows. Running an eatery in Darkshire is a grim task. With supply lines from Westfall and Stormwind constantly harassed by highwaymen, wolves, and undead, fresh provisions are virtually nonexistent. Grual makes do with whatever the wilderness provides. From wolf flank to whatever scavenged meats local adventurers drag through the door, Grual cooks with pragmatism born of necessity. Grual is infamous for his specialty dishes, most notably his famous 'Dusky Crab Cakes' and seasoned wolf kabobs. Given that coastal crabs are nowhere near the gloomy inland woods of Duskwood, his crab cakes rely on a rather revolting substitute: the gooey legs of local Venom Web Spiders. Whether patrons realize they are eating arachnid meat or simply prefer not to ask, Grual keeps the kitchen running without apologies.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_chef-grual-8d8d3ebad1af5a8306c7/1-0000.mp3", duration = 65.9853061, start = 0},
  },
}
P.transport["npc:chef-jessen"] = {
  hash = "350a3a",
  fullHash = "350a3a",
  text = "Chef Jessen. Chef Jessen is Southshore's resident meat vendor and culinarian, working to keep the coastal town fed amidst constant border tensions. He is best remembered for his famous turtle bisque. Operating out of Southshore in the southern Hillsbrad Foothills, Chef Jessen provides provisions and meat to locals and visiting Alliance soldiers alike. He possesses notable culinary expertise. Years past, before plague and war disrupted northern Lordaeron, he regularly ventured north past Dalaran to the shores of Lordamere Lake. There, he harvested meat from native snapjaw turtles to concoct his prized Soothing Turtle Bisque, a hearty recipe he is willing to share with aspiring travelers who assist him in gathering ingredients.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_chef-jessen-28d93d93a10fd51b0d51/1-0000.mp3", duration = 43.6767347, start = 0},
  },
}
P.transport["npc:chief-archaeologist-greywhisker"] = {
  hash = "516795",
  fullHash = "516795",
  text = "Chief Archaeologist Greywhisker. In Darnassus, Chief Archaeologist Greywhisker gathers reports from the coast. The Ironforge dwarf works outside the Temple of the Moon, where he coordinates the Explorers' League's research and tracks colleagues in Darkshore. Chief Archaeologist Greywhisker works outside the Temple of the Moon in Darnassus, far from his home in Ironforge. He represents the Explorers' League, which sent him across the sea to Kalimdor for fieldwork. There, he speaks with night elf scholars such as Tarelvir and seeks knowledge of the ancient lands. In Ironforge, his lectures covered ancient lore and primordial beings, including the Wild God Agamaggan. Now he hopes to learn what the night elves' ancestral lands hold. In Kalimdor, Greywhisker oversees dwarven excavations and follows expeditions searching ancient coastal ruins. He depends on travelers to carry messages to prospectors across the sea in Darkshore. Field research in unexplored lands is perilous, and he waits anxiously for reports from the dig sites, hoping his colleagues are safe among the ruins.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_chief-archaeologist-greywhisker-36cb92d1d2e9afdda067/1-0000.mp3", duration = 66.795102, start = 0},
  },
}
P.transport["npc:christoph-jeffcoat"] = {
  hash = "1756eb",
  fullHash = "1756eb",
  text = "Christoph Jeffcoat. Christoph Jeffcoat is a Forsaken merchant stationed in the settlement of Tarren Mill within the Hillsbrad Foothills. He supplies local crafters and travelers with essential trade goods, cooking seasonings, and specialty recipes. In an active war zone contested by the Alliance and the Syndicate, his mundane wares keep the northern Horde war effort running. While Tarren Mill stands as the Forsaken's military stronghold in Hillsbrad Foothills, a garrison cannot fight on malice alone. Christoph Jeffcoat handles the quiet, practical side of occupation, vending reagents, tools, threads, and spices to soldiers and traveling artisans. From the soothing spices required for local culinary recipes like turtle bisque to rare schematics and alchemical vials, Jeffcoat ensures that Horde forces passing through southern Lordaeron are fully provisioned for the battles against Southshore and the regional perils.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_christoph-jeffcoat-b07a29b9ba9058369eca/1-0000.mp3", duration = 53.8644898, start = 0},
  },
}
P.transport["npc:chronormu"] = {
  hash = "f989a8",
  fullHash = "f989a8",
  text = "Chronormu. Chronormu, who goes by the mortal name Chromie, is a bronze dragon disguised as an energetic female gnome. Tasked with safeguarding the flow of time on Azeroth, she often works directly with mortals rather than observing from afar. In the Western Plaguelands, she quietly intervenes in the tragic aftermath of the Third War to right disrupted temporal threads. Though she appears to mortals as an eccentric and cheerful gnome named Chromie, Chronormu is a member of the bronze dragonflight serving under the Timeless One, Nozdormu. Bronze dragons are charged by the titans with guarding history and correcting disruptions in the timeways. In the form of a female gnome, she walks beside mortals as an approachable, optimistic peer. Chronormu has taken up residence within the ruined ruins of Lordaeron, particularly watching the devastated Western Plaguelands. The catastrophic downfall of the kingdom and the spread of the Scourge tore deeply into the region's history, leaving temporal anomalies and trapped remnants. Working discreetly from places like the ruins of Andorhal, she enlists mortal adventurers to mend tangled timelines and investigate disturbances without revealing the full terrifying majesty of the dragonflight unless necessary.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_chronormu-de84296454a676c6142d/1-0000.mp3", duration = 74.475102, start = 0},
  },
}
P.transport["npc:clarice-foster"] = {
  hash = "e4f004",
  fullHash = "e4f004",
  text = "Clarice Foster. Clarice Foster is a Forsaken woman residing deep beneath the bluffs of Mulgore within the Pools of Vision. Far from the plagued glades of Lordaeron, she spends her days in contemplation among the tauren seers and mystics. While most Forsaken remain in the northern lands of Lordaeron rebuilding their kingdom under the Undercity, Clarice Foster has traveled to the heart of the tauren lands in Kalimdor. Sheltered within the cavernous Pools of Vision beneath the mesa of Thunder Bluff, she dwells alongside Forsaken apothecaries and tauren shamans who study the spiritual and elemental mysteries of the earth.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_clarice-foster-de3836269ae71252e738/1-0000.mp3", duration = 35.7093878, start = 0},
  },
}
P.transport["npc:colonel-kurzen"] = {
  hash = "c7237e",
  fullHash = "c7237e",
  text = "Colonel Kurzen. Colonel Conrad Kurzen was once a decorated and noble officer of the Stormwind Army, sent to lead an expedition into northern Stranglethorn Vale. After descending into sudden madness and tyranny, he turned his force into a rogue jungle militia operating out of an armed compound. Today, his former subordinates at the nearby Rebel Camp actively seek his death to end his reign of terror. Before his downfall, Colonel Conrad Kurzen was regarded in Stormwind as an exceptionally capable and noble officer. Trusted by the kingdom's leadership, he was granted command of an expeditionary unit dispatched south into the dense jungles of Stranglethorn Vale. However, deep within the humid wilds, Kurzen began to exhibit erratic behavior and extreme megalomania, declaring absolute sovereignty over the surrounding wilderness and abandoning his allegiance to Stormwind. Kurzen's sudden transformation divided his ranks. While many soldiers succumbed to blind loyalty or twisted zealotry, others grew appalled by his madness and brutality—including his act of throwing Emerine Junis into the compound's prison simply for spurning his advances. Led by Lieutenant Doren, a group of conscience-stricken soldiers broke away to establish the Rebel Camp along the northern road. These loyalist defectors now wage a desperate war against Kurzen to stop his rampaging force.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_colonel-kurzen-3b76a7b0ad867cbed5b8/1-0000.mp3", duration = 84.0620408, start = 0},
  },
}
P.transport["npc:commander-mar-alith"] = {
  hash = "8f8df4",
  fullHash = "8f8df4",
  text = "Commander Mar'alith. Commander Mar'alith is the stalwart night elf military commander directing the Cenarion Circle's vanguard at Cenarion Hold in Silithus. Clad in heavy armor and wielding a grand glaive, he coordinates the martial resistance against the silithid swarms and Twilight's Hammer cultists. Beneath his resolute leadership lies a deep personal sorrow regarding the mysterious fate of his beloved wife, Natalia. Stationed at the heart of Cenarion Hold, Commander Mar'alith bears the tremendous responsibility of safeguarding the Circle's desert bastion. While the druids unravel the ancient ecological and cosmic anomalies of Silithus, Mar'alith handles the grim, practical necessities of war. He oversees tactical strikes against the bustling silithid hives of Hive'Ashi, Hive'Zora, and Hive'Regal, ensuring that the relentless insectoid incursions do not overwhelm the expedition's central foothold. Despite his stern military bearing, Mar'alith is visibly strained by a harrowing personal tragedy. His beloved wife, Natalia Mar'alith, ventured into the shifting sands on an assignment for the Circle and failed to return. Caught between his duty to the Cenarion expedition and agonizing grief, the commander appears increasingly distracted, clinging to whatever hope remains while desperate for news of what truly became of her in the wastes.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_commander-mar-alith-8daeb3c4ac40393f2e57/1-0000.mp3", duration = 81.8938776, start = 0},
  },
}
P.transport["npc:councilman-millstipe"] = {
  hash = "01876c",
  fullHash = "01876c",
  text = "Councilman Millstipe. Councilman Millstipe is a member of Darkshire's governing council, residing within the town hall of Duskwood. Deeply resentful of royal neglect and judicial meddling from the capital, he actively seeks retribution against criminals who endanger the darkened region. While Darkshire struggles under the shadow of the undead and ferocious beast attacks, its local council fights an uphill battle against the bureaucracy of Stormwind City. Councilman Millstipe represents the town's growing bitterness toward the crown. When the notorious grave robber Dextren Ward was caught selling freshly dug corpses to the necromancer Morbent Fel, Darkshire's leaders sentenced him to death. Instead, Stormwind's House of Nobles intervened, commuting Ward's execution and locking him safely away inside the Stormwind Stockade.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_councilman-millstipe-2725ccf23e887dddc322/1-0000.mp3", duration = 47.4644898, start = 0},
  },
}
P.transport["npc:count-remington-ridgewell"] = {
  hash = "5fe8cd",
  fullHash = "5fe8cd",
  text = "Count Remington Ridgewell. In Stormwind Keep, Count Remington Ridgewell tends a collection fit for a noble’s pride. A wealthy human in the House of Nobles, he gathers rare artifacts, heirlooms, and fine art. Count Remington Ridgewell favors antiquities over military campaigns or local uprisings. His family’s personal museum holds jewelry and artifacts, and he spends his wealth gathering relics from fallen civilizations and houses across Azeroth. To fill his gallery, he finances adventurers and sends field agents such as Mayara Brightwing to retrieve rare objects from dangerous ruins, from Alterac’s mountain redoubts to the volcanic wastes of the Burning Steppes.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_count-remington-ridgewell-74be44b574806f41d448/1-0000.mp3", duration = 40.6465306, start = 0},
  },
}
P.transport["npc:crane-operator-bigglefuzz"] = {
  hash = "dca355",
  fullHash = "dca355",
  text = "Crane Operator Bigglefuzz. Crane Operator Bigglefuzz is a goblin dockhand working the heavy machinery at the port of Ratchet. After an overloaded crane mishap scattered cargo across the docks, he finds himself desperate to recover a valuable stolen bottle before his superiors notice. Like many goblin dockworkers, Crane Operator Bigglefuzz prioritized efficiency and haste over basic safety margins. While attempting to hoist an excessively heavy haul from a merchant vessel, his crane buckled, sending crates crashing down across the Ratchet wharves. In the ensuing chaos, opportunistic scoundrels swept in, leaving Bigglefuzz to scramble to clean up the mess and salvage the most precious goods before Gazlowe or the local port masters dock his pay. The worst casualty of the accident was not the broken wood, but a crate containing rare ninety-nine-year-old port. Before Bigglefuzz could secure the spill, an elusive vagrant named Mad Magglish snatched a bottle and fled into hiding, threatening to leave Bigglefuzz answering for an irreplaceable loss.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_crane-operator-bigglefuzz-10cb98cea8eb9c6e7bb5/1-0000.mp3", duration = 63.3730612, start = 0},
  },
}
P.transport["npc:craven-drok"] = {
  hash = "036d10",
  fullHash = "036d10",
  text = "Craven Drok. In Orgrimmar, Craven Drok keeps to the Cleft of Shadow and seeks travelers for a delicate matter. He wants them to consider how the Alliance sees the Horde. Craven Drok avoids Orgrimmar's sunlit avenues and wanders the winding paths beneath the city. The Cleft of Shadow draws warlocks, rogues, and practitioners of less honorable trades. Drok keeps out of sight and hires passersby to handle discreet errands, including one about the Horde's standing with the Alliance.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_craven-drok-3ae73b37eb175bd36513/1-0000.mp3", duration = 28.9959184, start = 0},
  },
}
P.transport["npc:cyrus-therepentous"] = {
  hash = "a1138e",
  fullHash = "a1138e",
  text = "Cyrus Therepentous. Cyrus Therepentous is a formidable black dragonspawn residing in the cavernous depths of Slither Rock in the Burning Steppes. Rather than immediately striking down intruders, he tests daring mortals to see if they possess the strength to serve the purposes of the Black dragonflight. Secluded inside a cavern at Slither Rock, Cyrus Therepentous oversees the volcanic crags of the Burning Steppes. Like many of his kind, he views mortal travelers with immense condescension, declaring that only fools would disturb his lair. Yet beneath his ferocious exterior lies a cold calculation: rather than consuming every trespasser on sight, he offers them a lethal challenge against his minions, willing to exploit those resilient enough to survive the trials of flame.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_cyrus-therepentous-e98dbdee7536fd36daaa/1-0000.mp3", duration = 44.9828571, start = 0},
  },
}
P.transport["npc:darcy-parker"] = {
  hash = "b69230",
  fullHash = "b69230",
  text = "Darcy. Darcy is a waitress serving drinks and warm meals at the Lakeshire Inn. Amid the constant threats looming over Redridge, she keeps her spirits up by looking after local defenders—particularly Guard Parker. Behind the busy counter of the Lakeshire Inn, Darcy works day and night to keep the town's weary militia fed and watered. Lakeshire sits under constant pressure from gnolls and Blackrock orcs, making the tavern one of the few places of warmth left in the settlement. Darcy takes a personal interest in the guards posted around town, frequently recruiting traveling adventurers to run hot meals and friendly errands out to those stationed along the borders. Darcy's warmth extends especially toward Guard Parker, who patrols the roads near Three Corners. Convinced he works too hard on an empty stomach, she regularly sends travelers out with lunch to keep him on his feet. Her affections have not gone unnoticed—Darcy keeps a watchful eye on Martie Jainrose, whom she considers a jealous rival for Parker's favor, turning the defense of Lakeshire into the backdrop for an earnest small-town romance.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_darcy-parker-de8a85bc5894a2faaccf/1-0000.mp3", duration = 64.6008163, start = 0},
  },
}
P.transport["npc:dark-cleric-beryl"] = {
  hash = "c6ad14",
  fullHash = "c6ad14",
  text = "Dark Cleric Beryl. Dark Cleric Beryl is a Forsaken priest trainer stationed in the Gallows' End Tavern in Brill. He guides newly awakened undead priests as they learn to wield shadow magic and adapt to their new, unholy existence under the Dark Lady. Residing on the upper floor of the Gallows' End Tavern in Brill, Dark Cleric Beryl serves the Forsaken by mentoring nascent priests. Beryl teaches that a Forsaken priest's power comes from darkness and shadow, yet one must also know the light before mastering the dark. He assists newly risen practitioners as they turn their focus toward shadow and the dark arts, guiding them through early trials like crafting their Garments of Darkness and proving their dedication to the new path.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dark-cleric-beryl-704c3b32194ea0db5a10/1-0000.mp3", duration = 43.4938776, start = 0},
  },
}
P.transport["npc:darkmaster-gandling"] = {
  hash = "16010a",
  fullHash = "16010a",
  text = "Darkmaster Gandling. Darkmaster Gandling is the mortal headmaster of Scholomance, overseeing the instruction and training of necromancers for the Cult of the Damned. Operating from the depths of the ruined Keep of Caer Darrow, he serves the Scourge by orchestrating gruesome magical experiments upon the living and dead alike. Within the dark halls beneath Caer Darrow, Darkmaster Gandling governs Scholomance, the premier academy for the Scourge's aspiring necromancers. A living human serving the Cult of the Damned, Gandling worked alongside the lich Ras Frostwhisper to orchestrate atrocities against countless innocent captives taken from the surrounding lands. Students who enter his classrooms are instructed in plague brewing, reanimation, and flesh sculpting. Residing deep within the Headmaster's Study, Gandling commands the dark relics and spirits trapped inside the ancient school. He wields devastating arcane and shadow magic in conjunction with forbidden necromantic arts, cursing intruders and hurling them through shadow portals into the sealed chambers surrounding his study, where they must fight alone against the risen dead while Gandling shields himself from harm.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_darkmaster-gandling-e5f8cdd761a50117f526/1-0000.mp3", duration = 68.1795918, start = 0},
  },
}
P.transport["npc:darn-talongrip"] = {
  hash = "c4014b",
  fullHash = "c4014b",
  text = "Darn Talongrip. Darn Talongrip is an orc scout stationed along the frontier of the Stonetalon Mountains near Malaka'jin. He monitors local threats in the crags and helps coordinate Horde communication between forward outposts and regional commanders. Darn Talongrip watches the rugged ascents leading into Stonetalon from the southern Barrens. Stationed in the settlement of Malaka'jin, Darn directs recruits toward the Horde's new fronts in Ashenvale. His post serves as an early line of contact for travelers winding upward into contested peaks. From his post in Malaka'jin, Darn ensures messages and frontline reports reach key commanders like Kadrak at the watch tower in the northern Barrens. Outlying encampments in these mountains operate under constant pressure, making Darn's role as a sentry and courier essential to keeping the Horde vanguard informed.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_darn-talongrip-278bb58209bf13b443e4/1-0000.mp3", duration = 49.0057143, start = 0},
  },
}
P.transport["npc:daryl-the-youngling"] = {
  hash = "d4d089",
  fullHash = "d4d089",
  text = "Daryl the Youngling. Daryl the Youngling is a human hunter residing at Farstrider Lodge in the southeastern hills of Loch Modan. Eager to prove his marksmanship among veteran dwarven trackers, he challenges traveling adventurers to hone their wilderness skills and test their mettle against the local beasts. Farstrider Lodge is primarily a haven for dwarven mountaineers, trackers, and seasoned outdoorsmen who watch over the wilderness of Loch Modan. Daryl stands out as a young human striving to earn his place alongside these veteran stalkers. Rather than relying on mere bravado, he actively seeks to measure his hunting instincts against other travelers, issuing challenges to hunt down the tough wild boars and beasts roaming the crags and lakeshore.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_daryl-the-youngling-ea9daf51960dcbd21e18/1-0000.mp3", duration = 42.6318367, start = 0},
  },
}
P.transport["npc:dashel-stonefist"] = {
  hash = "874c9a",
  fullHash = "874c9a",
  text = "Dashel Stonefist. In Old Town, Dashel Stonefist is known for his quick temper and heavy hands. The dwarf called Fist keeps to Stormwind City's rougher alleys, where dangerous connections draw the attention of covert investigators. In Old Town, Dashel Stonefist is known as Fist for the street fights that have earned him the name. Locals and city guards see a drunken, combative dwarf ready to throw a punch outside a tavern. His place in the district puts him at the nexus of Stormwind's underworld, where smugglers, cutpurses, and political agitators trade coin and rumors beyond the eyes of Cathedral Square.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dashel-stonefist-457f796bca624bdfeb91/1-0000.mp3", duration = 34.0897959, start = 0},
  },
}
P.transport["npc:david-trias"] = {
  hash = "4f1149",
  fullHash = "4f1149",
  text = "David Trias. David Trias is the Forsaken rogue trainer stationed in Deathknell. He instructs freshly awakened undead in the arts of stealth, subterfuge, and bladecraft to aid Queen Sylvanas and the Forsaken. Positioned amidst the tombstones and ruins of Deathknell, David Trias is tasked with identifying and training those newly risen undead who possess a talent for unseen murder. For the fledgling Forsaken, survival requires more than sheer force of arms; it demands precise strikes from the dark. Trias decrypts orders and teaches initiates how to wield daggers, conceal their movements, and turn their reanimated reflexes into lethal precision against the living and the Scourge.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_david-trias-19e1681ec83f62e7f3fc/1-0000.mp3", duration = 41.3518367, start = 0},
  },
}
P.transport["npc:dawnwatcher-selgorm"] = {
  hash = "a3aff9",
  fullHash = "a3aff9",
  text = "Dawnwatcher Selgorm. Dawnwatcher Selgorm is a human representative of the Argent Dawn stationed upon the Craftsmen's Terrace in Darnassus. Acting as an observer and liaison in the night elven capital, he monitors reports of shadowy cult activity and dark threats stirring across northern Kalimdor. While the Argent Dawn focuses heavily on the undead scourge festering in the Eastern Plaguelands, their vigilance extends anywhere ancient evil takes root. Dawnwatcher Selgorm stands watch in Darnassus, bridging the gap between the insular night elves and the broader crusade against malevolence. From the Craftsmen's Terrace, he gathers intelligence on emerging threats in Kalimdor's wilderness, enlisting capable Alliance travelers to strike at cultists and dark powers before their influence can corrupt the realm.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dawnwatcher-selgorm-71e2b0229aed591c2adb/1-0000.mp3", duration = 46.6808163, start = 0},
  },
}
P.transport["npc:dawnwatcher-shaedlass"] = {
  hash = "2b23e0",
  fullHash = "2b23e0",
  text = "Dawnwatcher Shaedlass. Dawnwatcher Shaedlass is a night elf affiliated with the Argent Dawn, stationed within the Craftsmen's Terrace of Darnassus. Acting as a quiet eyes-and-ears operative in Kalimdor, he seeks news of his fellow order members sent on perilous reconnaissance into hostile lands. While the Argent Dawn is most famous for its bitter crusade against the Scourge in the Eastern Plaguelands, its vigilance extends far beyond Lordaeron. Dawnwatcher Shaedlass maintains a presence in the night elven capital of Darnassus, watching over the faction's interests in Kalimdor. From his quiet post on the Craftsmen's Terrace, he keeps tabs on covert expeditions against dark cults and corrupting powers that threaten the wider world.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dawnwatcher-shaedlass-ba95513c338cb6783a9c/1-0000.mp3", duration = 43.4938776, start = 0},
  },
}
P.transport["npc:dazalar"] = {
  hash = "901646",
  fullHash = "901646",
  text = "Dazalar. In Dolanaar, Dazalar trains young night elf hunters for the wilds of Teldrassil. He teaches them to aim true and form bonds with the beasts of the great boughs. Dazalar trains young hunters in Dolanaar before they venture beyond Shadowglen. Night elf rangers and sentinels patrol the wilderness, and he teaches newcomers the patience and discipline needed to protect Teldrassil's fragile ecosystem. Dazalar teaches hunters to tame and care for beasts. The Kaldorei seek a pact with forest predators such as nightsabers, owls, and strigid hunters, training them to fight beside their companions with respect rather than force.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dazalar-452d7c3ee19b0316cd7c/1-0000.mp3", duration = 40.0195918, start = 0},
  },
}
P.transport["npc:deathguard-bartholomew"] = {
  hash = "e4cb66",
  fullHash = "e4cb66",
  text = "Deathguard Bartholomew. Deathguard Bartholomew is a vigilant Forsaken soldier stationed in the town of Brill. Tasked with maintaining security across Tirisfal Glades, he helps travelers navigate the blighted settlement and assists in enforcing discipline among local defenders. Standing watch in the settlement of Brill, Deathguard Bartholomew represents the stalwart military backbone of the Forsaken. Like his fellow Deathguards throughout Tirisfal Glades, he defends reclaimed territory from lingering Scourge, fanatical Scarlet Crusaders, and any other threats to Lady Sylvanas's domain. In addition to keeping watch, he provides directions to travelers attempting to navigate the town's facilities and participates in maintaining orderly conduct among the newly risen.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deathguard-bartholomew-0d9debc772b20cd9d69f/1-0000.mp3", duration = 44.042449, start = 0},
  },
}
P.transport["npc:deathguard-burgess"] = {
  hash = "5f3124",
  fullHash = "5f3124",
  text = "Deathguard Burgess. Deathguard Burgess is a Forsaken sentry stationed in the town of Brill within Tirisfal Glades. Standing watch over the settlement, he keeps order and directs travelers to vital services across the hamlet. Positioned in the settlement of Brill just north of the Undercity, Deathguard Burgess serves as one of the town guards maintaining security against the Scourge and Scarlet Crusade. Like other Deathguards throughout Tirisfal Glades, Burgess aids arriving Forsaken by providing directions to local tradesfolk, class trainers, and civic services, keeping the vulnerable outpost running smoothly.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deathguard-burgess-5711f4ed40b5ea758b83/1-0000.mp3", duration = 33.9853061, start = 0},
  },
}
P.transport["npc:deathguard-humbert"] = {
  hash = "a68967",
  fullHash = "a68967",
  text = "Deathguard Humbert. Deathguard Humbert is a Forsaken sentry stationed in Tarren Mill within the Hillsbrad Foothills. Assigned to monitor the encroaching Alliance presence, he finds himself in an embarrassing predicament after losing his military gear to the dwarves of Dun Garok. While tasked with maintaining Tarren Mill's perimeter against regional threats, Deathguard Humbert suffered a humiliating setback. Sent by High Executor Darthalia to watch Dun Garok from a hidden camp, he left one morning to gather firewood, and dwarven scouts from Dun Garok made off with his prized sword and assorted equipment, leaving the undead soldier desperate to salvage his pride and armament before high command takes notice.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deathguard-humbert-ea84542c23b4a7c366c5/1-0000.mp3", duration = 42.1877551, start = 0},
  },
}
P.transport["npc:deathguard-linnea"] = {
  hash = "eb6fbf",
  fullHash = "eb6fbf",
  text = "Deathguard Linnea. Deathguard Linnea is a Forsaken soldier stationed at a Deathguard waystation in southeastern Tirisfal Glades. She helps secure the roads between Brill and the eastern borders, watching for threats posed by the Scarlet Crusade and lingering Scourge. Adventurers passing along the main thoroughfares often assist her unit with patrol duties. Deathguard Linnea stands sentinel at a small fortified post southeast of Brill. Life—or unlife—on patrol in Tirisfal Glades is treacherous, as the Forsaken must vigilantly defend their fledgling realm against Scarlet Crusade infiltrators and mindless Scourge prowling the wilderness. Stationed alongside her fellow guards, Linnea oversees patrol efforts along the roadway, coordinating reports with local authorities such as Magistrate Sevren in Brill to keep the eastern road toward the Bulwark secure.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deathguard-linnea-46cfd837bd006e864d1b/1-0000.mp3", duration = 50.964898, start = 0},
  },
}
P.transport["npc:deathguard-samsa"] = {
  hash = "a3b6da",
  fullHash = "a3b6da",
  text = "Deathguard Samsa. Deathguard Samsa is a Forsaken sentry stationed in Tarren Mill within the Hillsbrad Foothills. Tasked with maintaining Horde vigilance on a tense frontier, he directs traveling champions to strike at local threats encroaching on the settlement. Standing watch in Tarren Mill, Deathguard Samsa represents the defensive backbone of the Forsaken in the contested Hillsbrad Foothills. Tarren Mill serves as the Horde's primary outpost in the region, facing immediate pressure from Alliance outposts like Southshore as well as savage local wildlife. Samsa's duties involve securing the perimeter and directing capable adventurers to eliminate threats before they endanger the encampment.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deathguard-samsa-a8896eb51e2beac38658/1-0000.mp3", duration = 41.6914286, start = 0},
  },
}
P.transport["npc:deathguard-simmer"] = {
  hash = "da14de",
  fullHash = "da14de",
  text = "Deathguard Simmer. Deathguard Simmer is a Forsaken soldier stationed just outside Deathknell in Tirisfal Glades. He sizes up newly risen Forsaken and sends them to raid the human pumpkin farm to the west, patrolled by the Scarlet Crusade, for reagents the apothecaries of Brill need. Posted just outside Deathknell, Deathguard Simmer represents the Forsaken military line holding the border between the safe haven of Deathknell and the wider perils of Tirisfal Glades. The region crawls with living humans—most notably the fanatical Scarlet Crusade—who view all undead as abominations to be purged with fire and blade. Simmer tests fledgling Forsaken by sending them west to the Solliden Farmstead, where the Scarlet Crusade patrols from its nearby tower, to steal ten pumpkins and carry them to Apothecary Johaan in Brill.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deathguard-simmer-8b8339b657d4109cccce/1-0000.mp3", duration = 50.1812245, start = 0},
  },
}
P.transport["npc:deathstalker-faerleia"] = {
  hash = "d7b278",
  fullHash = "d7b278",
  text = "Deathstalker Faerleia. Deathstalker Faerleia is an operative of the Forsaken intelligence agency stationed deep within enemy territory inside Pyrewood Village. Operating out of the settlement's town hall, she orchestrates covert strikes against the Pyrewood Council, the village leaders Arugal uses as puppets. As an agent of the Deathstalkers—the covert intelligence and assassin branch of the Undercity—Faerleia is tasked with infiltrating Pyrewood Village in southern Silverpine Forest. The isolated human enclave harbors dark secrets, including a curse that transforms its populace under the night sky. Stationed within the upper levels of the town hall, Faerleia coordinates operations to disrupt the settlement from the inside, calling on Horde operatives to eliminate the influential members of the Pyrewood Council.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deathstalker-faerleia-c730e11376f2b18deb4c/1-0000.mp3", duration = 46.0016327, start = 0},
  },
}
P.transport["npc:deathstalker-lesh"] = {
  hash = "e5a4d8",
  fullHash = "e5a4d8",
  text = "Deathstalker Lesh. Deathstalker Lesh is a Forsaken rogue serving as a forward scout at Southpoint Tower in the Hillsbrad Foothills. Operating directly under High Executor Darthalia, she keeps watch over the human farms in the Hillsbrad Fields to gauge when the Forsaken should strike. Perched at Southpoint Tower on the southern road through the Hillsbrad Foothills, Deathstalker Lesh monitors the human farmers and town militia working the nearby Hillsbrad Fields. As an operative of the Deathstalkers—the Forsaken's secretive intelligence and assassination network—Lesh tracks enemy movements and numbers for High Executor Darthalia in Tarren Mill. When the moment is right, Lesh sends word to Darthalia with a coded message, 'The raven's cry from the west doth beckon', signaling that Hillsbrad is ripe for the Forsaken's attack.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deathstalker-lesh-ab9664f1869ed4eb6daa/1-0000.mp3", duration = 47.4383673, start = 0},
  },
}
P.transport["npc:deathstalker-rane-yorick"] = {
  hash = "09cd14",
  fullHash = "09cd14",
  text = "Rane Yorick. Deathstalker Rane Yorick is an operative of the Forsaken intelligence guild stationed deep in Silverpine Forest. Together with her brother Quinn, she was sent to scout the farms of northern Silverpine and report to High Executor Hadrec. The Deathstalkers serve as Lady Sylvanas Windrunner's eyes, ears, and blades across Lordaeron. Operating out of shadows and hidden posts, agents like Rane Yorick monitor the wilderness for threats that could disrupt Forsaken dominion. When sent to scout northern Silverpine Forest, Rane and her brother Quinn found themselves hemmed in by surrounding feral dangers, turning an undercover reconnaissance mission into a battle for survival.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deathstalker-rane-yorick-a7a8aa2105473dcc5876/1-0000.mp3", duration = 44.3297959, start = 0},
  },
}
P.transport["npc:deathstalker-vincent"] = {
  hash = "05abf8",
  fullHash = "05abf8",
  text = "Deathstalker Vincent. Deathstalker Vincent was a Forsaken scout sent alongside Deathstalker Adamant to infiltrate Shadowfang Keep. Slain by the mad mage Arugal, his corpse remains inside the stronghold as a grim warning to any who challenge the feral worgen within. Before the Forsaken could launch a full-scale assault against the beasts holding Shadowfang Keep, intelligence on the fortress's interior was desperately needed. Two operatives from the Deathstalkers, the intelligence arm of the Forsaken, slipped past the barricades: Vincent and Adamant. Their mission ended in disaster. While Adamant was captured and locked away in a dungeon cell, Vincent was dragged directly before Shadowfang's master. Refusing to bend the knee or serve Arugal's dark designs, Vincent was executed on the spot, his body discarded on the stone floor to rot as a testament to the mage's fury.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deathstalker-vincent-dbb58a0905cdd0faf0a6/1-0000.mp3", duration = 51.7746939, start = 0},
  },
}
P.transport["npc:deathwing"] = {
  hash = "aef05c",
  fullHash = "aef05c",
  text = "Deathwing. Deathwing the Destroyer, once known as Neltharion the Earth-Warder, is the fallen Dragon Aspect of the black dragonflight. Driven mad by the dark whispers of the Old Gods, he turned against the other Aspects and plunged the world into fire and turmoil. Though defeated near Grim Batol after the Second War and believed slain or hidden away, the terror of his legacy still haunts the deep places of Azeroth. Before he was known as the Destroyer, Neltharion was granted dominion over the earth and the subterranean vaults of Azeroth by the titan pantheon. Yet dwelling so close to the world's deepest chambers exposed him to the insidious whispers of the imprisoned Old Gods. During the ancient War of the Ancients, the madness took complete hold. He deceived the other Dragon Aspects into imbuing a golden disc, the Dragon Soul, with portions of their essence under the guise of halting the Burning Legion, only to turn the terrible weapon against his allies and unleash catastrophic devastation. In the present year, the mortal kingdoms largely assume Deathwing was destroyed or permanently driven from the world. However, the black dragonflight remains an active scourge across Azeroth. Led by his cunning brood, including his daughter Onyxia and son Nefarian, black drakes manipulate the politics of mortals and terrorize the landscape from mountain lairs. The scars of the black Aspect's ancient treachery run deep, and travelers wandering through craggy wastelands and deep subterranean tunnels still fear the stirring of the Great Dragon.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deathwing-b3e4a4dd8947b98f97a2/1-0000.mp3", duration = 94.5893878, start = 0},
  },
}
P.transport["npc:deino"] = {
  hash = "3dfc10",
  fullHash = "3dfc10",
  text = "Deino. In Orgrimmar's Valley of Spirits, Deino trains Horde mages in the arcane arts. She teaches spellcasters to master arcane and elemental forces, and sends seasoned mages across Kalimdor to study ancient magic and seek remote tutors. Deino trains Horde mages in Orgrimmar's Valley of Spirits. Totems, huts, and quiet waters surround the raised platforms where she teaches. Troll spellcasters balance spiritual reverence with arcane mastery, a path Deino shares with fellow instructors Enyo and Pephredo. Deino sends promising mages beyond Durotar to study arcane mysteries. In Ashenvale's corrupted wilds, they gather tainted Waters of Xavian and enchanted hair from the Laughing Sisters. When a student's power outgrows Orgrimmar's instruction, Deino directs them to remote masters, including Tabetha, a hermit sorceress in Dustwallow's swamplands.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deino-a50cf5fd1724a743efe9/1-0000.mp3", duration = 55.6930612, start = 0},
  },
}
P.transport["npc:demisette-cloyce"] = {
  hash = "714b20",
  fullHash = "714b20",
  text = "Demisette Cloyce. In Stormwind's Mage Quarter, Demisette Cloyce teaches warlocks beneath the Slaughtered Lamb. She guides students in fel magic and sends those ready for more toward other summoners. Warlocks gather in the cellar beneath the Slaughtered Lamb in Stormwind's Mage Quarter, while the city's authorities uphold order and the Holy Light. Demisette Cloyce lives in the catacombs below, teaching those willing to study forbidden arts. She warns that dark energies corrupt only those without the discipline to master them. Demisette guides warlocks beyond Stormwind when they have gained enough mastery. She connects them with summoners such as Menara Voidrender in the Barrens, where they can seek potent artifacts and learn to bind formidable fel steeds.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_demisette-cloyce-3b3528105fff7ea77526/1-0000.mp3", duration = 42.8930612, start = 0},
  },
}
P.transport["npc:deputy-feldon"] = {
  hash = "f210e7",
  fullHash = "f210e7",
  text = "Deputy Feldon. Deputy Feldon is a member of the Redridge town guard stationed just south of the Great Lakeshire Bridge. Tasked with watching the primary road into Lakeshire, he keeps a nervous vigil against the aggressive gnoll packs creeping toward the town perimeter. Standing watch near the southern approach to the Lakeshire bridge, Deputy Feldon represents an overextended town guard fighting to keep basic trade and travel routes open. With the Blackrock orcs pressing from the north and gnoll packs overrunning the southern hills, guardsmen like Feldon are stretched to their limits. Unable to leave his post without compromising the town's perimeter, he relies on passing adventurers to cull the gnolls encroaching on the roadway before they can cut Lakeshire off entirely.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deputy-feldon-8e6deb57cfc395dea0ec/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["npc:deputy-rainer"] = {
  hash = "ef7d7a",
  fullHash = "ef7d7a",
  text = "Deputy Rainer. Outside Westbrook Garrison, Deputy Rainer holds Elwynn's western border. The Stormwind Army officer faces gnolls and bandits from Westfall, coordinating local defenses while reinforcements fail to arrive. At Westbrook Garrison, Elwynn Forest's westernmost post, the road crosses into Westfall. Political paralysis in Stormwind City leaves much of the army abroad or caught in bureaucracy, and border posts like this one lack troops. Deputy Rainer organizes the defense from outside the tower with the few forces at hand. Riverpaw gnolls and wandering thieves threaten the local roads, so he depends on passing travelers and mercenary adventurers to keep the forest trails secure. Deputy Rainer watches for the Riverpaw pack and warns travelers about Hogger, the infamous gnoll chieftain. He also carries word of the troubled lands beyond the river. The chaos at Elwynn's border begins in Westfall's lawless farmlands, so he sends capable volunteers across the border toward Gryan Stoutmantle and the struggling People's Militia.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deputy-rainer-c0628c627a6b12937047/1-0000.mp3", duration = 65.3322449, start = 0},
  },
}
P.transport["npc:dirge-quikcleave"] = {
  hash = "be6ac6",
  fullHash = "be6ac6",
  text = "Dirge Quikcleave. Inside Gadgetzan's inn, Dirge Quikcleave holds court as a goblin culinary master and vendor. His inventive dishes are renowned across Azeroth, and seasoned chefs come to him to master artisan cooking. In dusty Gadgetzan, Dirge Quikcleave serves drinks and meat to travelers parched by the Tanaris sands. Though his kitchen is in a frontier tavern, he claims to be Azeroth's greatest living culinary artist. Cooking trainers in cities send their most promising students to him when ordinary lessons are spent. Dirge's demanding recipes call for unusual ingredients, from giant clam meat and eggs for his Clamlette creations to exotic beasts from distant shores. Dirge Quikcleave pairs a gourmand's bravado with a goblin's eye for business. Across Kalimdor, he keeps contacts with eccentric figures and seeks out dangerous culinary ventures. Those who bring him fierce beast cuts, such as meat from the monstrous chimaeroks of Feralas's Isle of Dread, can receive hearty recipes fit to sustain champions on perilous journeys. They must not ask too many questions about Dirge's private dealings.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dirge-quikcleave-5d3f7109ac115f7c33e5/1-0000.mp3", duration = 68.884898, start = 0},
  },
}
P.transport["npc:doan-karhan"] = {
  hash = "943d88",
  fullHash = "943d88",
  text = "Doan Karhan. In the southern Barrens, Doan Karhan studies the Burning Legion’s demonic artifacts. A human scholar and practitioner of the dark arts, he lives alone to pursue his research, especially into the enigmatic Orb of Soran'ruk. Doan Karhan keeps a solitary camp in the southern Barrens, far from the Alliance’s civilized bastions. He withdrew into the wilderness to study dangerous demonic relics without disturbance. He knows much about powerful fel vessels, possesses the Orb of Zargain, and is absorbed by the legendary Orb of Soran'ruk. Warlocks seeking knowledge of artifact crafting and dark rituals often come to him.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_doan-karhan-c2129081cbc98096f774/1-0000.mp3", duration = 41.6130612, start = 0},
  },
}
P.transport["npc:doctor-gregory-victor"] = {
  hash = "17b621",
  fullHash = "17b621",
  text = "Doctor Gregory Victor. Doctor Gregory Victor is a Forsaken surgeon stationed at the Horde outpost of Hammerfall in the Arathi Highlands. Renowned as the premier trauma physician within the Horde, he evaluates aspiring medics seeking to master advanced triage and battlefield first aid. His cold, clinical efficiency keeps frontline warriors stitched together amidst bitter regional conflicts. While many view Forsaken apothecaries with suspicion, Doctor Gregory Victor serves the Horde through practical battlefield surgery rather than blighted alchemy. Stationed deep within the contested Arathi Highlands at Hammerfall, he operates on soldiers battered by Syndicate brigands, Boulderfist ogres, and Alliance forces. His station doubles as the primary proving ground for Horde field medics, demanding ruthless efficiency and prioritizing critical patients under intense pressure.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_doctor-gregory-victor-a9454190b6291ca2fe86/1-0000.mp3", duration = 53.6293878, start = 0},
  },
}
P.transport["npc:doctor-gustaf-vanhowzen"] = {
  hash = "d5a3f6",
  fullHash = "d5a3f6",
  text = "Doctor Gustaf VanHowzen. Doctor Gustaf VanHowzen serves as the trauma surgeon and chief physician of Alliance Trauma in Theramore Isle. Stationed within Foothold Citadel, he trains the island's healers and evaluates medics who wish to master the highest tiers of field triage and bandage work. Located on the ground floor of Foothold Citadel in Theramore Isle, Doctor Gustaf VanHowzen oversees the medical care of Lady Jaina Proudmoore's forces and trains the outpost's frontline healers. Facing harsh conditions in Dustwallow Marsh, VanHowzen insists on rigorous field competence, personally putting experienced medics through an intense triage test to ensure they can prioritize critical wounds under severe pressure.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_doctor-gustaf-vanhowzen-473b14696b2c342af315/1-0000.mp3", duration = 44.0946939, start = 0},
  },
}
P.transport["npc:donova-snowden"] = {
  hash = "25a98e",
  fullHash = "25a98e",
  text = "Donova Snowden. Donova Snowden is an intrepid dwarven researcher encamped alongside the thermal waters near Frostfire Hot Springs in Winterspring. Despite the bitter cold and hostile wildlife, she studies the strange thermal activity of the region and monitors the increasingly corrupted Winterfall furbolgs. While most travelers stick to the safety of Everlook, Donova Snowden has chosen to camp in the freezing wilderness near the Frostfire Hot Springs. She spends her days investigating the curious geothermic anomalies bubbling up through the permafrost, as well as the dark influences encroaching upon Winterspring's native wildlife. Practical and determined, she enlists passing adventurers of both the Alliance and the Horde to gather samples and help curb local threats.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_donova-snowden-316ca84e5b239b444338/1-0000.mp3", duration = 46.7853061, start = 0},
  },
}
P.transport["npc:donyal-tovald"] = {
  hash = "cb3bac",
  fullHash = "cb3bac",
  text = "Donyal Tovald. In Stormwind Keep, Donyal Tovald tends the Royal Library’s historical works. Under an initiative sponsored by young King Anduin Wrynn, he preserves and copies books for wider public use. Donyal Tovald tends the Royal Library’s collection in Stormwind Keep. The library holds historical accounts, scrolls, and scholarly volumes, chiefly for the nobility and royal court. Young King Anduin Wrynn has sponsored an effort to make that knowledge more accessible to ordinary citizens. Tovald preserves and copies the texts, helping keep the Alliance’s lessons and triumphs recorded amid the kingdom’s political troubles.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_donyal-tovald-dde814ac2c56e397c334/1-0000.mp3", duration = 40.2546939, start = 0},
  },
}
P.transport["npc:doomsayer-wiserunner"] = {
  hash = "1b6f7d",
  fullHash = "1b6f7d",
  text = "Seer Wiserunner. This respected tauren elder is known as Seer Wiserunner, serving his people faithfully in the rolling hills of Mulgore. From a cave in the hills northwest of Bloodhoof Village, he aids young tauren braves as they undertake the traditional rites of passage that lead toward spiritual adulthood. Seer Wiserunner stands among the gentle bluffs of Mulgore as an elder and mystic of the shu'halo. When young tauren complete their initial trials of strength and vision, they are sent to seek his counsel during their ancestral rites. He interprets visions of the Earth Mother and guides the youth on how to honor their forebears, offering the steady wisdom that binds the scattered nomadic tribes into a unified community.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_doomsayer-wiserunner-ca47efc50c775b356e50/1-0000.mp3", duration = 41.4563265, start = 0},
  },
}
P.transport["npc:doras"] = {
  hash = "2e3a30",
  fullHash = "2e3a30",
  text = "Doras. Above Orgrimmar, Doras directs the Horde's wind riders across Kalimdor. He oversees the capital's wyverns, sending couriers, scouts, and travelers on their way. Doras tends the wind riders on a wooden platform above the Valley of Strength. The Horde settled in Durotar, and these clever, leathery-winged beasts became its chief means of communication and travel across Kalimdor. Doras pairs resting mounts with riders and sees that important messages and reinforcements reach distant outposts. Their routes reach the Crossroads, Thunder Bluff, and settlements deep in Ashenvale or Dustwallow Marsh.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_doras-27509db4034c49ab03aa/1-0000.mp3", duration = 40.4897959, start = 0},
  },
}
P.transport["npc:doren"] = {
  hash = "cbdfff",
  fullHash = "cbdfff",
  text = "Doren. Lieutenant Doren commands the Rebel Camp nestled in northern Stranglethorn Vale. Once an officer under Colonel Kurzen, Doren led a mutiny after his superior and fellow expeditionaries descended into madness. Now, he directs a guerrilla resistance determined to uncover the source of the affliction and eliminate Kurzen. Lieutenant Doren initially deployed to Stranglethorn Vale under the banner of Stormwind and the command of Colonel Kurzen. The expedition was meant to establish a foothold in the wild southern jungle, but it quickly soured as Kurzen and his inner circle succumbed to an erratic, violent insanity. Refusing to abandon their sanity or their honor, Doren and a cadre of loyalists broke rank. They fled north and carved out the Rebel Camp along the road, choosing defection over servitude to a madman.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_doren-3fe4d5463f80d82c6467/1-0000.mp3", duration = 49.4497959, start = 0},
  },
}
P.transport["npc:drum-fel"] = {
  hash = "184bc3",
  fullHash = "184bc3",
  text = "Drum Fel. Drum Fel is an orc commander stationed at the Horde outpost of Hammerfall in the Arathi Highlands. Alongside his wife, Korin, he directs military efforts to secure the refuge against encroaching trolls, ogres, and human remnants. His strategic push is vital to carving out a lasting foothold for the Horde in Arathi. Situated within the fortified refuge of Hammerfall, Drum Fel oversees the defense and territorial expansion of the Horde in Arathi. Surrounded by rival factions, he coordinates military strikes against the Witherbark forest trolls and the Boulderfist ogre clan holding Boulder'gor and Boulderfist Hall. Drum recognizes that Hammerfall cannot merely survive through isolation; it must break its neighbors' strength to thrive. To that end, he regularly directs veteran champions into hostile territory to disrupt regional threats before they can mount an assault on the Horde encampment.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_drum-fel-42e4744f16f755600f67/1-0000.mp3", duration = 55.6930612, start = 0},
  },
}
P.transport["npc:drusilla-la-salle"] = {
  hash = "86fda9",
  fullHash = "86fda9",
  text = "Drusilla La Salle. Outside Northshire Abbey, Drusilla La Salle teaches warlocks in the graveyard. The human trainer works beyond the Holy Order’s reach, guiding new spellcasters in shadow and summoning. When forbidden knowledge leaves the abbey, she moves to claim it. Drusilla La Salle teaches novice warlocks among the headstones outside Northshire Abbey. Paladins and priests practice beneath the abbey’s stained glass, while warlocks keep to society’s edges because demonology and fel magic are taboo in Stormwind. Recruits receive tainted correspondence before Drusilla shows them how to wield shadow power without drawing the abbey authorities’ immediate anger.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_drusilla-la-salle-d8d5ed62904dba6eb086/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["npc:duke-hydraxis"] = {
  hash = "e3f126",
  fullHash = "e3f126",
  text = "Duke Hydraxis. Duke Hydraxis is a noble water elemental commanding the Hydraxian Waterlords from a remote, wave-battered islet off the coast of Azshara. Pledged to Neptulon the Tidehunter, he rallies mortal adventurers to strike against his ancient elemental rivals, particularly Ragnaros the Firelord. Perched on a solitary rock northeast of the Ravencrest Monument in Azshara, Duke Hydraxis serves as the primary emissary of the Hydraxian Waterlords. While most elementals bound to Azeroth are hostile and chaotic, Hydraxis acts with measured purpose. As a devoted vassal of Neptulon the Tidehunter, he considers water the purest and most essential of the primal forces. He watches the rising turmoil across Azeroth with cold scrutiny, seeking champions capable of shifting the balance of elemental warfare. Hydraxis's central campaign targets the blazing hosts of the Firelord, Ragnaros. He sees the encroachment of fiery elementals as a blight upon the world that must be extinguished. Before bestowing his trust or the tools needed to challenge Ragnaros's fiery stronghold in the Molten Core, Duke Hydraxis demands that mortals prove their strength, resilience, and loyalty by slaying hostile elementals across the continents. Those who prove their worth earn the blessings of the sea and the means to douse the sacred flames guarding the Firelord's domain.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_duke-hydraxis-d05bdcc20944ffb7b816/1-0000.mp3", duration = 81.6587755, start = 0},
  },
}
P.transport["npc:durnan-furcutter"] = {
  hash = "89f92f",
  fullHash = "89f92f",
  text = "Durnan Furcutter. Durnan Furcutter is a dwarven clothier and leather merchant operating out of Anvilmar in Coldridge Valley. Working inside Anvilmar, he equips freshly trained dwarven and gnomish adventurers with lightweight attire suited to withstand the biting mountain chills. Anvilmar serves as the first proving ground for young dwarves and exiled gnomes, and not every warrior steps forth clad in heavy iron. Durnan Furcutter caters to scouts, rogues, and spellcasters who need light, pliable layers to stay agile without succumbing to the bitter winds of Dun Morogh. Positioned right near the hearth of Anvilmar, he sells everyday tailoring and stitched leather, claiming his stock is the finest to be found in the entire valley. Like any true dwarf stationed in the snowy foothills, Durnan appreciates a strong drink almost as much as an honest trade. He orders steaming mugs of Scalding Mornbrew from Nori Pridedrift, who sells the brew piping hot across Coldridge Valley, to fight off the freezing draft. Adventurers running errands in the valley often find themselves rushing a hot mug into his welcoming hands before it cools, then carrying the empty back to Nori.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_durnan-furcutter-1966ad4652a2fe5f8f6b/1-0000.mp3", duration = 68.4146939, start = 0},
  },
}
P.transport["npc:ebru"] = {
  hash = "a86825",
  fullHash = "a86825",
  text = "Ebru. Ebru is a night elf druid sheltering in the crags above the Wailing Caverns. As one of Naralex's few remaining uncorrupted disciples, she watches helplessly as her master's dream of restoring the Barrens curdles into a nightmare. From her perch, she enlists travelers brave enough to enter the subterranean depths to cull the mutated horrors spawned by the Nightmare. While most of Naralex's followers succumbed to the emerald corruption creeping through the caverns, Ebru managed to escape the nightmare's grasp. Camped inside the cavernous skull formation overlooking the entrance to the Wailing Caverns, she keeps vigil over the descent. She knows that Naralex's noble plan—to tap subterranean springs and transform the arid Barrens into lush woodland—has gone horribly awry, and she desperately directs willing adventurers to eliminate the burgeoning deviate beasts threatening to overrun the surrounding plains.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ebru-513fc9ada44b538f008e/1-0000.mp3", duration = 54.9355102, start = 0},
  },
}
P.transport["npc:einar-stonegrip"] = {
  hash = "41bfd5",
  fullHash = "41bfd5",
  text = "Einar Stonegrip. Einar Stonegrip is a dwarven trapper stationed along the main crossroads of the Wetlands. Rather than risk an uncomfortable reunion with his estranged wife in Menethil Harbor, he relies on passing adventurers to haul his crocolisk skins to town. Perched at the central intersection connecting Dun Algaz, Dun Modr, and Menethil Harbor, Einar Stonegrip earns his living braving the sodden marshes of the Wetlands. He hunts the local crocolisks for their sturdy hides, supplying leatherworkers and merchants along the coast. Though rugged enough to wrestle reptiles out of the mire, he is thoroughly cowed by domestic strife. Embroiled in a bitter falling-out with his wife, Sida, Einar stays out on the road, hiring travelers to deliver his bundles of skins to his trading partner James Halloran rather than set foot in Menethil Harbor himself.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_einar-stonegrip-7b6535ea989aaec0d690/1-0000.mp3", duration = 49.1363265, start = 0},
  },
}
P.transport["npc:elanaria"] = {
  hash = "ea60cd",
  fullHash = "ea60cd",
  text = "Elanaria. Elanaria is a night elf warrior mentor and coordinator stationed on the Warrior's Terrace in Darnassus. She directs developing fighters across Kalimdor, testing their mettle against dangerous threats such as the satyr Vorlus Vilehoof and spiritual entities like the Shade of Elura. Her guidance serves as a crucial bridge for Alliance soldiers honing their martial prowess in the night elven capital. Standing proudly on the Warrior's Terrace within the boughs of Darnassus, Elanaria serves as an instructor and point of contact for martial champions. In an era where the night elves have formally aligned with the Grand Alliance, her role extends beyond mentoring local Sentinels to preparing warriors of all backgrounds for the harsh challenges facing their lands. Elanaria does not offer easy praise; she expects discipline, resilience, and proven strength. She assigns seasoned adventurers to strike down formidable adversaries plaguing Teldrassil and Darkshore, including the corrupt satyr Vorlus Vilehoof and troubled spirits like the Shade of Elura. She also liaises with skilled craftsmen like Smith Mathiel to ensure that deserving warriors are properly armed for war.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_elanaria-182ca23a1aa639478631/1-0000.mp3", duration = 71.4971429, start = 0},
  },
}
P.transport["npc:elder-bloodhoof"] = {
  hash = "6b9b07",
  fullHash = "6b9b07",
  text = "Elder Bloodhoof. Elder Bloodhoof is an ancestral spirit found resting just north of Bloodhoof Village in Mulgore. Appearing prominently to travelers during the Lunar Festival, he stands as a revered guardian spirit of the Bloodhoof tribe. Elder Bloodhoof represents the deep spiritual bond the tauren share with their lineage. Manifesting near Bloodhoof Village, this ghostly elder watches over his people and rewards respectful travelers who seek wisdom during the Lunar Festival. His presence reinforces the enduring guidance of deceased chieftains and tribal forebears, whose spirits remain intimately tied to the plains of Mulgore.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_elder-bloodhoof-15648d1c7a2e643a2989/1-0000.mp3", duration = 37.0155102, start = 0},
  },
}
P.transport["npc:elder-bronzebeard"] = {
  hash = "f6f0e2",
  fullHash = "f6f0e2",
  text = "Elder Bronzebeard. Elder Bronzebeard is an ancient spirit of the earthen who appears in the Mystic Ward of Ironforge during the Lunar Festival. Bearing the name of the clan that rules the city, his spectral presence serves as a bridge between modern dwarves and their stony stone-hewn ancestors. Appearing near the pool in Ironforge's Mystic Ward, Elder Bronzebeard does not wear the flesh of modern dwarves; instead, his ghostly form is that of an earthen, the ancient race forged from living stone by the Titans. Dwarven scholars and explorers are only beginning to uncover their origins through excavations across Khaz Modan and beyond, making this spirit's presence a striking living relic. His very name and visage suggest he is a direct ancestor of the Bronzebeard clan, standing silent witness to how far his stoneborn progeny have evolved.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_elder-bronzebeard-888aa76a89f9f4d8235e/1-0000.mp3", duration = 53.002449, start = 0},
  },
}
P.transport["npc:elder-darkcore"] = {
  hash = "2569e3",
  fullHash = "2569e3",
  text = "Elder Darkcore. Elder Darkcore is an ancient spirit who appears during the Lunar Festival within the throne room of the Ruins of Lordaeron above the Undercity. Representing the honored ancestors of the world, he offers his blessing and festive tokens to travelers who seek him out. His presence marks a peaceful, reflective moment amidst the ruins of a fallen human kingdom. During the annual Lunar Festival, the spirits of ancient elders manifest across Azeroth to share their wisdom with adventurers. Elder Darkcore takes his vigil in one of the world's most somber locations: the royal throne room in the Ruins of Lordaeron, directly above the entrance to the Undercity. Surrounded by the blood-stained floor where King Terenas Menethil II fell, this spectral ancestor offers a Coin of Ancestry and his blessing to those brave enough to enter the heart of Forsaken territory to pay their respects.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_elder-darkcore-7611de4118379f33cdcc/1-0000.mp3", duration = 53.3159184, start = 0},
  },
}
P.transport["npc:elder-goldwell"] = {
  hash = "709afc",
  fullHash = "709afc",
  text = "Elder Goldwell. Elder Goldwell is an ancient earthen spirit lingering near the dwarven settlement of Kharanos in Dun Morogh. Appearing during the Lunar Festival, this revered ancestor represents the forgotten origins of modern dwarven civilization. Elder Goldwell manifests as a translucent earthen spirit, watching over the snowy slopes of Kharanos. Unlike modern mortal dwarves of flesh and bone, his stony form echoes the ancient Titan-forged race from which the Bronzebeard clan descended. His presence during ancestor celebrations offers travelers a chance to honor that ancient heritage.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_elder-goldwell-2e95eabf0ed9d26d304a/1-0000.mp3", duration = 35.1608163, start = 0},
  },
}
P.transport["npc:elder-graveborn"] = {
  hash = "d53ea7",
  fullHash = "d53ea7",
  text = "Elder Graveborn. Elder Graveborn is an ancestral spirit who manifests just southeast of Brill during the Lunar Festival. Appearing as a spectral earthen elder, he honors travelers and guides pilgrims searching for other ancient spirits scattered throughout northern Lordaeron. Appearing just beyond the Forsaken town of Brill, Elder Graveborn stands among the haunted woods of Tirisfal Glades as part of the worldwide Lunar Festival. Despite the blighted surroundings and the troubled state of the kingdom, the spectral elder offers peaceful greetings to travelers seeking the festival's traditional blessings. In addition to bestowing his own ancestral wisdom, Graveborn shares news of other elders lingering nearby—pointing pilgrims toward spirits abiding in the Undercity, the Sepulcher, and across the Plaguelands.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_elder-graveborn-4418c6353e71687585f8/1-0000.mp3", duration = 46.315102, start = 0},
  },
}
P.transport["npc:elder-morningdew"] = {
  hash = "f64ffe",
  fullHash = "f64ffe",
  text = "Elder Morningdew. Elder Morningdew is an ancient night elf spirit who appears during the Lunar Festival in Thousand Needles. She offers wisdom and ancestral blessings to travelers who seek her out amid the arid canyons and dried salt flats of the Shimmering Flats. Throughout the Lunar Festival, the spirits of revered ancestors manifest across Kalimdor and the Eastern Kingdoms to celebrate wisdom, legacy, and peace. Elder Morningdew is one such apparition, visiting Thousand Needles to greet honoring pilgrims. Bound by neither faction nor mortal conflict, she bestows her coin of ancestry upon any adventurer respectful enough to seek her counsel and receive her blessing.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_elder-morningdew-426b3c2aa0e5b069986e/1-0000.mp3", duration = 39.7583673, start = 0},
  },
}
P.transport["npc:elder-obsidian"] = {
  hash = "6ae753",
  fullHash = "6ae753",
  text = "Elder Obsidian. Elder Obsidian is an ancestral earthen spirit who manifests at the Sepulcher in Silverpine Forest during the annual Lunar Festival. Appearing among the graves claimed by the Forsaken, he offers the wisdom and blessings of the ancient world to travelers honoring the festival. Standing amid the somber tombs of the Sepulcher, Elder Obsidian provides a striking contrast to Silverpine Forest's gloomy expanse. As an ethereal earthen elder, his spirit manifests during the Lunar Festival to celebrate the ancient heritage of Azeroth. While the surrounding crypts are held by the Forsaken and menaced by feral worgen, Obsidian greets wayfarers of all allegiances in peace, bestowing Coin of Ancestry and ancient blessings upon those who take the time to seek out his wisdom.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_elder-obsidian-f8ddcaad83fe16f98277/1-0000.mp3", duration = 47.882449, start = 0},
  },
}
P.transport["npc:elder-runetotem"] = {
  hash = "1c0024",
  fullHash = "1c0024",
  text = "Elder Runetotem. During the Lunar Festival, Elder Runetotem appears outside Razor Hill in Durotar. The tauren spirit offers wisdom and a blessing to travelers who seek her. Elder Runetotem appears beside Razor Hill, far from the grassy plains and sacred burial grounds of Mulgore. Her presence brings the ancient traditions of the Shu'halo to the Horde's home along the Great Sea. During the Lunar Festival, spirits of great leaders, shamans, and heroes appear throughout the world to commune with the living. Elder Runetotem carries the name of a line that reveres the Earth Mother and seeks spiritual communion. Travelers who honor her receive ancestral tokens and her blessing.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_elder-runetotem-183dd9d5371773d8cc20/1-0000.mp3", duration = 42.3444898, start = 0},
  },
}
P.transport["npc:elder-skyseer"] = {
  hash = "e8d7d9",
  fullHash = "e8d7d9",
  text = "Elder Skyseer. Elder Skyseer is the spirit of an ancestral tauren residing atop the towering bluffs of Freewind Post in Thousand Needles. As an honoured elder returned from the spirit world, he observes the ongoing journeys of the Horde and remains deeply tied to the resting grounds of his people. Perched high above the salt canyons of Thousand Needles, Elder Skyseer lingers at the windswept mesa settlement of Freewind Post. While the tauren of Freewind Post bustle around the outpost's perilous bridges and wooden platforms, Skyseer watches over the realm as an ancestor who has crossed beyond the mortal veil. He serves as an ancestral beacon for travelers seeking the wisdom of past generations, offering his blessings to those who honor old traditions. Though his spirit commonly manifests among the wind-carved needles, Skyseer belongs to the long line of tauren ancestors whose people honor the sacred soil of Mulgore, where the ancestral spirits of Red Rocks watch over the tribes. Spirits like Skyseer reveal how thin the veil between the physical realm and the ancestral spirits remains for the tauren, guiding future generations through remembrance and ritual.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_elder-skyseer-3b6e0d847c2cb7a991f0/1-0000.mp3", duration = 68.7804082, start = 0},
  },
}
P.transport["npc:elder-starweave"] = {
  hash = "342384",
  fullHash = "342384",
  text = "Elder Starweave. During the Lunar Festival, Elder Starweave rests in Auberdine as a night elf ancestral spirit. She shares ancient wisdom with pilgrims along Darkshore’s coast. In Auberdine, Elder Starweave appears as an ethereal shade among the coastal dwellings. The Cenarion Circle and the peoples of Kalimdor honor her as an ancestor. Travelers pass through the port on their way inland or across the sea, but those who pause before her receive an ancestral blessing. She speaks of the stars, whose paths in this age differ from those of old, and sees them as beacons of hope and fortitude for generations to come.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_elder-starweave-d06cf9eba0ea03ae0eeb/1-0000.mp3", duration = 38.8179592, start = 0},
  },
}
P.transport["npc:eleanor-shackleton"] = {
  hash = "b289de",
  fullHash = "b289de",
  text = "Eleanor Shackleton. Eleanor Shackleton is a Forsaken outdoorswoman found camping southwest of Brill in Tirisfal Glades. Rather than lingering within town or the Undercity, she assists wandering travelers in learning wilderness survival and field crafts. She shares her surname with other Forsaken surviving in the region, suggesting lingering ties from life before the plague. While many newly awakened Forsaken head straight to Brill or delve into the Undercity, Eleanor Shackleton makes her camp in the haunted woods to the southwest. Surviving out in Tirisfal requires pragmatic self-reliance, and Eleanor serves as an instructor for fledgling adventurers seeking to live off the blighted land. Through her various field lessons, she guides travelers in establishing campsites, gathering firewood, and maintaining trade crafts while roaming far from civilization's forge fires and kitchens. In the shattered remnants of Lordaeron, family names often serve as the sole surviving tether to an undead's mortal past. Eleanor carries the surname Shackleton, shared by Pierce Shackleton and Samantha Shackleton in the Undercity's Magic Quarter. Whether the three maintain close bonds or merely carry common ancestry from their mortal days, each has carved out a distinct role in serving the Forsaken cause across the blighted kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_eleanor-shackleton-24a1f824b4a220620527/1-0000.mp3", duration = 77.557551, start = 0},
  },
}
P.transport["npc:elu"] = {
  hash = "c286b2",
  fullHash = "c286b2",
  text = "Elu. Elu is an apprentice wind rider stationed atop Freewind Post in Thousand Needles. Eager to begin his formal training and take to the skies, he tasks Horde travelers with retrieving wild wyvern eggs from nearby roosts. Perched high above the salt flats and canyon floor at Freewind Post, Elu spends his days tending to the settlement's aerial mounts while dreaming of his own flight. As a young tauren apprentice, he longs to join the ranks of the master wind riders who patrol the towering mesas of Kalimdor. Before he can begin true flight training, however, he must prove his capability by supplying the roost with fresh wyvern stock, sending capable adventurers to harvest intact eggs from the fierce wild wyverns nesting at Highperch.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_elu-e38abbffce10f3b964b3/1-0000.mp3", duration = 44.0946939, start = 0},
  },
}
P.transport["npc:eva-sarkhoff"] = {
  hash = "bce57c",
  fullHash = "bce57c",
  text = "Eva Sarkhoff. Eva Sarkhoff is the spectral remnant of the former head maid of House Barov, lingering alongside her husband Lucien just outside the horrors of Scholomance. Tortured and slain by the Butcher during the fall of Caer Darrow, her spirit seeks brave mortals to avenge their deaths and destroy their cursed remains. Eva served the wealthy Barov family for decades as their head maid, caring for the sprawling keep of Caer Darrow alongside her husband Lucien, the family butler. As the Barovs grew paranoid about their aging mortality and vast wealth, they struck a catastrophic pact with Kel'Thuzad. The manor was gradually handed over to the fledgling Cult of the Damned, warping the grand residence into Scholomance, a secretive academy of necromancy. Eva and Lucien hid in the keep's corridors for six months, scavenging food while watching cultists and monstrosities steadily take over their home.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_eva-sarkhoff-567adbfffa0af34e42e6/1-0000.mp3", duration = 53.8383673, start = 0},
  },
}
P.transport["npc:falfindel-waywarder"] = {
  hash = "8c77c7",
  fullHash = "8c77c7",
  text = "Falfindel Waywarder. Falfindel Waywarder is a night elf druid stationed at Thalanaar, the outpost guarding the border between Feralas and the Thousand Needles. From this frontier watchpost, he works to heal corrupted lands and safeguard the southern wilderness of Kalimdor. Travelers wandering down from Stonetalon or the Barrens often find him seeking aid to restore balance to the wild. Thalanaar marks the gateway where the lush forests of Feralas descend into the towering mesas and dry salt plains of Thousand Needles. Falfindel Waywarder stands watch at this remote outpost, greeting weary travelers who have ventured far across the continent. Surrounded by natural grandeur and lurking dangers, he serves as a point of contact for the night elves seeking to monitor both local threats and broader environmental calamities across Kalimdor. Despite his southern post, Falfindel remains deeply concerned with the devastation far to the north in Stonetalon Mountains. The Charred Vale, ruined by dark sorcery and fiery destruction, stands as a painful scar upon Kalimdor's wilderness. When adventurers deliver aid to Falfindel to assist in its recovery, he calls upon the spirits of the forest. Summoning forth swarms of wisps, he directs them to make haste north to Stonetalon to begin mending the scorched earth. In addition to coordinating restoration efforts, Falfindel keeps a close watch on the surrounding region, including the quilboar dens of Razorfen Kraul. By reviewing recovered journals and gathering intelligence on quilboar leadership, Falfindel ensures that the Alliance understands the rising dangers threatening the passes between Feralas and the central deserts.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_falfindel-waywarder-5db54f6f706a820dfced/1-0000.mp3", duration = 102.19102, start = 0},
  },
}
P.transport["npc:falla-sagewind"] = {
  hash = "73b0a3",
  fullHash = "73b0a3",
  text = "Falla Sagewind. Falla Sagewind is a reclusive tauren mystic perched high upon a rocky peak overlooking the central Barrens. Stationed between the Crossroads and the Lushwater Oasis, she studies the natural and mystical anomalies troubling the surrounding land. Adventurers probing the twisted corruption seeping from the nearby Wailing Caverns often seek her guidance. Falla Sagewind makes her camp far above the dust and bustle of the Barrens trails, situated on a secluded summit just southwest of the Crossroads. From this vantage, she keeps a solemn watch over the fragile savannas below, observing the sudden shifts in wildlife behavior and the encroaching corruption rising from the subterranean fissures of the Wailing Caverns. Her solitary vigil separates her from the daily trade of the Crossroads, positioning her as an observant hermit tuned to the spirits and the land's silent wounds.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_falla-sagewind-20dcf67f21a1882ba36f/1-0000.mp3", duration = 53.4726531, start = 0},
  },
}
P.transport["npc:fallen-hero-of-the-horde"] = {
  hash = "dd927c",
  fullHash = "dd927c",
  text = "Fallen Hero of the Horde. The Fallen Hero of the Horde is the lingering spirit of an orc warrior standing watch on the southern road out of the Swamp of Sorrows. Bound by regret and dishonor, he warns passing travelers of the horrors awaiting them in the Blasted Lands and seeks champions willing to deliver his tortured soldiers from demonic bondage. In life, this warrior was a celebrated champion dispatched with a handpicked regiment of soldiers to investigate the Blasted Lands and report back on the presence of the Burning Legion. His dispatch never made it; the courier sent north toward Stonard was ambushed and slain by the Swamp Talker and his murlocs. Stranded without orders or reinforcements, the commander eventually marched his soldiers south into the shattered wastes to confront the growing darkness. It was a fatal misjudgment. Overwhelmed by demonic forces, his army was scattered, captured, and subjected to horrific torment at the hands of the dreadlord Razelikh the Defiler.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_fallen-hero-of-the-horde-d7b9e3c0e5e69a75c015/1-0000.mp3", duration = 59.8204082, start = 0},
  },
}
P.transport["npc:farmer-furlbrow"] = {
  hash = "fb1950",
  fullHash = "fb1950",
  text = "Farmer Furlbrow. Near the Jansen Stead, Farmer Furlbrow and his wife are stranded beside their broken wagon. Driven from their northern Westfall farm by the Defias Brotherhood, they hope to reach Elwynn Forest. Theodore Furlbrow left his pumpkin patch in northern Westfall with his wife, Verna, as criminals drove them from their home. They salvaged what they could and set out for Elwynn Forest, urging neighbors such as Farmer Saldean to leave too. Near the Jansen Stead, their wagon broke down, leaving them exposed to bandits and wild beasts. Verna tends to their horse, Old Blanchy, while Theodore keeps watch over the road. He hopes to recover the pocket watch Verna's father gave him on their wedding day and warn Sentinel Hill about the approaching bandits.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_farmer-furlbrow-054c4b8e610c202ba594/1-0000.mp3", duration = 45.6097959, start = 0},
  },
}
P.transport["npc:farmer-saldean"] = {
  hash = "77324a",
  fullHash = "77324a",
  text = "Farmer Saldean. At Saldean's Farm in central Westfall, Farmer Saldean keeps working the troubled fields beside his wife, Salma. While other farmers flee or give up, the veteran homesteader faces rogue harvest golems and growing banditry. Farmer Saldean remembers when Westfall prospered, before those years crumbled away. Overgrown fields, rampaging mechanical harvest watchers, and predatory bandits now surround his farm, but he refuses to yield his land. Other homesteaders have abandoned their acres or turned to thievery. Saldean and his wife, Salma, stay and work to harvest what little grain they can. He asks wandering adventurers to destroy the rogue Harvest Watchers that have taken over his fields and his neighbors' fields, so he can clear the soil for planting. Between Sentinel Hill and the northern bridge, Saldean's defense of his homestead helps keep civilian life going. He remains tied to the People's Militia despite the hard times, and sends able-bodied travelers to Gryan Stoutmantle once his immediate troubles are settled. Clearing the wild harvest reapers can only give his farm a temporary reprieve. The lawlessness strangling the countryside still has to be dealt with.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_farmer-saldean-d60cf31b87d6acf07fef/1-0000.mp3", duration = 71.7583673, start = 0},
  },
}
P.transport["npc:feegly-the-exiled"] = {
  hash = "8eed25",
  fullHash = "8eed25",
  text = "Feegly the Exiled. Near the Bael Modan excavation in the southern Barrens, Feegly the Exiled lurks alone. Once praised as one of the expedition’s finest diggers, he was driven off by General Twinbraid after claiming an uncovered relic’s power as his own.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_feegly-the-exiled-3910644387298b39e0d6/1-0000.mp3", duration = 16.1959184, start = 0},
  },
}
P.transport["npc:feero-ironhand"] = {
  hash = "a5bf2e",
  fullHash = "a5bf2e",
  text = "Feero Ironhand. Feero Ironhand is a human paladin stationed at Maestra's Post in the western reaches of Ashenvale. Standing guard along the border between Darkshore and the forest, he works closely with Delgren the Purifier to combat the shadowy Cult of the Dark Strand. Located along the road leading south from Darkshore into Ashenvale, Maestra's Post serves as a critical watchpoint for travelers and Alliance defenders alike. Feero Ironhand operates out of this outpost, maintaining communications and trade lines with Auberdine while keeping a vigilant watch over the surrounding woods. Together with Delgren the Purifier, Feero focuses his efforts against the malevolent Cult of the Dark Strand, ensuring the cultists and forest predators do not sever the path between Darnassus's supply lines and the front lines of Ashenvale.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_feero-ironhand-40b3f00de39068055f5b/1-0000.mp3", duration = 50.7820408, start = 0},
  },
}
P.transport["npc:fel-zerul"] = {
  hash = "a689c8",
  fullHash = "a689c8",
  text = "Fel'zerul. Fel'zerul is an orc warlock stationed at Stonard in the murky depths of the Swamp of Sorrows. Acting under direct orders from Warchief Thrall, he investigates the ominous presence lurking within the sunken Temple of Atal'Hakkar. While Thrall's Horde generally views dark arts with suspicion, the Warchief recognizes that understanding sinister powers requires those who study them. Fel'zerul was dispatched to Stonard specifically to unravel the corruption surrounding the Pool of Tears and the submerged Temple of Atal'Hakkar. By directing adventurers to recover artifacts and investigate the exiled Atal'ai trolls, the warlock seeks to determine what evil stirs beneath the murky waters before it threatens the Horde's southern outpost.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_fel-zerul-45c66edaeb0399c35eea/1-0000.mp3", duration = 44.8261224, start = 0},
  },
}
P.transport["npc:felgur-twocuts"] = {
  hash = "d3e48a",
  fullHash = "d3e48a",
  text = "Felgur Twocuts. Felgur Twocuts is a blunt orc scout stationed at Ghost Walker Post in Desolace. He coordinates Horde efforts against the regional centaur clans. Standing watch amid the bleak expanse of Ghost Walker Post in central Desolace, Felgur Twocuts has little patience for pleasantries. As a forward scout for the Horde, he assesses the threats facing travelers and settlers venturing west through the mountains, particularly the local Kolkar centaur. Felgur directs Horde champions to cull the local centaur chieftains and collect bounties on the warring tribes who threaten to overrun the region. He is a central contact for anyone seeking to secure the Horde's foothold in Desolace.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_felgur-twocuts-95a45b2bf1fb04614424/1-0000.mp3", duration = 41.4563265, start = 0},
  },
}
P.transport["npc:felix-whindlebolt"] = {
  hash = "ee02bb",
  fullHash = "ee02bb",
  text = "Felix Whindlebolt. Felix Whindlebolt is a displaced gnome refugee taking shelter at Anvilmar in Coldridge Valley. In his haste to flee the radiation flooding Gnomeregan, he lost his personal belongings, and hostile Frostmane trolls made off with them. Following the tragic fall of Gnomeregan, thousands of gnomes found themselves wandering the freezing reaches of Dun Morogh in search of safety. Felix Whindlebolt fled the irradiated city in such haste that he lost all his personal belongings and tools. To make matters worse, Frostmane ice trolls carried his chest, his box and his bucket of bolts back to their camps southwest of Anvilmar, leaving him stranded, destitute, and relying on sympathetic wanderers to retrieve his stolen gear.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_felix-whindlebolt-a1d9d8f7c734062ee384/1-0000.mp3", duration = 44.8783673, start = 0},
  },
}
P.transport["npc:field-marshal-snowfall"] = {
  hash = "cbb2f1",
  fullHash = "cbb2f1",
  text = "Field Marshal Snowfall. Field Marshal Snowfall is a dwarven military officer stationed in Ironforge's Military Ward to coordinate the Alliance war effort against the rising silithid threat. Facing an ancient evil stirring in the southern sands of Silithus, he oversees the massive logistical drive required to equip the allied armies. Snowfall tracks donated raw materials and rewards those who aid the realm's preparation for war. Standing watch in Ironforge's Military Ward, Field Marshal Snowfall serves as the central coordinator for the Alliance's mobilization against Ahn'Qiraj. He views the brewing conflict not merely as a border skirmish, but as a critical fight against an ancient enemy hostile to all creations of the Titans. Snowfall oversees staggering stockpiles of supplies—millions of bandages, tons of metal bars, leathers, herbs, and rations gathered by adventurers—ensuring that Alliance forces will be armed, armored, and fed when the march south to Silithus begins. Mobilizing an entire faction requires coordination between blacksmiths, gathers, cooks, and soldiers across every Alliance territory. Snowfall monitors each stage of this immense operation, accepting commendation signets and offering supply requisitions to volunteers. Once the required war supplies are fully gathered across both factions, the stockpiles are packed and hauled south to Cenarion Hold, readying the grand assault against the insectoid swarms and the Old God lurking behind the Scarab Wall.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_field-marshal-snowfall-2559805a9e6b69c6c692/1-0000.mp3", duration = 95.1640816, start = 0},
  },
}
P.transport["npc:field-marshal-stonebridge"] = {
  hash = "08d9d0",
  fullHash = "08d9d0",
  text = "Field Marshal Stonebridge. At Stormwind's gates, Field Marshal Stonebridge helps oversee the city's defenses with General Marcus Jonathan. She also receives reports and trophies from major victories. Field Marshal Stonebridge watches the eastern archway at the entrance to the Valley of Heroes, beside Stormwind's main gates. A senior officer in the Grand Alliance, she works closely with General Marcus Jonathan. From the gate, she watches defenders, travelers, and returning champions enter the capital, ready to organize the garrison if danger breaches the outer defenses. Field Marshal Stonebridge also receives reports and spoils from campaigns against great threats to the kingdom. Senior commanders rely on officers like her to confirm important intelligence and mark victories in the field, including the defeat of warlords and monsters in the crags of Blackrock Mountain.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_field-marshal-stonebridge-a49f7ac200efeae099d4/1-0000.mp3", duration = 51.5918367, start = 0},
  },
}
P.transport["npc:fizzle-brassbolts"] = {
  hash = "451446",
  fullHash = "451446",
  text = "Fizzle Brassbolts. Fizzle Brassbolts is a prominent gnomish engineer stationed out on the baked salt flats of the Mirage Raceway in Thousand Needles. Alongside his rival, the goblin Pozzik, Fizzle co-founded the raceway to pit gnomish precision engineering against reckless goblin ingenuity in high-speed rocket car races. He constantly seeks parts, fuel, and strange desert reagents to keep his racing team running. Out in the shimmering heat of the Shimmering Flats, political alliances and ancient grudges yield to the roar of motorized engines. Fizzle Brassbolts arrived here with one goal in mind: proving once and for all that gnomish craftsmanship is vastly superior to crude goblin tinkering. Together with his goblin counterpart Pozzik, he helped lay out the Mirage Raceway, bringing race cars, pit crews, and spectators to an otherwise desolate basin. Racing across dry salt beds at breakneck speeds requires constant improvisation, and Fizzle does not shy away from unorthodox experiments. Whether testing volatile mixtures concocted from local creature venom or contracting travelers to fetch replacement mechanical parts, Fizzle is determined to keep his driver's wheels turning faster than any explosive goblin contraption.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_fizzle-brassbolts-864f1ca45e2ef64a46e1/1-0000.mp3", duration = 75.5983673, start = 0},
  },
}
P.transport["npc:fleet-master-seahorn"] = {
  hash = "d326c8",
  fullHash = "d326c8",
  text = "Fleet Master Seahorn. Fleet Master Seahorn is a seasoned tauren mariner who serves as the naval commander of the Blackwater Raiders in Booty Bay. Stationed on the upper balcony of the Salty Sailor Tavern alongside Baron Revilgaz, he oversees the goblin port's maritime defenses. His primary duty is protecting the harbor from the looming threat posed by their sworn enemies, the Bloodsail Buccaneers. While tauren are renowned across Kalimdor as plains-dwellers, Fleet Master Seahorn chose a vastly different life upon the ocean. Clad in pirate regalia, he commands the fleet of the Blackwater Raiders, the private naval arm of the Steamwheedle Cartel's operation in Stranglethorn Vale. Stationed atop the Salty Sailor Tavern, Seahorn works shoulder-to-shoulder with Baron Revilgaz, coordinating shipping routes, crew deployments, and coastal defenses for the lawless yet strictly managed port of Booty Bay. Beyond repelling pirate raids, Seahorn manages varied commercial and salvage ventures across the Eastern Kingdoms. He coordinates recovery efforts for lost sunken treasures off the Arathi coast near Faldir's Cove, working with salvage divers to secure elven relics. He also keeps Revilgaz informed of lucrative opportunities passing through town, such as competitive angling and local trade, ensuring the Blackwater fleet stays well-funded and ahead of rival operations.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_fleet-master-seahorn-24aedf6040e2cec86d12/1-0000.mp3", duration = 83.2522449, start = 0},
  },
}
P.transport["npc:foggy-mackreel"] = {
  hash = "df43b3",
  fullHash = "df43b3",
  text = "Foggy MacKreel. Foggy MacKreel is an intrepid dwarf stranded precariously on the ruined lower masonry of the Thandol Span. Despite the shattered stonework beneath his feet and the dizzying drop below, his only real concern is fulfilling his moonshine delivery north to Southshore. Perched on the broken pylons beneath the shattered Thandol Span, Foggy MacKreel appears utterly unfazed by his perilous predicament. While Dark Iron sabotage and war damage have left the grand bridge between the Wetlands and the Arathi Highlands fractured, MacKreel treats his precarious footing as a minor inconvenience. His primary thought is not his rescue, but an undelivered batch of potent moonshine destined for the patrons of Southshore in the Hillsbrad Foothills. He readily hires passing adventurers nimble enough to reach his ledge to finish the courier run on his behalf.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_foggy-mackreel-4489592cd5f76ad280bb/1-0000.mp3", duration = 50.9387755, start = 0},
  },
}
P.transport["npc:foreman-stonebrow"] = {
  hash = "842e6b",
  fullHash = "842e6b",
  text = "Foreman Stonebrow. Foreman Stonebrow is a dwarven overseer representing the Miners' League at Gol'Bolar Quarry in eastern Dun Morogh. After aggressive troggs erupted from the rock and overran the excavation site, he was forced to organize a defense and hire adventurers to clear the pits. Foreman Stonebrow was charged with directing operations at Gol'Bolar Quarry, a key dwarven excavation nestled in the mountains east of Kharanos. When deep digging broke into hidden trogg burrows, subterranean beasts swarmed the pits and drove the miners from their equipment. Refusing to abandon the site entirely, Stonebrow remains at the rim of the quarry to enlist any able-bodied travelers willing to push the troggs back.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_foreman-stonebrow-a6c86823346870b3f104/1-0000.mp3", duration = 41.6130612, start = 0},
  },
}
P.transport["npc:foreman-thazz-ril"] = {
  hash = "2ae147",
  fullHash = "2ae147",
  text = "Foreman Thazz'ril. Peons work under Foreman Thazz'ril in the Valley of Trials. The orc labor supervisor keeps crews on schedule and supplies ready for young warriors, but slacking workers and nearby cultists frustrate him. In the Valley of Trials, Foreman Thazz'ril directs peons who chop lumber and gather materials for the encampment and young warriors. Building a home in Durotar's harsh red rock takes steady labor, yet the peons often nap under the desert sun. Thazz'ril sends newly arrived recruits to rouse the sleepers with his blackjack, and keep construction moving. While scouting the Burning Blade Coven for mineral resources, Thazz'ril fled the dark cultists inside and accidentally left his treasured enchanted pick behind. Warlocks and their demonic minions now gather in the cave. Too cautious to retrieve the tool himself, Thazz'ril relies on young Horde aspirants to venture into the depths and bring it back.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_foreman-thazz-ril-b9e45635f4402d4edb16/1-0000.mp3", duration = 56.5028571, start = 0},
  },
}
P.transport["npc:foreman-thistlenettle"] = {
  hash = "a4919d",
  fullHash = "a4919d",
  text = "Foreman Thistlenettle. In the Deadmines, Foreman Thistlenettle once led a dwarven mining crew. He worked for both the Miners' League and the Explorers' League until a cave-in trapped his crew below Moonbrook. He died with them and rose again as a ghoul, still carrying his guild badge through the dark, collapsed tunnels.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_foreman-thistlenettle-cd321060c3982d52d8a2/1-0000.mp3", duration = 17.5542857, start = 0},
  },
}
P.transport["npc:frahun-shadewhisper"] = {
  hash = "b44388",
  fullHash = "b44388",
  text = "Frahun Shadewhisper. At Aldrassil in Shadowglen, Frahun Shadewhisper trains night elf rogues. He teaches new scouts and rogues stealth, agility, and covert strikes. Erion Shadewhisper, another rogue trainer in Darnassus, shares his family name. At Aldrassil in Teldrassil, Frahun Shadewhisper teaches new rogues concealment and bladecraft. Night elf society honors priests, sentinels, and druids, yet scouts and infiltrators also help safeguard the World Tree's boughs. Recruits bring Frahun an encrypted sigil. He weighs their potential and guides their first steps in the craft.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_frahun-shadewhisper-d6375cde4a90be0da114/1-0000.mp3", duration = 36.1012245, start = 0},
  },
}
P.transport["npc:furl-scornbrow"] = {
  hash = "01977c",
  fullHash = "01977c",
  text = "Furl Scornbrow. At a watchtower northwest of Razor Hill, Furl Scornbrow keeps watch over Durotar. Too old for the front lines, he crafts sturdy packs for young travelers. Furl Scornbrow watches the central plains from a wooden tower northwest of Razor Hill. In the tense days after Orgrimmar was founded, sentries like Furl sounded signal horns against hostile quilboar, centaur, and Kul Tiras interlopers. Durotar has since grown more stable, and Razor Hill has secured its borders. Emergencies come less often, leaving Furl long quiet hours at his post. Furl says his old bones and fading strength leave him unable to fight. Still, an orc does not easily surrender their purpose. He uses his hands to make canvas sacks and packs for fresh recruits carrying supplies. In exchange for coarse thread and practical materials, he equips green adventurers setting out to prove their worth to the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_furl-scornbrow-3e92cec613609ea07776/1-0000.mp3", duration = 57.7828571, start = 0},
  },
}
P.transport["npc:gaerolas-talvethren"] = {
  hash = "ae6fce",
  fullHash = "ae6fce",
  text = "Gaerolas Talvethren. At Starbreeze Village, Gaerolas Talvethren guards the Sleeping druids in troubled Teldrassil. He seeks aid against aggressive furbolgs and corruption spreading through the boughs. Gaerolas Talvethren guards the Sleeping druids at Starbreeze Village. They slumber in communion with the Emerald Dream, and his watch has grown uneasy as unnatural corruption spreads through the forest and unsettles Teldrassil. Gaerolas calls on travelers to push back the Gnarlpine furbolgs, whose minds have turned to madness and savagery. He hopes to uncover the taint spreading from their shamans and the roots of their distress, preserving what sanctity remains in eastern Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gaerolas-talvethren-34245d5d8d71fc31ccf3/1-0000.mp3", duration = 40.4897959, start = 0},
  },
}
P.transport["npc:galgar"] = {
  hash = "a388ae",
  fullHash = "a388ae",
  text = "Galgar. Near the Den in the Valley of Trials, Galgar feeds young recruits serving the Horde. He asks newcomers to gather wild cactus apples for his Cactus Apple Surprise. Galgar cooks near the Den's fire in the Valley of Trials, feeding young orcs and trolls through their first rites of passage. Durotar is a dry, harsh red wasteland, where food must be found across the land. Galgar sends novice warriors to gather ripe cactus fruit, testing their attention and resilience while stocking his kitchen. Galgar's specialty is called Cactus Apple Surprise. He says gathering spiny desert fruit is a simple task meant to ease fresh recruits into adventuring. The dish still feeds hungry trainees. Every Horde warrior begins somewhere, and Galgar starts them with foraging in the desert.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_galgar-cd919c45fcfaac8501b6/1-0000.mp3", duration = 48.2481633, start = 0},
  },
}
P.transport["npc:gar-thok"] = {
  hash = "098c2b",
  fullHash = "098c2b",
  text = "Gar'Thok. At Razor Hill, Gar'Thok directs recruits leaving the Valley of Trials to secure Durotar. The veteran orc warrior survived the Kul Tiras landings on Durotar's coast and now coordinates defense against human encroachers and native threats. After the Third War, Gar'Thok marched to Durotar under Warchief Thrall and served as a lieutenant under Nazgrel during the first days of building the new homeland. When Rexxar, the half-ogre wanderer, arrived in Durotar, Gar'Thok warned him that quilboar were raiding the settlement's perimeter. He enlisted the beastmaster to protect the fragile new settlement. Gar'Thok's resolve was tested when Grand Admiral Daelin Proudmoore's Kul Tiras fleet landed on Durotar's eastern shores. At an outlying watch post, Gar'Thok saw naval marines overwhelm and slaughter his garrison. His forces were decimated, but he survived. The surprise assault left him vigilant against the surviving marines, who still occupy Tiragarde Keep and the coastal shipwrecks. From the barracks at Razor Hill, Gar'Thok oversees the defense of central Durotar. He quickly sends emerging Horde warriors, shamans, and scouts to drive out hostile Kul Tiran remnants, repossess salvaged supplies, and recover military orders left in the coastal ruins. Durotar's safety is far from assured, and Gar'Thok keeps pressure on those who challenge the Horde's right to this soil.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gar-thok-d3f38179a7ceedda95a5/1-0000.mp3", duration = 89.2342857, start = 0},
  },
}
P.transport["npc:gart-mistrunner"] = {
  hash = "030610",
  fullHash = "030610",
  text = "Gart Mistrunner. Gart Mistrunner is the resident druid trainer stationed at Camp Narache on the Red Cloud Mesa. He welcomes novice tauren called by the Earth Mother and guides them through their first rites of nature magic. Standing watch over Camp Narache, Gart Mistrunner represents the ancient druidic path rekindled among the Shu'halo. New tauren druids are directed straight to Gart upon taking their first steps on the Red Cloud Mesa, often carrying a verdant note commending them into his care. Through his patient guidance, young practitioners learn to commune with the natural world, drawing upon the restorative powers of nature and the lunar radiance of Mu'sha to heal their allies and strike down threats to the land.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gart-mistrunner-ed9da69bd3757fc5af10/1-0000.mp3", duration = 41.482449, start = 0},
  },
}
P.transport["npc:gath-ilzogg"] = {
  hash = "3c7d87",
  fullHash = "3c7d87",
  text = "Gath'Ilzogg. Gath'Ilzogg is the fearsome Blackrock orc warlord who commands the invasion force occupying Stonewatch Keep in the Redridge Mountains. Under his brutal leadership, the orcs seized the fortress and launched devastating raids against the town of Lakeshire, earning him an urgent bounty from the town's desperate magistrate. Gath'Ilzogg marched north out of the Burning Steppes under orders to secure Redridge for the Blackrock clan. Aided by the foul sorcery of the renegade human warlock Morganth, Gath'Ilzogg's warband battered the defenders of Stonewatch Keep and seized the high ground overlooking the entire region. From this entrenched redoubt, he oversees aggressive raids into the valleys and down toward the bridge of Lakeshire, steadily suffocating the human settlement. He rarely fights alone, keeping elite Blackrock guards and a vicious black dragon whelp named Singe close at hand.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gath-ilzogg-76e39c748c9e9750ab81/1-0000.mp3", duration = 55.8497959, start = 0},
  },
}
P.transport["npc:gazin-tenorm"] = {
  hash = "b735c8",
  fullHash = "b735c8",
  text = "Gazin Tenorm. In Stormwind's Cathedral of Light, Gazin Tenorm keeps watch near the altar after a dangerous scouting mission in Elwynn Forest. Gazin Tenorm stays in the Cathedral of Light, though his thoughts remain in Elwynn Forest. He and his close friend Henze Faulk went into the woods to gather proof of the Defias Brotherhood's movements for the royal court. Defias forces ambushed them. Gazin escaped to Stormwind, but Henze was left in mortal danger. Now Gazin seeks a hero of the Light to help his companion.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gazin-tenorm-626c674895ed14b6f60a/1-0000.mp3", duration = 31.5297959, start = 0},
  },
}
P.transport["npc:gelkak-gyromast"] = {
  hash = "123266",
  fullHash = "123266",
  text = "Gelkak Gyromast. Along Mist's Edge in northern Darkshore, Gelkak Gyromast is stranded after threshadons sank his ship. The gnome talks like a pirate captain and wants his mechanical first mate, the Threshwackonator 4100, working again. West of the Ruins of Mathystra, Gelkak Gyromast is stranded on Darkshore's northern coast. The gnome talks like an old sea dog and calls himself captain. Threshadons sank his ship just offshore, and he washed up on the misty shore. The key to his mechanical first mate, the Threshwackonator 4100, broke on the rocks. Crawlers, foreststriders and murlocs rummaging through the wreckage carried off its pieces.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gelkak-gyromast-98d7ccbb6ce76b109ab7/1-0000.mp3", duration = 42.0832653, start = 0},
  },
}
P.transport["npc:general-marcus-jonathan"] = {
  hash = "24bbff",
  fullHash = "24bbff",
  text = "General Marcus Jonathan. General Marcus Jonathan is the High Commander of Stormwind Defense, stationed directly at the gates in the Valley of Heroes. A veteran of the Second War, he oversees the garrison protecting the capital and manages military requests from the kingdom's frontier settlements. Mounted atop his steed in the Valley of Heroes, General Marcus Jonathan stands as the first line of defense and the highest-ranking military officer overseeing the city gates. He fought in the Second War alongside renowned soldiers like Reginald Windsor under the command of General Turalyon. In this era of rising tension, Jonathan must balance the immediate security of the capital with the increasingly desperate calls for aid from frontier towns like Lakeshire.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_general-marcus-jonathan-9b97d134b3156b10ffc4/1-0000.mp3", duration = 43.0759184, start = 0},
  },
}
P.transport["npc:gerard-tiller"] = {
  hash = "bab578",
  fullHash = "bab578",
  text = "Gerard Tiller. At the Maclure Vineyards, Gerard Tiller works under the warm sun and longs for spring water. He offers a shiny red apple to any traveler who brings him a skin of it. Gerard Tiller works the grounds outside the barn at the Maclure Vineyards, south of Goldshire. The vineyard is known for its grapes, and keeping the harvest going takes hard labor. The chores leave Gerard thirsty, so he welcomes travelers who bring him a skin of fresh spring water. In return, he gives them shiny red apples gathered from local orchards.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gerard-tiller-b2c937c64ca9b8f10948/1-0000.mp3", duration = 33.1232653, start = 0},
  },
}
P.transport["npc:gerrig-bonegrip"] = {
  hash = "4021d7",
  fullHash = "4021d7",
  text = "Gerrig Bonegrip. Gerrig Bonegrip is an unassuming dwarven shopkeeper tucked away in the shadowy corridors of Ironforge's Forlorn Cavern. Behind the counter of Bonegrip's Runes and Dooms, he quietly buys and sells esoteric texts concerning dark rituals and forgotten ancient powers.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gerrig-bonegrip-03c4e0c75fc861e9c8a3/1-0000.mp3", duration = 17.4759184, start = 0},
  },
}
P.transport["npc:gershala-nightwhisper"] = {
  hash = "e71371",
  fullHash = "e71371",
  text = "Gershala Nightwhisper. Gershala Nightwhisper is a night elf researcher residing in the coastal settlement of Auberdine in Darkshore. Driven by grave concern over the path taken by the high elves of Quel'Thalas, he studies specimens of cursed aquatic and demonic creatures to understand how magical corruption warps both mind and body. Stationed peacefully within Auberdine, Gershala Nightwhisper looks beyond the immediate coastal troubles of Darkshore toward a broader, creeping danger. Watching with dismay as the remaining high elves embrace perilous arcane practices and dub themselves blood elves, Gershala seeks to understand the biological and spiritual descent that follows unchecked magic. To unlock these secrets, he directs seasoned Alliance adventurers into the submerged halls of Blackfathom Deeps to harvest corrupted brain stems from the naga and satyr who dwell within. Gershala's grim focus on brain stems from naga and satyr stems from their shared lineage: both races were once night elves before yielding to Queen Azshara and demonic bargains. By dissecting the physical marks left upon their nervous systems by millennia of demonic and abyssal energies, he hopes to uncover warnings or safeguards that might keep other elven kin from plunging into similar monstrous deformity.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gershala-nightwhisper-31190327ae618737a44b/1-0000.mp3", duration = 76.4865306, start = 0},
  },
}
P.transport["npc:gilshalan-windwalker"] = {
  hash = "5baf98",
  fullHash = "5baf98",
  text = "Gilshalan Windwalker. At Aldrassil's roots in Shadowglen, Gilshalan Windwalker studies the corruption spreading through Teldrassil. His work begins with the Webwood spiders and their growing aggression. Gilshalan Windwalker watches Shadowglen from the stone steps at Aldrassil's entrance. Teldrassil was planted to restore the night elves' lost sanctuary and their harmony with nature, yet signs of spiritual malaise appeared almost at once. Gilshalan studies how the corruption affects the local beasts, beginning with the venomous spiders weaving webs nearby. Gilshalan studies the Webwood spiders in Shadowthread Cave, north of Shadowglen. Once part of the forest's balance, the spiders have grown hostile and tainted. He sends young novices to gather venom sacs and intact eggs. By studying them, he hopes to learn how the venom has changed and whether the corruption passes through generations or spreads from Teldrassil's soil.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gilshalan-windwalker-ba4851a9b8ed7fb21eae/1-0000.mp3", duration = 57.6783673, start = 0},
  },
}
P.transport["npc:gilthares-firebough"] = {
  hash = "0b5118",
  fullHash = "0b5118",
  text = "Gilthares Firebough. Gilthares Firebough waits in a tower at Northwatch Hold, held captive by Theramore. Once a deckhand on a moonshine transport between Ratchet and Booty Bay, he seeks a chance to escape. Gilthares Firebough is held in a tower at Northwatch Hold. His ship carried illicit cargo between Ratchet and Booty Bay when naval forces from Theramore blasted it to splinters. The sole survivor, Gilthares was dragged ashore in chains and locked away. He wears vivid red and bears little affection for the Alliance zealots who slaughtered his crew. Still, he cares little who helps him break free, so long as they can fight their way down from the ramparts.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gilthares-firebough-e43e6999010b8183d3d8/1-0000.mp3", duration = 40.1763265, start = 0},
  },
}
P.transport["npc:gnoarn"] = {
  hash = "98ea2d",
  fullHash = "98ea2d",
  text = "Gnoarn. Gnoarn is an exiled gnome residing in Tinker Town within the dwarven mountain city of Ironforge. Displaced following the devastating fall of Gnomeregan, he assists his scattered people by directing adventurers to assist fellow gnomish engineers and survivors. Like the majority of his brethren, Gnoarn was forced to flee the depths of Gnomeregan when troggs invaded and catastrophic radiation rendered the great subterranean metropolis uninhabitable. Taking refuge in Ironforge's Tinker Town under the hospitality of the Bronzebeard dwarves, Gnoarn spends his days keeping track of other survivors. He serves as an informal coordinator among the refugees, pointing capable travelers toward gnomes abroad who urgently require assistance, such as the stranded pilot Bingles Blastenheimer in Loch Modan or the ambitious engineer Shoni the Shilent in Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gnoarn-d6144fcf79e3c9d7ecf9/1-0000.mp3", duration = 51.6440816, start = 0},
  },
}
P.transport["npc:godrick-farsan"] = {
  hash = "f40989",
  fullHash = "f40989",
  text = "Godrick Farsan. Godrick Farsan is an undead warlock assistant located in the Undercity, serving alongside Carendin Halgar in the Magic Quarter. Despite being entirely blind, he says that he sees in a different way. Situated amidst the summoning circles of the Magic Quarter, Godrick Farsan aids Master Carendin Halgar in guiding aspiring Forsaken warlocks. Though he lacks physical sight, Godrick says he can still see in a different way, without explaining the means. He tests practitioners seeking to bind greater demonic entities, dispatching them to gather pure hearts and essences needed for intricate summoning rituals.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_godrick-farsan-6e0dbdaa6606a09553fb/1-0000.mp3", duration = 36.1534694, start = 0},
  },
}
P.transport["npc:golnir-bouldertoe"] = {
  hash = "68a56d",
  fullHash = "68a56d",
  text = "Golnir Bouldertoe. Golnir Bouldertoe is a dwarven mining vendor stationed beside the bustling Great Forge in Ironforge. He provides essential supplies for miners and prospectors while handling dispatches for local couriers and travelers. Standing within the roaring heat of Ironforge's Great Forge, Golnir Bouldertoe outfits prospectors and craftsmen with the necessities of their trade. From sturdy mining picks to fluxes and coal, his wares fuel the tireless smelting fires and smithies that define the dwarven capital. Kin to Geofram Bouldertoe, Golnir is a reliable point of contact for workers arriving in the city, often directing fresh hands or receiving supply missives shuttled in from nearby outposts.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_golnir-bouldertoe-3fbf65963cf6681ea35f/1-0000.mp3", duration = 43.0497959, start = 0},
  },
}
P.transport["npc:gorbold-steelhand"] = {
  hash = "e4bec2",
  fullHash = "e4bec2",
  text = "Gorbold Steelhand. In Auberdine, Gorbold Steelhand keeps trade moving along Darkshore’s coast. The dwarven merchant brings goods from far across the Great Sea for travelers, crafters, and night elves. Gorbold Steelhand brings Ironforge trade to Auberdine. Night elves populate much of northern Kalimdor, so Alliance outposts depend on merchants who cross the Great Sea. Gorbold works alongside the kaldorei, selling trade goods, reagents, crafting supplies, and tools. Travelers come to him as they prepare to explore Darkshore’s dangerous shores and forests. Gorbold Steelhand watches the perilous waters off Auberdine as closely as his stock. Reefs along Darkshore have swallowed Alliance vessels, and lost cargo draws the merchant’s interest. Travelers who dive into the deep ocean may find him eager to hear about salvage and lost logs from sunken wrecks.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gorbold-steelhand-ee22431e27c90f455652/1-0000.mp3", duration = 52.48, start = 0},
  },
}
P.transport["npc:gordon-wendham"] = {
  hash = "3f26c9",
  fullHash = "3f26c9",
  text = "Gordon Wendham. Gordon Wendham is a Forsaken weaponsmith and merchant operating out of the bustling Trade Quarter in the Undercity. He equips newly arrived champions and local defenders of the Dark Lady with reliable steel, blades, and bludgeons. Beyond hawking basic armaments, he frequently serves as a local point of contact for couriers arriving from the surface. Situated amidst the damp stonework and chemical canals of the Undercity's Trade Quarter, Gordon Wendham provides essential weaponry to those taking up arms for the Forsaken. From basic daggers and hand axes to sturdy broadswords and maces, his stock caters to fledgling fighters who need dependable iron before venturing out into the contested reaches of Lordaeron. Beyond his merchant trade, Wendham is integrated into the capital's busy logistics network. Travelers sent on errands from flight masters and couriers—such as those connecting from the bat handlers atop the ruins—are often directed straight to his stall. His central location in the Trade Quarter makes him an accessible and recognizable fixture for coordinating basic supplies and dispatches throughout the underground city.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gordon-wendham-056c973b74ab6c53db92/1-0000.mp3", duration = 68.9632653, start = 0},
  },
}
P.transport["npc:gramma-stonefield"] = {
  hash = "97f6f6",
  fullHash = "97f6f6",
  text = "Gramma Stonefield. At the Stonefield farm in Elwynn, Gramma Stonefield quietly works to ease a family feud. Gramma Stonefield has watched the Stonefields and the Maclures bicker for decades across the road. The oldest living member of the Stonefield clan, she sees their rivalry as senseless and harmful. When her grandson Tommy Joe Stonefield falls in love with Maybell Maclure, Gramma chooses compassion over clan loyalty. She turns to her old friend William Pestle in Goldshire and quietly plans ways for the sweethearts to meet in secret, despite the hostility between their farms.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gramma-stonefield-b657090387af89778788/1-0000.mp3", duration = 36.2579592, start = 0},
  },
}
P.transport["npc:grand-mason-marblesten"] = {
  hash = "aed91d",
  fullHash = "aed91d",
  text = "Grand Mason Marblesten. Grand Mason Marblesten is an esteemed dwarven stonemason stationed in the busy Commons of Ironforge. Deeply devoted to the royal legacy of Khaz Modan, he has been commissioned by King Magni Bronzebeard to build a memorial to Sully Balloo, a dwarven soldier who died in the Thandol Span tragedy. Adventurers often meet him when assisting with the materials needed to complete this solemn tribute. Dwarven stonemasonry is not merely a trade; it is an enduring art form that shapes the very soul of Ironforge. Grand Mason Marblesten stands among the city's foremost masters of the chisel, representing the centuries-old tradition of carving halls, pillars, and great effigies straight from the living mountain. Based in the Commons, he oversees civic projects and commemorative monuments that immortalize Bronzebeard history. Marblesten's most poignant task is a memorial King Magni commissioned for Sully Balloo, a soldier who died in the Thandol Span tragedy, as a tribute to his grieving widow. Wanting a truly lasting piece, the Grand Mason insists on one of the finest stones available: Alterac Granite from Darrow Hill in Hillsbrad.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_grand-mason-marblesten-8ff2d21aa4f1de658c2b/1-0000.mp3", duration = 70.1387755, start = 0},
  },
}
P.transport["npc:granis-swiftaxe"] = {
  hash = "a7c20d",
  fullHash = "a7c20d",
  text = "Granis Swiftaxe. Granis Swiftaxe is a dwarf warrior trainer stationed inside the Thunderbrew Distillery in Kharanos. Known for his blunt demeanor and hardy training regimen, he mentors fledgling Alliance fighters emerging from Coldridge Pass before directing seasoned warriors to the city of Ironforge. Found warming himself among the casks of the Thunderbrew Distillery, Granis Swiftaxe serves as the primary combat instructor for young warriors traversing Dun Morogh. He possesses the unyielding pride typical of dwarven fighters, showing open amusement and disdain toward non-warriors who try to catch his ear. Once a student demonstrates sufficient prowess in combat, Granis sends them up the mountain path to seek out master trainer Muren Stormpike in the Military Ward of Ironforge.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_granis-swiftaxe-f51e6169e18c4b15f9f4/1-0000.mp3", duration = 44.8522449, start = 0},
  },
}
P.transport["npc:great-father-winter"] = {
  hash = "721480",
  fullHash = "721480",
  text = "Great-father Winter. In Orgrimmar, Great-father Winter hears children's wishes during the Feast of Winter Veil. Hired by Smokywood Pastures, he brings holiday cheer near Grommash Hold in the Valley of Strength, though the work wears on him. Greatfather Winter in the Valley of Strength is an orc performer hired by the Smokywood Pastures merchant company. Ancient lore tells of a majestic elemental spirit who wanders the land, bringing snow and seasonal renewal, but the figure in Orgrimmar promotes company wares and entertains Horde children. Some critics say the commercial mascot cheapens genuine seasonal traditions. Still, few deny the festive excitement he brings to the city streets. Greatfather Winter works outside Grommash Hold, beneath decorated evergreens. Children climb onto his lap to tell him what gifts they want, while he promotes Smokywood Pastures discounts and offers holiday greetings. The long shift wears him down. He admits he keeps festive spirits in his pack to quiet the noise when work ends, and visiting adventurers bring him snacks to help him endure.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_great-father-winter-d2079b645ed891d9857d/1-0000.mp3", duration = 65.9069388, start = 0},
  },
}
P.transport["npc:greatfather-winter"] = {
  hash = "c70f31",
  fullHash = "c70f31",
  text = "Greatfather Winter. Greatfather Winter is the legendary personification of the winter season and the central figure of the Feast of Winter Veil. While ancient legends revere him as a mythical being who blankets Azeroth in snow to allow the land to rest and renew, modern city-dwellers know him primarily through the commercial spectacle managed by the goblins of Smokywood Pastures. According to ancient lore, Greatfather Winter is an ethereal wanderer who walks the world late in the year, casting his billowing snowy cloak across the land so nature may slumber and be reborn. Dwarves view him as an embodiment or herald of the titans, pointing to the frosted crags of Dun Morogh as living proof of his favor. Other traditions, such as those of the tauren, respect his role in the season's turning while attributing the cold and storms to the elemental work of the Sun and Moon, giving the Earth Mother time to rest. Wherever the legend traveled, communities learned to gather and feast together against the cold, celebrating the promise of returning life. In major settlements like Ironforge and Orgrimmar, the ancient spirit has been thoroughly reshaped by the enterprising goblins of Smokywood Pastures. The trading cartel popularized the depiction of Greatfather Winter as a jolly, red-suited elder with a white beard who rides a flying sleigh and hands out holiday treats and toys. Smokywood Pastures hires local actors—a dwarf in Ironforge and an orc in Orgrimmar—to listen to children's wishlists, receive offerings of milk and gingerbread cookies, and advertise seasonal merchandise beneath lavishly decorated trees.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_greatfather-winter-07f40eec49aad387621d/1-0000.mp3", duration = 94.7722449, start = 0},
  },
}
P.transport["npc:greatmother-hawkwind"] = {
  hash = "57e771",
  fullHash = "57e771",
  text = "Greatmother Hawkwind. Greatmother Hawkwind is a revered tauren elder resting by the water well on Red Cloud Mesa. As the mother of Camp Narache's leader, Chief Hawkwind, she embodies the enduring spirit and communal responsibility of the tribe despite her advanced age. Greatmother Hawkwind spends her days beside the fresh water well at Camp Narache, serving as the spiritual matriarch for young tauren beginning their rites of passage. Though years have slowed her stride, she refuses to let age sideline her duty to the village. She believes that every member of the tribe, young or old, has an active role to play in sustaining the community, often asking fledgling youths to lend a hand with simple domestic chores like fetching fresh water. As the mother of Chief Hawkwind, the chieftain of Camp Narache, Greatmother Hawkwind provides steady counsel and quiet dignity amidst the threats facing Red Cloud Mesa. While her son organizes hunters and warriors against encroaching Bristleback quilboar and local predators, she tends to the moral heart of the settlement, reminding the newly awakened that strength begins with humility and service to one's kin.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_greatmother-hawkwind-32e2b88987b45522cf12/1-0000.mp3", duration = 69.9559184, start = 0},
  },
}
P.transport["npc:greta-mosshoof"] = {
  hash = "29e3e4",
  fullHash = "29e3e4",
  text = "Greta Mosshoof. Greta Mosshoof is a tauren druid allied with the Emerald Circle at the Emerald Sanctuary in southern Felwood. Alongside night elves and fellow guardians of nature, she investigates the foul taint creeping across the ancient forest and directs scouts into the Shadow Council stronghold of Jaedenar. Stationed at the Emerald Sanctuary on the southern boundary of Felwood, Greta Mosshoof works alongside the Emerald Circle to combat the pervasive corruption consuming the ancient woods. Rather than surrendering the blighted lands to the demonic taint left in the wake of the Third War, she coordinates efforts to understand and push back the spreading rot. Her investigations zero in on the poisoned waters of Felwood and the foul cultists burrowed within Jaedenar.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_greta-mosshoof-98f3626cbd40b4e9ae58/1-0000.mp3", duration = 45.0612245, start = 0},
  },
}
P.transport["npc:grimbooze-thunderbrew"] = {
  hash = "5fb38b",
  fullHash = "5fb38b",
  text = "Grimbooze Thunderbrew. In Westfall's Dagger Hills, Grimbooze Thunderbrew brews potent spirits and speaks in verse. The eccentric dwarf belongs to the Thunderbrew clan. Grimbooze Thunderbrew camps in the Dagger Hills, where he tends his private casks. He comes from the Thunderbrew brewing family of Kharanos and left the snowy peaks of Dun Morogh for Westfall's windswept hills. Jovial and devoted to potent spirits, he speaks only in rhymes. A traveler must complete a simple task before he answers any questions, and he is always ready to test a thirsty palate.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_grimbooze-thunderbrew-c01ebaec15a1e9937b2b/1-0000.mp3", duration = 33.6195918, start = 0},
  },
}
P.transport["npc:grish-longrunner"] = {
  hash = "b2ec74",
  fullHash = "b2ec74",
  text = "Grish Longrunner. At the Great Lift, Grish Longrunner watches the boundary between the southern Barrens and Thousand Needles. The tauren scout carries messages for the Horde and tracks movement across the crossing. Grish Longrunner keeps watch beside the Great Lift in the southern Barrens. Its platform connects the dry southern Barrens with the canyons of Thousand Needles. Quilboar packs roam nearby, and rival groups threaten the crossing. Grish watches travelers and keeps the Horde informed, so reinforcements can be called where they are needed.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_grish-longrunner-a24ac40a83efdb2907e6/1-0000.mp3", duration = 32.1828571, start = 0},
  },
}
P.transport["npc:grub"] = {
  hash = "50bc07",
  fullHash = "50bc07",
  text = "Grub. At a hut east of the Crossroads, Grub runs a roadside eatery with a cook and a baker. He is known for teaching travelers to cook with the Barrens' local vermin. East of the Crossroads, Grub shares a hut with Duhng, his cook, and Tarban Hearthgrain, a baker. Grub makes use of the Barrens' dig rats instead of letting them go to waste. He offers travelers a recipe for simmering the rodents into stew.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_grub-1b73527559ab6757ac7c/1-0000.mp3", duration = 24.5812245, start = 0},
  },
}
P.transport["npc:grull-hawkwind"] = {
  hash = "856cdf",
  fullHash = "856cdf",
  text = "Grull Hawkwind. Grull Hawkwind is a young tauren brave stationed at Camp Narache on the Red Cloud Mesa in Mulgore. As the son of Chief Hawkwind, he helps guide novice tauren taking their very first steps into the world. He directs young hunters and warriors through their earliest trials to test their resolve and honor their ancestors. Standing proudly beside the braves and elders of Camp Narache, Grull Hawkwind bears both the proud lineage of Chief Hawkwind and the responsibility of preparing the tribe's youth. He serves as an initial mentor for new arrivals on the Red Cloud Mesa, assessing their readiness to serve the Shu'halo. By assigning trials that test stamina, tracking, and survival against local beasts such as plainstriders and mountain cougars, Grull ensures that young tauren understand that balance and respect for nature are foundational to life in Mulgore.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_grull-hawkwind-83619a3656106917de20/1-0000.mp3", duration = 51.2, start = 0},
  },
}
P.transport["npc:grunt-dogran"] = {
  hash = "505d20",
  fullHash = "505d20",
  text = "Grunt Dogran. Grunt Dogran waits in captivity deep in the southern Barrens. Once assigned to the Crossroads and then Camp Taurajo, he was taken during a patrol into Agama'gor. Grunt Dogran was sent from the Crossroads to reinforce Camp Taurajo after rising in the Horde military. He led a detachment of grunts into Agama'gor, where they met the Bristleback quilboar in a fierce clash. Dogran was badly wounded and crippled. His comrades retreated without him, and the quilboar dragged him into captivity.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_grunt-dogran-4124dc8b8bd707883dfa/1-0000.mp3", duration = 30.5893878, start = 0},
  },
}
P.transport["npc:grunt-logmar"] = {
  hash = "3f9daf",
  fullHash = "3f9daf",
  text = "Grunt Logmar. Grunt Logmar is an orc warrior of the Horde stationed in the southern Barrens at Camp Taurajo. Dutiful and vigilant, he monitors threats surrounding the camp and coordinates efforts to locate and aid missing Horde scouts in the region. Stationed among the tauren at Camp Taurajo, Grunt Logmar serves as a watchful orc guard on the southern Barrens frontier. The settlement sits close to hostile quilboar grounds and the mountain passes leading into Stonetalon and Mulgore, requiring constant vigilance. Logmar coordinates scouting reports and reaches out to capable Horde travelers when his comrades find themselves ambushed or captured by local hostiles.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_grunt-logmar-15182566cfa37e221612/1-0000.mp3", duration = 38.3477551, start = 0},
  },
}
P.transport["npc:grunth"] = {
  hash = "76a724",
  fullHash = "76a724",
  text = "Grunth. In Orgrimmar, Grunth eagerly seeks the company of Horde champions. The young orc lives in the Drag orphanage and, during Children's Week, journeys across Kalimdor and the Eastern Kingdoms to learn what it means to be a hero. Grunth is a young orc orphan in the Drag of Orgrimmar, where Orphan Matron Battlewail cares for him. Raised in Durotar's harsh red wastes, he watches armored adventurers with awe and asks them questions without end. Are armored warriors truly terrifying? Why does lightning on water not kill every fish? Will he ever see someone fight an actual dragon? During Children's Week, an Orcish Orphan Whistle summons Grunth to travel with adventurers on a tour across the world. He wants to meet High Chieftain Cairne Bloodhoof in Mulgore, see the ruined throne room of Lordaeron, and visit the rugged frontiers where his people fight for their future.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_grunth-66bfe6d1574d5d67a373/1-0000.mp3", duration = 54.7265306, start = 0},
  },
}
P.transport["npc:guard-berton"] = {
  hash = "2cc8ac",
  fullHash = "2cc8ac",
  text = "Guard Berton. Guard Berton is a human town guardsman stationed outside the Lakeshire Inn in Redridge Mountains. Frustrated by the bureaucratic delays of Stormwind's legal system, he seeks swift justice against Targorr the Dread, an imprisoned orc leader. While Redridge Mountains buckles under the threat of the Blackrock orc invasion, Guard Berton remains posted outside the Lakeshire Inn. Despite local defenses being pushed to the brink, Berton's attention is fixed on a captive enemy: Targorr the Dread. Targorr was captured and locked away deep within the Stormwind Stockade, sentenced to death for his crimes against the kingdom. Yet with Stormwind's execution postponed indefinitely, Berton refuses to let the brutal raider linger in a cell while Lakeshire bleeds. Taking matters into his own hands, he hires willing adventurers to bypass royal delays and execute the orc directly.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_guard-berton-b39ada116aabf340c4a4/1-0000.mp3", duration = 52.9240816, start = 0},
  },
}
P.transport["npc:guard-howe"] = {
  hash = "e13124",
  fullHash = "e13124",
  text = "Guard Howe. Guard Howe is a town guardsman stationed near the southern foot of the Lakeshire bridge in the Redridge Mountains. Driven by a personal vendetta against the Blackrock orcs encroaching on the valley, he offers bounties to any adventurer willing to cut down the invaders. Positioned just south of the large stone bridge spanning Lake Everstill, Guard Howe stands watch over the heart of Lakeshire. Like many in the beleaguered town, he sees the encroaching Blackrock orcs as an existential threat to Redridge. Harbouring a bitter desire for revenge against the clan, Howe actively recruits passing mercenaries to hunt orcs in the eastern hills, offering pay in exchange for tangible proof of their defeat.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_guard-howe-a4aaf500ad5d436e8a08/1-0000.mp3", duration = 41.8742857, start = 0},
  },
}
P.transport["npc:gubber-blump"] = {
  hash = "0547c0",
  fullHash = "0547c0",
  text = "Gubber Blump. Along Auberdine’s shore, Gubber Blump fishes, teaches angling, and looks for fresh crab meat. Gubber Blump fishes on the Darkshore coast, between Auberdine’s flight master and ferry pier. While most dwarves favor stone halls or forges, he chooses the shore. He teaches fishing and sells simple angling gear to travelers. Crab meat is among his favorite foods, and he often relies on travelers to bring in catches from the dangerous coast or recover his family fishing tackle. Gubber Blump speaks freely about his family, especially his cousin Graun Blump, who has a beard and an unusual odor. Travelers who help with coastal work, such as gathering crawler legs or finding his family pole, may receive a handwritten thank-you letter and a shiny fishing lure for their next cast.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gubber-blump-9df6897ced04245c8456/1-0000.mp3", duration = 47.5428571, start = 0},
  },
}
P.transport["npc:gurda-ragescar"] = {
  hash = "7efb2e",
  fullHash = "7efb2e",
  text = "Gurda Ragescar. Gurda Ragescar was an orc stationed at a small Horde outpost southwest of Splintertree Post in Ashenvale. Alongside Feran Strongwind, she fell defending their camp against local perils in the shadowed forest. Resting just southwest of the fortified walls of Splintertree Post, Gurda Ragescar maintained a modest Horde camp under the dense canopy of Ashenvale. Deep within territory contested by night elven defenders and wild beasts, maintaining such isolated positions is perilous work. Gurda, along with Feran Strongwind and their detachment of guards, was ultimately overrun and killed at their post, leaving only the remnants of their final stand for passing allies to discover. Travelers wandering near the trail may come across the tragic scene of Gurda's defeat. Even in death, the possessions and tasks carried by her encampment offer clues to Horde endeavors across the woods, including missing documents and orders disrupted by the ambush.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gurda-ragescar-84d6e6da473d459fb05b/1-0000.mp3", duration = 58.0963265, start = 0},
  },
}
P.transport["npc:hagar-lightninghoof"] = {
  hash = "81cad4",
  fullHash = "81cad4",
  text = "Hagar Lightninghoof. Hagar Lightninghoof is a tauren scout stationed high atop Freewind Post in Thousand Needles. Driven by rumors of a strange clutch hidden in the canyon depths, he investigates reports of an alien egg guarded fiercely by local wind serpents. While stationed among the towering bluffs of Freewind Post, Hagar Lightninghoof caught wind of rumors regarding an unnatural egg nestled deep inside a cavern below. The local wind serpents guarded the nest with unusual ferocity, keeping curious scouts at bay. Seeking an adventurer bold enough to brave the serpents' den, Hagar hopes to study the specimen firsthand and discern what manner of beast could warrant such defensive instincts from the canyon's natural predators.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_hagar-lightninghoof-de16ae175e4fd8fa03e7/1-0000.mp3", duration = 42.3967347, start = 0},
  },
}
P.transport["npc:halaan-hawk-eye"] = {
  hash = "5a2ba9",
  fullHash = "5a2ba9",
  text = "Halaan Hawk-Eye. Halaan Hawk-Eye is a Skyborne lookout stationed atop the watchtower of Thendal Village on Zephras Isle. Lacking both magical sensitivity and the mystic skysight of his peers, he relies instead on keen mundane vision to monitor the surrounding island. From his perch, he tracks the distant anchor pylons and warns visitors of their faltering arcane stability. Perched high above Thendal Village, Halaan Hawk-Eye serves his people without the gifts common to many Skyborne. He cannot draw upon the arcane power flowing through the ley lines beneath Zephras Isle, nor can he gaze between worlds through the mystical skysight. Instead, Halaan relies entirely on his sharp natural senses. From his vantage point on the watchtower, he scans the horizon to observe the island's anchor pylons, calling attention to their increasingly volatile and inconsistent arcane energies.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_halaan-hawk-eye-3212c38b17007b6ec07d/1-0000.mp3", duration = 52.8195918, start = 0},
  },
}
P.transport["npc:hana-zua"] = {
  hash = "15cd87",
  fullHash = "15cd87",
  text = "Hana'zua. In the Valley of Trials, Hana'zua lies wounded after meeting Sarkoth on the canyon ridges. The Darkspear scout waits for help from young Horde initiates. Hana'zua lies wounded on the ridges above the Valley of Trials. The Darkspear scout met Sarkoth, a vicious scorpid that stalks the cliffs, and its venomous sting nearly killed him. Unable to move or make his way back to camp, he waits in the dust for passing recruits. He needs them to kill Sarkoth and carry word of his plight to the Den.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_hana-zua-de8999282098eb7ec814/1-0000.mp3", duration = 28.6040816, start = 0},
  },
}
P.transport["npc:hands-springsprocket"] = {
  hash = "7fc7e3",
  fullHash = "7fc7e3",
  text = "Hands Springsprocket. Hands Springsprocket is an industrious gnome stationed at the entrance of Coldridge Pass in Dun Morogh. He coordinates shipments between the secluded training grounds of Coldridge Valley and the town of Kharanos, though recent trogg incursions have severely hampered his efforts. Perched at the mouth of Coldridge Pass, Hands Springsprocket finds his regular supply runs thoroughly disrupted. He routinely delivers provisions to the Thunderbrew distillery and the inn in Kharanos, but hostile Rockjaw troggs have overrun the subterranean tunnel leading out of the valley. With trade and foot traffic halted by the beasts, Hands is forced to rely on capable travelers to carry essential crates through the dangerous mountain corridor.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_hands-springsprocket-a351aba8b22c52bbaa5e/1-0000.mp3", duration = 42.1355102, start = 0},
  },
}
P.transport["npc:hansel-heavyhands"] = {
  hash = "b00036",
  fullHash = "b00036",
  text = "Hansel Heavyhands. Hansel Heavyhands is an unusually massive Dark Iron dwarf stationed with the Thorium Brotherhood atop Thorium Point in the Searing Gorge. Tasked with perilous field work by the outpost's overseers, he consistently delegates dangerous jobs to passing adventurers using a colorful array of petty physical complaints. His hulking frame stands out among his kin, even if his enthusiasm for fieldwork does not match his size. Even by the broad-shouldered standards of the Dark Iron clan, Hansel Heavyhands is an anomaly. Towering over his brethren with a massive frame that borders on orcish in width and height, his sheer physical presence suggests a warrior built for frontline slaughter. Yet despite his imposing build and formidable moniker, Hansel appears utterly uninterested in unnecessary physical exertion, preferring the relative security of the Thorium Brotherhood's camp high above the volcanic ash. Taskmaster Scrange and Master Smith Burninate frequently assign Hansel the grim chore of culling the fiery beasts lurking in the slag pits below. When told to clear out the predatory Incendosaurs crawling through the Cauldron, Hansel begs off citing sore feet. When ordered to exterminate the Greater Lava Spiders infesting the searing wastes, he claims the blasted volcanic ridge is afflicted with a 'frigid climate' that has given him a miserable cold. Consequently, any mercenary willing to brave the magma flows finds Hansel ready with an open contract.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_hansel-heavyhands-f235cf550cd10486e51b/1-0000.mp3", duration = 89.3387755, start = 0},
  },
}
P.transport["npc:harb-clawhoof"] = {
  hash = "62223d",
  fullHash = "62223d",
  text = "Harb Clawhoof. Harb Clawhoof is a tauren mount breeder stationed just outside Bloodhoof Village in Mulgore. He tends to the tribe's sturdy kodos, offering them to worthy tauren riders and trusted champions of Thunder Bluff. Situated near the pens of Bloodhoof Village, Harb Clawhoof spends his days tending the massive kodo beasts that serve as the backbone of tauren travel and labor. Built to carry immense weight across vast distances, these sturdy animals are essential to life on the plains. Harb ensures each beast is well-cared for, disciplined, and matched only with riders who command the respect of the tauren people. While tauren naturally earn the trust required to ride Harb's kodos, outsiders face stricter scrutiny. Due to their immense size and temperament, kodos are not easily guided by those unfamiliar with their nature. Non-tauren allies who wish to ride away atop one of Harb's prized mounts must first prove their loyalty and earn exalted status with Thunder Bluff.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_harb-clawhoof-e01f6e7712f1b6e07dc5/1-0000.mp3", duration = 59.8465306, start = 0},
  },
}
P.transport["npc:harken-windtotem"] = {
  hash = "5035a6",
  fullHash = "5035a6",
  text = "Harken Windtotem. Harken Windtotem is a tauren huntsman residing in Bloodhoof Village in Mulgore. Dedicated to the traditions of his people, he tasks young hunters and travelers with proving their tracking and foraging skills across the golden plains. Situated near the heart of Bloodhoof Village, Harken Windtotem serves as an instructor and guide for those learning the hunting ways of the tauren. Life on the plains of Mulgore demands respect for the natural world alongside the practical skill to sustain one's tribe. Harken evaluates young adventurers by directing them to hunt the native swoops that circle the mesas, collecting their quills to gauge a hunter's patience, aim, and ability to harvest without waste.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_harken-windtotem-e5574ca5c0089fb5e63e/1-0000.mp3", duration = 41.2212245, start = 0},
  },
}
P.transport["npc:harlan-bagley"] = {
  hash = "912e27",
  fullHash = "912e27",
  text = "Harlan Bagley. At the Lionheart Armory in Stormwind City, Harlan Bagley tends to the arms and equipment his customers need. He is a human merchant in the Trade District, serving citizens and visiting adventurers from his shop on the district's northern side. Harlan Bagley keeps the Lionheart Armory on the northern side of Stormwind's Trade District. He tends its stock and sells defensive gear from behind the counter. Trade and regional couriers bring supplies to the shop as the capital faces distant border conflicts and shortages.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_harlan-bagley-11859d731a44cca77389/1-0000.mp3", duration = 29.675102, start = 0},
  },
}
P.transport["npc:harlo-barnaby"] = {
  hash = "209047",
  fullHash = "209047",
  text = "Harlo Barnaby. Harlo Barnaby is a wounded dwarven refugee residing in Menethil Harbor. Having barely escaped the slaughter when the Dark Iron clan seized Dun Modr, he now alerts travelers to the tragedy that unfolded in the northern marshes. Harlo Barnaby lived in Dun Modr until the northern stronghold fell to a sudden, savage assault by the Dark Iron dwarves. In the chaos of the ambush, Harlo fled south toward safety, only to catch a stray axe square in the back. Knocked unconscious by the blow, he somehow survived the trek across the marshland and awoke bandaged in Menethil Harbor. Though alive, his wounds and memories of the massacre leave him unable to return, prompting him to urge Alliance adventurers to investigate the smoking ruins of his former home.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_harlo-barnaby-fbf5b50cd26024cc5b8d/1-0000.mp3", duration = 45.1395918, start = 0},
  },
}
P.transport["npc:hegnar-rumbleshot"] = {
  hash = "7a7f0a",
  fullHash = "7a7f0a",
  text = "Hegnar Rumbleshot. Hegnar Rumbleshot is a dwarven gunsmith stationed along the snowy roadway leading from Coldridge Pass toward Kharanos. He maintains a busy shooting range and equips local hunters and mountaineers with firearms and ammunition. Set up at a small campsite between Coldridge Pass and Kharanos, Hegnar Rumbleshot caters to dwarven marksmen, travelers, and the local militia. His camp features a popular shooting range where mountain folk hone their aim against the wild beasts prowling Dun Morogh. Supplying so many eager shooters means Hegnar burns through munitions at a brisk pace, leaving him perpetually reliant on fresh shipments of ammunition from his supplier, the dwarf engineer Loslor Rudge.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_hegnar-rumbleshot-62dfad8350faeec88118/1-0000.mp3", duration = 41.2995918, start = 0},
  },
}
P.transport["npc:henze-faulk"] = {
  hash = "9b2366",
  fullHash = "9b2366",
  text = "Henze Faulk. Near Heroes' Vigil in Elwynn Forest, Henze Faulk lies gravely wounded. He shielded his companion Gazin Tenorm from the Defias Brotherhood, and now awaits a paladin's aid. Henze Faulk lies near the stone ring east of Stormwind, at Heroes' Vigil. Defias marauders ambushed him and his friend Gazin Tenorm there. Henze took the attack so Gazin could survive, and fell to the bandits' blades. Gazin reached the Cathedral of Light to seek help. Henze remains between life and death, awaiting the aid of a paladin carrying a Symbol of Life.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_henze-faulk-3c4b367296e3c6d1d2a3/1-0000.mp3", duration = 35.2130612, start = 0},
  },
}
P.transport["npc:heralath-fallowbrook"] = {
  hash = "a2bd25",
  fullHash = "a2bd25",
  text = "Heralath Fallowbrook. Heralath Fallowbrook is a dying night elf druid imprisoned deep within Razorfen Kraul. Dispatched to investigate the thorny corruption surrounding the remains of the Ancient Agamaggan, he was captured and brutalized by the Razorfen tribe. With his final breaths, he seeks to send word of his fate and a cherished pendant back to his wife in Darnassus. Sent by his people to investigate the ancient boar god Agamaggan and the spreading briars choking the southern Barrens, Heralath Fallowbrook sought the root of Razorfen Kraul's corruption. Instead of unearthing answers, the night elf was taken prisoner by the quilboar. Locked in a squalid pen and relentlessly beaten, Heralath succumbed to severe wounds and raging fever. Before fading entirely, he shared what he knew with a fellow captive, the dwarf Henrig Lonebrow, urging him to warn the sentinel outpost at Thalanaar about the aggression stirred up by the quilboar crone Charlga Razorflank.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_heralath-fallowbrook-98e16d1fe54b79003e3a/1-0000.mp3", duration = 59.924898, start = 0},
  },
}
P.transport["npc:high-executor-derrington"] = {
  hash = "e3c3d8",
  fullHash = "e3c3d8",
  text = "High Executor Derrington. High Executor Derrington commands the Forsaken vanguard stationed at the Bulwark on the eastern border of Tirisfal Glades. A no-nonsense military officer, he oversees the Horde's front-line defense against the Scourge and Scarlet Crusade threats emanating from the Western Plaguelands. From this fortified barricade, he directs seasoned champions toward contested ruins like Andorhal and Scholomance. Standing directly before the fortified barricades of the Bulwark, High Executor Derrington serves as the gatekeeper between the haunted safety of Tirisfal Glades and the rotting horrors of the Western Plaguelands. Derrington holds little patience for political maneuvering in the Undercity, viewing the front lines as a crucible of sheer survival. For Horde soldiers and sellswords seeking to test their mettle, Derrington provides direct military orders, sending scouts and strike teams deep into plagueridden territory to blunt enemy incursions before they breach Tirisfal. Derrington's defensive position is beleaguered on multiple axes. To the east lies the Scourge, entrenched in the shattered town of Andorhal and spilling through the countryside via corrupting cauldrons. Simultaneously, the zealous fanatics of the Scarlet Crusade contest northern fortifications and skirmish relentlessly with Forsaken patrols. Derrington coordinates surgical counterattacks, sabotage against the Scarlet lines, and the systematic disruption of Scourge cauldron fields to safeguard the eastern border.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_high-executor-derrington-2aa41af7508cf6c03c3e/1-0000.mp3", duration = 88.2938776, start = 0},
  },
}
P.transport["npc:high-priest-rohan"] = {
  hash = "204c46",
  fullHash = "204c46",
  text = "High Priest Rohan. High Priest Rohan is the preeminent leader of the Church of the Holy Light within Ironforge, found pacing inside the Hall of Mysteries. He oversees the spiritual development of fledgling priests across the Alliance and aids those seeking mastery over the Holy Light. Through his guidance and sacred relics, he maintains spiritual ties between the mountain kingdom, Stormwind, and distant allies. Pacing the quiet flagstones of the Hall of Mysteries in the Mystic Ward, High Priest Rohan acts as the highest-ranking representative of the Church of the Holy Light in Ironforge. While dwarves historically honored the titans, dwarven priests have deeply embraced the Light's virtues of wisdom, compassion, and justice. Rohan serves as a patient teacher to young acolytes, teaching them the discipline necessary to channel holy magic and steel their minds against despair. Rohan recognizes that spiritual insight takes many shapes across the Alliance. Once priests under his tutelage grasp the fundamentals, he directs them outward—sending human and dwarven students to High Priestess Laurena in Stormwind City, or dispatching night elf disciples to Priestess Alathea at the Temple of the Moon in Darnassus to master elusive mysteries like Elune's Grace. Beyond the capitals, he urges devotees to render assistance wherever hardship strikes, even directing healers abroad to aid the druids of the Cenarion Circle in distant Azshara. In addition to his teachings, Rohan holds custody over sacred relics essential to the wider Alliance priesthood and paladin brotherhoods. Among his possessions is a blessed exorcism censer, seasoned through years of cleansing vile spirits. When the Order of the Silver Hand and Lord Grayson Shadowbreaker require the vessel to temper the holy calling of their knights, Rohan freely yields it—asking only for charitable alms to replenish Ironforge's dwindling food reserves for the city's needy.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_high-priest-rohan-ff8224e3aa675cd1dbb2/1-0000.mp3", duration = 119.118367, start = 0},
  },
}
P.transport["npc:highlord-demitrian"] = {
  hash = "cad20d",
  fullHash = "cad20d",
  text = "Highlord Demitrian. Highlord Demitrian is a solitary human hermit dwelling amidst the strange crystals of northwestern Silithus. Describing himself as a loyal servant of Prince Thunderaan, he possesses the esoteric knowledge required to wake the slumbering elemental lord. Adventurers bearing ancient elemental bindings seek him out to unlock the power of the Windseeker. Found lingering at an abandoned encampment in the Crystal Vale, Demitrian appears out of place in the desolate wastes of Silithus. Though he is tied to the Twilight's Hammer whose ravaged camp he haunts, Demitrian acts above all as a herald for Prince Thunderaan, the Windseeker. He treats visitors with aloof indifference unless they carry proof of the Windseeker's shattered essence.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_highlord-demitrian-dc5784d82721f084df00/1-0000.mp3", duration = 42.762449, start = 0},
  },
}
P.transport["npc:hogger"] = {
  hash = "a877bc",
  fullHash = "a877bc",
  text = "Hogger. In southwestern Elwynn Forest, Hogger leads the Riverpaw gnolls in raids on farms and travelers. His violent attacks have earned him a bounty from the Stormwind Marshals. Hogger commands the Riverpaw pack from Hogger Hill in southwestern Elwynn Forest. Since the Third War, the gnolls have grown bolder and more coordinated in their raids on nearby homesteads. The Riverpaw have joined forces with the Defias Brotherhood, exchanging their raw ferocity for arms, tactical direction, and magical support. To protect Elwynn's borders and trade routes from further bloodshed, Marshal Dughan has posted a bounty on Hogger's head.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_hogger-6035a06da04a58d05da4/1-0000.mp3", duration = 38.3216327, start = 0},
  },
}
P.transport["npc:holt-thunderhorn"] = {
  hash = "62c5e8",
  fullHash = "62c5e8",
  text = "Holt Thunderhorn. Holt Thunderhorn is a tauren hunter trainer stationed upon Hunter Rise in the elevated city of Thunder Bluff. He instructs novice and seasoned track-masters in their craft, offering basic martial guidance and pointing maturing marksmen toward specialized trials across Mulgore and beyond. Perched on Hunter Rise above the sweeping plains of Mulgore, Holt Thunderhorn serves the Horde as a seasoned instructor in ranged combat, tracking, and survival. Like many elders of his craft, he guides young tauren as they make the transition from roaming hunters into disciplined defenders of their new capital.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_holt-thunderhorn-dde861d55f5fbe74fdab/1-0000.mp3", duration = 33.8808163, start = 0},
  },
}
P.transport["npc:huldar"] = {
  hash = "689455",
  fullHash = "689455",
  text = "Huldar. Huldar is a dwarven teamster stationed along the southern road of Loch Modan, near the shores of the lake. Tasked with hauling vital blast powder to the dig site in the south, his delivery caravan faces relentless harassment from local threats and Dark Iron saboteurs. Hauling explosives through Loch Modan is no simple trade route. Huldar was tasked with driving wagonloads of mining blast powder down toward the southern excavation site, where dwarven archaeologists and prospectors desperately need supplies. However, the wilderness roads have become increasingly hazardous. With local wildlife, troggs, and Dark Iron infiltrators lurking near the lake's southern bend, Huldar finds himself stranded by his damaged wagon, relying on wandering travelers to safeguard the remaining powder kegs and ensure the shipment reaches the dig.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_huldar-104c0e56e5a31d159f5b/1-0000.mp3", duration = 51.7485714, start = 0},
  },
}
P.transport["npc:illiyana-moonblaze"] = {
  hash = "4ae57a",
  fullHash = "4ae57a",
  text = "Illiyana Moonblaze. Illiyana Moonblaze is a night elf supply officer stationed at Silverwing Grove in Ashenvale. Operating alongside the Silverwing Sentinels, she supplies Alliance champions waging war against the Warsong Outriders. Illiyana Moonblaze serves as the supply officer for the Silverwing Sentinels nestled in Silverwing Grove. From her post near the path into Warsong Gulch, she outfits the defenders who hold the southern woods of Ashenvale against the Warsong clan. Beyond keeping the grove's stores, Illiyana equips Alliance volunteers preparing to clash with the Warsong clan in Warsong Gulch. As champions earn favor with the Silverwing Sentinels, she rewards their service with custom rations, specialized draughts, and masterwork armaments designed specifically for woodland skirmishes. She also maintains weapons and armor for weary fighters returning from the frontline, keeping the Sentinels' war effort supplied and functional.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_illiyana-moonblaze-98c7a0dc3d2fc75d168d/1-0000.mp3", duration = 56.7379592, start = 0},
  },
}
P.transport["npc:ilthalaine"] = {
  hash = "d09026",
  fullHash = "d09026",
  text = "Ilthalaine. In Shadowglen, Ilthalaine keeps watch over the sacred glade and guides young night elves as they begin their lives in Teldrassil. He teaches them to defend their home and tend its balance. Ilthalaine watches the woodland paths just outside Shadowglen's heart. He sees changes in the forest that ordinary eyes miss. When young night elves awaken to their duties, he welcomes them and grounds them in Kaldorei traditions. His guidance prepares them to care for Teldrassil and shoulder the responsibilities of its defenders. Heavy spring rains have brought more nightsabers and thistle boars to Shadowglen than the glade can feed. Ilthalaine asks young defenders to thin their numbers, leaving room for the woodland's other creatures to flourish and restoring nature's balance. Ilthalaine tests young elves against local wildlife and points them toward their chosen callings. He gives each traveler a class sigil and directs them to their mentors in the Aldrassil sanctuary. Warriors, druids, rogues, priests, and hunters all find where their service to the Kaldorei begins.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ilthalaine-886a22f8a7f9b839916a/1-0000.mp3", duration = 66.324898, start = 0},
  },
}
P.transport["npc:innkeeper-allison"] = {
  hash = "c4bce6",
  fullHash = "c4bce6",
  text = "Innkeeper Allison. In Stormwind's Trade District, Innkeeper Allison keeps the Gilded Rose ready for travelers and merchants. The busy inn stands between the bank and auction house, where she offers hearthstone bindings, drinks, and shelter. Innkeeper Allison welcomes travelers at the Gilded Rose in Stormwind. The inn stands between the Trade District auction house and the city's main vaults, and its ground floor sees a steady flow of peddlers, mercenaries, and visiting diplomats. She keeps order behind the main counter and offers lodging and hearthstone services. Allison also joins local holiday festivities and coordinates small errands for traveling heroes seeking rest in the capital.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_innkeeper-allison-7c17214c766b60d1646a/1-0000.mp3", duration = 42.7363265, start = 0},
  },
}
P.transport["npc:innkeeper-farley"] = {
  hash = "8fd328",
  fullHash = "8fd328",
  text = "Innkeeper Farley. At the Lion's Pride Inn in Goldshire, Innkeeper Farley welcomes travelers with food, beds, and hearthstones. Well-liked and observant, he keeps misplaced mail and hears the troubles of those on the road. Travelers bound for Stormwind, Westfall, and Duskwood find Innkeeper Farley behind the Lion's Pride Inn counter in Goldshire. He offers meals, ale, cheese, and a bed, and sets hearthstones for those who need one. With a welcoming hand and a sharp eye, Farley serves all who pass through this busy waystation and keeps order at the inn.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_innkeeper-farley-b32a8994c1722036d924/1-0000.mp3", duration = 36.075102, start = 0},
  },
}
P.transport["npc:innkeeper-firebrew"] = {
  hash = "5baaf7",
  fullHash = "5baaf7",
  text = "Innkeeper Firebrew. Innkeeper Firebrew manages the Stonefire Tavern in the bustling Commons of Ironforge. A genial host to weary mountaineers and visiting dignitaries alike, he serves hearty dwarven staples and keeps travelers rested beneath the mountain. Situated in the central ring of the Commons, Innkeeper Firebrew's establishment is often the first sanctuary encountered by travelers entering through the Great Gates of Ironforge. Behind a counter laden with flagons of ale, skins of stout, and roasted joints of meat, Firebrew offers hospitality to adventurers bound for the snowy passes of Dun Morogh or deeper into the mountain kingdom. His tavern remains a lively crossroad where miners, riflemen, and emissaries gather to escape the drafty tunnels and exchange tales around the hearth.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_innkeeper-firebrew-ef4ba8410bca04e20ac5/1-0000.mp3", duration = 45.4530612, start = 0},
  },
}
P.transport["npc:innkeeper-grosk"] = {
  hash = "292570",
  fullHash = "292570",
  text = "Innkeeper Grosk. At Razor Hill, Innkeeper Grosk welcomes travelers on the road between the Valley of Trials and Orgrimmar. His inn offers food, drink, and a place to rest in central Durotar. Razor Hill links Durotar’s southern training grounds with Orgrimmar’s high walls. Innkeeper Grosk shelters warriors, scouts, and peons at his inn. Travelers find basic provisions, hearty meats, and cool water beneath its sturdy timbers. Grosk also helps the laborers who keep Durotar running. Ukor, a timid peon, hauled food to the Valley of Trials only to learn it was not needed. He asks travelers to carry the load back to Grosk’s inn in Razor Hill.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_innkeeper-grosk-b1ad29cdd178b5afcf12/1-0000.mp3", duration = 41.8481633, start = 0},
  },
}
P.transport["npc:innkeeper-gryshka"] = {
  hash = "dda7f2",
  fullHash = "dda7f2",
  text = "Innkeeper Gryshka. At the Broken Tusk in Orgrimmar, Innkeeper Gryshka welcomes travelers with food, drink, and a hearthstone binding. She keeps the inn supplied with meat from hunters across Durotar and the Barrens. Innkeeper Gryshka welcomes travelers at the Broken Tusk in Orgrimmar's Valley of Strength. The inn stands just beyond the city's main gates, where warriors, messengers, and newcomers to Thrall's Horde can find shelter. Gryshka keeps the Broken Tusk's kitchen supplied with fresh meat. Trusted hunters across Horde lands send her game, including Zargh at the Crossroads and Grimtak in Durotar, who ship their finest cuts to the inn.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_innkeeper-gryshka-5654daa7e179f88a7de0/1-0000.mp3", duration = 38.6612245, start = 0},
  },
}
P.transport["npc:innkeeper-keldamyr"] = {
  hash = "688571",
  fullHash = "688571",
  text = "Innkeeper Keldamyr. In Dolanaar, Innkeeper Keldamyr offers food, drink, and a place to rest. Young night elves leaving Shadowglen can find shelter at his inn beneath the boughs of the World Tree. Dolanaar is the first village many newcomers reach after leaving the sheltered glade of Aldrassil. At the village's central inn, Innkeeper Keldamyr offers bread, spring water, and soft beds beneath Teldrassil's canopy. Travelers, sentinels, and young novices bound for Darnassus pause at his counter to rest, bind their Hearthstones, and gather rations for the journey through the boughs. An inn high among the branches depends on steady supplies from nearby settlements and tradesfolk. Couriers bringing goods are often sent to Keldamyr's desk, tying his inn to the daily trade that keeps Dolanaar running.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_innkeeper-keldamyr-8d5d44a4919deec46279/1-0000.mp3", duration = 50.8865306, start = 0},
  },
}
P.transport["npc:innkeeper-norman"] = {
  hash = "e7c877",
  fullHash = "e7c877",
  text = "Innkeeper Norman. Innkeeper Norman tends the hearth at the primary tavern in the Trade Quarter of the Undercity. A quiet, diligent Forsaken, he offers travelers of the Horde respite, hearthstone bindings, and food suited to the varied tastes of both the living and the dead. Located in the bustling Trade Quarter beneath the ruined Capital City of Lordaeron, Innkeeper Norman provides lodging for emissaries, mercenaries, and adventurers passing through the Forsaken stronghold. Despite the damp chill and alchemical stenches of the Undercity, Norman's tavern remains a bustling hub for travelers looking to anchor their hearthstones, share news from across Azeroth, or prepare for expeditions into the Plaguelands. While Norman typically keeps to his duties selling provisions and managing rooms, the seasonal arrival of Hallow's End reveals a more peculiar side. During the holiday, Norman participates in the seasonal revelry, demanding peculiar displays—such as clucking like a chicken—from adventurous patrons eager to earn holiday treats like Undercity mints.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_innkeeper-norman-fbd7f282787dd7d8c169/1-0000.mp3", duration = 62.3281633, start = 0},
  },
}
P.transport["npc:innkeeper-pala"] = {
  hash = "e84f3c",
  fullHash = "e84f3c",
  text = "Innkeeper Pala. Innkeeper Pala manages the Cat and the Shaman, the bustling tavern situated on the lower tier of Thunder Bluff. She offers visiting adventurers a hearthstone binding, cold drinks, and a place to rest between journeys across Mulgore and beyond. Perched on the lower rise of Thunder Bluff's sweeping mesas, Innkeeper Pala tends the hearth at the Cat and the Shaman. The establishment serves as one of the primary gathering points for travelers stepping off the central lifts or arriving from the sprawling plains of Mulgore. Holding a steady vigil over her common room, Pala ensures that weary warriors, wandering druids, and visiting allies of the Horde find a dependable shelter, a warm drink, and a familiar home away from home.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_innkeeper-pala-e3cf4a7f084955af13f1/1-0000.mp3", duration = 43.284898, start = 0},
  },
}
P.transport["npc:jahan-hawkwing"] = {
  hash = "1c9751",
  fullHash = "1c9751",
  text = "Jahan Hawkwing. At the Crossroads, Jahan Hawkwing keeps Horde travelers supplied with armor. The tauren armorer works from this outpost in the Barrens, where predators roam the plains. Jahan Hawkwing tends to the armor needs of Horde travelers and defenders at the Crossroads. In the Barrens, durable gear can mean survival against centaur, quilboar, and wild beasts. Jahan works with local leatherworkers, sending cured hides for delivery so his shop stays stocked with dependable tanned leather and sturdy chainmail.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_jahan-hawkwing-a4e3ddad74d438fb85c1/1-0000.mp3", duration = 32.0783673, start = 0},
  },
}
P.transport["npc:james-halloran"] = {
  hash = "5d923f",
  fullHash = "5d923f",
  text = "James Halloran. James Halloran is a human tanner working out of the Wetlands to supply fine hides across the eastern continents. Based in Menethil Harbor, he makes a living harvesting the tough, prized skins of the region's native crocolisks. He relies on passing travelers and nearby trade channels to gather raw materials and transport his finished leathers to market. From his home in Menethil Harbor, James Halloran makes his living from the marshland just outside town. As an enterprising tanner, Halloran recognized that the perilous bogs offer a lucrative commodity: crocolisk skins. Transforming the rugged hide of marsh reptiles into high-quality leather requires rare craftsmanship, and Halloran's finished goods are shipped out through local trade channels to buyers all across Azeroth. Operating so close to the marsh comes with constant danger. Halloran cannot easily hunt every beast himself while tending to curing vats and trade logistics. He frequently hires hardy travelers to handle the rougher chores of skinning young marsh beasts and managing routine deliveries between his work site and surrounding settlements, ensuring his bustling leather craft stays fully supplied.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_james-halloran-3d72f7e2d64b87448bb3/1-0000.mp3", duration = 69.0677551, start = 0},
  },
}
P.transport["npc:jannok-breezesong"] = {
  hash = "cfb1a7",
  fullHash = "cfb1a7",
  text = "Jannok Breezesong. In Dolanaar, Jannok Breezesong trains young night elf rogues. He teaches stealth, cunning, and bladecraft to kaldorei setting out beneath the World Tree's boughs. Beneath Dolanaar's boughs, Jannok Breezesong teaches novice night elf rogues. He trains those who work quietly beyond the ranks of Teldrassil's sentinels and druids. His lessons teach them to stalk through shadows, strike from behind, and survive unseen among the boughs. When rogues finish their first lessons in Dolanaar, Jannok sends them to more experienced trainers in Darnassus.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_jannok-breezesong-7fd4cdedb0a26e29f422/1-0000.mp3", duration = 35.3697959, start = 0},
  },
}
P.transport["npc:jasper-fel"] = {
  hash = "4f08c2",
  fullHash = "4f08c2",
  text = "Jasper Fel. In Stormwind's Old Town, Jasper Fel supplies daggers and vials from SI:7 headquarters. He keeps watch on visitors and warns them to mind their speech. Inside SI:7 headquarters in Old Town, Jasper Fel supplies the agents who work there. He offers simple daggers and empty vials for brewing and applying poisons. Jasper works under Mathias Shaw's intelligence division and warns visitors to mind their speech. In a place built for espionage, careless words can put people in danger.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_jasper-fel-c50e7302463761d6da94/1-0000.mp3", duration = 30.5110204, start = 0},
  },
}
P.transport["npc:jen-shan"] = {
  hash = "21f55b",
  fullHash = "21f55b",
  text = "Jen'shan. In the Valley of Trials, Jen'shan teaches young hunters the ways of the wild. The Darkspear jungle troll trains orc and troll marksmen in tracking, ranged combat, and survival. Jen'shan trains new hunters in the Valley of Trials. Young orcs and Darkspear trolls come to her with inscribed tablets and parchments that direct them to her. She teaches them archery, marksmanship, and wilderness survival, preparing them for the scorpids and boars on the canyon floor.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_jen-shan-18f7c7906d49ceb998c4/1-0000.mp3", duration = 27.7159184, start = 0},
  },
}
P.transport["npc:jennea-cannon"] = {
  hash = "8e5ccf",
  fullHash = "8e5ccf",
  text = "Jennea Cannon. In Stormwind, Jennea Cannon guides new mages through their first studies. From the Wizard's Sanctum in the Mage Quarter, she teaches caution and self-control, and investigates disturbances in local arcane energies. At the top of the Wizard's Sanctum's spiral walkway, Jennea Cannon guides those who come to Stormwind to study the arcane. She teaches more than spells, insisting that students learn caution and self-control. Even those who do not study magic hear her warning: without training, magic can burn its wielder. Jennea sends promising apprentices beyond the city walls to test what they have learned. At Mirror Lake in Elwynn Forest, they study how natural water sources meet arcane resonance. As they advance, she sends them to investigate disturbances at the Blue Recluse or gather volatile reagents for their first true wizard's implements. When an apprentice outgrows Jennea's lessons, she points the way to greater masters. Those who show true potential may continue up the Sanctum's hierarchy with High Sorcerer Andromath, or travel beyond the kingdom to practitioners such as Tabetha, deep in the Dustwallow Marsh.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_jennea-cannon-c423f16f021a5fea130d/1-0000.mp3", duration = 70.0865306, start = 0},
  },
}
P.transport["npc:jocaste"] = {
  hash = "b74740",
  fullHash = "b74740",
  text = "Jocaste. In Darnassus, Jocaste trains night elf hunters arriving from the wilds of Teldrassil. Jocaste trains night elf hunters in Darnassus's Cenarion Enclave. Young trackers come to her after their first training in Shadowglen, ready to take up the hunt in the capital. She teaches marksmanship and survival in the wild, along with the bond between a hunter and the beasts of Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_jocaste-e1bab19f4f69883f62c3/1-0000.mp3", duration = 23.4579592, start = 0},
  },
}
P.transport["npc:john-j-keeshan"] = {
  hash = "e38e15",
  fullHash = "e38e15",
  text = "John J. Keeshan. Corporal John J. Keeshan is a human soldier of Stormwind's army who fought the Blackrock orcs in the Redridge Mountains. After being captured during the fighting around Stonewatch, he was dragged deep into Render's Rock as a prisoner of war. John J. Keeshan is a corporal in the service of Stormwind, posted to the Redridge Mountains as the Blackrock orcs pressed against Lakeshire and its defenders. When the fighting flared up around Stonewatch Keep, Keeshan was in the thick of it alongside the other soldiers holding the line for the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_john-j-keeshan-cacb711eb54c2a2bf016/1-0000.mp3", duration = 31.3208163, start = 0},
  },
}
P.transport["npc:jorah-annison"] = {
  hash = "f65130",
  fullHash = "f65130",
  text = "Jorah Annison. In the Magic Quarter, Jorah Annison helps spellcasters find knowledge scattered across Azeroth. The Forsaken cartographer knows both the land and the ancient texts warlocks seek. Jorah Annison makes maps in the Undercity's Magic Quarter, but the work does not hold his interest. He would trade every map in the shop for one good book. Jorah knows more about ancient texts than almost anyone, and warlocks share his taste for a scholar's work. Warlocks seeking the elusive Tome of the Cabal are often sent to Jorah Annison. His knowledge reaches beyond the ruins of Lordaeron, and he can point them toward places where ancient texts and remnants of dark sects might be found. He joins the study of old lore to the geography of distant lands.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_jorah-annison-3f89db0b82c3dfe5f61c/1-0000.mp3", duration = 45.844898, start = 0},
  },
}
P.transport["npc:jorgen"] = {
  hash = "4e7290",
  fullHash = "4e7290",
  text = "Jorgen. Jorgen keeps watch beside the water at Stormwind's Valley of Heroes entrance. His quiet perch draws people with matters they cannot discuss openly. Jorgen keeps to the water just right of Stormwind's great entrance. Above him, statues of heroes look over the bridge, while he watches those who come and go below. People seeking information they want kept off the record can find a quiet contact there.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_jorgen-a4104bfebc698ac25d34/1-0000.mp3", duration = 25.077551, start = 0},
  },
}
P.transport["npc:josef-gregorian"] = {
  hash = "04fc22",
  fullHash = "04fc22",
  text = "Josef Gregorian. Josef Gregorian is a Forsaken tailoring trainer found working in the Magic Quarter of the Undercity. He guides ambitious Horde tailors seeking to weave enchanted fabrics, providing expertise and directing them toward specialized garments. Amid the dim alchemical lanterns and damp vaults of the Magic Quarter, Josef Gregorian maintains the fine craft of tailoring for the Forsaken and their Horde allies. While life in the subterranean kingdom has turned cold, cloth-working remains vital for warlocks, mages, and priests who channel raw energies through woven fibers. Gregorian serves as a dependable instructor in the capital, ready to teach foundational patterns and to stitch the first robes of young mages who bring him the right materials.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_josef-gregorian-5e9a90ccd1df98a2629f/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["npc:kaal-soulreaper"] = {
  hash = "54f455",
  fullHash = "54f455",
  text = "Kaal Soulreaper. In the Undercity, orc warlock Kaal Soulreaper trains apprentices and keeps close ties with practitioners of the dark arts across the Horde. Among the Forsaken, he guides students toward mentors in distant lands. Kaal Soulreaper works in the Undercity's Magic Quarter, where Horde warlocks come to learn from his mastery of demonic entities and curses. Thrall's Horde strictly regulates and monitors fel magic within Orgrimmar, while the subterranean sanctums of Lordaeron offer practitioners like Kaal ample harbor. Beyond teaching, Kaal connects those seeking greater power with mentors across the sea, including Menara Voidrender in the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kaal-soulreaper-d43c6a909a9d1a650c9e/1-0000.mp3", duration = 40.4114286, start = 0},
  },
}
P.transport["npc:kali-remik"] = {
  hash = "bd4234",
  fullHash = "bd4234",
  text = "Kali Remik. In Sen'jin Village, Kali Remik guides young hunters toward their next training. She is a Darkspear troll hunter who knows the tracking and survival ways of Durotar. Kali Remik guides young scouts in Sen'jin Village, where they begin their lives beyond the Valley of Trials. A Darkspear troll tracker, she knows Durotar's dry lands and the Horde's settlements. When a novice is ready to leave the local training grounds, Kali sends promising hunters to Thotar in Razor Hill. There they begin learning to tame beasts, strengthening the Horde's frontier ranks.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kali-remik-4f08c71da8bb68ac8f12/1-0000.mp3", duration = 34.0897959, start = 0},
  },
}
P.transport["npc:kaltunk"] = {
  hash = "edea4f",
  fullHash = "edea4f",
  text = "Kaltunk. At the heart of the Valley of Trials in Durotar, Kaltunk welcomes young orcs and points them toward their first duties for the Horde. Kaltunk watches over new arrivals in the Valley of Trials and directs them toward Gornek and the path of discipline. While trainers and elders set trials and hunting rites, the orc overseer gives recruits clear orders so they know where to go. The Valley of Trials was chosen to test the strength and resilience of the youths who walk its canyon floors. Kaltunk brings the same rugged practicality to his work. He offers no grand speeches or coddling, and expects each orc to find a place in the world and serve the warchief.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kaltunk-26cda4936bbca7f9cb1a/1-0000.mp3", duration = 39.9412245, start = 0},
  },
}
P.transport["npc:kanati-greycloud"] = {
  hash = "319ea0",
  fullHash = "319ea0",
  text = "Kanati Greycloud. Kanati Greycloud is a tauren hunter stationed at Whitereach Post within Thousand Needles. Alongside his hunting companions, he musters what defense he can while enduring constant hostility from the local Galak centaur. Kanati Greycloud makes his camp at Whitereach Post, high atop the sandstone spires of western Thousand Needles. While the canyon offers abundant game and open vistas, it is hemmed in by the Galak centaur, whose warbands contest every inch of the arid flats below. Together with other tauren hunters, Kanati keeps watch over the canyon floor, striving to preserve the post against the brutal depredations of the surrounding marauders.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kanati-greycloud-e2d035704389522f1ba2/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["npc:kaplak"] = {
  hash = "147ef6",
  fullHash = "147ef6",
  text = "Kaplak. In Razor Hill, Kaplak trains young orc and troll rogues for the Horde. He teaches stealth, subterfuge, and bladecraft before sending them to Orgrimmar. Kaplak trains new Horde rogues in Razor Hill. Orcish custom favors open combat and roaring charges, but he teaches the quieter skills needed to survive: stalking unseen, picking locks, and striking from behind. When his students outgrow his training in Durotar's dusty red ravines, he sends them north to Orgrimmar, where senior guild operatives can deepen their craft.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kaplak-5853e9a4843409037f4f/1-0000.mp3", duration = 34.9779592, start = 0},
  },
}
P.transport["npc:karang-amakkar"] = {
  hash = "c75877",
  fullHash = "c75877",
  text = "Karang Amakkar. Karang Amakkar is an orc scout stationed at Zoram'gar Outpost along the rocky coast of Ashenvale. Operating on the fringe of Horde territory, he focuses on curbing the violent furbolg tribes that threaten the outpost's supply lines and borders. Adventurers travelling through the outpost rely on his local intelligence to navigate the perilous tensions of the forest. Perched at Zoram'gar Outpost on the Zoram Strand, Karang Amakkar serves the Horde at one of its most vulnerable border outposts. The encampment faces constant pressure from the sea, the night elves, and wild beasts inland. Karang keeps a close eye on the hostile native populations that surround the road eastward, ensuring that Horde couriers and scouting parties do not get ambushed by territorial indigenous tribes. Karang focuses much of his attention on the furbolg populations native to the ancient woods, notably the Foulweald tribe. With corruption and primal hostility driving these bear-folk into frenzies, Karang tasks capable warriors with culling their leader and clearing out dens before the tribes can muster organized assaults against Zoram'gar.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_karang-amakkar-e92ac5c5b526ea0febb0/1-0000.mp3", duration = 68.7281633, start = 0},
  },
}
P.transport["npc:kargal-battlescar"] = {
  hash = "b8873d",
  fullHash = "b8873d",
  text = "Kargal Battlescar. At the Far Watch Post, Kargal Battlescar guards the eastern edge of the Barrens. He watches the crossing from Durotar, judges incoming recruits, and sends capable fighters west to strengthen Horde defenses. Kargal Battlescar watches the road into the Barrens from the Far Watch Post. Travelers and new adventurers cross the bridge over the Southfury River, leaving the Valley of Trials behind. The Barrens is a dangerous, contested land, where aggressive wildlife, centaur raiders, and quilboar tribes threaten the frontier. Kargal inspects those who pass and gathers willing recruits for the Horde. He sends them onward to the Crossroads, where they can aid local commanders in securing the frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kargal-battlescar-63ef34068e726ab9574c/1-0000.mp3", duration = 44.0163265, start = 0},
  },
}
P.transport["npc:karos-razok"] = {
  hash = "e3f4ae",
  fullHash = "e3f4ae",
  text = "Karos Razok. Karos Razok is the Forsaken bat handler stationed at the Sepulcher in Silverpine Forest. He oversees the roost of undead fliers that connect this contested frontier outpost directly to the Undercity and other Horde strongholds. Perched on the wooden platform above the crypts of the Sepulcher, Karos Razok tends to the skeletal bats vital for Forsaken communications. With Silverpine Forest infested by Moonrage worgen, rogue Dalaran magi, and the human remnants of Ambermill, overland travel along the northern road is treacherous. Razok ensures that messengers, fresh recruits, and vital supplies can cross above the haunted canopy, keeping the front line linked straight back to the capital in Tirisfal Glades.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_karos-razok-29f064d06f1801e29362/1-0000.mp3", duration = 44.8261224, start = 0},
  },
}
P.transport["npc:katie-hunter"] = {
  hash = "24f2a6",
  fullHash = "24f2a6",
  text = "Katie Hunter. At the Eastvale Logging Camp stables, Katie Hunter tends horses for Stormwind and trusted Alliance champions. She works with Randal Hunter to keep travelers and soldiers mounted for the kingdom’s roads. Katie Hunter tends the horses at the Eastvale Logging Camp in eastern Elwynn Forest. While lumberjacks cut timber for Stormwind’s reconstruction, she raises dependable pintos, mares, and swift steeds for riders. Her horses carry people along the kingdom’s roads and the dangerous routes of southern Azeroth.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_katie-hunter-67110542fe5f98fe5a62/1-0000.mp3", duration = 32.3395918, start = 0},
  },
}
P.transport["npc:kaymard-copperpinch"] = {
  hash = "8a9146",
  fullHash = "8a9146",
  text = "Kaymard Copperpinch. In Orgrimmar, Kaymard Copperpinch sells Smokywood Pastures goods for Winter Veil. He trades in the Valley of Strength, where travelers can find festive wares and help with holiday troubles. Kaymard Copperpinch brings Smokywood Pastures to the Valley of Strength each Feast of Winter Veil. Great-father Winter receives visitors nearby as Kaymard sells fine treats, festive wrapping paper, and other holiday goods. To a goblin, no grand festival is complete without a lively exchange of coin. Kaymard also handles troubles that threaten Smokywood Pastures during the festival. Holiday confections go missing, and Metzen the Reindeer disappears. Kaymard calls on Horde adventurers to solve these problems and keep Winter Veil running smoothly.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kaymard-copperpinch-5642e75d0c5a6b108e69/1-0000.mp3", duration = 46.3412245, start = 0},
  },
}
P.transport["npc:keeper-albagorm"] = {
  hash = "7cae14",
  fullHash = "7cae14",
  text = "Keeper Albagorm. Keeper Albagorm is a keeper of the grove stationed at the idyllic sanctuary of Stonetalon Peak. Deeply concerned by the devastation corrupting the southern reaches of the mountains, he enlists travelers to help heal the scorched wilderness of the Charred Vale. Perched within the peaceful boughs of Stonetalon Peak, Keeper Albagorm stands vigil over one of Kalimdor's sacred elven refuges. Like many sons of Cenarius, he feels the pain of the natural world acutely. His attention is drawn southward toward the smoldering ruins of the Charred Vale, set afire by a greedy mechanized army of industrialists and now held by Bloodfury harpies who block any regrowth. From his sanctuary, Albagorm works tirelessly to halt the spread of the corruption and restore balance to the wounded forest.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_keeper-albagorm-83212f85c47a2b64e56f/1-0000.mp3", duration = 46.4457143, start = 0},
  },
}
P.transport["npc:keeper-bel-dugur"] = {
  hash = "8527a4",
  fullHash = "8527a4",
  text = "Keeper Bel'dugur. Keeper Bel'dugur is a scholarly Forsaken residing deep within the Apothecarium of the Undercity. While ostensibly serving the interests of his people by commissioning expeditions to recover dark tomes and magical artifacts, subtle clues reveal far more sinister allegiances. Situated among the vats and researchers of the Apothecarium, Keeper Bel'dugur tasks adventurers with retrieving dangerous arcane and occult relics from across Azeroth. Among his most prominent interests is the Book of Ur, a legendary treatise on extra-dimensional beings locked away inside Shadowfang Keep. While many in the Undercity seek magical knowledge to cure or weaponize the condition of the undead, Bel'dugur's curated acquisitions appear tailored toward unearthing ancient, forbidden powers.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_keeper-bel-dugur-5c68136078f73a0423a6/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["npc:keeper-bel-varil"] = {
  hash = "20ef1f",
  fullHash = "20ef1f",
  text = "Keeper Bel'varil. Keeper Bel'varil is a Forsaken caretaker and researcher stationed at Tarren Mill in the Hillsbrad Foothills. Working closely alongside Wordeen Voidglare, he directs Horde adventurers to gather magical relics and binding materials from the surrounding lands to further their occult studies. Amid the besieged village of Tarren Mill, Keeper Bel'varil quietly supports the Forsaken's magical and alchemical research. While royal apothecaries and soldiers occupy themselves with the Alliance garrison down the road at Southshore, Bel'varil focuses on practical sorcery, dispatching travelers to recover stone tokens and binding bracers from nearby elemental and enchanted threats.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_keeper-bel-varil-f0299108a6f0fd03234a/1-0000.mp3", duration = 42.004898, start = 0},
  },
}
P.transport["npc:keldran"] = {
  hash = "09d3f2",
  fullHash = "09d3f2",
  text = "Keldran. North of the Valley of Spirits in Orgrimmar, Keldran works to clear a path toward peace with the Alliance. He directs covert strikes against demonic remnants, hoping to show that the modern Horde has forsaken the Burning Legion. Keldran works from Orgrimmar’s red rock terraces while Thrall governs from the Valley of Wisdom. The Alliance still sees all orcs as bloodthirsty puppets of demonic masters, a reputation forged during the first wars. Keldran believes Thrall is weary of endless conflict, but peace talks cannot begin while demon-worshiping cults endure in Kalimdor. Without the Warchief’s formal sanction, he takes the initiative himself. He directs trusted agents toward distant threats, hoping to erase the demonic stain and clear the way for diplomacy.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_keldran-e46c2a0dbd41c7ae4af0/1-0000.mp3", duration = 50.4163265, start = 0},
  },
}
P.transport["npc:kelm-hargunth"] = {
  hash = "c4e4b1",
  fullHash = "c4e4b1",
  text = "Kelm Hargunth. At Mor'shan Base Camp, Kelm Hargunth keeps the Warsong Outriders supplied. He equips Horde champions fighting night elves in Warsong Gulch with care packages and provisions. At Mor'shan Base Camp, Kelm Hargunth manages supplies for the Warsong Outriders. The camp stands on the northern edge of the Barrens, beside the border with Ashenvale. Scouts and raiders skirmish beyond its stockade while Kelm sees that weapons, armor, and rations reach the fighters. The Warsong Outriders face the Silverwing Sentinels, and a steady flow of provisions matters as much as fury in battle. Kelm gives specialized supplies to warriors who have proven themselves in Warsong Gulch. His stores include care packages with field dressings and iron rations, along with armaments marked with the Warsong clan's crimson insignia. These supplies go to fighters serving the Horde's campaign in the forests to the north.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kelm-hargunth-4b10228dccdbf149667b/1-0000.mp3", duration = 56.8946939, start = 0},
  },
}
P.transport["npc:kerlonian-evershade"] = {
  hash = "f939d6",
  fullHash = "f939d6",
  text = "Kerlonian Evershade. At the Grove of the Ancients in Darkshore, Kerlonian Evershade wakes from a long sleep in the Emerald Dream. The night elf Druid of the Claw needs help crossing the troubled wilds to reach Maestra's Post. Kerlonian Evershade follows the bear totem as one of the Druids of the Claw. For centuries, these druids slept in barrows and communed with the Emerald Dream. They were called from their slumber during the Third War. Now Kerlonian rests beneath the ancient trees of the Grove of the Ancients, still shaking off the supernatural grogginess of his long sleep. He must travel through Darkshore's troubled forests to reach Maestra's Post on the Ashenvale border. The road from the Grove of the Ancients is dangerous. Blackwood furbolgs prowl the Twilight Vale, while Dark Strand cultists lurk along the road into Ashenvale. Sleep has weakened Kerlonian, and sudden bouts of exhaustion still trouble him. He depends on sympathetic Alliance travelers for protection as he journeys south to rejoin his fellow night elves.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kerlonian-evershade-893238dffbb36bd6f470/1-0000.mp3", duration = 60.6302041, start = 0},
  },
}
P.transport["npc:kernobee"] = {
  hash = "e53a24",
  fullHash = "e53a24",
  text = "Kernobee. Kernobee is a goblin engineer trapped deep within the ruined halls of Gnomeregan. After stumbling upon dangerous secrets involving Dark Iron dwarf sabotage, he was captured, beaten unconscious, and left to die among the troggs in the dormitory quarters. While conducting business or scavenging within the fallen gnome capital, Kernobee uncovered a grave secret: the Dark Iron dwarves were directly involved in the construction and operation of the massive super rig burrowing beneath the city. Realizing the immense value—and lethality—of this intelligence, he attempted to flee immediately to Ratchet to deliver word to his associate, Tinkerwiz. Unfortunately, the Dark Irons caught him before he could make his escape. Rather than killing him outright, his captors battered Kernobee unconscious and tossed him into a small room along the dormitory corridor, opposite the Clean Zone. Left stranded among feral troggs and radiation fallout, the battered goblin depends entirely on passing adventurers to revive him and shield him until he can reach safety.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kernobee-4f0019b823002cc6fee7/1-0000.mp3", duration = 66.4032653, start = 0},
  },
}
P.transport["npc:keryn-sylvius"] = {
  hash = "656e67",
  fullHash = "656e67",
  text = "Keryn Sylvius. On the second floor of Goldshire’s Lion’s Pride Inn, Keryn Sylvius trains young rogues. In the reading room, she teaches stealth and bladecraft and quietly guides promising operatives toward Stormwind’s intelligence service. Keryn Sylvius keeps to the reading room above the Lion’s Pride Inn. Downstairs, travelers crowd the floor with town guards, while upstairs she watches the steady flow of road gossip. She mentors rogues learning their trade in Elwynn Forest. When promising operatives outgrow petty theft and roadside skulduggery, Sylvius discreetly sends them to Stormwind City to contact SI:7.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_keryn-sylvius-2ec5bb303a77aa3e1d83/1-0000.mp3", duration = 38.4783673, start = 0},
  },
}
P.transport["npc:khelden-bremen"] = {
  hash = "8856d2",
  fullHash = "8856d2",
  text = "Khelden Bremen. On the upper floor of Northshire Abbey, Khelden Bremen teaches human mages their first spells. He prepares novices to serve Stormwind through the arcane arts. Khelden Bremen teaches new human mages in a study on the upper floor of Northshire Abbey. While clergy and defenders pursue their work below, he shows novices how to focus and shape magical energy safely. His lessons prepare them for the road through Elwynn Forest and for further study in Stormwind's Mage Quarter.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_khelden-bremen-c05be3fd46276382c115/1-0000.mp3", duration = 28.917551, start = 0},
  },
}
P.transport["npc:kil-hala"] = {
  hash = "bb9ab9",
  fullHash = "bb9ab9",
  text = "Kil'hala. Kil'hala is a jungle troll tailoring trainer stationed at the Crossroads in the Barrens. Skilled in working with both everyday cloth and exotic woven materials, he instructs Horde crafters looking to refine their needlework. Beyond common thread, he weaves nether-lace robes for young Horde mages who bring him locks of hair from the laughing sisters of Ashenvale. Positioned at the bustling hub of the Crossroads, Kil'hala offers his tailoring expertise to passing travelers and Horde recruits. While much of his craft involves common spun bolts and garments fit for dry plains life, his knowledge extends into rare magical textiles. As a favor to the mage Deino, he fashions nether-lace robes for young mages who bring him hair taken from the laughing sisters, dryads of Ashenvale's forests.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kil-hala-52113f39032461f021ed/1-0000.mp3", duration = 46.3934694, start = 0},
  },
}
P.transport["npc:kin-weelay"] = {
  hash = "fe0279",
  fullHash = "fe0279",
  text = "Kin'weelay. Kin'weelay is a renowned Darkspear witch doctor stationed at Grom'gol Base Camp in Stranglethorn Vale. Dispatched directly from Orgrimmar, he offers mystical aid and counsel to the Horde vanguard in the jungle. His spiritual expertise is vital in unravelling dark mojo and aiding the rescue of young Yenniku. Recognized among the Darkspear as one of their most powerful practitioners of traditional witchcraft, Kin'weelay commands deep knowledge of spirits, hexes, and soul magic. When matters involving ancestral spirits or hostile troll enchantments arise, Horde scouts in Stranglethorn Vale look to him to pierce the magical veil.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kin-weelay-e5a67cc5c589965bb099/1-0000.mp3", duration = 39.5232653, start = 0},
  },
}
P.transport["npc:kindal-moonweaver"] = {
  hash = "cac271",
  fullHash = "cac271",
  text = "Kindal Moonweaver. Kindal Moonweaver is a night elf secluded within a concealed nook in the craggy mountains of Feralas, just north of the Grimtotem Compound. Deeply troubled by the mistreatment of wildlife in the wilderness, she watches the aggressive tauren tribe below while seeking help to free captured beasts. She is kin to Jer'kai Moonweaver, sharing a mission to defend the forest's innocent creatures. Perched upon a narrow, winding mountain path partially hidden behind timber east of Dire Maul, Kindal Moonweaver maintains a secret vigil over the valley below. While much of Feralas is contested between the Horde, the night elves of Feathermoon, and the ancient ruins of Eldre'Thalas, Kindal focuses on a more localized and immediate cruelty. Down in the hollow, the Grimtotem tribe operates a fortified compound, capturing and penning up local fauna for reasons far from benign. From her concealed overlook, Kindal watches for anyone willing to brave the enemy camp and undo the suffering inside. Kindal's primary concern lies with the sacred balance and gentle creatures of Feralas that cannot defend themselves against brutish captors. Along with her kin, Jer'kai Moonweaver, she seeks the emancipation of caged beasts and looks out for young animals left stranded by violent poaching. Rather than engaging in grand territorial war, her attention is fixed on compassion: freeing caged sprites and finding a home for an orphaned sprite darter.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kindal-moonweaver-a8ea13f834f41ba35a79/1-0000.mp3", duration = 87.9542857, start = 0},
  },
}
P.transport["npc:kirge-sternhorn"] = {
  hash = "ef4892",
  fullHash = "ef4892",
  text = "Kirge Sternhorn. In the Barrens, Kirge Sternhorn guides travelers crossing central Kalimdor. The tauren keeps watch over the southern trails and sends new Horde adventurers north to the Crossroads. New wanderers often find the sun-baked Barrens daunting. Kirge Sternhorn watches over travelers south of the central trails, between the southern camps and the heart of Kalimdor. Marauding quilboar and fierce predators roam the savanna, and Kirge helps young adventurers find their footing. He ensures they seek out the greater Horde presence gathering to the north.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kirge-sternhorn-cc1a95fcc9bf8e35d2a7/1-0000.mp3", duration = 34.8995918, start = 0},
  },
}
P.transport["npc:klannoc-macleod"] = {
  hash = "26ffd7",
  fullHash = "26ffd7",
  text = "Klannoc Macleod. On Fray Island, Klannoc Macleod puts warriors to the test. The human warrior welcomes fighters from both the Alliance and the Horde who seek mastery of combat stances. Those who earn his respect are sent inland to face greater trials of strength. Klannoc Macleod puts seasoned fighters through their paces on Fray Island, off the Merchant Coast in the Barrens. Though human, he leaves Alliance and Horde quarrels aside. He judges each contender by grit, blade work, and resolve under fire. Klannoc Macleod's trial on Fray Island is called the Affray. Contenders climb onto raised iron grating and face relentless waves of eager brawlers as he watches. Those who endure the onslaught and defeat his chosen champion earn his approval and prove they have the temperament for berserker training.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_klannoc-macleod-8200599689c2056d8aa5/1-0000.mp3", duration = 47.2032653, start = 0},
  },
}
P.transport["npc:kor-ghan"] = {
  hash = "bc094e",
  fullHash = "bc094e",
  text = "Kor'ghan. In Orgrimmar’s Cleft of Shadow, Kor'ghan watches over remedies and toxins. The Darkspear troll stands outside Rekkul's Poisons and seeks help preparing antidotes for Durotar’s venomous predators. Kor'ghan keeps watch over remedies and toxins outside Rekkul's Poisons in Orgrimmar’s Cleft of Shadow. From the capital, he sends travelers into Durotar’s red canyons to gather venomous components from scorpids. He needs them to prepare antidotes for the dangers of the wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kor-ghan-9db1bb6b738937133f15/1-0000.mp3", duration = 30.8244898, start = 0},
  },
}
P.transport["npc:korran"] = {
  hash = "77db57",
  fullHash = "77db57",
  text = "Korran. At the Crossroads, Korran watches the Barrens for threats to the Horde. The Darkspear troll serves Belgrom Rockmaul in Orgrimmar and studies the silithid emerging across the scrublands. At the Crossroads, Korran watches for threats beyond the quilboar and centaur clans. Belgrom Rockmaul in Orgrimmar stationed the troll scout there to observe changes in the land. Korran coordinates the gathering of intelligence for the Horde's leadership. Korran now focuses on the Field of Giants in the southern Barrens. Strange, aggressive insectoid creatures called silithid have begun burrowing into the earth. To learn where the swarm came from and what danger it poses to the young Horde, Korran asks passing adventurers to dig up intact eggs with his claw tool.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_korran-38c4592599fc0bfe7a58/1-0000.mp3", duration = 45.9232653, start = 0},
  },
}
P.transport["npc:kravel-koalbeard"] = {
  hash = "684bc0",
  fullHash = "684bc0",
  text = "Kravel Koalbeard. Kravel Koalbeard is a scheming dwarven entrepreneur and con artist stationed out at the Mirage Raceway in the Shimmering Flats. Rather than cheering purely for the love of the sport, he views the fierce gnome and goblin racing rivalry as a golden opportunity to fill his pockets. From scavenging stray machine parts to fixing race results through blackmail and booze, Kravel is always hunting for his next profitable scheme. While most spectators and crew members at the Mirage Raceway are consumed by mechanical rivalries and the roar of rocket engines, Kravel Koalbeard has his eyes squarely on everyone's coin purses. He is an opportunist who operates in the dusty cracks of the raceway encampment, quick to offer contracts and favors that rarely have clean motives. Kravel sees the high-stakes friction between gnome and goblin engineers not as an inspiring competition, but as a fertile ground for extortion, sabotage, and theft.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kravel-koalbeard-f2e0aa6a0aa8fc81efaf/1-0000.mp3", duration = 58.644898, start = 0},
  },
}
P.transport["npc:kreldig-ungor"] = {
  hash = "1500f9",
  fullHash = "1500f9",
  text = "Kreldig Ungor. Kreldig Ungor is an enterprising dwarven operative representing Reclaimers Inc., stationed high among the crags of Nijel's Point in Desolace. Tasked with managing field operations in the barren wasteland, he hires Alliance adventurers to recover lost cargo and secure valuable local reagents. His salvage and recovery contracts make him a central contact for travelers navigating the hostile region. Nijel's Point offers the Alliance a rare sanctuary amid the blighted canyons of Desolace, making it an ideal staging ground for commercial opportunists like Kreldig Ungor. Representing Reclaimers Inc., Kreldig has ventured far from the safety of Khaz Modan into a desolate wilderness contested by centaur clans, demons, and the Horde. Where others see ruin and ash, Kreldig sees untapped profit and lost assets ripe for recovery. A primary venture bringing Kreldig to Desolace involves the lost vessel of Karnitol, which wrecked along the treacherous western coast. Karnitol's shipment held prized goods, and Kreldig orchestrates efforts to track down the debris and retrieve the scattered cargo before scavengers or coastal sea giants can claim it all. Beyond maritime salvage, Kreldig oversees the procurement of Desolace's strange biological and mineral treasures for Reclaimers Inc. The harsh environment breeds unique fauna and flora, whose parts fetch high prices among alchemists and engineers back in the Eastern Kingdoms. Adventurers willing to brave the wasteland's predators find steady pay beneath Kreldig's ledger.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kreldig-ungor-5999e47dbf369a218208/1-0000.mp3", duration = 93.675102, start = 0},
  },
}
P.transport["npc:krolg"] = {
  hash = "331f6c",
  fullHash = "331f6c",
  text = "Krolg. Krolg is an uncorrupted furbolg living in an isolated hut south of Mystral Lake in Ashenvale. Formerly a member of the Foulweald tribe, he was cast out by his kin, who fell to demonic madness, and will only speak with those who appear to him in furbolg form. While most of the Foulweald furbolgs in Ashenvale have succumbed to the demonic taint left behind by the Burning Legion, Krolg remains lucid and untouched by madness. Residing in a secluded shelter south of Mystral Lake, he keeps a cautious vigil over the forest. Having witnessed the tragic descent of his brethren into senseless violence, he refuses to interact with outsiders at face value, speaking only with beings that appear as kin.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_krolg-ee041de308bac72a4066/1-0000.mp3", duration = 42.7363265, start = 0},
  },
}
P.transport["npc:krom-stoutarm"] = {
  hash = "6682e1",
  fullHash = "6682e1",
  text = "Krom Stoutarm. Krom Stoutarm is a dwarven scholar and warlock found deep within the Library of the Hall of Explorers in Ironforge. Unlike most of his kin who delve solely into ancient stone and titan relics, Krom studies darker, arcane texts and demonic rituals. He acts as an indispensable contact for Alliance warlocks seeking esoteric knowledge across Kalimdor and the Eastern Kingdoms. The Hall of Explorers is typically known for dwarven archaeologists obsessed with picks, shovels, and titan artifacts. Krom Stoutarm cuts an unusual figure among them. Lurking in the Library surrounded by massive tomes, he pursues occult lore and the binding rites of demonic summoners. His presence in Ironforge demonstrates that while warlock arts are widely distrusted, scholar-practitioners who study the forbidden arts still operate within the mountain city's halls. When Alliance warlocks seek to bind potent demonic servants like the felhunter, their journey inevitably crosses paths with Krom. Possessing knowledge of scattered occult volumes, he directs aspiring summoners far across the seas—including dangerous forays among the centaur of Thousand Needles—to recover torn pages and fragments of the infamous Tome of the Cabal.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_krom-stoutarm-923a9f742b1443d31f81/1-0000.mp3", duration = 73.9526531, start = 0},
  },
}
P.transport["npc:krusk"] = {
  hash = "b3b4c4",
  fullHash = "b3b4c4",
  text = "Krusk. Krusk is an orc scout stationed at Tarren Mill in the Hillsbrad Foothills. Dispatched directly under Warchief Thrall's orders to investigate the Syndicate and recover relics from the ruins of Durnholde Keep, he now coordinates reconnaissance and rescue efforts after his initial infiltration was ambushed. When Warchief Thrall turned his attention back to the ruins of Durnholde Keep, he dispatched Krusk and a small strike team to scout Syndicate activity and retrieve relics tied to the fortress's grim past. However, the human outlaws proved more entrenched and coordinated than anticipated. An ambush inside Durnholde's crumbling walls overwhelmed the orcish scout squad. Krusk managed to fight his way out, but his comrades were taken captive: Drull and Tog'thar were locked away within the ruins, while the expedition's leader, Gol'dir, was moved to another Syndicate hold. Regrouping at Tarren Mill, Krusk now directs Horde adventurers to breach Durnholde, recover the lost items, and liberate his trapped comrades. Beyond recovering his scouts, Krusk remains fixated on dismantling the Syndicate's hold over Hillsbrad. The fallen nobles of Alterac represent a volatile threat, operating out of Durnholde Keep and scheming against both Horde outposts and their former Alliance brethren. Working from Tarren Mill, Krusk tracks the movements of Syndicate leaders, such as Lord Aliden Perenolde, hoping to sever their leadership before they can threaten the tenuous Horde foothold in Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_krusk-621de8a3a5d1154c31a4/1-0000.mp3", duration = 92.1861224, start = 0},
  },
}
P.transport["npc:kuray-bin"] = {
  hash = "aade92",
  fullHash = "aade92",
  text = "Kuray'bin. Kuray'bin is a Darkspear jungle troll scout stationed at a guard post outside Splintertree Post in Ashenvale. He watches the surrounding forest trails for night elf scouts sneaking close to the Horde encampment. Positioned just outside Splintertree Post, Kuray'bin keeps watch against Alliance infiltration in the deep woods of Ashenvale. The Silverwing Sentinels constantly patrol the surrounding canopy, sending agile outrunners across the border to gather intelligence on Horde lumber operations and defenses. Knowing that unmonitored scouts quickly become ambushing forces, Kuray'bin directs capable Horde fighters to hunt down the outrunners before they can report back to Silverwing Outpost.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kuray-bin-850a2df0a074e9dbd0cb/1-0000.mp3", duration = 42.6057143, start = 0},
  },
}
P.transport["npc:kzan-thornslash"] = {
  hash = "6034a0",
  fullHash = "6034a0",
  text = "Kzan Thornslash. In the Valley of Trials, Kzan Thornslash supplies weapons to new Horde recruits. He is an orc merchant in Durotar. Kzan Thornslash supplies weapons to young orcs and Darkspear trolls in the Valley of Trials. They are taking their first steps as Horde warriors. He offers basic hand axes, shortswords, clubs, and staves for recruits facing local wildlife and hazards.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kzan-thornslash-b33e5532c47a77a24a68/1-0000.mp3", duration = 24.0326531, start = 0},
  },
}
P.transport["npc:laird"] = {
  hash = "1e3e14",
  fullHash = "1e3e14",
  text = "Laird. At Auberdine's inn, Laird sells fish and cooking supplies to travelers along Darkshore's coast. Laird sells fish and supplies inside Auberdine's inn. Sailors, locals, and travelers come to him while Darkshore's waters churn with dangers greater than those along Teldrassil's sheltered shores. For anglers willing to cast from the misty beaches, the local catch can bring a handsome profit. Laird stays in touch with fishing operations across the channel in Teldrassil. Shipments come from his fellow fisher Nessa Shadowsong, linking Rut'theran Village with the mainland port and keeping coastal trade moving.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_laird-71ed9174608c33183803/1-0000.mp3", duration = 38.2432653, start = 0},
  },
}
P.transport["npc:lakota-windsong"] = {
  hash = "fbc47d",
  fullHash = "fbc47d",
  text = "Lakota Windsong. Lakota Windsong is a young tauren held captive atop the bluffs of Darkcloud Pinnacle in Thousand Needles. After rejecting an unwanted proposal from Arnak Grimtotem, she was abducted by force and awaits rescue from the Grimtotem tribe's clutches. Not long after the Third War, Lakota Windsong was pursued by Arnak Grimtotem. Unwilling to join his clan or accept his courtship, she turned down his proposal. Arnak refused to take no for an answer; he returned under cover of night, slaughtered Lakota's brother when he tried to intervene, and carried her off into the jagged heights of Thousand Needles. Confined high above the canyon floor at Darkcloud Pinnacle, she remains trapped under heavy guard while Arnak still insists on making her his bride.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lakota-windsong-dd381394450f0248ac68/1-0000.mp3", duration = 45.8187755, start = 0},
  },
}
P.transport["npc:lanka-farshot"] = {
  hash = "22ea15",
  fullHash = "22ea15",
  text = "Lanka Farshot. Lanka Farshot is a tauren hunter trainer stationed at Camp Narache within the Red Cloud Mesa. He guides novice tauren hunters as they take their first steps in tracking, marksmanship, and surviving the plains of Mulgore. Standing watch over Camp Narache, Lanka Farshot greets new tauren called to the path of the hunter. Fresh recruits arrive carrying an etched note directing them to seek his counsel. Under his steady eye, apprentices learn the fundamentals of ranged combat, tracking prey, and respecting the wild beasts that roam the grassy plains of Mulgore. His teachings ensure that every young hunter serves as a capable scout and provider for the tribe.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lanka-farshot-7f54065a9b5c4fd7785f/1-0000.mp3", duration = 42.0832653, start = 0},
  },
}
P.transport["npc:lar-prowltusk"] = {
  hash = "d6c343",
  fullHash = "d6c343",
  text = "Lar Prowltusk. Southwest of Sen'jin Village, Lar Prowltusk watches the Durotar frontier. He guards the young troll settlement and sends travelers against nearby threats. Lar Prowltusk watches the coast southwest of Sen'jin Village. As a Darkspear sentinel, he helps guard the tribe's new home after its people fled their sunken island chain. Hostile neighbors keep harassing Sen'jin Village as the trolls work to secure a permanent home. Lar directs scouts and warriors to watch the coast and curb these attacks, especially those by the Kolkar centaur, giving the settlement room to breathe.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lar-prowltusk-c770499a045f6c23ad8d/1-0000.mp3", duration = 37.5379592, start = 0},
  },
}
P.transport["npc:laris-geardawdle"] = {
  hash = "814f54",
  fullHash = "814f54",
  text = "Laris Geardawdle. Laris Geardawdle is an eccentric gnomish researcher stationed in the Library of the Hall of Explorers in Ironforge. He dedicates his academic life to studying the bizarre nature and origins of oozes across Azeroth. Adventurers willing to collect noxious slime samples find him an eager, if slightly unhinged, patron. Tucked away among the towering bookshelves and ancient relics of the Hall of Explorers, Laris Geardawdle pursues a rather unglamorous niche of natural philosophy: the genesis of oozes. While his dwarven colleagues pore over Titan tablets and ancient stone carvings, Laris is convinced that Azeroth's vile, gelatinous horrors hold fascinating alchemical and biological secrets. He tasks roving explorers with gathering caustic samples from remote corners of the world, eager to test his strange hypotheses on how these mindless puddles of malice come to life.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_laris-geardawdle-068a592ad2b259e9aae5/1-0000.mp3", duration = 55.0138776, start = 0},
  },
}
P.transport["npc:lars"] = {
  hash = "55964e",
  fullHash = "55964e",
  text = "Lars. Lars is a beleaguered human survivor camping out in the wilderness of Duskwood. Along with his companion Sven Yorgen, he struggles to hold his ground on the northern edge of the Hushed Bank against the terrors that stalk the forest. Perched in a modest camp on the northern edge of the Hushed Bank, Lars ekes out a precarious survival far from the questionable safety of Darkshire. Duskwood is treacherous at the best of times, but the surrounding woods crawl with ferocious beasts, relentless undead, and creeping worgen. Lars stays close by Sven Yorgen, striving simply to stay alive in an increasingly hostile wilderness. Survival at the camp requires constant vigilance against the local predators. Lars finds himself sorely pressed by the relentless packs of starving dire wolves that haunt the shadows around their fire. Unable to lower his guard or drive them back alone, he relies on capable travelers to thin the hungry predators before his small camp is completely overrun.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lars-776ff9bd6d992492ccca/1-0000.mp3", duration = 60.5257143, start = 0},
  },
}
P.transport["npc:lelanai"] = {
  hash = "bc4b0b",
  fullHash = "bc4b0b",
  text = "Lelanai. In Darnassus, Lelanai cares for the night elves’ saber mounts in the Cenarion Enclave. She offers nightsabers and swift war beasts to her kin and trusted allies of the city. Lelanai tends the great cats of Kalimdor in the Cenarion Enclave, beside riding instructor Jartsam. Night elves have long bonded with the fierce predators of northern forests. They train nightsabers and frostsabers to carry sentinels and scouts across rugged ground with a predator’s grace. In the capital, Lelanai provides these mounts to riders. Lelanai offers saber mounts to night elves with the proper skill, while outsiders face a higher bar. The cats are sacred to the kaldorei, who keep their distance from strangers. She entrusts a mount to a non-night elf only when they have earned the highest respect and renown with Darnassus.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lelanai-dd5236081568f51708e6/1-0000.mp3", duration = 50.4163265, start = 0},
  },
}
P.transport["npc:lieutenant-haggerdin"] = {
  hash = "233c07",
  fullHash = "233c07",
  text = "Lieutenant Haggerdin. Lieutenant Haggerdin is a dwarven officer stationed upon the Headland in the Alterac Mountains. Standing watch outside the fortified gate to Alterac Valley, he acts as the primary recruitment and liaison officer for the Stormpike Guard. He evaluates aspiring Alliance champions and rewards those who prove their valor against the Frostwolf Clan. Perched in the snowy heights of the Headland above the Hillsbrad Foothills, Lieutenant Haggerdin oversees the muster point for the Alliance's ongoing campaign in Alterac Valley. Dwarven banners flutter beside the massive wooden gate as recruits and veterans assemble under his watchful eye, preparing to plunge into the frigid warzone. Serving the Stormpike Expedition, Haggerdin ensures that only tested warriors represent Ironforge and the Grand Alliance in the valley. Through challenges like the Proving Grounds, he tasks recruits with recovering banners and relics, and bestows official commendations, insignias, and rank recognitions as soldiers rise through the ranks of the Stormpike Guard.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lieutenant-haggerdin-4bbfc362f6bb4ad0032b/1-0000.mp3", duration = 61.1265306, start = 0},
  },
}
P.transport["npc:lieutenant-lisande"] = {
  hash = "cd98ac",
  fullHash = "cd98ac",
  text = "Lieutenant Lisande. Lieutenant Lisande is an emissary of the Argent Dawn stationed upon the high mesas of Thunder Bluff. As a human operating openly in tauren lands, she serves as a liaison against the shared existential threat of the Scourge. While human faces are rare across the windblown heights of Thunder Bluff, the Argent Dawn transcends traditional faction enmities. Lieutenant Lisande serves the holy order by watching for signs of the Lich King's taint even in remote Kalimdor. When undead forces stir on the plains below, she rallies brave Horde champions to ride out and investigate the encroaching menace before it can defile the sacred earth.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lieutenant-lisande-f14201e51132778254fc/1-0000.mp3", duration = 36.8326531, start = 0},
  },
}
P.transport["npc:lieutenant-nevell"] = {
  hash = "66d30e",
  fullHash = "66d30e",
  text = "Lieutenant Nevell. Lieutenant Nevell is an officer of the Argent Dawn stationed outside the gates of Ironforge in Dun Morogh. Serving as a bulwark against the spreading darkness of the Scourge, he coordinates local defenders and alerts arriving adventurers to undead threats probing the dwarf kingdom's borders. While the Argent Dawn is most renowned for holding the line in the shattered Plaguelands of Lordaeron, its vigilance reaches far into the south. Stationed in the freezing winds outside Ironforge, Lieutenant Nevell represents the order's proactive defense against necromantic incursions. When Scourge activity stirs in the mountain passes of Dun Morogh, Nevell directs recruits and capable adventurers toward the front lines to ensure Ironforge's snowy doorstep remains secure.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lieutenant-nevell-07bb01e34e7d381991b2/1-0000.mp3", duration = 43.5983673, start = 0},
  },
}
P.transport["npc:lieutenant-orrin"] = {
  hash = "3b973b",
  fullHash = "3b973b",
  text = "Lieutenant Orrin. At Stormwind's gates, Lieutenant Orrin watches for Scourge incursions and calls for scouts. The Argent Dawn officer stands in the Valley of Heroes, where he directs recruits to investigate undead threats beyond the capital. Lieutenant Orrin watches the road from the Valley of Heroes. The Argent Dawn is known for holding the front lines in the ruined north, but it also guards strongholds farther south, including Stormwind City. When necromantic magic stirs beyond the capital, Orrin sounds the alarm and rallies adventurers before the undead can threaten the people within. Lieutenant Orrin connects the Argent Dawn with volunteers in the southern kingdom. When signs of the Scourge appear beyond Stormwind's gates, he sends scouts to gather intelligence and secure hazardous artifacts. Cracked necrotic crystals are among the objects they recover, helping the order understand and repel the undead threat.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lieutenant-orrin-03793c7393f787e43f94/1-0000.mp3", duration = 54.0995918, start = 0},
  },
}
P.transport["npc:loganaar"] = {
  hash = "f2552d",
  fullHash = "f2552d",
  text = "Loganaar. Loganaar is a night elf druidic instructor residing in the haven of Nighthaven in Moonglade. Dedicated to guiding initiates from both the Alliance and the Horde, he instructs young druids as they attune to the wild and prepare for the call of the Emerald Dream. Situated amidst the serene boughs of Nighthaven, Loganaar serves as a primary mentor to newly initiated druids traveling to Moonglade. Regardless of whether an initiate hails from Darnassus or Thunder Bluff, Loganaar provides guidance in balance, shape-shifting, and reverence for nature. He reminds his students that even within cold stone and unfamiliar lands, true tranquility must be found within oneself. He also acts as a welcoming guide for those journeying deeper into the Cenarion Circle's affairs, sending promising students to wanderers like Torwa Pathfinder in Un'Goro Crater or deeper into ancient woodland rites. Beyond fundamental spellcraft, Loganaar prepares students for the ultimate destiny shared by Kalimdor's traditional protectors: the deep slumber of the Emerald Dream. He instructs initiates on the sacred connection between Azeroth's primal spirit realm and the waking world, reminding them that true mastery will one day require hibernating for centuries to walk among nature's purest, unblemished forms under the guidance of the demigods.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_loganaar-e55f70f0a44400c1db7b/1-0000.mp3", duration = 81.6326531, start = 0},
  },
}
P.transport["npc:lomac-gearstrip"] = {
  hash = "8ae00f",
  fullHash = "8ae00f",
  text = "Lomac Gearstrip. Lomac Gearstrip is an ambitious gnome inventor based in Tinker Town within Ironforge. Renowned for formulating the devastating NG-5 explosive, he liaises with fellow gnomish researchers operating across Kalimdor. Amid the clanging gears and hissing pipes of Ironforge's Tinker Town, Lomac Gearstrip pursues the finer points of gnomish ordnance. Like many exiled gnomes who fled the tragedy at Gnomeregan, Lomac has integrated his tinkering operations directly into the dwarven capital. His workshop focuses on volatile chemical mixtures and specialized munitions designed to overcome heavily defended enemy strongholds. Lomac's proudest contribution to modern combat engineering is the NG-5 explosive. Formulated for maximum destructive yield, the compound demands precise handling and rare chemical reagents. To refine and deploy such hazardous inventions in the field, Lomac maintains contact with old colleagues stationed in distant theaters, exchanging technical orders and dangerous supplies across the Great Sea.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lomac-gearstrip-79f4f5f28c2459aaaae4/1-0000.mp3", duration = 63.4253061, start = 0},
  },
}
P.transport["npc:longbraid-the-grim"] = {
  hash = "a2da55",
  fullHash = "a2da55",
  text = "Longbraid the Grim. Longbraid the Grim is an Ironforge dwarf commander stationed just outside the fallen fortress of Dun Modr in the northern Wetlands. Mourning the loss of his brother and the overrun of the Thandol Span, he coordinates the surviving dwarf forces against the invading Dark Iron clan. Positioned within sight of the bridge to the Arathi Highlands, Longbraid the Grim rallies what remains of the dwarven garrison after the Dark Iron clan seized Dun Modr. The sudden assault devastated the regional defenders and resulted in the death of Longbraid's own brother during the siege of the Thandol Span. Burdened by grief and hatred, Longbraid refuses to abandon the northern boundary, directing travelers and surviving mountaineers in surgical strikes to curb the Dark Iron advance. Beyond defending the approach to the bridge, Longbraid oversees broader dwarven operations across the Wetlands. He dispatched vital soldiers to escort Prospector Whelgar into the marshlands and works relentlessly to reclaim the lost fortifications of Dun Modr, vowing retribution against the Dark Iron saboteurs.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_longbraid-the-grim-678b450b35c6e138a903/1-0000.mp3", duration = 65.0710204, start = 0},
  },
}
P.transport["npc:loramus-thalipedes"] = {
  hash = "615e4e",
  fullHash = "615e4e",
  text = "Loramus Thalipedes. Loramus Thalipedes is a reclusive night elf demon hunter secluded on a remote isle off the coast of Azshara. Flanked by loyal felhounds, he dedicates his existence to destroying Razelikh the Defiler, directing seasoned champions through rituals to strike down the dreadlord. Perched on a solitary, storm-tossed island southeast of Hetaera's Clutch, Loramus Thalipedes stands apart from the rest of his kin. He is a demon hunter—an exile who underwent the agonizing ritual of blinding himself to gain spectral sight. Surrounded by three towering felhounds named Raytaf, Shahiar, and Zaman, Loramus watches the unseen currents of demonic corruption across Azeroth while keeping a watchful vigil over the shattered ruins of Azshara.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_loramus-thalipedes-e9bec468b00bc161d8bd/1-0000.mp3", duration = 45.1134694, start = 0},
  },
}
P.transport["npc:lord-arkkoroc"] = {
  hash = "a5ed65",
  fullHash = "a5ed65",
  text = "Lord Arkkoroc. Lord Arkkoroc is an ancient, towering sea giant who dwells within the ruined Temple of Arkkoran along the ragged coast of Azshara. Described by the demon hunter Loramus Thalipedes as a lesser deity, he holds sway over the surrounding waters and commands lesser sea giants who serve as his sons. Reclining amidst the brine-crusted ruins of the Temple of Arkkoran, Lord Arkkoroc is far more than a typical sea giant. To hermits like Loramus Thalipedes, this colossal being is considered a lesser deity whose divine will shapes the surrounding waters. His sons patrol the crags and shallows around the sanctuary, enforcing his quiet dominion over Azshara's tempestuous shores.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lord-arkkoroc-9ee3f4b58d7b0272a3e9/1-0000.mp3", duration = 43.8595918, start = 0},
  },
}
P.transport["npc:lord-baurles-k-wishock"] = {
  hash = "95e9b0",
  fullHash = "95e9b0",
  text = "Lord Baurles K. Wishock. In Stormwind Keep, Lord Baurles K. Wishock lives among the petitioners and dignitaries. Barkeeps know him for unpaid tabs and a taste for strong drink, but his nights in the city’s underbelly brought him near darker dealings. Lord Baurles K. Wishock moves among petitioners and dignitaries in Stormwind Keep, where he belongs to the influential House of Nobles. Though his station is high, he often drinks in the Mage Quarter’s dive bars, especially the Slaughtered Lamb, and leaves large bills unpaid. There, he hears of a warlock coven practicing dark arts in cellars beneath the floorboards. Wishock sets out to have the tavern closed and asks fellow nobles for a formal investigation. Uncovering demonic cabals in Stormwind rarely goes unpunished.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lord-baurles-k-wishock-b91eff872d7949e780d4/1-0000.mp3", duration = 47.0465306, start = 0},
  },
}
P.transport["npc:lord-grayson-shadowbreaker"] = {
  hash = "685f96",
  fullHash = "685f96",
  text = "Lord Grayson Shadowbreaker. Lord Grayson Shadowbreaker is a veteran paladin commander of the Knights of the Silver Hand stationed within Stormwind's Cathedral of Light. One of the Alliance's foremost paladins, he trains budding champions of the Light and oversees the sacred, arduous trials required for senior paladins to claim their holy chargers. Lord Grayson Shadowbreaker stands among the foremost defenders of the Alliance, anchoring the order's presence in Stormwind City. A veteran of the Silver Hand, Grayson does not merely instruct recruits in martial skill; he tests their spiritual conviction. When promising knights demonstrate their readiness, Grayson dispatches them north toward the contested front lines of the Western Plaguelands to aid Commander Ashlam Valorfist at Chillwind Camp.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lord-grayson-shadowbreaker-9cfceae2ee091431d4c7/1-0000.mp3", duration = 45.035102, start = 0},
  },
}
P.transport["npc:lord-jorach-ravenholdt"] = {
  hash = "9f9316",
  fullHash = "9f9316",
  text = "Lord Jorach Ravenholdt. Lord Jorach Ravenholdt is the master of Ravenholdt, an elite guild of rogues and assassins operating out of a secluded estate in the Alterac Mountains. He directs the league's clandestine operations, training promising operatives while waging a bitter war against the regional bandits of the Syndicate. Lord Jorach Ravenholdt presides over the Assassin's League from his hidden manor nestled in the crags between Alterac and Hillsbrad. A nobleman of mysterious heritage, he opens his halls to outlaws, cutpurses, and assassins regardless of allegiance, provided they exhibit exceptional skill and respect his authority. Under his command, the league acts as both a fraternity for master thieves and an independent syndicate for wetwork and espionage. Ravenholdt harbors a fierce hatred for the Syndicate—the band of disgraced Alterac nobles turned outlaws—and routinely directs his subordinates and visiting freelancers to sabotage their camps and plunder their assets.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lord-jorach-ravenholdt-cf33fbb7553336212d8e/1-0000.mp3", duration = 58.0179592, start = 0},
  },
}
P.transport["npc:lord-maxwell-tyrosus"] = {
  hash = "aeb428",
  fullHash = "aeb428",
  text = "Lord Maxwell Tyrosus. Lord Maxwell Tyrosus is the supreme commander of the Argent Dawn, stationed at their forward redoubt of Light's Hope Chapel in the Eastern Plaguelands. A veteran paladin of the Silver Hand from the Third War, he guides the coalition's crusade against the Scourge and orchestrates strikes into blighted strongholds like Stratholme. Maxwell Tyrosus rode alongside Uther the Lightbringer during the catastrophic Third War, guarding the exits of Andorhal when the Scourge tore through the kingdom. After the fall of Lordaeron, he cast his lot with the Argent Dawn, an order that welcomes anyone willing to stand against the Scourge, in stark contrast to the human-only zealotry of the Scarlet Crusade. Tyrosus now leads the Argent Dawn and oversees the defenses of Light's Hope Chapel. From his command post within the chapel, he oversees broad military operations across the Plaguelands, including tactical assaults led by Duke Nicholas Zverenhoff against Baron Rivendare inside the ruins of Stratholme.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lord-maxwell-tyrosus-d67d75216ac50ae51180/1-0000.mp3", duration = 61.2571429, start = 0},
  },
}
P.transport["npc:lord-shalzaru"] = {
  hash = "c0fd60",
  fullHash = "c0fd60",
  text = "Lord Shalzaru. Lord Shalzaru is the tyrannical leader of the Hatecrest naga operating out of the Isle of Dread off the coast of Feralas. Ruling his serpentine followers with absolute cruelty, he oversees extensive excavations among the submerged and ruined elven settlements. His recent discovery of a strange, ancient relic has drawn the attention of outside investigators eager to wrest it from his grasp. Lord Shalzaru commands the Hatecrest naga, directing their presence along the southern coast of Feralas. From his subterranean lair within a cavern on the Isle of Dread, he enforces his rule through cruelty and ruthless authority. Under his command, the Hatecrest scour the ancient ruins of ancient Kalimdor, searching for forgotten treasures and powerful relics left behind from the Sundering. During excavations south of the primary ruins across the Isle of Dread, Shalzaru personally uncovered a strange, ancient relic. The purpose and power of this artifact remain a mystery, but its recovery by such a powerful naga warlord presents a clear threat. Operatives on the mainland seek brave champions to venture into the serpent's den, end Shalzaru's command, and secure the odd relic before the Hatecrest can turn it to darker ends.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lord-shalzaru-3bc6c08cc344dd547818/1-0000.mp3", duration = 74.6318367, start = 0},
  },
}
P.transport["npc:lorekeeper-raintotem"] = {
  hash = "67f0f0",
  fullHash = "67f0f0",
  text = "Lorekeeper Raintotem. Lorekeeper Raintotem is a tauren elder stationed in northern Mulgore just south of Red Rocks. He tends to the sacred burial grounds and asks adventurers to drive off the Bristleback quilboar disturbing them. Positioned near the sacred bluffs of Red Rocks in Mulgore, Lorekeeper Raintotem tends to the spiritual obligations of his people. He asks adventurers to drive Bristleback Interlopers from the burial ground, restoring peace to the ancestors' resting place. Beyond testing fledgling heroes, Lorekeeper Raintotem watches over the hallowed burial sites at Red Rocks. When Bristleback quilboar interlopers disturb the sanctified resting places of deceased tauren chieftains and shamans, Raintotem enlists travelers to restore dignity and quiet the disturbed dead.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lorekeeper-raintotem-ade483dda57e9d94af9e/1-0000.mp3", duration = 46.2106122, start = 0},
  },
}
P.transport["npc:loslor-rudge"] = {
  hash = "de7d37",
  fullHash = "de7d37",
  text = "Loslor Rudge. Loslor Rudge is an enterprising dwarven engineering supplier stationed at Steelgrill's Depot in Dun Morogh. He provides mechanical parts, tools, and munitions to tinkerers across the snowy mountain ridges, keeping critical connections open with gunsmiths like Hegnar Rumbleshot. Operating out of Steelgrill's Depot just down the road from Kharanos, Loslor Rudge keeps a steady inventory of engineering essentials—ranging from copper modulators and bronze tubing to blasting powder and spanners. Dun Morogh's harsh weather and sprawling tinker operations mean practical parts are constantly in demand, and Loslor prides himself on keeping the local gearheads supplied. However, the wilderness between outposts is treacherous; when a courier taking a shortcut near the Grizzled Den was chased away by wendigos, an essential shipment of ammunition meant for his valued client, gunsmith Hegnar Rumbleshot, was left behind in the snow.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_loslor-rudge-1a82353fff37b2936dba/1-0000.mp3", duration = 59.3763265, start = 0},
  },
}
P.transport["npc:lotwil-veriatus"] = {
  hash = "c3c2c3",
  fullHash = "c3c2c3",
  text = "Lotwil Veriatus. Lotwil Veriatus is an eccentric gnomish scholar conducting dangerous elemental experiments in the dusty wastes of the Badlands. Stationed east of Kargath with his sarcastic apprentice Lucien Tosselwrench and a mechanical attendant named Servo, he is dedicated to blending arcane theory, alchemy, and engineering into a unified discipline. Originally from Kharanos in Dun Morogh, Lotwil envisions a grand University for his Enlightened Assembly of Arcanology, Alchemy, and Engineering Sciences. He believes these three disciplines should not be practiced in isolation, but harmonized. In pursuit of this dream, he chose the harsh Badlands as his laboratory to study native rock elementals and construct binding shackles capable of mastering elemental forces. While an accomplished researcher—having studied elemental machines and defeated dark iron constructs in the past—his single-minded focus often blinds him to the explosive hazards of his fieldwork.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lotwil-veriatus-1f7bc01571edfe11a918/1-0000.mp3", duration = 57.8089796, start = 0},
  },
}
P.transport["npc:lucius"] = {
  hash = "2cdae8",
  fullHash = "2cdae8",
  text = "Lucius. At the Lakeshire docks, Lucius watches the Redridge waterfront. The dwarf works undercover for Stormwind’s SI:7, helping agents with reconnaissance and trade skills. Lucius watches the Lakeshire docks for SI:7, Stormwind’s intelligence service. He keeps an eye on trade, unusual traffic, and threats moving into the Redridge Mountains. Agents sent east from Stormwind come to him to coordinate covert work and practice field skills such as lockpicking. Through Lucius, Stormwind keeps a hidden reach beyond Elwynn Forest.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lucius-b00a682b2857d64eedb1/1-0000.mp3", duration = 35.2914286, start = 0},
  },
}
P.transport["npc:lyria-du-lac"] = {
  hash = "48b103",
  fullHash = "48b103",
  text = "Lyria Du Lac. In Goldshire, Lyria Du Lac trains young warriors behind the village smithy. She teaches them to master their stances and arms. Lyria Du Lac trains young warriors in the yard behind Goldshire's forge. She teaches those fresh from Northshire Abbey, judges their readiness, and introduces specialized combat techniques. Warriors take up shield and blade for Stormwind, facing the threats of Elwynn Forest.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_lyria-du-lac-d83e16ba652e3d04a6bd/1-0000.mp3", duration = 26.4359184, start = 0},
  },
}
P.transport["npc:ma-stonefield"] = {
  hash = "7e39fc",
  fullHash = "7e39fc",
  text = "Ma Stonefield. At Stonefield Farm in western Elwynn, Ma Stonefield tends to hardships close to home. Beside Auntie Bernice, she faces farm troubles, neighboring rivalries, and pests. Ma Stonefield watches over the farm beside her family cottage in southwestern Elwynn Forest, with Auntie Bernice Stonefield at her side. The neighboring Maclure homestead and nearby pumpkin patches bring little peace. Wild boars threaten the Stonefield crops, and Princess causes the greatest trouble. The enormous prize sow tramples fields and devours the harvest the family worked hard to grow.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ma-stonefield-299280a6b6cb85108b85/1-0000.mp3", duration = 37.6163265, start = 0},
  },
}
P.transport["npc:mad-magus-tirth"] = {
  hash = "808534",
  fullHash = "808534",
  text = "Magus Tirth. Magus Tirth is an eccentric human wizard dwelling out on the salt flats of the Mirage Raceway in Thousand Needles. Known locally for breeding chickens and tormenting his polymorphed apprentice, he is also a scholar of formidable arcane lore who has squandered valuable tomes on racing bets. While most mages of his caliber study in the libraries of Dalaran or Stormwind, Magus Tirth has taken up residence amid the grease and roar of the Shimmering Flats. Surrounded by speeding rocket cars, Tirth peddles chickens to passersby, drinks, gambles, and has long since cursed his unfortunate apprentice, 'Plucky' Johnson, into poultry form. Despite this eccentric demeanor, Tirth possesses genuine arcane mastery, having authored esoteric texts on magical power before losing them to reckless wagers on the speedway.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mad-magus-tirth-55913d22aa03ec0a1eea/1-0000.mp3", duration = 50.0244898, start = 0},
  },
}
P.transport["npc:magga"] = {
  hash = "315e7f",
  fullHash = "315e7f",
  text = "Magga. Near the Den in the Valley of Trials, Magga welcomes new arrivals. The orc lives in Durotar and greets Horde travelers beginning their journey through the valley. Young orcs and Darkspear trolls first meet the wider world in the Valley of Trials. Near the Den, Magga greets those arriving in the valley. Trainers and recruits keep busy nearby, while Magga helps bring the small camp together.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_magga-a158b8660e4d3fd227d8/1-0000.mp3", duration = 24.4244898, start = 0},
  },
}
P.transport["npc:magis-sparkmantle"] = {
  hash = "100e4f",
  fullHash = "100e4f",
  text = "Magis Sparkmantle. Magis Sparkmantle is a gnome mage trainer stationed inside the Thunderbrew Distillery in Kharanos. He offers guidance and training to fledgling spellcasters who venture out from Coldridge Valley into the heart of Dun Morogh. While dwarves gather in the Thunderbrew Distillery for hearty ales, Magis Sparkmantle provides an arcane presence among the casks and kegs of Kharanos. Gnome mages often integrate closely with their dwarven allies across Dun Morogh, and Sparkmantle serves as a key mentor for novice spellcasters ready to expand their theoretical and practical grasp of the arcane arts. Beyond instructing novices in basic incantations, Magis ensures that promising students connect with broader magical circles. When mages outgrow early local instruction or require specialized guidance, Sparkmantle directs them further afield, sending them toward fellow practitioners like Bink or mentors stationed across the Alliance's primary hubs.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_magis-sparkmantle-e28add57e5a8eb4c92e6/1-0000.mp3", duration = 56.5028571, start = 0},
  },
}
P.transport["npc:magistrate-henry-maleb"] = {
  hash = "d0ff8b",
  fullHash = "d0ff8b",
  text = "Magistrate Henry Maleb. Magistrate Henry Maleb oversees civic administration in the port town of Southshore, the Alliance's primary coastal bastion in the Hillsbrad Foothills. Tasked with maintaining order amid constant threats, he focuses much of his authority on hunting down the Syndicate conspirators targeting the town's leadership. Operating from the town hall in Southshore, Magistrate Henry Maleb handles civil governance for one of the last true Alliance settlements in Lordaeron. The town sits under constant siege from the Forsaken to the north and West, while ruthless highwaymen prowl the foothills. Maleb stepped into his current station after the mysterious assassination of the prior magistrate, an act he attributes directly to the Syndicate. Determined not to suffer the same fate, he coordinates active investigations to root out hidden assassins, dismantle Syndicate supply networks, and unmask the rogue nobles pulling the strings from the ruins of Alterac.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_magistrate-henry-maleb-14f10a7d2aff404eea45/1-0000.mp3", duration = 54.2302041, start = 0},
  },
}
P.transport["npc:magus-rimtori"] = {
  hash = "4995f6",
  fullHash = "4995f6",
  text = "Magus Rimtori. Magus Rimtori is a rogue blood elf sorceress leading an expedition among the ancient ruins of Azshara. Known for her ruthless deception, she manipulated the Horde into securing her passage across Kalimdor before butchering her orcish escort. Magus Rimtori led an expedition of high-borne blood elves across the sea to the ancient shores of Azshara. To ensure her party survived the perils of Kalimdor, she manipulated the orc Belgrom, charming and playing him until he agreed to supply an armed escort. Once the soldiers had delivered her safely to her destination, Rimtori revealed her true colors, turning on her protectors and massacring the entire garrison. Establishing her forces at the Thalassian Base Camp, she ventured out into the coastal wilds accompanied by elite bodyguards to hunt for forgotten magical artifacts.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_magus-rimtori-0515281ddbb8d13c628e/1-0000.mp3", duration = 49.5281633, start = 0},
  },
}
P.transport["npc:mai-ah"] = {
  hash = "942b9c",
  fullHash = "942b9c",
  text = "Mai'ah. At the Valley of Trials in Durotar, Mai'ah trains young Darkspear trolls in magic. She guides new spellcasters as they begin their path among the Horde. Young Darkspear trolls come to Mai'ah in the Valley of Trials to learn magic. Orcs favor the elements or the warrior's path, but trolls have a rare gift for arcane study. Candidates bring glyphic inscriptions, and Mai'ah teaches them to shape raw power into controlled incantations. That control matters in Durotar, where danger waits beyond the den.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mai-ah-26c917d792f7972af7dd/1-0000.mp3", duration = 31.8432653, start = 0},
  },
}
P.transport["npc:major-mattingly"] = {
  hash = "f80c74",
  fullHash = "f80c74",
  text = "Major Mattingly. At Stormwind’s main gates, Major Mattingly helps guard the capital and advises crafters on protection from dragons. Major Mattingly is a high-ranking officer responsible for Stormwind City's landward defense. He stands watch in the Valley of Heroes under General Marcus Jonathan, alongside the city's garrison. His duties include overseeing gate patrols and travelers entering the city. Mattingly also knows the lethal nature of dragons and guides skilled crafters who seek to make protective dragonscale gear for facing dangerous lairs.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_major-mattingly-0f25ef2645ccec30b2ff/1-0000.mp3", duration = 31.9477551, start = 0},
  },
}
P.transport["npc:major-samuelson"] = {
  hash = "77e3f1",
  fullHash = "77e3f1",
  text = "Major Samuelson. In Stormwind Keep, Major Samuelson commands the city guard and its personnel. The high-ranking veteran officer serves in the throne room and once mentored Lieutenant Farren Orinelle. Before Stormwind's royal court, Major Samuelson leads the Stormwind City Guard. He oversees officer postings and military orders across the realm. He mentored Lieutenant Farren Orinelle, who serves at Southshore in the Hillsbrad Foothills. When junior commanders struggle or seek transfer from distant frontier garrisons, their requests and official reports travel across the kingdom to Samuelson's desk in the capital.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_major-samuelson-97442a590398014acffa/1-0000.mp3", duration = 37.9297959, start = 0},
  },
}
P.transport["npc:mankrik"] = {
  hash = "3c7ae6",
  fullHash = "3c7ae6",
  text = "Mankrik. At the Crossroads, Mankrik carries grief and a thirst for vengeance. A quilboar ambush separated him from his wife, Olgra, and he now hunts the bristled beasts across the Barrens. Mankrik and his wife Olgra traveled through the Barrens when quilboar swarmed them during a skirmish at a small tauren settlement. The fighting tore them apart, and Mankrik saw Olgra vanish beneath tusks and thorn-woven weapons. Fury drove him to fight recklessly until a blow left him unconscious. Along the Gold Road, a passing tauren druid found Mankrik bleeding out and bound his injuries. He survived the ambush, but Olgra was gone. At the Crossroads, Mankrik recovers, paralyzed by grief and consumed by bloodlust. Thork and other local leaders warn that hatred has clouded his judgment, and they refuse to send official war parties. Mankrik refuses to move on. Uncertain of Olgra's fate, he calls on any willing Horde travelers to search the Barrens for signs of his lost mate and slaughter any quilboar they meet.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mankrik-0751ff9d406f8ba09fc5/1-0000.mp3", duration = 66.0636735, start = 0},
  },
}
P.transport["npc:marcus-redpath"] = {
  hash = "a076c7",
  fullHash = "a076c7",
  text = "Marcus Redpath. Marshal Marcus Redpath is the senior military authority defending the Alliance town of Southshore in the Hillsbrad Foothills. He organizes patrols and bounty contracts to hold off surrounding ogres, murlocs, and naga. His leadership is essential to maintaining Lordaeron's last southern bastion on the coast. Marcus Redpath is the marshal of Southshore, the Alliance port on the southern coast of the Hillsbrad Foothills. Southshore endured the fall of Lordaeron's capital and the devastating Scourge invasion, and Redpath now stands at the head of its defense, guarding the port's beleaguered survivors. In the wake of the Third War, Southshore stands virtually alone against hostile forces pressing in from every side. Marshal Redpath coordinates defense operations across the Hillsbrad Foothills, enlisting seasoned adventurers to push back the Crushridge ogres creeping down from Alterac and purge dangerous naga and murloc encampments along the coastline. With the Forsaken occupying the north and Tarren Mill heavily fortified nearby, Redpath's vigilance is one of the few barriers preventing the regional Alliance presence from collapsing entirely.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_marcus-redpath-02d22b6ae12628ddbd71/1-0000.mp3", duration = 68.8587755, start = 0},
  },
}
P.transport["npc:mardant-strongoak"] = {
  hash = "e9f8c2",
  fullHash = "e9f8c2",
  text = "Mardant Strongoak. Mardant Strongoak is a night elf druid trainer residing in Aldrassil in the heart of Teldrassil. He guides fledgling druids in communing with the spirits of nature and introduces them to the mysteries of the Emerald Dream. Within the boughs of Aldrassil, young night elves who feel the call of the wild turn to Mardant Strongoak. His primary task is teaching novitiates how to open their senses to nature spirits, interpret their murmurs, and channel rejuvenating magics. For those taking their initial steps as protectors of the wild, he is often the first master to unveil the vast complexities and ancient perils of the Emerald Dream.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mardant-strongoak-33ae4fbd25822c5677d1/1-0000.mp3", duration = 40.4897959, start = 0},
  },
}
P.transport["npc:marek-ironheart"] = {
  hash = "de3fd0",
  fullHash = "de3fd0",
  text = "Marek Ironheart. Marek Ironheart is a veteran dwarven hunter stationed at the Farstrider Lodge in south-eastern Loch Modan. Dedicated to the traditions of the wild, he tests wandering travelers and marksmen alike before welcoming them into the ranks of the lodge's honored hunters. Perched on the scenic ridge overlooking the lake, the Farstrider Lodge serves as an outpost for the finest marksmen and trackers in the dwarven lands. Marek Ironheart embodies this frontier spirit. Unimpressed by titles or talk, Marek requires anyone seeking the lodge's respect to demonstrate their practical prowess against the varied beasts roaming Loch Modan, proving they have the patience and nerve demanded of a true stalker of the wild.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_marek-ironheart-4e6cff3659c9ab55a114/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["npc:marisa-du-paige"] = {
  hash = "4b42b7",
  fullHash = "4b42b7",
  text = "Marisa du'Paige. In the caves outside the Deadmines, Marisa du'Paige fights beside Moonbrook's outlaws. Rare among their laborers and highwaymen, she uses arcane magic in the tunnels of southwestern Westfall. Deep in the caves leading toward the Deadmines beneath Moonbrook, cutpurses, renegade miners, and thugs guard the tunnels. Marisa du'Paige is a skilled human mage among them. Many spellcasters train in Stormwind's Mage Quarter or serve the Kirin Tor, but Marisa has joined the outlaws and brigands in Westfall's underground passages.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_marisa-du-paige-afd3e6be96684be91d7b/1-0000.mp3", duration = 34.8995918, start = 0},
  },
}
P.transport["npc:marleth-barleybrew"] = {
  hash = "797478",
  fullHash = "797478",
  text = "Marleth Barleybrew. Marleth Barleybrew is an ambitious dwarven brewer stationed out in Brewnall Village. Frustrated by the Thunderbrew clan's dominance over the local beer market, she constantly schemes to prove her family's brew is superior to Kharanos's famous Thunder Ale. In Dun Morogh, alcohol is taken as seriously as steel, and the rivalry between the Barleybrew and Thunderbrew families is legendary. Marleth Barleybrew resents the near-monopoly that Ragnar Thunderbrew and his kin maintain out of the Thunderbrew Distillery in Kharanos. Convinced her own craft is every bit as robust, she seeks clever ways to slip Barleybrew kegs into the hands of tavern patrons. Rather than engaging in open conflict, she opts for petty subterfuge, recruiting passing travelers to secretly swap out Kharanos's prized ale casks with her own.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_marleth-barleybrew-b9372df6bb711ae98c0d/1-0000.mp3", duration = 48.9273469, start = 0},
  },
}
P.transport["npc:marryk-nurribit"] = {
  hash = "cabab4",
  fullHash = "cabab4",
  text = "Marryk Nurribit. Marryk Nurribit is the resident gnome mage trainer stationed at Anvilmar in Coldridge Valley. A bit more fond of local brews than disciplined pedagogy, he introduces fledgling gnomish arcanists to their craft while frequently soliciting spare coins for a drink. Tucked away inside the warm hearth of Anvilmar, Marryk Nurribit offers arcane guidance to young gnomes taking their very first steps into magic. Though knowledgeable in the arcane arts, his demeanor is decidedly casual—often seeming far more interested in nursing a flagon of dwarven ale and bumming spare pocket change off his new pupils than drilling them in complex theorems. Despite his vices, Marryk remains acutely aware of the perils outside Coldridge Valley, regularly warning aspiring spellcasters about the lingering radioactive and trogg-infested horrors of fallen Gnomeregan.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_marryk-nurribit-f5f2719c74b101c39e0f/1-0000.mp3", duration = 53.3681633, start = 0},
  },
}
P.transport["npc:marshal-maxwell"] = {
  hash = "ee13cb",
  fullHash = "ee13cb",
  text = "Marshal Maxwell. Marshal Maxwell is a high-ranking officer of the Stormwind army stationed at Morgan's Vigil in the Burning Steppes. Tasked with holding the Alliance's northernmost fortified ridge above the Redridge Mountains against the Blackrock clan and the Dark Iron dwarves, he directs scouting missions into the hostile crags below. He also plays a crucial role in coordinating efforts to discover the fate of his captured comrade, Marshal Reginald Windsor. Morgan's Vigil stands as a precarious outpost on the southern rim of the Burning Steppes, overlooking a wasteland choked with ash, dragonkin, and Blackrock orcs. Marshal Maxwell commands the Stormwind military detachment stationed here, providing a rare friendly sight for travelers braving the fiery crags. From this rocky bastion, he oversees defensive maneuvers to keep the hostile forces of the mountain contained before they can sweep southward into Redridge and Elwynn.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_marshal-maxwell-b7a0f33e5d261a031a68/1-0000.mp3", duration = 54.3085714, start = 0},
  },
}
P.transport["npc:martie-jainrose"] = {
  hash = "c20cb3",
  fullHash = "c20cb3",
  text = "Martie Jainrose. Martie Jainrose is Lakeshire's local herbalist, tending to her garden along the edge of Lake Everstill in the Redridge Mountains. Beside cultivating remedies and flowers for the beleaguered town, she contends with wild beasts trampling her plots and harbors a quiet affection for Guard Parker. Residing in Lakeshire, Martie Jainrose works diligently as the settlement's resident herbalist. Even as Blackrock orcs, gnolls, and local brigands threaten the region, Martie focuses on keeping the town supplied with fresh herbs and floral arrangements. Her daily labors are often disrupted by local wildlife—most notably the monstrous boar Bellygrub, who frequently ravages her prized garden beds. Beyond her herbal pursuits, Martie seems to hold a fondness for Guard Parker, though Parker is courting Darcy, who calls Martie a jealous rival.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_martie-jainrose-e7df128b8ffd61c3c69f/1-0000.mp3", duration = 51.2, start = 0},
  },
}
P.transport["npc:marukai"] = {
  hash = "c6b5d3",
  fullHash = "c6b5d3",
  text = "Marukai. Marukai is a Darkspear jungle troll stationed at Zoram'gar Outpost along the foggy coast of northwest Ashenvale. Dedicated to holding this remote beachhead for the Horde, she coordinates efforts to cull the encroaching Wrathtail naga who threaten the outpost. Zoram'gar Outpost sits isolated on the northern edge of the Zoram Strand, surrounded by ancient ruins, hostile night elf territory, and the restless sea. As the Wrathtail naga emerge in force from the waters and ancient elven ruins to claim the shoreline, Marukai works to keep the encampment from being overwhelmed. She directs Horde champions to push the serpent-folk back into the tide and collect their heads, ensuring the outpost remains a viable coastal stronghold.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_marukai-5905a11e7074cc2c9e00/1-0000.mp3", duration = 44.1208163, start = 0},
  },
}
P.transport["npc:master-apothecary-lydon"] = {
  hash = "fe0c54",
  fullHash = "fe0c54",
  text = "Apothecary Lydon. Apothecary Lydon is a morbid researcher of the Royal Apothecary Society stationed in Tarren Mill. Chronically depressed and intensely bored, he finds joy only in refining lethal concoctions and watching the living suffer. He spearheads the research into potent new toxins aimed at securing Hillsbrad for the Forsaken and furthering Sylvanas's New Plague. Stationed inside the chapel turned laboratory of Tarren Mill, Apothecary Lydon represents the cold, calculating ethos of the Royal Apothecary Society. He is afflicted by a profound, languid melancholy, disgusted by the blooming flowers and crisp air of Hillsbrad Foothills. The only diversion that lifts his perpetual gloom is the art of deathcraft. When left unattended, he passes the time poisoning, dissecting, and reanimating his unfortunate pet frog, Umpi, repeatedly waiting for new reagents to arrive.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_master-apothecary-lydon-9521a3548c5b677e7669/1-0000.mp3", duration = 55.797551, start = 0},
  },
}
P.transport["npc:master-vornal"] = {
  hash = "d7d66f",
  fullHash = "d7d66f",
  text = "Master Vornal. In Sen'jin Village, Master Vornal brews for the Darkspear trolls and keeps his craft to himself. The elderly jungle troll refuses to take on apprentices despite his deep knowledge of alchemy. Master Vornal brews draughts and spirits for his fellow Darkspear trolls in Sen'jin Village. Age is catching up with him, but he remains fiercely independent and refuses to train an apprentice. He mixes his remedies and volatile brews by his own hand. Master Vornal sometimes sends young adventurers to gather harsh or unusual ingredients from the surrounding lands. The materials go into solvents and other mixtures. He rewards those who help, but guards his methods and recipes, keeping the work of brewing to himself.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_master-vornal-c58ee43f74fe886a4189/1-0000.mp3", duration = 45.2963265, start = 0},
  },
}
P.transport["npc:mastok-wrilehiss"] = {
  hash = "890b8b",
  fullHash = "890b8b",
  text = "Mastok Wrilehiss. Mastok Wrilehiss is an orc officer stationed at Splintertree Post in eastern Ashenvale. Serving as a crucial defensive coordinator for the Horde in the contested forest, he directs scouts and warriors to secure nearby borders and handle corrupting elemental threats. His presence is vital for maintaining the precarious foothold the Horde holds amidst constant night elf hostility. Splintertree Post stands deep in the shadow of Ashenvale's towering canopy, completely surrounded by hostile night elven territory. Mastok Wrilehiss serves as one of the post's core defenders, monitoring supply routes and forest activity. The position is perilous; any sign of weakness invites swift strikes from the Sentinels who view the settlement as a despoiling intrusion. From his vantage within the stockade, Mastok actively tasks passing adventurers with critical strategic duties. He keeps watchful eyes on the borders leading into neighboring territories like the Stonetalon Mountains and dispatches scouts to consult shamans such as Je'neu Sancrea of the Earthen Ring at Zoram'gar Strand. His duties bridge military defense with monitoring the strange, corrupting forces afflicting the local elementals.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mastok-wrilehiss-66dd5e2d26bbded486e0/1-0000.mp3", duration = 71.1053061, start = 0},
  },
}
P.transport["npc:mathredis-firestar"] = {
  hash = "3b8d9a",
  fullHash = "3b8d9a",
  text = "Mathredis Firestar. Mathredis Firestar is an eccentric blood elf mage residing at Flame Crest in the Burning Steppes. He crafts powerful enchantments known as Lesser Arcanums, drawing upon the arcane research of his deceased master. In doing so, he feeds on the residual energies unleashed during the binding process to stave off his magic addiction. Mathredis Firestar learned the craft of making arcanums—concentrated gems of arcane empowerment—from his mentor, Telmius Dreamseeker. Telmius met a grim end within the ancient ruins of Dire Maul while trying to wrest magical secrets from the Shen'dralar. While Telmius invented these magical bindings, Mathredis lacks the mastery to produce the greatest of them. Instead, he specializes in Lesser Arcanums. For Mathredis, this work is far more than an academic exercise: like all blood elves following the fall of the Sunwell, he suffers from a gnawing hunger for arcane power. Binding materials to ancient librams releases violent discharges of magical energy, which Mathredis siphons to sustain himself. Adventurers who bring Mathredis the proper tomes—such as the Librams of Constitution, Resilience, Rumination, Tenacity, or Voracity—along with rare reagents will find him eager to trade his craft. The process binds volatile magical reagents directly to the text, concentrating their essence into an arcanum that can permanently enchant headwear or leg armor. So long as adventurers supply the components, Mathredis receives both payment and the ambient arcane sustenance he desperately craves.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mathredis-firestar-f8bc6fd78102a3ce9961/1-0000.mp3", duration = 95.4514286, start = 0},
  },
}
P.transport["npc:maur-grimtotem"] = {
  hash = "bd667b",
  fullHash = "bd667b",
  text = "Maur Grimtotem. Deep in Ragefire Chasm beneath Orgrimmar, Maur Grimtotem lies dead. Elder Crone Magatha Grimtotem sent him to seek peace with the troggs, and his remains and satchel are still in the caverns. Maur Grimtotem went into Ragefire Chasm beneath Orgrimmar as an envoy to the troggs. Most of the Horde saw them as savage brutes beyond negotiation, but Elder Crone Magatha Grimtotem thought peace might be possible, or at least said so. Maur carried her offer into the winding caverns. The troggs killed him, and his body remains under the watch of their chieftain, Oggleflint.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_maur-grimtotem-7eb72a3ca93e04ce6d0c/1-0000.mp3", duration = 37.2244898, start = 0},
  },
}
P.transport["npc:maur-raincaller"] = {
  hash = "efdb4e",
  fullHash = "efdb4e",
  text = "Maur Raincaller. Maur Raincaller is a tauren resident found residing in Bloodhoof Village in Mulgore. Connected to the natural and spiritual life of the plains, he assists the village elders and watches over local matters affecting the herds and wild beasts. Situated near the heart of Bloodhoof Village on the shores of Lake Stonebull, Maur Raincaller serves his community by attending to regional ecological and beast-related concerns. Like many who bear the mantle of Raincaller, he pays close attention to the balance of the elements and wildlife across the fertile plains of Mulgore. After a bite from the fearsome strider Mazzranache left his wound infected, Maur turns to capable young travelers to gather the animal parts he needs for a remedy.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_maur-raincaller-62e4b7211817636e0081/1-0000.mp3", duration = 44.042449, start = 0},
  },
}
P.transport["npc:maurin-bonesplitter"] = {
  hash = "d5b6f1",
  fullHash = "d5b6f1",
  text = "Maurin Bonesplitter. Maurin Bonesplitter is a Forsaken scholar and spellcaster stationed at Ghost Walker Post in Desolace. Appointed by Keldran to monitor demonic cult activity, he leverages his deep understanding of ancient lore to dismantle the Burning Blade. Maurin regards the cultists with sheer contempt, viewing them as fools blind to the dark entities pulling their strings. While Ghost Walker Post primarily serves as a tauren and Horde outpost amidst the arid wastes of Desolace, Maurin Bonesplitter stands apart as one of its few undead occupants. Rather than a brutish soldier, Maurin is a learned spellcaster possessing extensive knowledge of forbidden histories and occult forces. His arcane aptitude and sharp intellect caught the eye of Keldran, who dispatched him to the region to observe the growing demonic presence and coordinate targeted strikes against it. Maurin directs most of his malice toward the Burning Blade cult entrenched across Desolace. He harbors utter disgust for their reckless ambition, mocking the cultists for failing to understand that their borrowed power merely binds them as thralls to their demonic masters. Through scrying spells and ritual knowledge, Maurin enlists Horde adventurers to systematically disrupt the cult's summonings and undermine their operations across the barren landscape.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_maurin-bonesplitter-40a9fa0e0d20e2d3a101/1-0000.mp3", duration = 75.6506122, start = 0},
  },
}
P.transport["npc:maxan-anvol"] = {
  hash = "97d7ae",
  fullHash = "97d7ae",
  text = "Maxan Anvol. Maxan Anvol is a dwarven priest trainer stationed within the Thunderbrew Distillery in Kharanos. Dedicated to the Holy Light, he guides fledgling dwarven priests as they learn to channel divine power amid Dun Morogh's frigid climes. He tests young acolytes to ensure they are worthy of wearing the vestments of the church. While it might seem strange to find an ordained minister of the Holy Light stationed inside Thunderbrew Distillery, it suits dwarven culture well. Kharanos serves as the primary hub between Coldridge Valley and Ironforge, and the local inn is where travelers, mountaineers, and acolytes naturally gather. Maxan tends to the spiritual welfare of the hamlet alongside pints of stout, offering prayers and counsel to any who step through the doors. Maxan Anvol is responsible for vetting novice priests before they venture into the wider world. He tasks initiates with demonstrating mastery over fundamental curative prayers on wounded defenders of Dun Morogh. Those who prove their devotion and practical competence are bestowed their first proper priestly vestments, formally marking their recognized standing within the Church of the Holy Light.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_maxan-anvol-5dadb871f6a4799d6269/1-0000.mp3", duration = 67.8661224, start = 0},
  },
}
P.transport["npc:maybell-maclure"] = {
  hash = "40cfcc",
  fullHash = "40cfcc",
  text = "Maybell Maclure. At the Maclure Vineyards in Elwynn Forest, Maybell Maclure loves a Stonefield in secret. Her family’s bitter feud with the neighboring Stonefields keeps her apart from Tommy Joe Stonefield. Maybell Maclure works the family vineyards under the shadow of a long feud with the Stonefields next door. She has fallen in love with Tommy Joe Stonefield, heir to the rival farm. Their relatives keep them apart, and Maybell searches for a way to speak with him beyond her family’s watchful eyes.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_maybell-maclure-e88577b5193e4a941e69/1-0000.mp3", duration = 29.8057143, start = 0},
  },
}
P.transport["npc:melithar-staghelm"] = {
  hash = "43309e",
  fullHash = "43309e",
  text = "Melithar Staghelm. Outside Aldrassil in Shadowglen, Melithar Staghelm guides young night elves. He sends them to learn why the dryad Tarindrella has returned to the glade. His Staghelm name links him to Archdruid Fandral Staghelm, though their connection is unknown. Melithar Staghelm waits outside Aldrassil, where night elves first step into the world. A druid who listens to the forest spirits, he has learned that Tarindrella, a woodland protector, has returned to Shadowglen after years away. Sensing trouble, Melithar sends newcomers southwest of Aldrassil to find the dryad and learn why she has come back to the grove. The Staghelm name draws notice because Archdruid Fandral Staghelm leads the Cenarion Circle in Darnassus, after Malfurion Stormrage disappeared into the Emerald Dream. Melithar makes no claim to a grand heritage and says nothing of his lineage. Whether he belongs to the Archdruid's family or shares an ancient Kaldorei name remains unknown. For now, Melithar tends to his humble duties at the roots of Aldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_melithar-staghelm-bcfab332ad77db4f8956/1-0000.mp3", duration = 65.4367347, start = 0},
  },
}
P.transport["npc:merissa-stilwell"] = {
  hash = "eae90e",
  fullHash = "eae90e",
  text = "Merissa Stilwell. At Northshire Abbey, Merissa Stilwell welcomes newcomers to Northshire Valley. The young human townsperson offers a cheerful greeting and a helping hand to those training nearby. Merissa Stilwell greets fresh recruits arriving in Northshire Valley from her place at Northshire Abbey. She offers newcomers simple hospitality and practical advice on resting and finding their way. Her surname is shared by craftsmen and homesteaders across the kingdom, including the blacksmith Jordan Stilwell and the Westfall defender Daphne Stilwell. Merissa remains a peaceful local presence amid the kingdom's rising tensions.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_merissa-stilwell-df93be2c20c7472ee48a/1-0000.mp3", duration = 38.2432653, start = 0},
  },
}
P.transport["npc:merrin-rockweaver"] = {
  hash = "8aa5c7",
  fullHash = "8aa5c7",
  text = "Merrin Rockweaver. Merrin Rockweaver is a dwarven researcher representing the Explorers' League in the Wetlands. Following a violent raptor infestation that overran Whelgar's Excavation Site, she took refuge alongside Prospector Whelgar on a ridge overlooking the site. Merrin Rockweaver traveled to the Wetlands on behalf of the Ironforge Explorers' League to unearth ancient Titan secrets buried beneath the muck. The expedition ended in disaster when the large bones they unearthed drew raptors to the dig. Vicious prehistoric beasts swarmed the trenches, forcing Merrin and the surviving crew to abandon their equipment, notes, and progress. She is now trapped with the few survivors on a bluff overlooking the overrun ruins. Trapped on the bluff, the survivors refuse to let the expedition become an outright failure. While Ormer Ironbraid plots vengeance against the beasts and Prospector Whelgar seeks the tablet fragments left behind in the raptor-infested trenches, Merrin's thoughts turn to her husband Tarrel, who has not heard from her in weeks. She relies on the scout Longbraid sent to find the team to carry word of their plight back to him.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_merrin-rockweaver-3ecd5c8099b07bde5b98/1-0000.mp3", duration = 69.8253061, start = 0},
  },
}
P.transport["npc:miles-welsh"] = {
  hash = "231d0b",
  fullHash = "231d0b",
  text = "Miles Welsh. Miles Welsh is a Forsaken priest trainer residing deep within the Pools of Vision beneath Thunder Bluff. He offers spiritual instruction and shadow discipline to priests traversing the tauren capital. Miles Welsh stands far from the plague-scarred ruins of Lordaeron, making his home in the humid, spirit-laden grotto beneath Thunder Bluff known as the Pools of Vision. As a Forsaken priest, he instructs travelers who channel divine and shadowy energies. His presence in the heart of Mulgore reflects the tenuous diplomatic ties binding the Forsaken to the Horde, sharing sanctuary with tauren mystics and shamans while guiding acolytes in the arts of shadow and faith.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_miles-welsh-6d3eb29daa51580305dd/1-0000.mp3", duration = 41.1428571, start = 0},
  },
}
P.transport["npc:milli-featherwhistle"] = {
  hash = "722f10",
  fullHash = "722f10",
  text = "Milli Featherwhistle. Milli Featherwhistle is a master gnomish mechanostrider engineer stationed at Steelgrill's Depot in Dun Morogh. Following the fall of Gnomeregan, she meticulously handcrafts and maintains the clockwork mounts favored by her kin. She sells her prized mechanical creations to fellow gnomes and trusted allies of the exiled Gnomeregan survivors. Operating outdoors in the biting chill of Steelgrill's Depot just east of Kharanos, Milli Featherwhistle oversees the supply of clockwork steeds for Gnomeregan's displaced populace. Unlike the biological beasts favored by dwarves and night elves, Milli builds her entire inventory herself, personally calibrating gears, pistons, and balancing gyros to ensure each mechanical bird runs at peak efficiency across the snowy crags of Dun Morogh. Every frame and spring in Milli's workshop is rooted in blueprints originally drafted by High Tinker Gelbin Mekkatorque. While Milli has integrated modern performance improvements over the years—streamlining chassis weights and refining exhaust vents—she faithfully adheres to the High Tinker's foundational schematics. Her mechanical wonders prove that even in exile, gnomish technological ambition remains thoroughly unbroken.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_milli-featherwhistle-882cfd9ca3adf0ef69d0/1-0000.mp3", duration = 71.0269388, start = 0},
  },
}
P.transport["npc:milton-sheaf"] = {
  hash = "5e9f2a",
  fullHash = "5e9f2a",
  text = "Milton Sheaf. In Stormwind Keep, Milton Sheaf guards the kingdom's written history. He tends the Royal Library and calls on Alliance travelers to recover lost books and records. Milton Sheaf tends the Royal Library inside Stormwind Keep. While the court handles politics, noble disputes, and military concerns, he preserves the written record. He sees accurate histories of the Alliance and the Eastern Kingdoms as a duty, especially amid war, loss, and instability. Milton Sheaf sends travelers to recover books scattered across the realm. Volumes wear with use, while records lie in monastic archives, distant outposts, and forgotten ruins. He sends Alliance adventurers from Northshire Abbey to Southshore in the north to retrieve misplaced books, examine ancient texts, and return rare manuscripts safely to the keep.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_milton-sheaf-9b52c664c7e691952cd4/1-0000.mp3", duration = 49.6065306, start = 0},
  },
}
P.transport["npc:minor-manifestation-of-earth"] = {
  hash = "2082ac",
  fullHash = "2082ac",
  text = "Minor Manifestation of Earth. A Minor Manifestation of Earth is a localized elemental spirit bound to sacred stones in Mulgore and Durotar. Invisible to ordinary sight, it reveals itself only to fledgling shamans who drink the sacred Earth Sapta, providing the rough quartz required to carve their very first earth totem. The spirits of the earth dwell everywhere beneath the dirt and stone, but communicating with them requires deliberate ritual. At sacred landmarks like Kodo Rock in Mulgore and Spirit Rock in Durotar, Minor Manifestations of Earth linger in the unseen realm, surrounded by even smaller elemental presences. Only initiates who have drunk the Earth Sapta—a ritual draught brewed by shamanic mentors—can lift the veil between the physical world and the elements. Once acknowledged, the spirit imparts the earth's blessings along with a piece of rough quartz, granting the novice the spiritual focal point needed to fashion an Earth Totem.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_minor-manifestation-of-earth-76f325f7f22e83155875/1-0000.mp3", duration = 57.3387755, start = 0},
  },
}
P.transport["npc:minor-manifestation-of-water"] = {
  hash = "d685ce",
  fullHash = "d685ce",
  text = "Minor Manifestation of Water. The Minor Manifestation of Water is an elemental spirit found along North Tide's Run on the coast of Silverpine Forest. It serves as a vital trial for Horde shamans seeking to commune with and master the element of water. Before this peaceful spirit can be consulted, initiates must first cleanse its corrupted counterpart. Lurking along the mist-shrouded shores of North Tide's Run, west of the Sepulcher in Silverpine Forest, the Minor Manifestation of Water represents an essential rite of passage for developing shamans. Water elementals embody life, renewal, and fluidity, but they can easily fall victim to malevolent blight. An initiate must face and defeat a corrupted manifestation of this elemental before the pure Minor Manifestation of Water can reveal itself. Once cleansed, the spirit offers guidance to shamans completing their sacred journey to fashion a Water Totem.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_minor-manifestation-of-water-a24261f2f3cba6769d04/1-0000.mp3", duration = 56.3983673, start = 0},
  },
}
P.transport["npc:misha"] = {
  hash = "f6fc6e",
  fullHash = "f6fc6e",
  text = "Misha. Misha is the loyal bear companion of Rexxar, the Champion of the Horde. She wanders Kalimdor faithfully at the half-ogre beastmaster's side. Misha is a brown bear who walks at the side of the wandering Rexxar, a solitary spirit who trusts beasts more than people. Together they have forged a fierce, protective partnership that has weathered countless wildernesses and bloody battles. Misha is far more than a tame pet; she is a seasoned warrior. She fought alongside Rexxar in the brutal conflict against Grand Admiral Daelin Proudmoore at Theramore Isle, helping ensure the young Horde's survival. When not in battle, her keen senses and strength serve as an extension of Rexxar's will. Currently, travelers venturing along the long tracks through the Stonetalon Mountains, Desolace, and Feralas can spot Misha padding quietly beside Rexxar. Though fierce enough to tear apart any predator foolish enough to threaten them, she remains Rexxar's steadfast anchor in an otherwise untrustworthy world.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_misha-fbe473fe23ce276ab218/1-0000.mp3", duration = 62.5371429, start = 0},
  },
}
P.transport["npc:misha-tor-kren"] = {
  hash = "17593b",
  fullHash = "17593b",
  text = "Misha Tor'kren. At the Tor'kren Farm in western Durotar, Misha Tor'kren waits for word of her son. Kron went west toward the Southfury River to hunt crocolisks, but has not returned. Misha Tor'kren tends her farm near Thunder Ridge, southeast of the ridge. Her son Kron went west toward the Southfury River to hunt crocolisks and prove his mettle, but he never came home. With Durotar's frontier dangers stretching the orcish watchtowers thin, Misha has no word of where he is. She needs travelers willing to search the riverbanks for signs of her son.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_misha-tor-kren-2d0cc9aecc6bd7d8b12d/1-0000.mp3", duration = 34.2465306, start = 0},
  },
}
P.transport["npc:mitsuwa"] = {
  hash = "914078",
  fullHash = "914078",
  text = "Mitsuwa. Mitsuwa is a Darkspear troll stationed at Zoram'gar Outpost along the misty coast of Ashenvale. Deeply troubled by the ambush of his traveling kin, he enlists Horde champions to avenge the fallen and reclaim stolen spiritual talismans. Situated at the remote Zoram'gar Outpost on the strand of the Zoram Strand, Mitsuwa serves the Horde alongside his companion Marukai. When a group of traveling trolls bound for the encampment was ambushed and slaughtered by the aggressive Thistlefur furbolgs of northern Ashenvale, Mitsuwa took the loss as a grievous offense. Driven by duty and anger, he directs able-bodied warriors toward the Thistlefur dens to reclaim the stolen troll charms, ensuring the spirits of his kin are honored and their sacred possessions recovered from the beasts.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mitsuwa-38c9b8bf1db7c269d0e6/1-0000.mp3", duration = 47.36, start = 0},
  },
}
P.transport["npc:monte-gazlowe"] = {
  hash = "17340c",
  fullHash = "17340c",
  text = "Monte Gazlowe. At Ratchet, Monte Gazlowe keeps a neutral port open to traders from every side. He founded the town with the fortune he earned as the Horde’s chief engineer during the building of Durotar and Orgrimmar. At Ratchet, Monte Gazlowe runs a port where rivals can trade under the Steamwheedle Cartel. He founded the town on the barren coast after earning a handsome payday for his engineering work with the new Horde. Horde, Alliance, and independent traders may barter there, so long as they keep their weapons sheathed and their purses heavy. After the Third War, Warchief Thrall hired Monte Gazlowe as Durotar’s chief engineer to solve urgent problems for the new orc capital. Gazlowe took on the dangerous work of securing freshwater for Orgrimmar. His tunnels broke into underground kobold dens, but the wandering beastmaster Rexxar arrived in time to help blast the caverns shut. Gazlowe finished his assignments and remains a favored contractor and friend to Thrall. He has even sent his foreman, Rezlak, to keep helping with orc construction across Durotar. Trade brings good earnings to Ratchet, but maritime rivals and thieves trouble Monte Gazlowe’s business. The Southsea Freebooters have camps along the nearby Merchant Coast, where they seize cargo bound for Ratchet and steal goods from raw ore to Gazlowe’s custom-ordered boots. To protect his profits, the port boss often hires passing sellswords of any allegiance to clear pirate camps, recover stolen shipments, and settle scores with troublemakers at the docks.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_monte-gazlowe-deb530640ef96891e4aa/1-0000.mp3", duration = 91.7420408, start = 0},
  },
}
P.transport["npc:moon-priestess-amara"] = {
  hash = "58c493",
  fullHash = "58c493",
  text = "Moon Priestess Amara. West of Dolanaar, Moon Priestess Amara watches Teldrassil’s road to Darnassus. Two huntresses guard her as she keeps watch over the woodland paths. Moon Priestess Amara watches the road west of Dolanaar with two huntress companions, Nhemai and Yaeliura. As a priestess of the Sisterhood of Elune, she brings spiritual guidance to her post, while her watch helps keep Teldrassil’s roads secure. Travelers heading west can seek her direction toward Darnassus. Those burdened in spirit can also seek a path of redemption from her.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_moon-priestess-amara-a7c70ad324e4bd129b7a/1-0000.mp3", duration = 32.4963265, start = 0},
  },
}
P.transport["npc:mor-rogal"] = {
  hash = "6eb91d",
  fullHash = "6eb91d",
  text = "Mor'rogal. Mor'rogal is a tauren resident of Sun Rock Retreat in the Stonetalon Mountains. He serves as an advisor and guide for travelers seeking glory and peril within the rugged subterranean reaches of the crags. Perched within the refuge of Sun Rock Retreat, Mor'rogal takes a keen interest in the deep crevices and caverns that cut through the Stonetalon Mountains. Recognizing that the region's twisting subterranean passes offer both great riches and lethal danger, he directs brave Horde wanderers to investigate troubled areas like the Boulderslide Ravine. For Mor'rogal, delving into these treacherous depths is not merely a matter of survival, but a test of spirit for those who follow their heart and soul in search of glory.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mor-rogal-4bc84e6108230b3dabf9/1-0000.mp3", duration = 42.8146939, start = 0},
  },
}
P.transport["npc:morgan-pestle"] = {
  hash = "05e280",
  fullHash = "05e280",
  text = "Morgan Pestle. In Stormwind, Morgan Pestle runs Pestle's Apothecary in the Trade District. He works with his brother William Pestle in Goldshire, handling supplies and alchemical research for the capital. Morgan Pestle sells alchemical goods, reagents, and practical remedies at Pestle's Apothecary in Stormwind's Trade District. His brother William keeps a workshop at the Lion's Pride Inn in Goldshire, while Morgan tends their family trade in the capital. He receives supplies from the rural heartlands, including candles sent by William.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_morgan-pestle-f0893bb50b0cc5620037/1-0000.mp3", duration = 33.3844898, start = 0},
  },
}
P.transport["npc:morgan-the-collector"] = {
  hash = "58fdaf",
  fullHash = "58fdaf",
  text = "Morgan the Collector. At the Brackwell Pumpkin Patch, Morgan the Collector directs Defias extortion and gathering across Elwynn Forest. A high-ranking operative, he coordinates local theft from the farmhouse while Goldshire's guard keeps watch nearby. Morgan the Collector skims gold from Elwynn Forest's mines for the Defias Brotherhood. While common bandits harass travelers on the roads, he directs organized shakedowns and gathers stolen coin and supplies for the Brotherhood's wider network. His headquarters is the farmhouse at the Brackwell Pumpkin Patch, where loyal enforcers including Surena Caledon and Erlan Drudgemoor surround him.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_morgan-the-collector-3f301f98fa3afb260989/1-0000.mp3", duration = 37.8514286, start = 0},
  },
}
P.transport["npc:mountaineer-barleybrew"] = {
  hash = "9bf398",
  fullHash = "9bf398",
  text = "Mountaineer Barleybrew. Mountaineer Barleybrew is an Ironforge mountaineer stationed at the South Gate Outpost in Dun Morogh. Guarding the pass leading eastward toward Loch Modan, he relies on hearty dwarven brews to keep sentries alert in the biting cold. Perched at the South Gate Outpost guarding the snowy roadway toward Loch Modan, Mountaineer Wellart Barleybrew stands as part of Ironforge's border watch. Like many mountaineers serving in the bitter winds of Dun Morogh, he appreciates the fortifying qualities of fine dwarven drink. Bearing the name of the renowned Barleybrew clan, he helps see to it that shipments of potent Shimmer Stout make their way to fellow watchmen who need warmth and stamina during long shifts along the mountain passes.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mountaineer-barleybrew-4e8ed9325240f29c88e9/1-0000.mp3", duration = 46.1844898, start = 0},
  },
}
P.transport["npc:mountaineer-kadrell"] = {
  hash = "9f2940",
  fullHash = "9f2940",
  text = "Mountaineer Kadrell. Mountaineer Kadrell is a stalwart dwarven sentry stationed across from the Stoutlager Inn in Thelsamar. Serving as a crucial liaison within the Loch Modan Mountaineers, he coordinates reconnaissance, supply deliveries, and border defense across the region. Standing watch in the bustling settlement of Thelsamar, Mountaineer Kadrell acts as an anchor for dwarven defenses throughout Loch Modan. While outposts on the valley's fringes face relentless pressure from troggs, gnolls, and native beasts, Kadrell remains at the center of town to organize reinforcements, relay orders, and assess incoming field reports from wandering scouts. Kadrell's duties frequently involve maintaining contact between Thelsamar and remote forward positions. Whether coordinating with Mountaineer Stormpike or sending adventurers to report to sentries like Mountaineer Rockgar, Kadrell ensures that the isolated outposts guarding the mountain passes receive vital supplies, reinforcements, and defensive intelligence.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mountaineer-kadrell-5e117fd1e664bb0b9dd7/1-0000.mp3", duration = 59.8465306, start = 0},
  },
}
P.transport["npc:mountaineer-stormpike"] = {
  hash = "6cdfaa",
  fullHash = "6cdfaa",
  text = "Mountaineer Stormpike. Mountaineer Stormpike is an Ironforge mountaineer stationed at Algaz Station in northern Loch Modan. Watching over the mountain pass leading toward the Wetlands, he works tirelessly to keep vital supply routes safe from lurking troggs and kobolds. As a proud member of the Stormpike clan, his loyalty lies squarely with Ironforge and the safety of dwarven lands. Perched along the northern border of Loch Modan, Algaz Station serves as a critical checkpoint before the perilous descent into the Wetlands. Mountaineer Stormpike is stationed here amid rocky crags and constant wilderness threats. His primary duty is maintaining the line of communication and keeping the roads open for travelers and supply convoys traversing through Dun Algaz. The northern reaches of Loch Modan are plagued by relentless pests, from kobolds infesting nearby digs to subterranean troggs. Stormpike routinely enlists passing adventurers to disrupt these threats, particularly targeting the kobolds who have moved into the Silver Stream Mine and put their filthy paws on the Miners' League's stored dwarven tools.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mountaineer-stormpike-d36670d5618154e9c282/1-0000.mp3", duration = 66.9518367, start = 0},
  },
}
P.transport["npc:mountaineer-thalos"] = {
  hash = "4b25f8",
  fullHash = "4b25f8",
  text = "Mountaineer Thalos. Mountaineer Thalos is a dwarven sentry stationed at the Coldridge Valley mouth of Coldridge Pass. Tasked with guarding the route, he warns travelers about the sudden trogg infestation choking the tunnel. Adventurers carrying urgent reports from the valley rely on him to point the way safely toward Kharanos. Perched on the snowy border where Coldridge Valley gives way to the deeper crags of Dun Morogh, Mountaineer Thalos serves as the first line of defense for travelers leaving the dwarven training grounds. Coldridge Pass has become a treacherous chokepoint overrun by hostile troggs who have burrowed up from the subterranean depths. Thalos stands vigil in the cold, warning the unready to turn back and assessing whether hardy couriers possess the grit to fight their way through to the wider kingdom. When Grelin Whitebeard finishes his report on the Frostmane troll movements within the secluded valley, the courier carrying it to his brother Senir in Kharanos is told to speak with Mountaineer Thalos before entering the tunnel. After verifying that an adventurer is capable of braving the infested passage, Thalos directs them onward to Kharanos, where regional commanders coordinate Dun Morogh's defense. His watchful presence ensures that vital intelligence reaches Ironforge's military leaders rather than dying in the snow.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mountaineer-thalos-9d16f65ee8894013c9ea/1-0000.mp3", duration = 78.8114286, start = 0},
  },
}
P.transport["npc:mupsi-shacklefridd"] = {
  hash = "b9a019",
  fullHash = "b9a019",
  text = "Mupsi Shacklefridd. Outside Ratchet in the Barrens, Mupsi Shacklefridd helps travelers repair ties with the Steamwheedle Cartel. Mupsi Shacklefridd works along the coastal road just outside Ratchet. Steamwheedle guards patrol the port town's edge as merchants come and go. Travelers on poor terms with the goblins can seek a way back into the cartel's good graces through Mupsi, if they bring the supplies and labor it demands.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mupsi-shacklefridd-e069eb27e9f1ae7696c5/1-0000.mp3", duration = 24.6595918, start = 0},
  },
}
P.transport["npc:mux-manascrambler"] = {
  hash = "061ba0",
  fullHash = "061ba0",
  text = "Mux Manascrambler. Mux Manascrambler is an eccentric goblin engineer dwelling in the desert outpost of Gadgetzan. Unlike many of his peers focused strictly on explosives or mining equipment, Mux harbors a peculiar fascination with the supernatural and occult energies. Tucked away inside a building in central Gadgetzan, behind Driz Plunkbow and his clanking Butcherbots, sits Mux Manascrambler. While the Steamwheedle Cartel trades heavily in oil, guns, and salvage, Mux focuses his ingenuity on more esoteric pursuits: the realm of spirits and supernatural anomalies. He uses his technical acumen to design bizarre devices capable of detecting, distilling, and interacting with spectral remnants, bridging crude goblin craftsmanship with the invisible worlds of the dead.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mux-manascrambler-143f7e3cd926291b96c5/1-0000.mp3", duration = 47.595102, start = 0},
  },
}
P.transport["npc:mydrannul"] = {
  hash = "5c32db",
  fullHash = "5c32db",
  text = "Mydrannul. At the Warrior's Terrace in Darnassus, Mydrannul keeps basic supplies ready for sentinels, soldiers, and visitors. Mydrannul keeps a supply stall among the Warrior's Terrace military pavilions and training grounds. Darnassus's defenders and travelers can find everyday field gear there, including ammunition for archers and gunners, throwing blades, flint, pouches, and simple rations. His stall helps sentinels and trainees preparing for duty on Teldrassil find the basic sundries they need.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_mydrannul-89c7d17c335fb9a81d67/1-0000.mp3", duration = 30.2759184, start = 0},
  },
}
P.transport["npc:nalpak"] = {
  hash = "935353",
  fullHash = "935353",
  text = "Nalpak. Nalpak is a tauren druid disciple who watches over the troubled Wailing Caverns in the Barrens. Stationed in the high cliff-cave overlooking the cavern entrance, he enlists passing adventurers to help contain the nightmare twisting the subterranean ecosystem. Perched inside a hidden cavern directly above the mouth of the Wailing Caverns, Nalpak remains loyal to the vision of Naralex. While his master lies trapped in a corrupted slumber deep below, Nalpak works to keep the spreading corruption at bay. He asks adventurers to gather deviate hides for use as leather.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_nalpak-46b77a142737cc2a49af/1-0000.mp3", duration = 34.8995918, start = 0},
  },
}
P.transport["npc:nara-meideros"] = {
  hash = "480d96",
  fullHash = "480d96",
  text = "Nara Meideros. In Stormwind's Park, Nara Meideros guides young seekers in Elune's teachings. As a night elf priestess in the human capital, she offers a familiar spiritual presence to her kin. Nara Meideros serves Elune far from Kalimdor, across the Great Sea in Stormwind City. In the Park, night elf druids and priests have tended a green refuge. Nara guides young seekers in devotion to the Moon Goddess. Human priests serve the Holy Light in nearby Cathedral Square, while Nara gives night elves visiting or living in the Eastern Kingdoms a connection to their own faith.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_nara-meideros-d8ee305f2f666a399603/1-0000.mp3", duration = 37.2244898, start = 0},
  },
}
P.transport["npc:narain-soothfancy"] = {
  hash = "c4b250",
  fullHash = "c4b250",
  text = "Narain Soothfancy. Narain Soothfancy is an eccentric gnome dwelling in a secluded beach hut just north of Steamwheedle Port in Tanaris. While he loudly advertises himself as a master soothsayer capable of divining the future, those who know him consider his psychic talents a complete farce compared to his genuine engineering genius. Perched on the eastern coast of Tanaris just north of the goblin docks, Narain Soothfancy lives as a retired engineer turned self-proclaimed master fortune teller. He routinely greets visitors by pressing unopened envelopes against his forehead or making wildly inaccurate guesses about their business, such as wondering if they have arrived seeking the legendary Ashbringer. Despite his theatrical charade, Narain possesses deep technical knowledge. Even ancient beings like the blue dragon Azuregos note that while Narain is a terrible psychic, his engineering aptitude is undeniably brilliant. A handbook titled 'Soothsaying for Dummies' rests nearby. Before settling by Steamwheedle Port, Narain suffered a catastrophic flying machine crash far to the south along Land's End Beach. He survived the wreck thanks to an unexpected rescue, though his eccentric personality and strange obsessions have kept him isolated on the desert shores, tinkering with arcane-adjacent technology and peddling dubious prophecies to anyone who passes by.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_narain-soothfancy-a0f66aa3382c1f14df94/1-0000.mp3", duration = 79.3077551, start = 0},
  },
}
P.transport["npc:nat-pagle"] = {
  hash = "77f5fe",
  fullHash = "77f5fe",
  text = "Nat Pagle. Nat Pagle is widely hailed as the most renowned angler in all of Azeroth, despite claiming he only fishes as an excuse to drink heavily. He makes his home on a secluded inlet in Dustwallow Marsh, where he trains elite anglers from both the Alliance and the Horde who manage to prove their patience. Though his name is synonymous with angling mastery across the known world, Nat Pagle is remarkably casual about his craft. Having cast lines for several decades, he often admits he has no great reverence for the sport itself, famously calling it little more than a convenient excuse to sit back and drink heavily. Despite this gruff nonchalance, Nat understands aquatic life and the art of angling better than anyone alive, even licensing fishing gear sought out by professionals. Pagle makes his camp on a small spit of land along the eastern coast of Dustwallow Marsh, far from the bustling taverns of the Eastern Kingdoms. He remains fiercely independent and uninterested in the politics of factions, welcoming Alliance travelers sent by trainers like Grimnur Stonebrand as well as Horde aspirants directed to him by Lumak in Orgrimmar. For Nat, anyone willing to scour the corners of the world for rare specimens deserves a lesson in genuine angling. Pagle has ventured into perilous waters, including an excursion into the ruins of Zul'Gurub where he misplaced his favorite measuring tape and tackle box near the waters prowled by the monstrous hydra Gahz'ranka.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_nat-pagle-4eb02288c03ac7c76cdb/1-0000.mp3", duration = 89.1036735, start = 0},
  },
}
P.transport["npc:natalia-mar-alith"] = {
  hash = "17e9d3",
  fullHash = "17e9d3",
  text = "Natalia Mar'alith. Mistress Natalia Mar'alith is a night elf priestess and Cenarion Circle researcher lost deep within the silithid nests of Hive'Regal. Once part of the expedition investigating Silithus alongside her husband, Commander Mar'alith, she has succumbed completely to the maddening influence of the Old Gods. When the Cenarion Circle established their outpost at Cenarion Hold to monitor the awakening sands, Natalia accompanied her husband, Commander Mar'alith, into the wastes. Eager to unravel the mystery behind the resurgence of the silithid and the ancient Qiraji ruins, she joined an exploratory party led by the famed explorer Brann Bronzebeard, accompanied by the dwarven researchers Rutgar Glyphshaper and Frankal Stonebridge.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_natalia-mar-alith-33884e5581a9151b9021/1-0000.mp3", duration = 43.4938776, start = 0},
  },
}
P.transport["npc:nathanos-blightcaller"] = {
  hash = "0d962a",
  fullHash = "0d962a",
  text = "Nathanos Blightcaller. Nathanos Blightcaller, once Nathanos Marris, stands at his ruined homestead in the Eastern Plaguelands as the deadly champion of Queen Sylvanas Windrunner. In life he was the first and only human Ranger Lord of Quel'Thalas, and in undeath he trains Forsaken hunters while guarding the eastern frontier with biting contempt for all who approach. Before the Third War, Nathanos Marris was an extraordinary marksman and tactical genius hailing from the rural outskirts of Lordaeron. Trained by the high elves of Quel'Thalas and close to Sylvanas Windrunner, he became the only human to ever attain the prestigious rank of Ranger Lord. His home remained the family estate in Lordaeron, the Marris Stead. When Prince Arthas and the Scourge swept through Lordaeron following the purge of Stratholme, the plague consumed the kingdom. Nathanos made a desperate stand at his estate, but fell to the monstrous abomination Ramstein the Gorger. Raised as a mindless undead thrall, he roamed the blighted fields killing in the Lich King's name. After Sylvanas shattered the Scourge's mental grip and established the Forsaken in the Undercity, she came for him, as he had somehow known she would, and tore his consciousness free from the Lich King's will, returning his tactical brilliance and fiery loyalty to her side.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_nathanos-blightcaller-67d3b290e709f9025f55/1-0000.mp3", duration = 79.7779592, start = 0},
  },
}
P.transport["npc:nida"] = {
  hash = "dc8f54",
  fullHash = "dc8f54",
  text = "Hilary. Hilary is a young human girl living in the lakeside town of Lakeshire in the Redridge Mountains. Distraught after dropping a cherished gift from her father into the lake, she spends her time crying along the town's docks. Amid the mounting threats of gnoll invasions and Blackrock orc warbands pressing down on Lakeshire, the children of the town still face everyday childhood troubles. Hilary accidentally dropped a necklace given to her by her father into the murky waters of Lake Everstill. Terrified that her father will be angry with her, the distraught girl waits by the town pier in tears, hoping someone brave enough will plunge into the lake to retrieve it.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_nida-89d781417e652e57705d/1-0000.mp3", duration = 40.0195918, start = 0},
  },
}
P.transport["npc:nikova-raskol"] = {
  hash = "923234",
  fullHash = "923234",
  text = "Nikova Raskol. In Old Town, Nikova Raskol grieves for her murdered grandson. The elderly Stormwind townswoman seeks justice against the Defias Brotherhood rioters held in the Stockade. Nikova Raskol wanders Old Town, carrying the grief of a recent loss. Her beloved grandson, Mac, was slain by Defias Brotherhood brigands. While the kingdom faces treason on a grand scale, Nikova bears the private cost of the Brotherhood's lawless rampage. Many criminals who wrecked havoc were captured and locked in the Stockade, but a violent inmate rebellion has seized the prison. The guards have failed to restore order, and Nikova turns to adventurers heading inside. She asks them to bring back red Defias bandanas as proof that her grandson's killers have faced retribution.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_nikova-raskol-bfebdb40c4c8dcdeb29e/1-0000.mp3", duration = 46.2367347, start = 0},
  },
}
P.transport["npc:nissa-firestone"] = {
  hash = "74ef64",
  fullHash = "74ef64",
  text = "Nissa Firestone. Nissa Firestone is a dwarven physician stationed above the bustle of the Great Forge in Ironforge. She serves as an instructor in field medicine, teaching travelers and soldiers how to dress wounds and bind trauma. Amid the clanging metal and blistering heat of the Great Forge, Nissa Firestone practices medicine from the upper floor of the Ironforge Physician shop. While dwarven warriors are famed for their endurance, even stone-hard skin splits against blade and claw. Nissa ensures that those heading out into the snows of Dun Morogh or beyond know how to keep themselves and their allies alive with basic bandaging and field dressings. For field medics who have mastered the basics of cloth and lint, Nissa recognizes when a student has outgrown her clinic. When practitioners reach the limits of what she can teach, she points them toward specialized triage officers in far-flung outposts, directing skilled healers to where the Alliance's casualties are heaviest.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_nissa-firestone-029015558a66590da55c/1-0000.mp3", duration = 57.3126531, start = 0},
  },
}
P.transport["npc:nogg"] = {
  hash = "d27cbe",
  fullHash = "d27cbe",
  text = "Nogg. Nogg is a goblin engineer operating out of a workshop in the Valley of Honor in Orgrimmar. He offers tinkering expertise and specialized craftsmanship to the Horde, notably analyzing strange mechanical salvage recovered from deep within Gnomeregan. Tucked away in Orgrimmar's Valley of Honor, Nogg runs an independent engineering workshop catering to adventurers and craftsmen alike. While the surrounding city relies heavily on traditional orcish steel and brute strength, Nogg provides the specialized mechanical finesse that only a goblin can offer. He maintains a keen interest in foreign contraptions and tech, happily examining curious trinkets and mechanical oddities dragged back from Alliance lands or subterranean ruins. Nogg takes special interest in items recovered from the fallen gnomish capital of Gnomeregan. When Horde operatives retrieve intricate rings or technological remnants from the irradiated vaults across the sea, Nogg is one of the few minds in Durotar capable of disassembling, deciphering, and retrofitting such bizarre clockwork mechanisms for Horde use.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_nogg-e855526002f2a23316ed/1-0000.mp3", duration = 66.2204082, start = 0},
  },
}
P.transport["npc:nori-pridedrift"] = {
  hash = "7967b0",
  fullHash = "7967b0",
  text = "Nori Pridedrift. Nori Pridedrift is an enterprising dwarf peddling his piping-hot Scalding Mornbrew throughout snowy Coldridge Valley. He makes his living braving the cold to supply shivering mountaineers with their morning pick-me-up, often enlisting swift recruits to run deliveries while the drink remains steaming. Life in Coldridge Valley is harsh and bitterly cold, and nothing cuts through the chill quite like a draught of Scalding Mornbrew. Nori Pridedrift has carved out a living by brewing and distributing this hot, coffee-like morning drink across the frozen drifts. Because the brew must be consumed while still scalding to be fully appreciated, delivery is a race against the elements. Nori frequently recruits brisk couriers to sprint fresh draughts out to freezing sentries before the mountain air robs the brew of its heat. Just as important as the brew itself are his limited supplies of sturdy mugs, which he expects his runners to return promptly.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_nori-pridedrift-ca631b3689e333c29f97/1-0000.mp3", duration = 55.8759184, start = 0},
  },
}
P.transport["npc:novice-elreth"] = {
  hash = "cad730",
  fullHash = "cad730",
  text = "Novice Elreth. Novice Elreth is an undead member of the Forsaken stationed inside the chapel at Deathknell. As newly risen undead awaken into their second life, she directs them to confront the mindless Scourge haunting the nearby graves and tend to the tragic aftermath of the plague. Inside the desecrated chapel at Deathknell, Novice Elreth assists the emerging undead as they struggle to understand their horrific awakening. Rather than succumbing to despair or the mindless hunger of the Scourge, the Forsaken must organize quickly to secure their territory. Elreth provides newly freed souls with early tasks, directing them to gather paws and wings from the wolves and bats to the south and deal with the lingering remnants of Lordaeron's tragic downfall, including the sorrow of her friend Marla Fipps, slain by her own husband Samuel after he joined the mindless Scourge.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_novice-elreth-f5dabc58a8aa0cd8c25d/1-0000.mp3", duration = 51.9836735, start = 0},
  },
}
P.transport["npc:oben-rageclaw"] = {
  hash = "96c0c0",
  fullHash = "96c0c0",
  text = "Oben Rageclaw. In Ban'ethil Barrow Den, Oben Rageclaw's spirit wanders, unable to wake or pass on. His sleeping body remains under the Gnarlpine furbolgs' control. Oben Rageclaw entered Ban'ethil Barrow Den to commune with nature and wander the Emerald Dream, as many Druids of the Claw do. When the Gnarlpine furbolgs fell to corruption and overran the barrows, Oben lay defenseless in his trance. A corrupted Gnarlpine shaman used dark rituals to take control of his comatose body. His spirit was left behind as an anguished ghost, unable to wake or pass on.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_oben-rageclaw-f0f3bff3859775e7c32d/1-0000.mp3", duration = 36.884898, start = 0},
  },
}
P.transport["npc:ogtinc"] = {
  hash = "d9a7fc",
  fullHash = "d9a7fc",
  text = "Ogtinc. Ogtinc is an independent furbolg hunter perched on a high ridge overlooking the Ruins of Eldarath in Azshara. Having parted ways with his tribe to serve the balance of nature, he acts as a trusted ally and mentor for the Cenarion Circle. Skilled hunters seeking to test their craft against the fiercest beasts of Kalimdor often seek out his guidance. While most furbolg in Kalimdor remain fiercely bound to their tribes—or have succumbed to corruption following the Third War—Ogtinc chose a distinct path. Departing from his kin, he dedicated his bow and survival lore to aiding the Cenarion Circle. He makes his camp high on a bluff southeast of Timbermaw Hold, vigilantly watching over the ancient, shattered lands of Azshara. Ogtinc is renowned among seasoned trackers for his intimate understanding of Kalimdor's wilderness. He tests hunters who have honed their skills across the continents, dispatching them to gather rare trophies—such as the antlers of courser beasts, the scale of wave-thrashed sea serpents, and parts from green dragonkin. Through these trials, he teaches that true hunting honors the natural world and preserves balance rather than mindlessly taking life.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ogtinc-554c575edaf7f4d06cd4/1-0000.mp3", duration = 71.0269388, start = 0},
  },
}
P.transport["npc:ogunaro-wolfrunner"] = {
  hash = "67fa3e",
  fullHash = "67fa3e",
  text = "Ogunaro Wolfrunner. In Orgrimmar’s Valley of Honor, Ogunaro Wolfrunner tends the Horde’s foremost wolf kennel beside the Hunter’s Hall. He breeds and trains fierce wolves for orc champions and their trusted allies. Ogunaro Wolfrunner tends Orgrimmar’s battle wolves beside the Hunter’s Hall in the Valley of Honor. Orcs and wolves have shared a bond for generations, across Draenor’s plains and Durotar’s wilderness. It rests on mutual respect, not simple domestication. Ogunaro entrusts only the hardiest beasts, from dire wolves to agile timber prowlers, to warriors who have proven their strength and worth to the warchief.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ogunaro-wolfrunner-e7a94dbc28cd93fdb21f/1-0000.mp3", duration = 39.7061224, start = 0},
  },
}
P.transport["npc:old-murk-eye"] = {
  hash = "5fc2af",
  fullHash = "5fc2af",
  text = "Old Murk-Eye. Near the Westfall Lighthouse, Old Murk-Eye prowls the southern coast. His kind revere him, and sailors fear the lethal menace he poses to anyone who wanders near the lighthouse. Old Murk-Eye prowls the surf around the Westfall Lighthouse, where he is far tougher and more aggressive than the murlocs common along Westfall’s shores. His attacks have brought enough grief to local mariners that the spectral Captain Grayson seeks his death. Grayson offers a bounty for Old Murk-Eye’s pristine scales, hoping to break his hold on the shallows.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_old-murk-eye-a92f49c67e0b481a1105/1-0000.mp3", duration = 31.8432653, start = 0},
  },
}
P.transport["npc:orendil-broadleaf"] = {
  hash = "1a8e40",
  fullHash = "1a8e40",
  text = "Orendil Broadleaf. Orendil Broadleaf is a skilled night elf herbalist and healer stationed at Maestra's Post in western Ashenvale. Known for his deep knowledge of forest flora, he concocts vital remedies to save young lives across the troubled woodlands. Positioned at Maestra's Post along the western threshold of Ashenvale, Orendil Broadleaf tends to the sick as a skilled healer. Recognized for his masterful knowledge of local herbs and restorative craft, Orendil relies on passing travelers to gather rare natural reagents. Even as tension and conflict encroach upon the forest, his tireless focus remains on safeguarding his kin and soothing their ailments.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_orendil-broadleaf-4164b28e6fad0608b885/1-0000.mp3", duration = 40.8032653, start = 0},
  },
}
P.transport["npc:orenthil-whisperwind"] = {
  hash = "2efbea",
  fullHash = "2efbea",
  text = "Orenthil Whisperwind. Beneath Teldrassil’s boughs, Orenthil Whisperwind lives among the night elves of Shadowglen. Orenthil Whisperwind lives among the night elves beneath Teldrassil’s canopy in Shadowglen. Little is known of his personal history.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_orenthil-whisperwind-219e5c910ed40b40b1c9/1-0000.mp3", duration = 15.0726531, start = 0},
  },
}
P.transport["npc:ormak-grimshot"] = {
  hash = "3e2a48",
  fullHash = "3e2a48",
  text = "Ormak Grimshot. In Orgrimmar's Valley of Honor, Ormak Grimshot trains hunters for life in the wild. Beside his wolf, Grimfang, he teaches Horde hunters to track, shoot, and tame beasts. Ormak Grimshot trains Horde trackers and marksmen in the Hunter's Hall. With his wolf, Grimfang, at his side, he teaches the skills needed to survive Kalimdor's wilderness. Orc and troll hunters who have completed their trials in Durotar learn from him how to tame and command wild beasts, and to form a lasting bond with an animal companion.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ormak-grimshot-f4de58bc5691ed7f4e5c/1-0000.mp3", duration = 34.0114286, start = 0},
  },
}
P.transport["npc:ormer-ironbraid"] = {
  hash = "7e097c",
  fullHash = "7e097c",
  text = "Ormer Ironbraid. Ormer Ironbraid is a dwarven archaeologist stationed at Whelgar's Excavation Site in the southern Wetlands. His team's historical research has been violently interrupted by ravenous raptors that overran the dig. Ormer seeks adventurous allies to clear out the beasts and avenge the miners driven from the site. Ormer Ironbraid arrived in the Wetlands as part of the dwarven effort to uncover Titan relics and ancient history at Whelgar's Excavation Site. Unfortunately, uncovering ancient stones also unearthed—or at least provoked—packs of fierce Wetlands raptors. Rather than cataloging ancient earthenware and tablets, Ormer spends his days watching the beasts prowl among the ruins, nursing a fierce hatred for the creatures that disrupted their work. Ormer refuses to abandon the dig, but he lacks the raw muscle to purge the site alone. He directs his frustration into a systematic campaign of extermination, enlisting passing travelers to slay raptors of increasing size and ferocity. For Ormer, reclaiming the excavation is not just about the artifacts—it is a deeply personal matter of dwarven pride and vengeance against the local wildlife.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ormer-ironbraid-49cbc7ed7e30b3ccf242/1-0000.mp3", duration = 71.4971429, start = 0},
  },
}
P.transport["npc:orokk-omosh"] = {
  hash = "ff26e7",
  fullHash = "ff26e7",
  text = "Orokk Omosh. In Orgrimmar's Valley of Honor, Orokk Omosh keeps his family's smithing craft alive. The aging orc has no children to inherit it, so he seeks worthy Horde apprentices to learn the Omosh armorcraft secrets. In the Valley of Honor, Orokk Omosh is the last smith of the Omosh line. He has no children to inherit his craft, and he will not let his family's techniques die with him. Capable Horde blacksmiths can undertake his demanding trials of metalwork. Those who prove their dedication earn the revered secrets of Omosh armorcraft. Among fellow artisans, Orokk is known for his boisterous delight in true mastery. Those who complete his craftsmanship trials often see him perform the Omosh Dance of Joy, a jubilant celebration of traditional smithing that echoes through Orgrimmar's halls.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_orokk-omosh-d2387b2cd1a4970c800d/1-0000.mp3", duration = 48.7444898, start = 0},
  },
}
P.transport["npc:orphan-matron-battlewail"] = {
  hash = "fb0eeb",
  fullHash = "fb0eeb",
  text = "Orphan Matron Battlewail. In Orgrimmar's Valley of Honor, Orphan Matron Battlewail cares for children left without families by war. With Tosamina, she gives them shelter and raises young orcs. Orphan Matron Battlewail cares for children who have lost their kin to violence. In Orgrimmar, where war's toll reaches even the young capital, she and Tosamina shelter and nurture the next generation of the Horde. The orphanage in the Valley of Honor opens its doors to passing adventurers. During Children's Week, travelers are called upon to mentor the children.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_orphan-matron-battlewail-991c6f7e3b03c54b08b9/1-0000.mp3", duration = 33.8546939, start = 0},
  },
}
P.transport["npc:orphan-matron-nightingale"] = {
  hash = "78503a",
  fullHash = "78503a",
  text = "Orphan Matron Nightingale. In Cathedral Square, Orphan Matron Nightingale cares for Stormwind’s orphaned children. She and Matron Shellene give them shelter and guidance, and invite Alliance adventurers to spend Children's Week with them. Outside the orphanage, south-east of the Cathedral of Light, Orphan Matron Nightingale cares for Stormwind’s most vulnerable children. Recent wars, gnoll attacks, and the rise of the Defias Brotherhood have left many without homes or parents. Nightingale and Matron Shellene give them shelter, basic care, and guidance under the Church of the Holy Light’s watch. Matron Nightingale believes children need hope as well as food and shelter. Each Children's Week, she asks Alliance heroes to take an orphan on journeys across Azeroth. She hopes meeting celebrated champions will build their confidence, show them the wider world beyond the city walls, and remind them they are not forgotten.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_orphan-matron-nightingale-7a29e6a32aabd95b295f/1-0000.mp3", duration = 57.9395918, start = 0},
  },
}
P.transport["npc:osric-strang"] = {
  hash = "89f739",
  fullHash = "89f739",
  text = "Osric Strang. In Stormwind's Old Town, veteran armor merchant Osric Strang supplies weary travelers and Alliance defenders with sturdy gear. His shop, Limited Immunity, specializes in heavy mail and plate armor, along with shields. Osric Strang runs Limited Immunity, where fighters find heavy armor and shields. He also helps arriving couriers who need a point of contact in the capital, including those coming from nearby settlements such as Sentinel Hill in Westfall.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_osric-strang-f08bcfc0a92aa9450b5f/1-0000.mp3", duration = 25.8612245, start = 0},
  },
}
P.transport["npc:overlord-mok-morokk"] = {
  hash = "72d0f6",
  fullHash = "72d0f6",
  text = "Overlord Mok'Morokk. Overlord Mok'Morokk is the brute chieftain of the Stonemaul ogres, presiding over Brackenwall Village in Dustwallow Marsh. Originally appointed by Rexxar for his strength, he has become a tyrannical and cowardly ruler who refuses to defend his clan against the black dragonflight. When Rexxar bested the previous chieftain Kor'gall and led the Stonemaul clan in defense of Durotar, he left Mok'Morokk in command, seeing promise in his sheer martial strength. That faith proved misplaced. Mok'Morokk quickly succumbed to the corrupting influence of absolute authority, ruling through intimidation and self-indulgence rather than stewardship. Instead of caring for his kin, he demands unearned tribute, lounges in Brackenwall Village, and bullies anyone who questions his command.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_overlord-mok-morokk-ffec17d393cbbdd3b67e/1-0000.mp3", duration = 49.0579592, start = 0},
  },
}
P.transport["npc:pao-ka-swiftmountain"] = {
  hash = "74ade3",
  fullHash = "74ade3",
  text = "Pao'ka Swiftmountain. Pao'ka Swiftmountain is a young tauren naturalist stranded among the wild wyverns of Highperch in Thousand Needles. Having traveled south under the guidance of Motega Firemane, his youthful curiosity got the better of him when he ventured too close to a nesting site and ended up cornered in the cliffs. Pao'ka came to the canyon country of Thousand Needles alongside Motega Firemane, eager to catalog and study the dangerous beasts of the canyons. His father had been reluctant to let his son go on such a perilous journey, and Pao'ka's recent misadventure proves those concerns were warranted. Fascinated by the magnificent wyverns inhabiting Highperch, the young scholar crept up the mountain trail behind a solitary tauren totem. Unsurprisingly, the territorial beasts took offense to his intrusion, driving him deep into the crags where he found himself trapped and terrified, unable to slip past the swooping predators to return to Whitereach Post.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_pao-ka-swiftmountain-1294df1f12154704e66f/1-0000.mp3", duration = 57.6, start = 0},
  },
}
P.transport["npc:parqual-fintallas"] = {
  hash = "168c09",
  fullHash = "168c09",
  text = "Parqual Fintallas. Parqual Fintallas is a Forsaken scholar and former human historian of Lordaeron, currently residing in the Undercity's Apothecarium. Despite the grim surroundings of his undead existence, he retains a polite demeanor and an enduring passion for ancient lore, often assisting travelers sent to consult his deep historical expertise. In life, Parqual was a respected human scholar of Lordaeron who knew all there was to know of the kingdom, immersing himself in historical texts. When the plague of undeath struck, Parqual was among the many citizens slain and raised, only to eventually break free under Lady Sylvanas Windrunner. While the Forsaken largely embrace cold pragmatism and turn away from their former lives, Parqual retains his scholarly passion and pleasant manners, still seeking enlightenment, though of a different nature than in life. Parqual dwells among the bubbling vats and alchemists of the Apothecarium in the Undercity. Despite his macabre surroundings, he remains an invaluable font of knowledge regarding Azeroth's history. When adventurers undertake rigorous intellectual trials—such as the elusive 'Test of Lore'—they are directed to Parqual, who sends them to the Scarlet Monastery's library for a book and then puts a question of his own to them.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_parqual-fintallas-a2bfe7ab779ff4fbb250/1-0000.mp3", duration = 80.7183673, start = 0},
  },
}
P.transport["npc:pilot-bellowfiz"] = {
  hash = "faa812",
  fullHash = "faa812",
  text = "Pilot Bellowfiz. Pilot Bellowfiz, affectionately known as 'Fizzer,' is a dwarven driver stationed at Steelgrill's Depot in Dun Morogh. As a member of the Ironforge Siege Brigade, he is responsible for maintaining and fielding heavy dwarven war machines, specifically his own siege engine, Jetsteam. Stationed just outside the bustling halls of Ironforge at Steelgrill's Depot, Pilot Bellowfiz represents the mechanical backbone of the dwarven military. Piloting the powerful siege engine known as Jetsteam, Bellowfiz spends his days tuning components, procuring essential parts, and keeping his machine battle-ready. Alongside his comrade Pilot Stonegear, Bellowfiz is constantly discussing vehicular designs, armor plating, and engine output, ensuring that the mountain kingdom's mechanized firepower remains unmatched across Khaz Modan.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_pilot-bellowfiz-c63d89f87f1ab90b494a/1-0000.mp3", duration = 51.2, start = 0},
  },
}
P.transport["npc:pilot-hammerfoot"] = {
  hash = "699800",
  fullHash = "699800",
  text = "Pilot Hammerfoot. Pilot Hammerfoot is a dwarven siege engine pilot of the Ironforge Siege Brigade, stationed near the mountain passes connecting Dun Morogh and Loch Modan. Worried for a fellow pilot lost in the hills, he seeks willing adventurers to search for his friend. His presence highlights the dangers faced by dwarves along the high alpine ridges. Ironforge's siege engines are the pride of its Siege Brigade, but driving them across harsh mountainous terrain carries extreme risk. Stationed at the North Gate Outpost overlooking the border between Dun Morogh and Loch Modan, Pilot Hammerfoot guards the pilots' engines and watches the mountain passes. When a pilot goes missing, finding him quickly becomes a priority, especially with savage beasts prowling the nearby hills.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_pilot-hammerfoot-cc82689609d01e9b4c39/1-0000.mp3", duration = 46.4195918, start = 0},
  },
}
P.transport["npc:pilot-longbeard"] = {
  hash = "2b5ec9",
  fullHash = "2b5ec9",
  text = "Pilot Longbeard. Pilot Longbeard is a dwarven siege engine pilot of the Ironforge Siege Brigade, stationed in the Hall of Arms within Ironforge's Military Ward. Though posted in the mountain city, he maintains close ties with gnomish tinkerers and fellow racing enthusiasts operating far away in the Shimmering Flats. Found amongst the martial displays and weaponsmiths of Ironforge's Military Ward, Pilot Longbeard represents the proud siege engine corps of Khaz Modan. While his duties keep him within the fortress city, Longbeard keeps an eager ear out for innovations and news from fellow mechanics across the continent, including the Brassbolts brothers tinkering out on the salt flats of Kalimdor. Longbeard serves as a point of contact for adventurous travelers heading south into Kalimdor. He frequently directs promising recruits and couriers toward the Shimmering Flats of Thousand Needles, where gnomish inventors push mechanical boundaries alongside their goblin rivals.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_pilot-longbeard-4da097c6af492119aefd/1-0000.mp3", duration = 55.4057143, start = 0},
  },
}
P.transport["npc:pilot-stonegear"] = {
  hash = "e37213",
  fullHash = "e37213",
  text = "Pilot Stonegear. Pilot Stonegear, nicknamed 'Stone', is a dwarf mechanic and driver in the Ironforge Siege Brigade stationed at Steelgrill's Depot. He operates the formidable siege engine known as Trollplow and works tirelessly to enhance its performance and armor. Adventurers traveling through Dun Morogh often help him secure rare materials to keep his war machine battle-ready. Stationed among the rumbling boilers and clanking tracks of Steelgrill's Depot, Pilot Stonegear serves Ironforge as a proud driver in the Siege Brigade. His pride and joy is Trollplow, a heavy siege tank built to smash through enemy lines. Stonegear takes his machine seriously—knowing that in the heat of battle, a driver's life depends entirely on the resilience of gears, plates, and steam pressure. He constantly seeks to fine-tune both Trollplow's combat efficiency and the everyday livability of its cramped cockpit. Like many dwarven and gnomish grease-monkeys at the depot, Stonegear is rarely content with factory specifications. He often spends off-duty hours debating engineering schematics with comrades like Pilot Bellowfiz. Whether chasing down rumors of exotic ores or tracking down volatile minerals to fuel enhanced plating and munitions, Stonegear relies on eager recruits to venture into the snowy wilderness and dangerous caves of Dun Morogh on supply runs.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_pilot-stonegear-a712dc01d28239cbb408/1-0000.mp3", duration = 82.5208163, start = 0},
  },
}
P.transport["npc:pixel"] = {
  hash = "2820bc",
  fullHash = "2820bc",
  text = "Pixel. Pixel is an enterprising goblin courier operating out of Splintertree Post in Ashenvale. Making her living delivering heavy goods across dangerous territories, she handles shipments like Warsong saw blades for the local Horde forces—though she never lets any cargo go without proper compensation. While Splintertree Post serves as a fortified bastion for the Horde amidst the hostile canopies of Ashenvale, Pixel remains firmly focused on profit. As an independent courier willing to haul freight into active war zones, she provides essential logistics for the Warsong Clan's logging efforts. However, true to goblin custom, contracts and coin dictate her cooperation. She holds fast to her deliveries until the client produces payment; for the saw blades, she wants a deadly blunderbuss to protect herself on the road. Always alert to an opportunity, she also pays passing adventurers for satyr horns, which are in high demand in Ratchet.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_pixel-1250c3a98a04bfcef153/1-0000.mp3", duration = 55.3012245, start = 0},
  },
}
P.transport["npc:piznik"] = {
  hash = "cc8b2e",
  fullHash = "cc8b2e",
  text = "Piznik. Piznik is a disgruntled goblin surveyor hiding deep within Windshear Mine in the Stonetalon Mountains. Once a high-ranking overseer in the local Venture Company operations, he was sidelined by the ruthless Gerenzo Wrenchwhistle. Now nursing a grudge, Piznik secretly gathers intel to undermine his former workplace. Before Gerenzo Wrenchwhistle seized supreme authority over Windshear Crag, Piznik held the enviable title of second-in-command across the entire operation. However, corporate restructuring in the Venture Company is unforgiving. Once Gerenzo took full control, Piznik found himself pushed aside and relegated to the murky depths of Windshear Mine. Rather than accepting his demotion quietly, Piznik bides his time underground, keeping a watchful eye on mine movements and quietly plotting revenge against the boss who demoted him.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_piznik-68b3630077652e005380/1-0000.mp3", duration = 54.0995918, start = 0},
  },
}
P.transport["npc:pozzik"] = {
  hash = "1fc949",
  fullHash = "1fc949",
  text = "Pozzik. Pozzik is an esteemed goblin tinkerer and racer stationed at the Mirage Raceway on the Shimmering Flats in Thousand Needles. Once one of the most respected engineers in Undermine, he now dedicates his technical genius to constructing experimental rocket cars and settling the ultimate debate of engineering supremacy against his gnome counterpart. Before retiring to the harsh salt flats of Thousand Needles, Pozzik built a legendary reputation among the goblins. As one of the most respected tinkerers out of Undermine, his technical expertise spans complex internal combustion, propulsion, and hazardous chassis construction. Rather than settling into comfortable obscurity, however, Pozzik took his mechanical mastery into the desert to push high-speed machinery far past its breaking point. At the Mirage Raceway, Pozzik teamed up with his perennial gnome counterpart, Fizzle Brassbolts. Despite the historic rivalry between goblin explosives and delicate gnomish calibration, the two worked together to construct the sprawling racetrack across the dried lakebed. They field opposing racing outfits, testing prototype rocket cars to definitively prove whose racial design philosophy dominates the track. Naturally, Pozzik is always on the lookout for resourceful adventurers willing to acquire parts and shave weight off his designs.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_pozzik-f8f5a3980e13e56769a5/1-0000.mp3", duration = 80.404898, start = 0},
  },
}
P.transport["npc:priestess-a-moora"] = {
  hash = "7fe24f",
  fullHash = "7fe24f",
  text = "Priestess A'moora. Priestess A'moora is a devout night elf servant of the Moon Goddess residing within the Temple of the Moon in Darnassus. Working closely under the guidance of High Priestess Tyrande Whisperwind's priesthood, she attends to rituals of spiritual purification and communion with Elune. Travelers exploring Teldrassil are often directed to her when matters involve sacred offerings and the mystical wildlife of the boughs. Within the serene marble halls of the Temple of the Moon, Priestess A'moora spends her days in contemplation and service. As an ordained priestess of Elune, she assists in tending the spiritual needs of Darnassus and preserving the delicate rituals passed down through millennia. While much of the Sisterhood oversees military defenses or diplomacy, A'moora focuses on traditional devotions and sacred matters concerning the natural spirits of Teldrassil. A'moora is tied to the sad fate of Lady Sathrah, a great spider once beloved of Elune whose silvery dew was kept in the temple for its healing powers. When Sathrah descended into madness, A'moora sent young adventurers to the northern borders of Teldrassil near Wellspring Lake to end her suffering and bring back her silvery spinnerets. Offered at the temple's fountain, the spinnerets become a sacrifice to Elune so that Sathrah might be reborn at peace.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_priestess-a-moora-a151e9719607b93dfb8b/1-0000.mp3", duration = 78.3412245, start = 0},
  },
}
P.transport["npc:priestess-anetta"] = {
  hash = "36bb7c",
  fullHash = "36bb7c",
  text = "Priestess Anetta. Inside Northshire Abbey, Priestess Anetta teaches new priests their first rites of the Holy Light. She is a human cleric and a member of the Brotherhood of Northshire. On the ground floor of Northshire Abbey, Priestess Anetta keeps to the quiet library wing. Defias bandits and kobolds trouble the valley, and she reminds those who pass that the Light may be the one thing that saves them someday. New human priests come to Priestess Anetta in the cloister with a hallowed letter of introduction. She teaches them to channel holy words to mend flesh and call down smiting radiance against evil. Under her guidance, the young acolytes prepare to carry the Light beyond Northshire's secluded walls.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_priestess-anetta-1330cc57da9eddb33d30/1-0000.mp3", duration = 45.1395918, start = 0},
  },
}
P.transport["npc:priestess-josetta"] = {
  hash = "94d5e3",
  fullHash = "94d5e3",
  text = "Priestess Josetta. In Goldshire, Priestess Josetta guides young priests beyond their first trials in Northshire. She teaches faith, devotion, and the work of serving others. Priestess Josetta tends to the people of Elwynn Forest from an upstairs room in the Lion's Pride Inn. Travelers, guards, and local workers come within her reach there. She offers spiritual care among ordinary folk, showing that service to the Holy Light can be given wherever people need comfort. Priestess Josetta guides young priests who have finished their first studies at Northshire Abbey. She sends them into the countryside to help wounded guards and comfort those who suffer. Their work teaches them that priesthood asks more than prayers learned by heart. They must put the Light to work and help mend a broken world. Priestess Josetta regrets that she did not travel farther when she was young. She chose familiar ground over the wider roads of Azeroth. Though she is content with her sacred service in Goldshire, she urges the young disciples who visit her to be bolder and carry their faith to distant frontiers.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_priestess-josetta-fd082e5692e737d29b2d/1-0000.mp3", duration = 65.515102, start = 0},
  },
}
P.transport["npc:prospector-ironband"] = {
  hash = "33e6af",
  fullHash = "33e6af",
  text = "Prospector Ironband. Prospector Darteus Ironband is an honest, hardworking dwarven surveyor who oversees an archaeological dig in southeastern Loch Modan. Working under the banner of the Dwarven Explorers' Guild, he is determined to uncover the earthen heritage buried beneath Khaz Modan. Despite setbacks and hostile local creatures, Ironband remains committed to sending regular progress reports and uncovered relics back to Ironforge. Darteus Ironband leads the dig at Ironband's Excavation Site nestled in the hills of southeastern Loch Modan. Like many field researchers in the Explorers' Guild, Ironband believes that the soil of Khaz Modan hides vital truths about the origins of the dwarven race. His camp works tirelessly digging trenches and sifting through rubble in search of ancient relics, stone tablets, and earthen artifacts. Despite the slow pace of unearthing buried history, Ironband's resolve remains unshaken, and he is always eager to recruit competent adventurers to safeguard his operation. Conducting an excavation in the rugged wilds is never quiet. The site faces relentless harassment from local troggs and wildlife, threatening the supply lines and equipment essential for the dig. Relics and valuable survey equipment are constantly at risk of being stolen or wrecked before they can be examined. Ironband relies on visiting Alliance travelers to protect the cargo shipments, keep hostile raiders at bay, and investigate missing guild contacts in the neighboring badlands.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_prospector-ironband-2f38cc1e3510671f7625/1-0000.mp3", duration = 89.7828571, start = 0},
  },
}
P.transport["npc:prospector-remtravel"] = {
  hash = "541a58",
  fullHash = "541a58",
  text = "Prospector Remtravel. In southern Darkshore, Prospector Remtravel leads an Explorers' League dig among ancient relics. The dwarf's scattered focus and the dangers around camp make his work perilous. The Explorers' League sent Prospector Remtravel across the sea to establish a dig in southern Darkshore. Night elves guard their ancestral lands, yet the League's drive to uncover Azeroth's origins carries its prospectors into forgotten places. Remtravel unearths fossilized history and ancient stones, while aggressive wildlife and hostile local threats make the camp difficult for one scatterbrained dwarf to manage.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_prospector-remtravel-ea5533cbefd93d3c5375/1-0000.mp3", duration = 38.4, start = 0},
  },
}
P.transport["npc:prospector-ryedol"] = {
  hash = "8dc2d3",
  fullHash = "8dc2d3",
  text = "Prospector Ryedol. Prospector Ryedol is an Explorers' League surveyor stationed on a dusty rise overlooking the eastern Badlands. Watching over the perilous excavations below, he strives to recover lost dwarven relics and maintain hope in a barren wasteland overrun by troggs and beasts. Perched upon a rugged hill just south of Hammertoe's Digsite, Prospector Ryedol represents the ongoing efforts of Ironforge's Explorers' League in the Badlands. The arid valley is rich in ancient titan secrets and earthen heritage, but field expeditions here are constantly beleaguered by savage troggs, ravenous coyotes, and territorial drakes. Ryedol coordinates retrieval efforts for dwarven gear stolen by the Dark Iron dwarves and seeks signs of hope amid the ruined outposts, determined not to let the League's sacrifices in the wastes be in vain.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_prospector-ryedol-b95817efcdab7e95bc03/1-0000.mp3", duration = 50.1812245, start = 0},
  },
}
P.transport["npc:prospector-stormpike"] = {
  hash = "451fce",
  fullHash = "451fce",
  text = "Prospector Stormpike. Prospector Stormpike is a blunt, short-tempered dwarf stationed within the Library of the Hall of Explorers in Ironforge. A member of the renowned Stormpike clan, he oversees logistical support for distant archaeological digs and lends his sharp intellect to deciphering coded missives. Tucked away amid the towering bookshelves of the Hall of Explorers, Prospector Stormpike coordinates excavation efforts across Khaz Modan and beyond. Despite his gruff demeanor and impatience with idle chatter, he is deeply dedicated to uncovering dwarven history, keeping distant sites supplied with essentials like blasting powder. Beneath his rough exterior lies a keen analytical mind skilled at breaking intricate ciphers, making him an unexpected asset to Alliance scouts dealing with clandestine threats.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_prospector-stormpike-5c9b223b4ed523da3838/1-0000.mp3", duration = 50.4163265, start = 0},
  },
}
P.transport["npc:prospector-whelgar"] = {
  hash = "17a898",
  fullHash = "17a898",
  text = "Prospector Whelgar. Prospector Whelgar is a dwarven archaeologist stationed at an excavation site in the Wetlands east of Menethil Harbor. His mission to uncover titan relics has stalled after vicious raptors overran the dig. He now seeks hardy adventurers willing to brave the beasts to recover ancient artifacts. Sent into the marshy wilderness of the Wetlands to unearth the history of the dwarven race, Prospector Whelgar established an archaeological camp known as Whelgar's Excavation Site. The valley was once rich with ancient stone relics, but the local raptors quickly grew territorial and drove his team into hiding. Despite the danger, Whelgar refuses to abandon his duty. He remains focused on recovering valuable relics—including the enigmatic Goaz Stone—before wild predators or rival scoundrels ruin the site entirely.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_prospector-whelgar-c6cc35ce1860884a3821/1-0000.mp3", duration = 49.1363265, start = 0},
  },
}
P.transport["npc:quartermaster-lewis"] = {
  hash = "44f6a6",
  fullHash = "44f6a6",
  text = "Quartermaster Lewis. At Sentinel Hill in Westfall, Quartermaster Lewis keeps supplies moving to the People's Militia. He serves local defenders and travelers holding the frontier against the Defias Brotherhood. Quartermaster Lewis keeps the militia's supplies in Sentinel Tower. Stormwind's royal leaders offer little aid to impoverished Westfall, so Sentinel Hill depends on local volunteers and whatever provisions they can gather. Lewis hands out field necessities, including dry rations, fresh water, arrows, shot, and throwing blades. The fighters standing watch need these basics to endure Defias raids.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_quartermaster-lewis-ca4e0e23b67aab1b62fc/1-0000.mp3", duration = 37.0677551, start = 0},
  },
}
P.transport["npc:quinn-yorick"] = {
  hash = "7bab21",
  fullHash = "7bab21",
  text = "Quinn Yorick. Quinn Yorick is a wounded Forsaken scout sheltering on the upper floor of a ruined farmhouse in the Ivar Patch. Having barely survived an encounter with the ghoul known as Ivar the Foul, he now relies on passing allies to help secure his survival. Tucked away inside an abandoned home at the Ivar Patch, Quinn Yorick lies gravely injured upstairs. His condition is the result of a vicious clash with Ivar the Foul, a ghoul lurking in the farm's barn in the northern stretches of Silverpine Forest. Sent with his sister Rane to scout Silverpine and report to High Executor Hadrec, Quinn cannot finish his mission or safely retreat alone, so he remains in hiding while travelers working for the Forsaken bring him healing and deal with the creature that nearly tore him apart.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_quinn-yorick-9d4e5952358d487b5ffb/1-0000.mp3", duration = 48.6138776, start = 0},
  },
}
P.transport["npc:ragnar-thunderbrew"] = {
  hash = "dc98ff",
  fullHash = "dc98ff",
  text = "Ragnar Thunderbrew. Ragnar Thunderbrew is a dwarven brewer and co-owner of the renowned Thunderbrew Distillery in Kharanos. Known across Dun Morogh for serving his family's signature Beer Basted Boar Ribs, he works constantly to keep the busy tavern stocked and its patrons satisfied. Standing inside the Thunderbrew Distillery at Kharanos, Ragnar Thunderbrew manages the establishment's culinary reputation alongside his family's brewing operations. The distillery is a central gathering place for local mountaineers, traveling adventurers, and gnome refugees fleeing Gnomeregan. Chief among his duties is preparing the family's renowned Beer Basted Boar Ribs, a hearty Dun Morogh specialty cooked with stout dwarven ale. However, maintaining steady supplies has become difficult; his usual meat provider enlisted in the King's Army, leaving Ragnar dependent on wandering mountaineers and hunters to keep fresh crag boar flanks coming into the kitchen. The Thunderbrew name is synonymous with dwarven alcohol and pub culture throughout Ironforge territory. Ragnar has kept the family distillery running since his older brother, Grimbooze Thunderbrew, disappeared in a drunken haze a few harvests ago, defending the family's fiercely guarded brewing heritage against thieves like the Dark Iron dwarves, who stole the recipe for Thunderbrew Lager. Between restless patrons, missing supply lines, and rowdy tavern disputes, Ragnar keeps a steady hand on the taps, ensuring no traveler departs Kharanos with an empty mug or an empty belly.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ragnar-thunderbrew-ce7fb208c2e0325da98b/1-0000.mp3", duration = 89.2081633, start = 0},
  },
}
P.transport["npc:rahauro"] = {
  hash = "7eb184",
  fullHash = "7eb184",
  text = "Rahauro. Rahauro is a tauren attendant found on the Elder Rise in Thunder Bluff, faithfully serving the elder crone Magatha Grimtotem. Acting on her behalf, he recruits brave adventurers to venture into the volcanic depths of Ragefire Chasm beneath Orgrimmar. He coordinates efforts to retaliate against the hostile troggs and recover missing possessions belonging to his mistress's fallen agents. Standing loyally near Magatha Grimtotem on the high terrace of Elder Rise, Rahauro acts as her direct intermediary. Magatha often operates through trusted underlings rather than soiling her own hooves with public recruitment. When reports emerge of wild creatures swarming beneath the orcish capital, it is Rahauro who handles the logistical details, dispatching Horde mercenaries to deal with the uprising. The troggs infesting the subterranean caverns of Ragefire Chasm did not respond kindly to diplomatic outreach. Magatha originally dispatched envoys in an attempt to forge peace with the primitive beasts, but the troggs turned violently on the delegates and butchered them. Viewing them as an intolerable threat to the Horde, Rahauro directs champions into the caverns to cull the troggs and assess their true strength.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_rahauro-f9f2971fd1a2bf05be54/1-0000.mp3", duration = 73.5085714, start = 0},
  },
}
P.transport["npc:raleigh-andrean"] = {
  hash = "9ae959",
  fullHash = "9ae959",
  text = "Raleigh Andrean. Raleigh Andrean is a Forsaken resident of the Undercity. His requests reveal a callous attitude toward his former human life and those he once knew. Before the Third War devastated Lordaeron, Raleigh Andrean lived an ordinary human life, married to a woman named Deliah and keeping company with his friend Valdred Moray. Like countless others, he fell when the Scourge tore through the kingdom, only to be raised as a mindless thrall in service to the Lich King. He regained his free will following the shattering of the Ner'zhul's grip and Sylvanas Windrunner's uprising, taking his place among the Forsaken in the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_raleigh-andrean-f474e4ceb76a3acb9394/1-0000.mp3", duration = 38.7657143, start = 0},
  },
}
P.transport["npc:randis"] = {
  hash = "123d1e",
  fullHash = "123d1e",
  text = "Randis. In Cathedral Square, Randis waits for a chance to see the world beyond Stormwind. During Children's Week, he eagerly joins willing adventurers across Alliance lands. Randis lives in the orphanage near Stormwind's Cathedral of Light, one of many children left without family by the realm's conflicts. When Children's Week comes each year, Orphan Matron Nightingale gives sympathetic heroes a whistle and entrusts them with his care. Curious and full of questions, Randis dreams of adventure, asks riddles, and declares that he wants to be king of Stormwind when he grows up. For Randis, who spends most days in Cathedral Square, leaving the capital is a grand adventure. He remarks that places like Ironforge smell odd, and his wonder shows what Alliance heroes fight to protect.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_randis-cd31b4a7e6b4efcdea7c/1-0000.mp3", duration = 50.964898, start = 0},
  },
}
P.transport["npc:ranger-glynda-nal-shea"] = {
  hash = "e4467c",
  fullHash = "e4467c",
  text = "Ranger Glynda Nal'Shea. Near Auberdine's watch, Ranger Glynda Nal'Shea directs the defense of Darkshore. The seasoned night elf sentry sends travelers to meet threats and investigate strange signs along the coast. From Auberdine, Sentinel Glynda Nal'Shea coordinates scouts as corruption grows and hostile forces press into Darkshore. She watches the wilderness around town and relies on capable travelers to guard the perimeter and protect night elf holdings along the coast. Glynda watches for dangers gathering along the shore, especially the bolder murlocs south of town. She oversees bounties on threats such as Murkdeep and sends scouts to examine strange finds, including a crimson crystal reported near Darkshore's eastern mountain range.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ranger-glynda-nal-shea-7a488f23e08091443f91/1-0000.mp3", duration = 46.4195918, start = 0},
  },
}
P.transport["npc:rau-cliffrunner"] = {
  hash = "522879",
  fullHash = "522879",
  text = "Rau Cliffrunner. Rau Cliffrunner is a tauren scout and scholar stationed high atop Freewind Post in Thousand Needles. Dedicated to protecting his people from regional threats, he studies the history and origins of the hostile Galak centaur through their ancient relics. Working closely with allies in Thunder Bluff, Rau coordinates ventures into dangerous enemy strongholds across the canyon. Perched on the perilous bluffs of Freewind Post, Rau Cliffrunner maintains a watchful eye over the sweeping, sun-scorched expanse of Thousand Needles. The tauren outpost serves as a crucial Horde sanctuary in an otherwise hostile territory teeming with ferocious predators, quilboar, and aggressive centaur clans. Rau acts as both an outpost organizer and a dedicated investigator, keen on neutralizing emerging threats before they can overwhelm the vulnerable mesa settlements.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_rau-cliffrunner-e76bb0986b12e6e2ef00/1-0000.mp3", duration = 50.6253061, start = 0},
  },
}
P.transport["npc:razzle-sprysprocket"] = {
  hash = "c0c6c7",
  fullHash = "c0c6c7",
  text = "Razzle Sprysprocket. Razzle Sprysprocket is a gnomish engineer residing in Kharanos in Dun Morogh. Known for his technical tinkering alongside Ozzie Togglevolt, he enlists travelers to help salvage disrupted gnomish machinery and components around the snowy hills. Following the tragedy at Gnomeregan, Razzle Sprysprocket found refuge among the snowdrifts of Dun Morogh, setting up his workshop in Kharanos. With a knack for delicate mechanical parts, Razzle works alongside fellow engineer Ozzie Togglevolt. Their efforts frequently involve recovering gyro-mechanisms and cog assemblies that were lost or scavenged during the flight from their irradiated homeland. Life in Dun Morogh is far from peaceful for a gnome inventor. Between the wild beasts of the frozen ridges and raids by local Frostmane trolls, Razzle's work is never entirely safe. Despite the dangers, he remains dedicated to keeping gnomish contraptions functional and recovering the lost wonders of Gnomeregan.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_razzle-sprysprocket-25a1f22a4f3edb88616d/1-0000.mp3", duration = 57.9395918, start = 0},
  },
}
P.transport["npc:red-jack-flint"] = {
  hash = "15909e",
  fullHash = "15909e",
  text = "Red Jack Flint. Red Jack Flint is a seasoned human mariner stationed within Menethil Keep in Menethil Harbor. A member of the crew of the vessel Maiden's Virtue, he serves as a point of contact for travelers seeking passage or contacts across the sea toward Kalimdor. Found inside the stone walls of Menethil Keep, Red Jack Flint is an experienced seafarer tied to the harbor's maritime trade. As part of the crew of the Maiden's Virtue, he navigates the dangerous sea routes linking the marshlands of Khaz Modan with distant shores. Rather than staying confined to naval routine, Flint directs capable adventurers to allies across the Great Sea, including contacts in Kalimdor like Fiora Longears.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_red-jack-flint-cf53b60e4ab1def4c5b8/1-0000.mp3", duration = 41.8742857, start = 0},
  },
}
P.transport["npc:rema-schneider"] = {
  hash = "324f1f",
  fullHash = "324f1f",
  text = "Rema Schneider. In Stormwind City, Rema Schneider works from the Canal Tailor and Fit Shop. She is a human citizen who often helps local shopkeepers and artisans with trade deliveries. Rema Schneider manages daily trade from the Canal Tailor and Fit Shop. The shop stands just west of the stone bridge into Cathedral Square, along Stormwind's canals. Cloth and finished garments move between local craftsmen, and Rema relies on helpful couriers to carry supplies between workshops.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_rema-schneider-93e04495e71cb54ee7a8/1-0000.mp3", duration = 28.2644898, start = 0},
  },
}
P.transport["npc:remulos"] = {
  hash = "7912ea",
  fullHash = "7912ea",
  text = "Remulos. Keeper Remulos is a demigod son of Cenarius and the venerable protector of Moonglade. Alongside Archdruid Fandral Staghelm and Hamuul Runetotem, he helps guide the Cenarion Circle in the absence of his fallen father and the sleeping Malfurion Stormrage. Unlike Staghelm, Remulos prioritizes the broader balance of nature over night elven isolationism. Keeper Remulos is an immortal keeper of the grove, bearing the lower body of a great stag and the antlered torso of an ancient dryad-father. He watches over Moonglade, the sacred sanctuary of Azeroth's druids nestled north of Mount Hyjal. While Malfurion Stormrage remains trapped in the Emerald Dream, Remulos provides divine authority and counsel to the mortals of the Cenarion Circle. He remains deeply invested in healing Azeroth's scars, offering aid to druids pursuing their sacred rites around Lake Elune'ara. Remulos frequently finds himself at ideological odds with Archdruid Fandral Staghelm. While Staghelm champions night elven supremacy and sought to restore their lost immortality through Teldrassil, Remulos vehemently opposed the planting of the new World Tree as an act of hubris. Defying Staghelm's isolationist faction, Remulos welcomed Hamuul Runetotem and the tauren into the Cenarion Circle, sharing nature's closely guarded mysteries with their shamans-turned-druids to restore the land collectively.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_remulos-af8565e5458ad1e00ecb/1-0000.mp3", duration = 85.2636735, start = 0},
  },
}
P.transport["npc:remy-two-times"] = {
  hash = "65c9dd",
  fullHash = "65c9dd",
  text = "Remy \"Two Times\". In Goldshire, Remy \"Two Times\" trades goods and pays for raw materials. He came from the Redridge Mountains and repeats the ends of his sentences. Remy \"Two Times\" trades from Goldshire, where he deals with travelers. He came west from the Redridge Mountains. When he speaks, he usually repeats the last words of each sentence twice. The odd habit gives him his nickname, but it does not keep him from seeking a profit in troubled Elwynn Forest. Kobolds overrun the local gold mines, and aggressive murlocs infest the riverbanks, disrupting trade in Elwynn. Remy turns to travelers for help. He pays for pouches of gold dust gathered from kobolds in the mines and keeps watch on suspicious murloc movements near Crystal Lake.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_remy-two-times-56d7b66a7d70cce60bc7/1-0000.mp3", duration = 43.52, start = 0},
  },
}
P.transport["npc:renato-gallina"] = {
  hash = "be3cfe",
  fullHash = "be3cfe",
  text = "Renato Gallina. In Stormwind's Trade District, Renato Gallina calls travelers toward his family's winery. Renato Gallina calls to passers-by among the Trade District stalls, proclaiming his family's vintages the finest in Stormwind. The Gallina family runs a winery along the Canals, and Renato promotes it with pamphlets. Travelers can bring one to his sister Suzetta at the shop for a free bottle of wine.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_renato-gallina-d34fa8429593d3dc3113/1-0000.mp3", duration = 23.6408163, start = 0},
  },
}
P.transport["npc:renee-lauer"] = {
  hash = "5570c5",
  fullHash = "5570c5",
  text = "Innkeeper Renee. Innkeeper Renee runs the Gallows' End Tavern in Brill, offering shelter, food, and drink to the Forsaken and to Horde travelers passing through Tirisfal Glades. Renee keeps the Gallows' End Tavern, the inn at the heart of Brill. Behind her counter she sells food, drink and general goods, and she welcomes weary newcomers to rest their bones, remarking that the Forsaken certainly do have huge appetites. For the undead of Tirisfal, her tavern is a cozy little place where victims of the plague try to make their way in the world. Renee's inn is often a newcomer's first stop in Brill. Calvin Montague of Deathknell sends fresh adventurers to her with a nondescript letter, word she has been eagerly waiting for. Below her floorboards, the tavern's cellar also holds a captured Scarlet Crusade zealot.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_renee-lauer-24960c1035b7abbd8d2e/1-0000.mp3", duration = 53.1330612, start = 0},
  },
}
P.transport["npc:renzik-the-shiv"] = {
  hash = "952eb7",
  fullHash = "952eb7",
  text = "Renzik \"The Shiv\". In Stormwind's Old Town, Renzik \"The Shiv\" directs SI:7's new rogue recruits. The goblin is Spymaster Mathias Shaw's trusted second-in-command, receiving promising agents sent from across the Alliance. Renzik keeps his past to himself. In Stormwind, he is known as a goblin who rose to become Spymaster Mathias Shaw's second-in-command in SI:7. He has little patience for pleasantries. When new recruits arrive, he asks whether they are ready to work or need a nap first. Renzik works inside SI:7's secretive fortress in Old Town, second-in-command to Mathias Shaw. Rogue mentors across the Alliance, from Ironforge to Darnassus, send their most promising agents to him. He sends them to field instructors such as Lucius in Redridge, where they can hone the skills needed to survive in the field.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_renzik-the-shiv-ed0c96f75a971e746972/1-0000.mp3", duration = 52.48, start = 0},
  },
}
P.transport["npc:rezlak"] = {
  hash = "36148d",
  fullHash = "36148d",
  text = "Rezlak. Along Durotar's roads south of Orgrimmar, Rezlak waits for help with his supply lines. The goblin entrepreneur belongs to the Tinkers' Union and hires travelers to recover missing supplies and drive off harpies. Rezlak waits beside the canyon road between Razor Hill and Orgrimmar. He represents the Tinkers' Union, a goblin syndicate focused on engineering, supply lines, and practical business. The factional tensions of Kalimdor matter little to him while trade runs smoothly. Dustwind harpies have raided his cargo caravans and made the routes unsafe. Rezlak remains at his post and hires passersby willing to earn a profit by recovering supplies and dealing with the harpies.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_rezlak-e02401a38fec00ee8454/1-0000.mp3", duration = 42.004898, start = 0},
  },
}
P.transport["npc:rhinag"] = {
  hash = "257cc1",
  fullHash = "257cc1",
  text = "Rhinag. Among the rocks near Durotar's northwestern border, Rhinag waits, weakened by scorpids' venom. The Darkspear troll depends on passing travelers to find him a remedy in time. Rhinag shelters among the rocks near Durotar's northwestern border after a Venomtail Scorpid stung him. The poison has left the Darkspear troll weak and isolated. He needs a venomtail antidote, and his survival depends on whether a passing traveler can find one before the toxins take their toll.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_rhinag-8e134c097c9d66eca86a/1-0000.mp3", duration = 27.3240816, start = 0},
  },
}
P.transport["npc:ringo"] = {
  hash = "be24ef",
  fullHash = "be24ef",
  text = "Ringo. Ringo is an unfortunate goblin explorer who ventured up the blistering heights of Fire Plume Ridge in Un'Goro Crater. Overwhelmed by the volcano's stifling heat and noxious vapors, he collapsed inside a cave, desperate for someone to help him back down. His close friend Spraggle Frock remains worried sick back at Marshal's Refuge. While goblins are known for braving hazardous environments in search of wealth or oddities, Fire Plume Ridge proves harsh even by their standards. Towering in the center of Un'Goro Crater, the active volcano spews ash, magma, and boiling steam. Ringo climbed about halfway up the southern face before the suffocating heat finally proved too much for him. Leaving his belongings scattered just outside, he crawled into a cave to shelter from the sweltering atmosphere, completely incapacitated by heat exhaustion.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ringo-c1cbe1053f2d16791686/1-0000.mp3", duration = 51.0171429, start = 0},
  },
}
P.transport["npc:rivern-frostwind"] = {
  hash = "42b0e4",
  fullHash = "42b0e4",
  text = "Rivern Frostwind. Rivern Frostwind is a night elf riding instructor stationed high atop Frostsaber Rock in northern Winterspring. Accompanied by his frost tiger companion Glacier, he watches over the native wintersabers and trains riders deemed worthy by his order. Only the most dedicated champions of the Alliance are granted the honor of riding one of his prized mounts. Perched on the icy promontory of Frostsaber Rock, Rivern Frostwind oversees the breeding and stewardship of the legendary Winterspring frostsaber. While nightsabers roam the lush forests of Teldrassil and Ashenvale, their sub-arctic cousins are bred to endure the bitter cold of northern Kalimdor. Rivern acts as a gatekeeper for these majestic predators. He demands that outsiders prove their commitment to preserving the beasts—gathering fresh meat from the tundra, clearing out Winterfall furbolgs, and driving back rampaging frost giants—before he will even consider entrusting one of the sabers to them.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_rivern-frostwind-02cdd62ceb2124540828/1-0000.mp3", duration = 57.3126531, start = 0},
  },
}
P.transport["npc:roetten-stonehammer"] = {
  hash = "956c57",
  fullHash = "956c57",
  text = "Roetten Stonehammer. Roetten Stonehammer is an enterprising dwarf found wandering the Library in Ironforge's Hall of Explorers. Representing the interests of Reclaimers Inc., he organizes expeditions and recruits adventurers to handle salvage operations in distant lands like Desolace. Amid the ancient tomes and dust of the Hall of Explorers' Library, Roetten Stonehammer keeps his eye on matters of practical recovery. Operating on behalf of Reclaimers Inc., Roetten connects daring mercenaries with lucrative salvage contracts across Kalimdor. Rather than digging purely for historical curiosity, his associates look to reclaim valuable cargo, wreckage, and rare reagents from perilous frontiers like the rugged wastes of Desolace.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_roetten-stonehammer-1d296699626350fac90b/1-0000.mp3", duration = 43.3893878, start = 0},
  },
}
P.transport["npc:royal-historian-archesonus"] = {
  hash = "a6b046",
  fullHash = "a6b046",
  text = "Royal Historian Archesonus. Royal Historian Archesonus is a dwarven scholar serving King Magni Bronzebeard within Ironforge's High Seat. Renowned for her scholarly works documenting recent catastrophes in the northern human kingdoms, she also directs research into ancient dwarven tragedies, notably the scorched remains of the Dark Iron kingdom. Stationed steps from King Magni Bronzebeard's throne in the High Seat, Royal Historian Archesonus maintains historical records on behalf of the Ironforge crown. Her academic gaze extends well beyond the Khaz Modan mountains. She authored 'The Fall of Lordaeron and the Scouring of the Eastweald' as well as 'On Plagues, Curses, and Blights,' tracking the horrific collapse of humanity's northern realm under the Scourge. Rather than hiding from dark histories, Archesonus approaches disasters methodically, seeking to record the truth of ruinous magic and political collapse. In addition to her texts on Lordaeron, Archesonus oversees inquiries into the War of the Three Hammers and the catastrophic destruction of the city of Thaurissan. Seeking recovered relics and charred tablets from the Burning Steppes, she enlists adventurers to search the Smoldering Ruins of Thaurissan. For Archesonus, understanding the cataclysm that scorched the Burning Steppes and bound the Dark Iron clan to the Firelord is vital statecraft—ensuring the Bronzebeard kingdom remembers exactly what sorcery and desperation can unleash.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_royal-historian-archesonus-42060c46a678659d949f/1-0000.mp3", duration = 86.9616327, start = 0},
  },
}
P.transport["npc:ruga-ragetotem"] = {
  hash = "712d6d",
  fullHash = "712d6d",
  text = "Ruga Ragetotem. At Camp Taurajo, Ruga Ragetotem trains warriors for the Horde. He tests them against the silithid in the southern Barrens before sending the proven toward custom armor. At Camp Taurajo, Ruga Ragetotem trains warriors who want to prove their strength in Kalimdor. Silithid have suddenly appeared to the south, carving hives into the Field of Giants. Ruga sends young fighters to hunt the insectoids and cut off their antennae. Those who endure the trial earn his respect and a recommendation to Thun'grim Firegaze, a renowned armorsmith.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ruga-ragetotem-f51756117b04697f0c38/1-0000.mp3", duration = 34.0897959, start = 0},
  },
}
P.transport["npc:rutgar-glyphshaper"] = {
  hash = "b3d365",
  fullHash = "b3d365",
  text = "Rutgar Glyphshaper. Rutgar Glyphshaper is a dwarven archaeologist stationed at the Bronzebeard Encampment in the southern reaches of Silithus. As a member of Brann Bronzebeard's expedition, he studies ancient silithid relics and runes, striving to uncover the mystery of the hives even after Brann wanders off into the desert. Rutgar Glyphshaper traveled to Silithus under the leadership of Brann Bronzebeard to investigate the vast silithid hives and unearth lost relics buried beneath the desert wastes. Establishing their base at the Bronzebeard Encampment south of Cenarion Hold, Rutgar and his companions frequently ventured directly into the bug hives to harvest inscribed stones and runic artifacts, often cooperating with Cenarion night elf researchers.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_rutgar-glyphshaper-cba476de49ac09d80ee9/1-0000.mp3", duration = 44.8261224, start = 0},
  },
}
P.transport["npc:ruul-eagletalon"] = {
  hash = "58aa4b",
  fullHash = "58aa4b",
  text = "Ruul Eagletalon. Ruul Eagletalon is a tauren resident of Bloodhoof Village in Mulgore. Stationed near the settlement's perimeter, he keeps a watchful eye on the local wildlife, particularly the aggressive Windfury harpies encroaching upon tauren lands. Ruul Eagletalon stands guard in Bloodhoof Village, tending to the security of the settlement as young braves arrive from Camp Narache. While Mulgore is a peaceful homeland compared to the arid wastes of the Barrens, territorial predators and hostile creatures continually press against the pastures. Ruul concerns himself with threats roaming the nearby plains, notably directing capable travelers to confront the savage Windfury harpies who prey on unwary nomads and game.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ruul-eagletalon-4443e6f06f9382b00891/1-0000.mp3", duration = 44.2253061, start = 0},
  },
}
P.transport["npc:ruul-snowhoof"] = {
  hash = "d14325",
  fullHash = "d14325",
  text = "Ruul Snowhoof. Ruul Snowhoof is a tauren druid held captive inside Thistlefur Hold in northern Ashenvale. Trapped in his bear form within a crude cage, he relies on Horde adventurers to break him out and guide him to safety. Ruul Snowhoof ventured into northern Ashenvale only to fall into the clutches of the corrupt Thistlefur furbolgs. When captured, he assumed the shape of a mighty bear—a guise his captors entirely mistook for an actual wild beast. Instead of slaying him outright, the furbolgs locked him inside a wooden cage deep within Thistlefur Hold, leaving him to slowly starve. Weakened and unable to safely drop his form or fight his way out alone, Ruul waits for allies of the Horde to spring his lock, fight off his jailers, and clear a path through the den so he can return to his sister, Yama Snowhoof, at Splintertree Post.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ruul-snowhoof-b5f86b520eb98c8e67fc/1-0000.mp3", duration = 51.2261224, start = 0},
  },
}
P.transport["npc:rwag"] = {
  hash = "aee7e4",
  fullHash = "aee7e4",
  text = "Rwag. In the Den, Rwag teaches the first steps of a rogue's craft. The orc trains newly arrived orcs and trolls in stealth, subterfuge, and dirty fighting in Durotar's Valley of Trials, under the Horde's watch. Deep in the Den, Rwag trains fledgling rogues, cutpurses, and thieves before they venture beyond the cave into Durotar. The new Horde champions martial honor and battlefield valor, but Rwag knows subtlety, poisons, and a well-placed dagger remain tools for survival in the unforgiving desert. He keeps watch over business in the Valley and distrusts the dark practitioners sheltering in the cave, especially the warlock Nartok.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_rwag-db15c8f2f9e096e2cc40/1-0000.mp3", duration = 42.3183673, start = 0},
  },
}
P.transport["npc:saelienne"] = {
  hash = "bedc45",
  fullHash = "bedc45",
  text = "Saelienne. On the Craftsmen's Terrace in Darnassus, Saelienne keeps an inn for travelers and artisans. She offers food, drink, and a place to bind a Hearthstone in the night elven capital. Innkeeper Saelienne welcomes residents and visitors to her inn on Darnassus's Craftsmen's Terrace. She gives travelers a calm place to rest and serves night elven refreshments and goods brought through the city port. Tradesfolk come in after long hours at the forge or loom. Saelienne's inn gives them a place to gather and recover.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_saelienne-aac430f0ae8544217811/1-0000.mp3", duration = 32.6530612, start = 0},
  },
}
P.transport["npc:sally-whitemane"] = {
  hash = "a69fd7",
  fullHash = "a69fd7",
  text = "High Inquisitor Whitemane. Whitemane is the High Inquisitor of the Scarlet Crusade, presiding over the Cathedral of the Scarlet Monastery. A powerful priestess of the Holy Light, her consuming hatred for the undead drives the Crusade's uncompromising zealotry. Together with Scarlet Commander Renault Mograine, she directs the order's military and ideological campaigns across Lordaeron. Rising rapidly through the Scarlet Crusade's hierarchy, Whitemane became its High Inquisitor and took command of the Scarlet Monastery's grand Cathedral. Renowned for her fearsome mastery of Holy magic, she has become one of the Crusade's foremost symbols through her absolute conviction, wielding the Light as an unrelenting weapon against any deemed unclean.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sally-whitemane-d86e62109eaa6abd48b0/1-0000.mp3", duration = 44.4604082, start = 0},
  },
}
P.transport["npc:salma-saldean"] = {
  hash = "928680",
  fullHash = "928680",
  text = "Salma Saldean. At Saldean's Farm, Salma Saldean keeps a welcome place for travelers. She and her husband, Farmer Saldean, tend the homestead in Westfall, where bandits threaten the farms and Stormwind has left the region. She offers meals in return for help around the farm. Salma Saldean welcomes travelers to a farm that has endured where neighboring homesteads have burned or fallen to the Defias Brotherhood. A hearty pot waits on the stove, and she looks for capable hands to help around the farmstead. Salma feeds her family and visitors with what Westfall provides. She teaches travelers to make Goretusk liver pie and Westfall stew with wild boar, vultures, murlocs, and stray okra.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_salma-saldean-64612cdc902203677528/1-0000.mp3", duration = 43.0497959, start = 0},
  },
}
P.transport["npc:sara-balloo"] = {
  hash = "9214aa",
  fullHash = "9214aa",
  text = "Sara Balloo. Sara Balloo is a grieving dwarven widow residing in the Military Ward of Ironforge. She spends her days mourning her late husband, Sully Balloo, clinging to any remnant or message left behind from his final days in service. Standing within the bustling Military Ward of Ironforge, Sara Balloo presents a somber contrast to the clatter of weaponry and martial drills. Her husband, Sully Balloo, fell in battle far from home, leaving her alone with memories and lingering grief. For Sara, closure arrives only through recovered words—a final letter carrying Sully's devotion across the mountains from the scene of his demise.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sara-balloo-1c93bbc43d00334c61cb/1-0000.mp3", duration = 38.2432653, start = 0},
  },
}
P.transport["npc:sara-timberlain"] = {
  hash = "3ad094",
  fullHash = "3ad094",
  text = "Sara Timberlain. At Eastvale Logging Camp, Sara Timberlain stitches gear for the Stormwind Army. She makes useful armaments from salvaged cloth and leather. Sara Timberlain works with needle and thread outside a small cottage on the western edge of Eastvale Logging Camp. Axes sound through the camp as workers fell trees. Though Eastvale lies far from settled lands, wolves and murlocs prowl nearby, and Sara still offers travelers hospitality. She turns scraps of linen and salvaged bandanas into sturdy gear. Her skill has earned official recognition and commissions to supply cloth and leather armaments to Stormwind's military forces.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sara-timberlain-6954c5a035f61a4f10a0/1-0000.mp3", duration = 39.9412245, start = 0},
  },
}
P.transport["npc:scooty"] = {
  hash = "b5015b",
  fullHash = "b5015b",
  text = "Scooty. Scooty is a goblin engineer operating out of the bustling pirate port of Booty Bay. Proclaiming himself a master of engineering, he maintains a delicate transponder setup linked directly to an experimental teleporter in the fallen city of Gnomeregan. His contraptions offer Horde operatives a direct, if perilous, technological bypass right into the heart of Dun Morogh. Operating amid the wharves and workshops of Booty Bay, Scooty holds court as one of the Steamwheedle Cartel's most ambitious tinkerers. While typical goblins obsess over gunpowder and explosives, Scooty turned his attention to instantaneous molecular transport. By calibrating complex transponder systems, he manages a direct operational link to a teleportation pad situated inside Gnomeregan. Horde forces looking to breach the subterranean gnome stronghold rely heavily on Scooty's tinkering to bypass treacherous Alliance territory altogether. Maintaining experimental goblin teleporters is rarely a dull enterprise. Scooty and his partner Sovik built the Transpolyporter 6000 after word reached them of a new gnomish rig in Gnomeregan, and by Scooty's own cheerful admission it has only exploded a dozen or so times. Despite the obvious physical perils involved in being dematerialized across continents, Scooty remains entirely confident in his genius, dismissing every catastrophic mechanical hiccup as merely a minor obstacle on the road to true innovation.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_scooty-36878b205f099fd1f033/1-0000.mp3", duration = 88.3461224, start = 0},
  },
}
P.transport["npc:scout-riell"] = {
  hash = "f1ddab",
  fullHash = "f1ddab",
  text = "Scout Riell. At Sentinel Hill, Scout Riell watches Westfall from the watchtower roof. She serves the People's Militia, tracking the Defias Brotherhood and calling on travelers to bring back the outlaws' red silk bandanas. Scout Riell watches the plains from the stone tower at Sentinel Hill, where banditry and harvest golems threaten Westfall. Stormwind's royal army is absent, and the crown refuses aid, leaving the People's Militia to defend the region. From the tower roof, Riell tracks the Defias Brotherhood's movements and gathers proof of their crimes. She calls on passing travelers to take red silk bandanas from the bandits.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_scout-riell-abed28d8661b1c715b60/1-0000.mp3", duration = 38.6612245, start = 0},
  },
}
P.transport["npc:scout-thaelrid"] = {
  hash = "ddb3f8",
  fullHash = "ddb3f8",
  text = "Argent Guard Thaelrid. Argent Guard Thaelrid is a wounded night elf scout sent by the Argent Dawn into the submerged ruins of Blackfathom Deeps. Trapped near the Pool of Ask'ar, he bears witness to the dark alliance taking root between the naga and the Twilight's Hammer cult. When strange reports trickled out of the Zoram Strand concerning foul rites deep beneath the sea, the Argent Dawn took interest. Dedicated to watching for rising evils and unnatural corruption across Azeroth, the order dispatched Scout Thaelrid to slip inside Blackfathom Deeps. His mission was simple: assess the depth of the threat, observe the movements within the flooded temple, and report back so the Dawn could decide where aid was most desperately needed.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_scout-thaelrid-0dd2274b7907fc4fce87/1-0000.mp3", duration = 44.3559184, start = 0},
  },
}
P.transport["npc:searn-firewarder"] = {
  hash = "528032",
  fullHash = "528032",
  text = "Searn Firewarder. In Grommash Hold, Searn Firewarder guides Horde shamans toward the elements. Inside Grommash Hold, Searn Firewarder guides shamans seeking the elements. Many Darkspear trolls commune with spirits through witch doctors and voodoo rituals. Searn guides initiates toward distant mentors and rites for the Call of Fire, Call of Water, and Call of Air, which teach them to commune with the elemental spirits of fire, water, and air. He stands among the Horde's high command in Orgrimmar.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_searn-firewarder-52a604fe692db50b6319/1-0000.mp3", duration = 29.9885714, start = 0},
  },
}
P.transport["npc:seer-graytongue"] = {
  hash = "187fe9",
  fullHash = "187fe9",
  text = "Seer Graytongue. Seer Graytongue is a venerable tauren elder and spiritual guide residing on Red Cloud Mesa in Mulgore. Stationed near Camp Narache, he tests young braves undertaking their earliest tribal trials. Through rituals such as the Rite of Strength, he ensures that the youth honor the Earthmother before stepping into the wider world. Seer Graytongue makes his home atop Red Cloud Mesa, serving as an early instructor for aspiring tauren braves and spellweavers. As young adventurers set forth from Camp Narache, Graytongue oversees critical steps of their sacred passage, including the Rites of the Earthmother. By testing their resolve against the harsh plains and dangerous beasts of Mulgore, he instills the virtues of honor, patience, and reverence that every true tauren must carry into adulthood.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_seer-graytongue-eec063bfbc88e0a30f31/1-0000.mp3", duration = 47.5689796, start = 0},
  },
}
P.transport["npc:seer-ravenfeather"] = {
  hash = "e888c7",
  fullHash = "e888c7",
  text = "Seer Ravenfeather. Seer Ravenfeather is a tauren shaman instructor stationed at Camp Narache on the Red Cloud Mesa. She guides fledging spiritualists through their early trials, helping them attune to the voices of the spirits and the land of Mulgore. Standing within the quiet shelters of Camp Narache, Seer Ravenfeather serves as a patient teacher for young tauren called to walk the shamanic path. The Red Cloud Mesa is a sacred proving ground, and Ravenfeather ensures that novice practitioners understand their duties before venturing into the wider expanses of Mulgore. She instructs them in the foundational rites needed to commune with elemental forces and honor the Earth Mother. Ravenfeather's primary charge is overseeing the initial spiritual steps of nascent shamans, directing them in the traditional rite known as the Call of Earth. Through her guidance, initiates prepare ceremonial saptas and seek communion with the earthen spirits nestled within the mesa's stony outcrops, forging a bond that anchors their elemental magic.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_seer-ravenfeather-c5c3664b9e8d8b83c02d/1-0000.mp3", duration = 62.6416327, start = 0},
  },
}
P.transport["npc:seereth-stonebreak"] = {
  hash = "ad2e0b",
  fullHash = "ad2e0b",
  text = "Seereth Stonebreak. Near Greatwood Vale, Seereth Stonebreak watches the land's disturbances. The orc shaman camps on the border of the Stonetalon Mountains and the Barrens, guiding travelers against environmental ruin, rogue machines, and rising tensions in Kalimdor. Seereth Stonebreak watches over Horde lands from her camp near Greatwood Vale. An orc shaman, she follows the harmony of the elements and protects the territories of the Horde. The land's spirits cried out against goblin plunder, and the Horde sent her to Stonetalon. There, she watches the landscape and guides travelers against dangers threatening the wild frontier. Seereth Stonebreak is troubled by turmoil across the Stonetalon range. Ruthless goblin ventures and mechanical shredders cutting through ancient woodlands have badly fractured the mountains' spiritual balance. She sends Horde envoys to confront the invaders and seek counsel from elder lorekeepers, in hopes of easing the land's distress.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_seereth-stonebreak-53d253d88f1cac69cd94/1-0000.mp3", duration = 57.7567347, start = 0},
  },
}
P.transport["npc:senator-mehr-stonehallow"] = {
  hash = "9277b4",
  fullHash = "9277b4",
  text = "Senator Mehr Stonehallow. Senator Mehr Stonehallow is an Ironforge politician and member of the Explorers' League stationed at the Gol'Bolar Quarry in Dun Morogh. Rather than debating policy in the capital, he has traveled to the front lines to personally oversee the containment of the local trogg infestation. He enlists eager adventurers to cull the beasts before they overrun the quarry completely. While most members of the Ironforge Senate spend their days safely sequestered within the great stone halls of the capital, Senator Mehr Stonehallow prefers direct action. As a dwarf dedicated both to governance and the historical pursuits of the Explorers' League, he understands the practical dangers facing the realm. When vicious Rockjaw troggs began clawing out of the deep rock in Gol'Bolar Quarry, Stonehallow made the journey to the mining pit himself. Convinced that bureaucratic posturing will not save the workers, he offers bounties to capable travelers to eradicate the aggressive troggs and reclaim the quarry.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_senator-mehr-stonehallow-000f578490f3df621c86/1-0000.mp3", duration = 58.5404082, start = 0},
  },
}
P.transport["npc:senior-surveyor-fizzledowser"] = {
  hash = "610b24",
  fullHash = "610b24",
  text = "Senior Surveyor Fizzledowser. Senior Surveyor Fizzledowser is a goblin researcher working from Gadgetzan in Tanaris. He investigates disruptions around the local water supply and sends adventurers to look into the disappearance of Scrimshank.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_senior-surveyor-fizzledowser-01e82cccc3d2a7b24ba8/1-0000.mp3", duration = 11.9902041, start = 0},
  },
}
P.transport["npc:sentinel-arynia-cloudsbreak"] = {
  hash = "f1c15b",
  fullHash = "f1c15b",
  text = "Sentinel Arynia Cloudsbreak. At Oracle Glade on Teldrassil, Sentinel Arynia Cloudsbreak watches over the northern groves. She guards the enchanted waters and woodland wildlife. Sentinel Arynia Cloudsbreak keeps watch in Oracle Glade, one of Teldrassil's most secluded reaches. Far from Darnassus, she serves the Sentinel army among ancient trees and ethereal springs, guarding the wilderness from disturbance. Disharmony stirs among Teldrassil's creatures despite the tree's sacred birth. Arynia asks passing adventurers and young night elves to look into local troubles, from strange wildlife to mystical signs around the enchanted springs.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sentinel-arynia-cloudsbreak-3bfbde0d0aa504a6e6b5/1-0000.mp3", duration = 38.9746939, start = 0},
  },
}
P.transport["npc:sentinel-aynasha"] = {
  hash = "a70c7d",
  fullHash = "a70c7d",
  text = "Sentinel Aynasha. Along Darkshore’s wild borders, Sentinel Aynasha scouts the dangers threatening night elven lands. She watches enemy movements and carries urgent intelligence across the frontier. Sentinel Aynasha scouts and fights with the Sentinels where night elven lands meet hostile incursions. She carries urgent messages across rough country and watches for enemy patrols. Her skill with a bow and her knowledge of survival help her cross contested ground.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sentinel-aynasha-eca4fa6f9734bfb0fe49/1-0000.mp3", duration = 28.1861224, start = 0},
  },
}
P.transport["npc:sentinel-elissa-starbreeze"] = {
  hash = "d50064",
  fullHash = "d50064",
  text = "Sentinel Elissa Starbreeze. In Auberdine, Sentinel Elissa Starbreeze watches over the misty coast of Darkshore. From the upper floor of a lodge across the bridge, she tracks growing threats and directs travelers toward dangers in the wilderness. Sentinel Elissa Starbreeze coordinates Auberdine's defenses from across the bridge. While other Sentinels patrol Darkshore's coast and woodlands, she watches from the upper floor of a building northeast of the town inn. She keeps alert for unusual disturbances across the region. Her directions send travelers to distant places, including the Tower of Althalaxx far to the north, so threats in the shadows do not catch Auberdine unaware.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sentinel-elissa-starbreeze-d40a307f9d247bde4273/1-0000.mp3", duration = 42.4228571, start = 0},
  },
}
P.transport["npc:sentinel-farsong"] = {
  hash = "3cbc07",
  fullHash = "3cbc07",
  text = "Sentinel Farsong. Sentinel Farsong is a night elf sentinel stationed at Silverwing Grove in Ashenvale. Serving as a crucial liaison for the Silverwing Sentinels, she coordinates intelligence and combat efforts against the encroaching Warsong Outriders in Warsong Gulch. Standing vigil within Silverwing Grove, Sentinel Farsong is deeply involved in the defense of Ashenvale's southern border. With the Warsong clan continuously harvesting lumber and pushing deeper into ancestral night elf territories, she mobilizes Alliance champions to strike at Warsong Outriders and ensures field reports reach Silverwing command. Her duties center on rallying volunteers to check the Horde's territorial expansion and preserve the sacred woods.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sentinel-farsong-0eb6e3f247a61e9301d6/1-0000.mp3", duration = 42.1877551, start = 0},
  },
}
P.transport["npc:sentinel-onaeya"] = {
  hash = "743889",
  fullHash = "743889",
  text = "Sentinel Onaeya. Sentinel Onaeya is a night elf guardian stationed at Maestra's Post in northwestern Ashenvale, near the border with Darkshore. Tasked with holding the line against encroaching perils, she rallies capable Alliance adventurers to safeguard the forest and aid fellow sentinels. Maestra's Post serves as a critical wayside outpost along the road from Darkshore into the dense, contested canopy of Ashenvale. Sentinel Onaeya stands guard outside the settlement's main lodge, keeping a vigilant watch over travelers and coordinating defensive actions. Between hostile wildlife, corrupting forces, and border tensions, sentinels like Onaeya represent the first line of defense for night elf settlements in the region. Onaeya receives news of Sentinel Aynasha, who is attacked by furbolgs while carrying an important message through Darkshore. She rewards adventurers who protect the poisoned sentinel until her antidote takes effect.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sentinel-onaeya-ea796b9292b8e3ebb4c2/1-0000.mp3", duration = 56.5028571, start = 0},
  },
}
P.transport["npc:sentinel-selarin"] = {
  hash = "e73fb2",
  fullHash = "e73fb2",
  text = "Sentinel Selarin. Sentinel Selarin is a night elf scout dispatched to the coastal settlement of Auberdine. Acting as an emissary for the defenders of Ashenvale, she seeks reinforcements to help stem the rising perils threatening the ancient forest. As tensions and dark threats mount across Ashenvale, the garrison there has found its resources stretched to the breaking point. Under the direction of Raene Wolfrunner, Sentinel Selarin traveled north along the forest road into Darkshore. Her mission was straightforward: seek out Terenthis in Auberdine and request assistance from the sentinels and scouts stationed on the coast. Upon arriving in Auberdine, Selarin found Terenthis thoroughly consumed by local duties and unable to personally answer the call. Rather than returning empty-handed, Selarin resolved to remain in town and enlist capable travelers passing through Darkshore. She directs proven adventurers south toward Astranaar, urging them to lend their blades and spells to Raene Wolfrunner's beleaguered forces.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sentinel-selarin-b94ef9aca1a2e2c73c81/1-0000.mp3", duration = 61.9363265, start = 0},
  },
}
P.transport["npc:sentinel-thenysil"] = {
  hash = "9367b6",
  fullHash = "9367b6",
  text = "Sentinel Thenysil. Sentinel Tara Thenysil is a night elf sentinel stationed in Astranaar within the ancient forest of Ashenvale. Vigilant over the surrounding wilderness, she keeps close tabs on military operations in the region and coordinates scouts watching neighboring territories. Her attention is particularly focused on allied movements pushing south into the contested Stonetalon Mountains. From her post in the fortified settlement of Astranaar, Sentinel Thenysil helps secure Ashenvale against growing hostility. Night elf holdings throughout the region face relentless encroachment, making communications between distant outposts vital. While much of the local garrison focuses directly on defending the forest road, Thenysil directs Alliance volunteers beyond Ashenvale's borders to ensure distant allies remain supported. Thenysil maintains a close personal and military friendship with Kaela Shadowspear, an operative deployed south into the crags of the Stonetalon Mountains. Learning that Kaela was dispatched alongside an eccentric gnome mage, Thenysil considered the unorthodox pairing an unmistakable sign of serious trouble brewing in the peaks. Wary of what dangers her comrade might face, she recruits capable adventurers to journey south, deliver support, and report on the unfolding mission.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sentinel-thenysil-f440b80b12e17be6986b/1-0000.mp3", duration = 79.3861224, start = 0},
  },
}
P.transport["npc:sentinel-tysha-moonblade"] = {
  hash = "8bed52",
  fullHash = "8bed52",
  text = "Sentinel Tysha Moonblade. Along Darkshore’s road, Sentinel Tysha Moonblade watches a troubled coast. The night elf scout stands west of Ameth'Aran, guiding travelers and seeking help with the restless spirits haunting the nearby ruins. Sentinel Tysha Moonblade watches the road through Darkshore. East of her lie the ruins of Ameth'Aran, where cursed Highborne ghosts and malevolent banshees linger among ancient stone pillars. Auberdine's defenses are stretched thin by dangers along the coast, so Tysha asks capable travelers to uncover the history of Ameth'Aran's fall and put down its restless dead.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sentinel-tysha-moonblade-d21e625f6e75cc561dd5/1-0000.mp3", duration = 36.8065306, start = 0},
  },
}
P.transport["npc:sentinel-velene-starstrike"] = {
  hash = "af0648",
  fullHash = "af0648",
  text = "Sentinel Velene Starstrike. Sentinel Velene Starstrike is a night elf guardian stationed at Silverwind Refuge in central Ashenvale. Tasked with protecting the sanctuary and the surrounding waters, she confronts encroaching unnatural threats such as rogue elementals and foul sorcerers. Her vigilance helps safeguard the ancient woodland from corrupting magical interference. Stationed beside the clear waters of Mystral Lake, Sentinel Velene Starstrike maintains a watchful vigil from Silverwind Refuge. Like many night elf sentinels scattered throughout Ashenvale, her primary duty is preserving the balance of the forest and repelling threats to elven sanctuaries. The serene grove serves as a vital rest stop for travelers traversing the central woods, making her presence essential to the area's ongoing safety. The peace around Silverwind Refuge is fragile. Velene keeps close watch over Mystral Lake, where erratic elemental spirits and reckless mage summoners disrupt the natural rhythm of the wilderness. Through her direction, champions are dispatched to suppress rogue water elementals and put an end to the careless practitioners disturbing the spirits of the land.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sentinel-velene-starstrike-3e7b86a422cdfc5b831a/1-0000.mp3", duration = 68.075102, start = 0},
  },
}
P.transport["npc:serge-hinott"] = {
  hash = "a7837f",
  fullHash = "a7837f",
  text = "Serge Hinott. In Tarren Mill, Serge Hinott brews mixtures for the Forsaken war effort. The Forsaken alchemist works alongside Apothecary Lydon, preparing concoctions, antidotes, and reagents for the Royal Apothecary Society. Serge Hinott brews remedies and other mixtures for the Forsaken in Tarren Mill. He works beside Apothecary Lydon, whose work includes chemical development and plague research against nearby human settlements such as Southshore. Hinott handles specialized brewing, including restorative salves and antidotes for field agents and scouts who face poisons or other toxic mishaps.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_serge-hinott-f199f4897324ecfd8015/1-0000.mp3", duration = 37.1983673, start = 0},
  },
}
P.transport["npc:shanda"] = {
  hash = "b5905d",
  fullHash = "b5905d",
  text = "Shanda. In Aldrassil, Shanda guides young night elf priests in the ways of Elune. She serves the Sisterhood of Elune in Shadowglen, teaching prayers, wards, and rites as her students prepare to defend Teldrassil. Shanda guides young night elves devoted to Elune from within Aldrassil. While druids tend Teldrassil's roots and boughs, priestesses keep the Kaldorei close to the White Lady. Shanda teaches new initiates to call on lunar grace for healing and protective wards, preparing them to face the corruption creeping into the World Tree's boughs. Young priests who awaken to their calling in Shadowglen come to Shanda to prove their devotion and learn their first prayers. Through rites such as In Favor of Elune, she tests their resolve, gives them blessed regalia, and teaches basic incantations. Her students learn to tend the wounded with a gentle hand and stand firm against the shadows.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_shanda-ea63cc01c1bdcede775e/1-0000.mp3", duration = 55.04, start = 0},
  },
}
P.transport["npc:shandris-feathermoon"] = {
  hash = "55ee4a",
  fullHash = "55ee4a",
  text = "Shandris Feathermoon. Shandris Feathermoon is the General of the Sentinel Army and, for ten thousand years, Tyrande Whisperwind's right hand. She now commands night elf military forces throughout Kalimdor from Feathermoon Stronghold on Sardor Isle off the coast of Feralas. Shandris Feathermoon is one of the oldest defenders of the night elves. For ten thousand years she has served at Tyrande Whisperwind's side as the high priestess's right hand among the Sentinels, through the long vigil that followed the Sundering. Following the Great Sundering and the founding of the Sentinels, Shandris became an indispensable commander within the night elf military. Today, General Feathermoon serves as the supreme field commander of the Sentinel army. Stationed on Sardor Isle, she oversees Feathermoon Stronghold, an imposing elven fortress that keeps watch over the primal wilds of Feralas. From this island outpost, she monitors the encroaching threats of savage gnolls, lingering Gordunni ogres, hate-fueled satyrs, and the expanding power of the Horde in southern Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_shandris-feathermoon-c16065c4b76656c89d8a/1-0000.mp3", duration = 64.235102, start = 0},
  },
}
P.transport["npc:shari-stilwell"] = {
  hash = "0b19ec",
  fullHash = "0b19ec",
  text = "Shari Stilwell. Shari Stilwell is a Forsaken paladin trainer stationed in the settlement of Brill within Tirisfal Glades. Bearing a surname shared with notable figures in the Eastern Kingdoms, she instructs Forsaken who take up the mantle of holy warriors. Her presence marks a rare and unconventional discipline among the undead under the Banshee Queen. Found among the blight-touched buildings of Brill, Shari Stilwell stands out as a mentor to Forsaken holy warriors. While the holy Light is excruciating to the undead, Shari guides fledgling Forsaken who endure that agonizing path. She aids newcomers seeking their footing in Tirisfal Glades through their early training and adjustments, offering guidance to those looking to secure a place within the Forsaken kingdom. Shari shares her family name with several living figures scattered across the southern kingdoms, including Daphne, Merissa, and the renowned smith Jordan Stilwell. Whether she was torn away from these kin during the fall of Lordaeron or shares only a distant lineage remains an unspoken tragedy of the Scourge's devastation.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_shari-stilwell-febde7d099cef2594012/1-0000.mp3", duration = 62.7983673, start = 0},
  },
}
P.transport["npc:shelene-rhobart"] = {
  hash = "f1f5bc",
  fullHash = "f1f5bc",
  text = "Shelene Rhobart. Shelene Rhobart is a Forsaken leatherworking trainer stationed along the road in Tirisfal Glades. Operating out of a Deathguard waystation, she supplies cured hides and leathercraft training to support the Forsaken's military and logistical efforts across the blighted lands. Shelene Rhobart plies her trade at a Deathguard waystation, an outpost situated southeast of Brill along the main road toward the ruins of Lordaeron. Even in undeath, practical crafts remain essential for survival and war. Shelene works with animal pelts collected from the prowling beasts of Tirisfal, refining tough hides into armor, straps, and field gear to supply local Forsaken patrols contending with both the Scourge and Scarlet crusaders.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_shelene-rhobart-705be13681ebf496b64f/1-0000.mp3", duration = 44.564898, start = 0},
  },
}
P.transport["npc:shindrell-swiftfire"] = {
  hash = "a2298f",
  fullHash = "a2298f",
  text = "Shindrell Swiftfire. Shindrell Swiftfire is a night elf sentinel and scout stationed in Astranaar, the heart of night elf operations in Ashenvale. Keenly aware of shifting perils along Kalimdor's western reaches, she directs capable Alliance adventurers toward gathering threats on the coastline and nearby mountain passes. Her duties make her an essential hub for coordinating local defense against emerging oceanic and wild menaces. From Astranaar's winding walkways, Shindrell Swiftfire serves as an alert observer of Ashenvale's broader frontiers. While the forest's Sentinels are constantly pressured by the Horde's logging incursions from the east and south, Shindrell keeps her eyes fixed on dangers that lie beyond the immediate woodland front. She acts as a vital liaison for travelers arriving from Darkshore or heading out toward the jagged ridges of Stonetalon, ensuring no sudden menace strikes Astranaar undefended from the flank. Among Shindrell's primary concerns is the troubled Zoram Strand on Ashenvale's northwestern shore. The sudden emergence of hostile naga crawling from the ocean depths poses a grave mystery and direct threat to the Kaldorei settlements. By dispatching seasoned fighters to investigate the shoreline and coordinate with scouts closer to the scene, Shindrell works to contain the serpentine invaders before they secure a permanent foothold on ancient night elf lands.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_shindrell-swiftfire-3bc56ce8ae93323314c9/1-0000.mp3", duration = 83.9836735, start = 0},
  },
}
P.transport["npc:shoni-the-shilent"] = {
  hash = "d1ecda",
  fullHash = "d1ecda",
  text = "Shoni the Shilent. Shoni the Shilent is an industrious gnome engineer stationed in Stormwind City's bustling Dwarven District. As commander of the Gnomeregan underground assault crew, she directs Alliance adventurers into the Deadmines to salvage the power supply of a goblin shredder, fuel for the machines she hopes will break a path back into Gnomeregan. Operating out of the smoky workshops of the Dwarven District, Shoni represents gnomish strategic ingenuity far from the lost halls of Gnomeregan. Her engineering plans are ambitious. With Gnomeregan in the hands of the troggs, Shoni is organizing an underground assault to retake it, and she sends operatives into the subterranean tunnels beneath Westfall for the parts her crew needs. Shoni's plan rests on the gnomes' own gyrodrillmatic excavationators, heavy drilling machines meant to break through the rocky underground borders of Gnomeregan and open the way for a gnomish assault. They lack the power to do it, so she wants the intact power supply, the Gnoam Sprecklesprocket, from a working goblin shredder deep in the Deadmines. Later, she also sends adventurers into Gnomeregan itself to tear apart its robots for spare parts to repair her fleet.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_shoni-the-shilent-b7ad880fbf48a28f5fc3/1-0000.mp3", duration = 71.7844898, start = 0},
  },
}
P.transport["npc:sicco-thermaplugg"] = {
  hash = "dee2a8",
  fullHash = "dee2a8",
  text = "Mekgineer Thermaplugg. Mekgineer Thermaplugg is the self-proclaimed ruler of ruined Gnomeregan and the greatest traitor in gnomish history. Once the trusted chief advisor of High Tinker Gelbin Mekkatorque, he orchestrated the catastrophic irradiation of the underground city in a twisted bid to seize power. Now thoroughly deranged and transformed into a leper gnome, he commands the irradiated halls from within a massive mechanical battle suit. Mekgineer Thermaplugg served for many years as chief advisor to High Tinker Gelbin Mekkatorque, who trusted him completely. All the while, Thermaplugg secretly coveted the office of High Tinker. What finally drove him to betray that trust, whether power or wealth, not even Mekkatorque can say; the High Tinker can only note that Thermaplugg would have had both in time.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sicco-thermaplugg-ab4450b8d5c7978b3ced/1-0000.mp3", duration = 47.9346939, start = 0},
  },
}
P.transport["npc:sida"] = {
  hash = "83289a",
  fullHash = "83289a",
  text = "Sida. Sida is a dwarven resident of Menethil Harbor in the Wetlands. Known for her estranged marriage to Einar Stonegrip, she spends her days in the port town while dealing with personal misadventures out in the surrounding marshes. Sida resides in the bustling Alliance port of Menethil Harbor, living apart from her husband, Einar Stonegrip. Their relationship is strained enough that Einar flatly refuses to travel to Menethil so long as Sida remains in town. Despite keeping to the coastal settlement, Sida occasionally ventures out into the dangers of the Wetlands, having recently suffered the misfortune of losing her personal bag during an expedition out toward Ironbeard's Tomb.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sida-666191dd555a5bdaf40e/1-0000.mp3", duration = 39.4971429, start = 0},
  },
}
P.transport["npc:sirra-von-indi"] = {
  hash = "e74687",
  fullHash = "e74687",
  text = "Sirra Von'Indi. Sirra Von'Indi is the resident historian of Darkshire, stationed within the town hall amid stacks of forgotten records. Versed in ancient languages and local history, he assists the township in deciphering mysterious documents and uncovering the dark past of Duskwood. Sirra Von'Indi serves as Darkshire's foremost scholar, keeping watch over the settlement's archives from inside the Darkshire Town Hall. While the town guard focuses on the immediate threats lurking in the woods, Sirra turns his attention to the written word, translating cryptic texts and preserving the fading history of Grand Hamlet before the shadow fell across the region.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sirra-von-indi-8bc01c3d801cf4aef744/1-0000.mp3", duration = 36.8326531, start = 0},
  },
}
P.transport["npc:sister-aquinne"] = {
  hash = "08acb7",
  fullHash = "08acb7",
  text = "Sister Aquinne. In Darnassus, Sister Aquinne studies beneath the Priesthood of Elune at the Temple of the Moon. The novice acolyte serves in the Temple Gardens. Sister Aquinne studies with the Priesthood of Elune in the night elf capital. She is stationed in the Temple Gardens, beneath the Temple of the Moon, learning from the High Priestess and elder sisters. When a once-great creature of the forest needed help, Aquinne sent willing travelers to Priestess A'moora inside the temple to learn what had to be done.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sister-aquinne-541234ac3029fee418af/1-0000.mp3", duration = 28.3689796, start = 0},
  },
}
P.transport["npc:skorn-whitecloud"] = {
  hash = "505afd",
  fullHash = "505afd",
  text = "Skorn Whitecloud. Skorn Whitecloud is an aging tauren hunter residing at Bloodhoof Village in the rolling plains of Mulgore. He guides young hunters in understanding their relationship with the land's predators and aids travelers who cross paths with Mulgore's lurking dangers. Living at Bloodhoof Village in Mulgore, Skorn Whitecloud is an old hunter who now serves as an instructor in the ways of the hunt. His primary role is instilling respect for the wild creatures of the plains. He tests aspiring hunters by sending them after the claws of Mulgore's cunning flatland prowlers, to be shown to Melor Stonehoof in Thunder Bluff, ensuring that those who take up the bow or spear understand the balance between predator and prey.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_skorn-whitecloud-67412ea42e66782f4357/1-0000.mp3", duration = 41.9526531, start = 0},
  },
}
P.transport["npc:skuerto"] = {
  hash = "e46e3c",
  fullHash = "e46e3c",
  text = "Skuerto. Skuerto is a dwarven scout stationed at Refuge Pointe in the Arathi Highlands. Sent there by Archmage Malin alongside Apprentice Kryten, he aids the Alliance in the field, helping secure magical relics on Malin's behalf. Skuerto, a dwarf of Ironforge, works as a scout in the dangerous Arathi Highlands. Stationed alongside Apprentice Kryten at Refuge Pointe, he works under the direction of Archmage Malin to recover arcane reagents and potent magical artifacts that once belonged to Malin's old master, Archmage Trelane. Despite the harsh conditions of the Highlands, Skuerto takes considerable pride in his wilderness scouting and reacts poorly to anyone questioning his competence. His work regularly brushes up against regional perils, from the hostile Syndicate and Boulderfist ogres to dangerous ancient entities tied to the land.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_skuerto-6b7f5ae1ed782b102fb4/1-0000.mp3", duration = 53.76, start = 0},
  },
}
P.transport["npc:smith-argus"] = {
  hash = "fa1818",
  fullHash = "fa1818",
  text = "Smith Argus. Smith Argus is the resident blacksmith and trainer stationed in the heart of Goldshire in Elwynn Forest. From his open-air forge near the Lion's Pride Inn, he repairs traveler gear, teaches novice smiths their fundamentals, and coordinates with craftsmen across southern Azeroth. His network ties Goldshire's local trade directly to logistical hubs like Stormwind and distant frontiers like Redridge. Situated just outside the Lion's Pride Inn, Smith Argus maintains one of the busiest anvils in Elwynn Forest. While Goldshire faces growing perils from nearby gnolls, kobolds, and Defias bandits, Argus keeps local militia and passing adventurers properly equipped. In addition to mending dented armor and forging sturdy implements, he serves as a blacksmithing trainer, initiating fledgling craftsmen into the fundamentals of working copper and bronze. Argus is not an isolated village smith; his workshop is a vital link in the Kingdom of Stormwind's regional supply chain. When craftsmen in neighboring settlements require specialized gear or raw materials, they look to Goldshire's central position. Farrier Verner Osgood in Redridge relies on Argus for shipments of crafted horseshoes to keep pack animals and cavalry moving, while metalworkers in Stormwind's Dwarven District regularly coordinate deliveries through him.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_smith-argus-b3f99a99a00c9059feeb/1-0000.mp3", duration = 80.0914286, start = 0},
  },
}
P.transport["npc:solm-hargrin"] = {
  hash = "50f749",
  fullHash = "50f749",
  text = "Solm Hargrin. Solm Hargrin is the rogue trainer stationed within Anvilmar in Coldridge Valley. A pragmatic dwarf who values honor amongst thieves, he instructs novice dwarven and gnomish scoundrels in the art of subterfuge. He firmly believes that covert operatives will prove vital as geopolitical tensions simmer across Azeroth. Tucked away in the dwarven stronghold of Anvilmar, Solm Hargrin watches the snowy passes of Coldridge Valley with a keen, calculating eye. While Ironforge relies heavily on the brute strength of its mountaineers and warriors, Hargrin understands that some threats require a quieter, sharper touch. He welcomes budding rogues of both dwarven and gnomish heritage, deciphering coded missives for them and drilling them in essential techniques like Eviscerate. Above all, Hargrin champions a creed of professional loyalty and honor among thieves, preparing his pupils for an increasingly volatile world where subtle knives often shape the fate of nations.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_solm-hargrin-2fd1b2ccbe9364565728/1-0000.mp3", duration = 57.2081633, start = 0},
  },
}
P.transport["npc:sprite-darter"] = {
  hash = "7d2f2a",
  fullHash = "7d2f2a",
  text = "Sprite Darter. Sprite Darters are small, iridescent faerie dragons native to the lush canopy of Feralas. Revered for their innate spiritual and magical qualities, they flit gracefully among the ancient trees. Recently, these rare creatures have become targets for local Grimtotem tauren who seek to capture and exploit them. Sprite Darters are elusive, winged woodland beasts native to the ancient forests of Feralas. Characterized by their gleaming, iridescent wings and mysterious spiritual essence, they embody the whimsical yet fierce magical ecology of Kalimdor's deep forests. Though generally peaceful and shy, their innate resistance to magical forces and natural power make them significant to those attuned to the wilderness. In recent times, the reclusive Sprite Darters have faced an unprecedented threat. The aggressive Grimtotem tauren clan inhabiting Feralas has begun rounding up and caging large numbers of these rare creatures for enigmatic purposes. Concerned night elves like Kindal Moonweaver actively recruit allies to disrupt the cages and liberate the trapped hatchlings before the Grimtotem bend them to their will. Beyond night elf efforts to safeguard them, the darters have caught the eye of outside observers studying primal power. Witch Doctor Uzer'i, a troll spiritualist operating out of Camp Mojache, takes a keen interest in the natural energies and muisek contained within the Sprite Darters, seeking their essence to unravel the unique magic thriving throughout Feralas.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_sprite-darter-e53edcc807f87b276548/1-0000.mp3", duration = 92.5257143, start = 0},
  },
}
P.transport["npc:stitches"] = {
  hash = "65e750",
  fullHash = "65e750",
  text = "Stitches. Stitches is a colossal, stitched-together undead abomination stalking Duskwood's main thoroughfare. His march threatens travelers, the Night Watch, and the town of Darkshire. Stitches is an undead abomination assembled from harvested corpses and unholy sorcery. Appearing near Abercrombie's shack northeast of Raven Hill Cemetery, the lumbering monstrosity immediately sets out eastward along the road toward Darkshire. Imbued with immense physical strength and relentless malice, Stitches tears through any Night Watch checkpoints stationed along the thoroughfare—including the defense camp across from Vul'Gol Ogre Mound and the outpost outside the Rotting Orchard—bringing outright slaughter to unwary travelers and town defenders alike.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_stitches-04366e2151d665b10403/1-0000.mp3", duration = 44.6432653, start = 0},
  },
}
P.transport["npc:supervisor-raelen"] = {
  hash = "6f7206",
  fullHash = "6f7206",
  text = "Supervisor Raelen. At Eastvale Logging Camp, Supervisor Raelen keeps timber moving toward Stormwind. She manages the laborers, tracks daily quotas, and oversees the lumber supply. Supervisor Raelen directs the woodcutters at Eastvale Logging Camp, near Marshal Patterson and the camp’s wagons. The camp stands on the edge of eastern Elwynn, near the Redridge Mountains, where the work brings its share of trouble. Raelen coordinates the crews and keeps them focused on their quotas despite hazards in the surrounding woods. She sees that gathered timber is processed, bundled, and sent on toward Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_supervisor-raelen-ba8791621c0c51bc257f/1-0000.mp3", duration = 37.6163265, start = 0},
  },
}
P.transport["npc:suzetta-gallina"] = {
  hash = "24d227",
  fullHash = "24d227",
  text = "Suzetta Gallina. At the Gallina Winery in Stormwind City, Suzetta Gallina tends the family wine business. Suzetta Gallina helps run the Gallina Winery along Stormwind's Canals. The shop offers wines imported from across the kingdom or crafted there. Her family supplies taverns, nobles, and common folk. Suzetta is no figure in high politics, but her work keeps the capital's trade moving through troubled times.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_suzetta-gallina-420f5837c7a02cec21c0/1-0000.mp3", duration = 26.4359184, start = 0},
  },
}
P.transport["npc:syral-bladeleaf"] = {
  hash = "3cfd93",
  fullHash = "3cfd93",
  text = "Syral Bladeleaf. In Dolanaar, Syral Bladeleaf guides night elves arriving from Shadowglen. As a resident of Teldrassil, she speaks for the Council of the Forest and directs them to local caretakers, herbalists, and elders who watch over the crown's boughs. Syral Bladeleaf helps direct new arrivals through Dolanaar beneath Teldrassil's canopy. She speaks for the Council of the Forest, sending night elves to community leaders and herbalists in the village and nearby wilderness. Her guidance leads travelers to Denalan, a botanist at Lake Al'Ameth, and helps them replenish supplies for the village elders. In Dolanaar, Syral carries out the Council of the Forest's work for the village. She helps see that medicinal elixirs reach those in need and that disruptions to the local ecosystem receive swift attention.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_syral-bladeleaf-9688feced77f8f240075/1-0000.mp3", duration = 49.4497959, start = 0},
  },
}
P.transport["npc:syurna"] = {
  hash = "5eb8a7",
  fullHash = "5eb8a7",
  text = "Syurna. In Darnassus, Syurna trains night elf rogues in the Cenarion Enclave. She guides aspiring scouts, spies, and covert operatives, then sends new rogues on trials of stealth and cunning. Syurna trains those who move unseen through Darnassus. In the Cenarion Enclave, she teaches rogues evasion, lockpicking, and lethal strikes. The Sentinels display the Kaldorei’s martial strength, while the Sisterhood of Elune holds its spiritual wisdom. The Kaldorei also depend on shadows and stealth, and Syurna sharpens the eyes and blades that guard Teldrassil. Syurna tests young operatives beyond the lessons taught in the enclave. She sends promising initiates into deeper fieldwork to see whether they have the instincts to survive beyond the World Tree’s boughs and serve the Alliance in perilous frontier lands.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_syurna-40a6f7a51097a9c66a0c/1-0000.mp3", duration = 50.2334694, start = 0},
  },
}
P.transport["npc:tabetha"] = {
  hash = "26dd68",
  fullHash = "26dd68",
  text = "Tabetha. Tabetha is a reclusive, powerful human mage dwelling deep within Dustwallow Marsh at an isolated farmstead in the Quagmire. Far from the politics of Dalaran or Theramore, she instructs aspiring spellcasters and aids those seeking mastery over potent arcane and occult relics. Hidden away in the sodden expanse of Dustwallow Marsh north of the Stonemaul Ruins, Tabetha lives in a secluded shack alongside her apprentices. Surrounding herself with alchemical vials and ancient tomes, she has deliberately chosen solitude over the academic hierarchies of the Eastern Kingdoms. Despite her remote location, her mastery of the arcane is renowned enough that spellcasters across Kalimdor brave beasts and mire alike to seek her guidance. Tabetha stands notably apart from factional hostilities. While human by birth, she turns away neither Alliance nor Horde initiates who demonstrate the will to learn, providing tutelage to mages and assisting warlocks with dangerous bindings such as the Orb of Orahil. Her past connects her to figures like Menara Voidrender, revealing an extensive history with esoteric magic that transcends simple faction allegiance.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tabetha-9bed085be771c71e41cb/1-0000.mp3", duration = 71.8367347, start = 0},
  },
}
P.transport["npc:tai-jin"] = {
  hash = "f3cce7",
  fullHash = "f3cce7",
  text = "Tai'jin. At the Razor Hill barracks, Tai'jin guides young Darkspear priests in their spiritual traditions. She teaches the balance of light and shadow and rites such as the Hex of Weakness. Tai'jin guides young priests from the Razor Hill barracks as they set out into Durotar. Orcs here turn chiefly to shamanism or warlock arts, while Darkspear trolls bring their communion with spirits and loas to the Horde. Tai'jin teaches the first principles of priesthood, the balance of light and shadow, and the spiritual heritage of troll culture.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tai-jin-8723d3f3de447ec8508f/1-0000.mp3", duration = 32.4179592, start = 0},
  },
}
P.transport["npc:taiga-wisemane"] = {
  hash = "5b631b",
  fullHash = "5b631b",
  text = "Taiga Wisemane. Taiga Wisemane is a tauren elder residing in Shadowprey Village along the rugged western coast of Desolace. Watchful of demonic meddling across the barren wastes, he works to thwart the Burning Blade cult entrenched in the region. He directs Horde champions to disrupt demonic rituals and seal open gateways before the Burning Legion gains ground. Though Shadowprey Village is predominantly a Darkspear troll fishing settlement tucked away against the ocean, Taiga Wisemane has taken up station there to monitor the dark sorceries stirring across Desolace. He remains acutely aware of the spiritual corruption bleeding into the soil, keeping his focus fixed eastward where shadow cults and demonic remnants fester among ancient ruins.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_taiga-wisemane-0c227be49c1f6c3336fd/1-0000.mp3", duration = 44.1991837, start = 0},
  },
}
P.transport["npc:takar-the-seer"] = {
  hash = "9202d9",
  fullHash = "9202d9",
  text = "Takar the Seer. East of Camp Taurajo, Takar the Seer keeps a lone camp in the Barrens. Though surrounded by Horde lands, he remains loyal to the Alliance and shares occult knowledge with certain travelers. Takar the Seer lives alone beneath a simple tent east of Camp Taurajo. Tauren braves and orc patrols watch the surrounding Barrens, yet leave his remote clearing undisturbed. He distrusts curious Horde visitors but rarely starts a fight, keeping watch on the horizon and to himself. His camp lies far from Stormwind's politics. Takar the Seer shares his knowledge with a few visitors from beyond his camp. Alliance warlocks who come from the Eastern Kingdoms seek his cryptic counsel when they try to bind dangerous beings from beyond this world. His understanding of hidden forces and the craft of souls draws these practitioners to his remote, perilous camp.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_takar-the-seer-b4947168b8797575a2fd/1-0000.mp3", duration = 53.0546939, start = 0},
  },
}
P.transport["npc:takata-steelblade"] = {
  hash = "44e6a9",
  fullHash = "44e6a9",
  text = "Takata Steelblade. Takata Steelblade is an orc warrior stationed at Ghost Walker Post in Desolace. Dispatched from Orgrimmar by Keldran alongside Maurin Bonesplitter, he spearheads the Horde's local campaign against demonic corruption. His primary focus is eradicating the regional satyr population affiliated with the sinister Burning Blade. Takata Steelblade was sent from the capital to Desolace under direct orders from Keldran, an influential figure in Orgrimmar committed to uncovering and purging demonic subversion. Operating out of the isolated Tauren encampment of Ghost Walker Post, Takata coordinates military efforts against the Legion-aligned forces plaguing the barren wastes. While his companion Maurin Bonesplitter attempts to track and dismantle the clandestine Burning Blade cultists directly, Takata focuses on their demonic allies: the satyrs. Takata has orchestrated aggressive strikes against Desolace's corrupted satyrs, decimating their ranks to break the cult's local power structure and halt their spreading taint.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_takata-steelblade-06631e3302a80b6c80e9/1-0000.mp3", duration = 61.8057143, start = 0},
  },
}
P.transport["npc:tal"] = {
  hash = "ad9b18",
  fullHash = "ad9b18",
  text = "Tal. Tal is the primary wind rider master of Thunder Bluff, tending the city's aerial roost high above the plains of Mulgore. He provides seasoned wyverns to Horde travelers looking to traverse the vast reaches of Kalimdor. Perched upon the central mesa of Thunder Bluff, Tal manages the vital aerial thoroughfare connecting the tauren capital to the rest of the Horde. From his perch, he tends to the loyal wind riders, or wyverns, ensuring they are healthy, well-fed, and prepared for long-distance journeys across Kalimdor's rugged landscapes. Whether sending messengers down to Camp Taurajo or dispatching scouts across the Barrens to Orgrimmar, Tal maintains an indispensable lifeline that keeps the towering mesa city in constant touch with its allies.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tal-d110fb92061cf87da26c/1-0000.mp3", duration = 45.4008163, start = 0},
  },
}
P.transport["npc:talen"] = {
  hash = "cdb561",
  fullHash = "cdb561",
  text = "Talen. Talen is a night elf amateur archaeologist encamped near the Zoram Strand in northwestern Ashenvale. Despite the constant danger posed by nearby naga and Horde outposts, he is dedicated to recovering ancient kaldorei relics buried along the coast. Perched at a small camp on the edge of the Zoram Strand, Talen spends his days pursuing historical curiosities rather than waging war. While the wilderness of Ashenvale is fraught with territorial skirmishes and hostile shoreline denizens, Talen remains focused on gathering long-lost treasures from the ruins submerged beneath the waves and sands. He relies heavily on passing adventurers to brave the savage Wrathtail naga and retrieve elusive artifacts—including pristine statuettes and the Ring of Zoram held by the naga leader Ruuzel.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_talen-ca780a23ecc0cec19765/1-0000.mp3", duration = 46.8114286, start = 0},
  },
}
P.transport["npc:tallow"] = {
  hash = "3f3630",
  fullHash = "3f3630",
  text = "Tallow. Tallow is a Forsaken warrior stationed in the fortified settlement of Tarren Mill within the Hillsbrad Foothills. Serving the Dark Lady and the Horde, he watches over the contested front lines, helping organize strikes against local Alliance threats. Situated in the heart of Tarren Mill, Tallow stands among the Forsaken and Horde forces holding the line in the Hillsbrad Foothills. The region is a powder keg of conflict, caught between nearby Southshore humans, wandering Syndicate outlaws, and hostile wildlife. Tallow helps direct capable adventurers into the field, testing their strength against the Boulderfist ogres of the Arathi Highlands before sending them on to aid the besieged outpost of Hammerfall.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tallow-e7c11bba725744d36f5a/1-0000.mp3", duration = 43.8857143, start = 0},
  },
}
P.transport["npc:talvash-del-kissel"] = {
  hash = "a0c280",
  fullHash = "a0c280",
  text = "Talvash del Kissel. Talvash del Kissel is a down-on-his-luck gnome jeweler who fled the fall of Gnomeregan and now resides in Ironforge's Mystic Ward. Plagued by debt and persistent rumors following the loss of his home, he seeks capable adventurers to help recover lost treasures and restore shattered relics. His keen eye for precious gems and ancient baubles makes him a valuable contact for those plumbing the depths of Uldaman. Once a respected jeweler in the technological heart of Gnomeregan, Talvash saw his livelihood obliterated alongside his home when the troggs overran the underground city. Escaping with the surviving refugees to the dwarven capital of Ironforge, he set up camp in the Mystic Ward. Unfortunately, relocation did not treat him kindly. Rumors of questionable dealings and unpaid obligations quickly piled up, sinking the craftsman into deep financial distress. Unable to rebuild his trade through conventional means, Talvash relies on freelance adventurers to retrieve lost assets and salvage his ruined reputation. Despite his misfortunes, Talvash has lost none of his gem-cutting precision or appraisal acumen. When explorers in the Badlands uncover an ancient, shattered necklace deep within the Titan vault of Uldaman, Talvash proves to be one of the few craftsmen in the Eastern Kingdoms capable of understanding its intricate enchantments. Restoring such power requires rare components and painstaking labor, but Talvash is eager to ply his trade—both to clear his debts and to prove his enduring skill.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_talvash-del-kissel-40c57e1dc616bac55d1b/1-0000.mp3", duration = 93.8318367, start = 0},
  },
}
P.transport["npc:tammra-windfield"] = {
  hash = "4e1d15",
  fullHash = "4e1d15",
  text = "Tammra Windfield. Tammra Windfield is a tauren resident of Sun Rock Retreat, nestled within the heights of the Stonetalon Mountains. Deeply attuned to the balance of the land, she guides Horde travelers in honoring the natural cycle of renewal and keeping hope alive amid the peaks. Her concerns lie with both the health of the untamed wilderness and the safety of her kin. Sun Rock Retreat serves as a vital sanctuary for the Horde within the craggy peaks of Stonetalon, surrounded by hostile harpies, Venture Company loggers, and lurking predators. Tammra Windfield stands among the settlement's caretakers, keeping a watchful eye on both the mountain wilderness and travelers who cross its threshold. Her gentle demeanor belies the resolve necessary to maintain a home in such rugged terrain. Like many of her people, Tammra honors the Earth Mother by observing the constant rhythm of growth and decay in nature. Through the tasks she entrusts to travelers—such as tending the cycle of rebirth and bringing forth new life—she works to counter the ravages that conflict and exploitation bring upon Stonetalon. To Tammra, protecting the land requires active healing, ensuring that life flourishes even in scarred mountain soil. Beyond her spiritual duties to the surrounding wild, Tammra bears deep concern for the companions and kin who brave the treacherous trails of the Stonetalon Mountains. When word spreads that travelers or family have vanished along the crags, she is among the first to seek out reliable aid. For Tammra, the endurance of Sun Rock Retreat depends as much on mutual protection and loyalty as it does on harmony with nature.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tammra-windfield-a7964eba0d108522b1e6/1-0000.mp3", duration = 96.522449, start = 0},
  },
}
P.transport["npc:tannok-frosthammer"] = {
  hash = "f3d937",
  fullHash = "f3d937",
  text = "Tannok Frosthammer. Tannok Frosthammer is a dwarven resident found at Thunderbrew Distillery outside Kharanos in Dun Morogh. He serves as an anxious recipient of goods coming from Coldridge Valley, deeply troubled by how trogg attacks have cut off the roads to Anvilmar. Stationed around the Thunderbrew Distillery in Kharanos, Tannok Frosthammer keeps a watchful eye on incoming deliveries and local tidings. The sudden surge of troggs swarming Coldridge Pass has severed normal transit from Coldridge Valley, leaving Tannok cut off from regular communication with the settlement at Anvilmar. Relying on couriers like the gnome tinkerer Hands Springsprocket to ferry vital supplies and news through the perilous, snowy mountain pass, Tannok represents the quiet worry shared by many Bronzebeards as subterranean threats crawl closer to their doorsteps.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tannok-frosthammer-2680986b8e15d3e22b66/1-0000.mp3", duration = 49.1885714, start = 0},
  },
}
P.transport["npc:tarindrella"] = {
  hash = "2d4814",
  fullHash = "2d4814",
  text = "Tarindrella. In Shadowglen, Tarindrella watches over Teldrassil's sheltered woods. The dryad works with night elf protectors to investigate corruption among the World Tree's wildlife. Tarindrella dwells in Shadowglen, a protected glade atop Teldrassil. Dryads are fierce caretakers of nature, born of the demigod Cenarius. Many live deep in ancient Kalimdor forests such as Ashenvale, but Tarindrella watches over this young grove. She bridges the wild spirits and young night elf defenders taking their first steps beyond Aldrassil. Her chief concern is a taint creeping through the forest. She sends reliable adventurers to drive back local pests and gather clues to its source. Teldrassil is the new crown of the night elf people, yet sickness has reached its groves. Furbolgs once lived peacefully in their homes; now they have gathered as the Gnarlpine tribe. Grells and grellkin tainted by wicked Fel Moss infest the hills around Shadowglen. Tarindrella suspects the moss is behind these changes. She directs initiates to confront the grells and bring back samples, hoping to halt the corruption before it overtakes the young grove.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tarindrella-2a3c39700b3e90923d1b/1-0000.mp3", duration = 73.5869388, start = 0},
  },
}
P.transport["npc:tarrel-rockweaver"] = {
  hash = "6068da",
  fullHash = "6068da",
  text = "Tarrel Rockweaver. Tarrel Rockweaver is an anxious dwarven husband stationed on the bridge leading into Menethil Harbor. Deeply worried for his wife Merrin, an archaeologist who ventured inland with Whelgar's excavation team, he watches the road hoping for news of her safety. While trade and military shipments flow through Menethil Harbor, Tarrel Rockweaver keeps an anxious vigil at the bridge on the edge of town. His wife, Merrin Rockweaver, joined Prospector Whelgar's prestigious archaeological expedition deeper into the Wetlands. When violent raptors overran the excavation site and cut off regular communication, Tarrel was left stranded in town, begging passing travelers to scout east toward Whelgar's Excavation Site to ensure she survived the disaster.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tarrel-rockweaver-8ada057fdd02630bf8a7/1-0000.mp3", duration = 46.9420408, start = 0},
  },
}
P.transport["npc:tatternack-steelforge"] = {
  hash = "cf86d3",
  fullHash = "cf86d3",
  text = "Tatternack Steelforge. On the Barrens frontier, Tatternack Steelforge offers work to travelers who can handle raw metal and dangerous wildlife. The orc smith studies local ores and seeks to arm Horde forces against threats across the plains. Across the Barrens, Horde outposts need weapons to face wild beasts, centaur raiders, and hostile quilboar. Tatternack Steelforge brings his people's metalworking knowledge to the frontier. He seeks practical weapons and unusual geological specimens to strengthen the Horde's foothold against those threats.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tatternack-steelforge-260d97756058fd07c539/1-0000.mp3", duration = 34.0114286, start = 0},
  },
}
P.transport["npc:tenaron-stormgrip"] = {
  hash = "c716d0",
  fullHash = "c716d0",
  text = "Tenaron Stormgrip. High in Aldrassil, Tenaron Stormgrip guides young night elves through their people's recent history. He also asks them to gather water from a moonwell. Tenaron Stormgrip guides young night elves on Aldrassil's winding wooden platforms. From high in Shadowglen's central tree, he watches the local woods and their moonwells. He teaches novices about their spiritual bond with the World Tree. Tenaron sends initiates to gather a phial of water from the moonwell north of Aldrassil. Along the way, he teaches them what followed the Battle of Mount Hyjal. Their journey carries on through Teldrassil and into Darnassus.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tenaron-stormgrip-bb203bcd5bc083966c4c/1-0000.mp3", duration = 37.0416327, start = 0},
  },
}
P.transport["npc:teronis-corpse"] = {
  hash = "9c8853",
  fullHash = "9c8853",
  text = "Teronis' Corpse. Teronis' Corpse lies on a secluded island within Lake Falathim in western Ashenvale. Before his untimely demise, this night elf scout was dispatched from Astranaar on a crucial mission to recover Dartol's Rod to aid in cleansing the forest. Sent forth by Raene Wolfrunner from the settlement of Astranaar, Teronis was tasked with recovering the lost rod of Dartol, an ancient night elf relic capable of purifying corrupted woodland magic. His search brought him deep into the waters of Lake Falathim, but the journey turned fatal when hostile murlocs swarmed the island. Teronis fell in battle, leaving his journal behind and the rod's radiant gemstone plundered by the lake's aggressive amphibians.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_teronis-corpse-cb87e4af7753a8a707cf/1-0000.mp3", duration = 43.4416327, start = 0},
  },
}
P.transport["npc:thadius-grimshade"] = {
  hash = "d61efa",
  fullHash = "d61efa",
  text = "Thadius Grimshade. Thadius Grimshade is a Wildhammer dwarf diviner dwelling within the mage tower of Nethergarde Keep in the Blasted Lands. Though he parted ways with Aerie Peak long ago to study esoteric and darker magical arts, he remains loyal to his kin at heart. Unlike most Wildhammer dwarves who prefer the open skies and roaring winds of the Hinterlands, Thadius Grimshade makes his home inside Nethergarde Keep. Driven by a thirst for arcane divination and darker mystic lore, he relocated to the edge of the tainted Blasted Lands to pursue his esoteric studies. Despite his brooding discipline and separation from his clan, he retains a deep fondness for his homeland and gryphonkind, offering his rare scrying talents to those who come seeking aid on behalf of Aerie Peak.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_thadius-grimshade-0686e2c594bd410be94b/1-0000.mp3", duration = 48.0653061, start = 0},
  },
}
P.transport["npc:thalia-amberhide"] = {
  hash = "554cbe",
  fullHash = "554cbe",
  text = "Thalia Amberhide. Thalia Amberhide is a tauren residing at Freewind Post in the jagged canyon of Thousand Needles. A loyal friend to her kin, she waits with mounting concern for the safe return of Lakota Windsong from the clutches of the Grimtotem clan. Perched atop the towering bluffs of Freewind Post, Thalia Amberhide is a quiet presence among the bustling tauren settlement. Her heart is heavy with worry for her close companion, Lakota Windsong, who was taken captive by Arnak Grimtotem and his treacherous kin. Thalia relies on passing Horde adventurers who brave the canyon depths to find Lakota, break her bonds, and guide her safely back up the lifts to the haven of the mesa.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_thalia-amberhide-dedb7be32c640d28a168/1-0000.mp3", duration = 41.0383673, start = 0},
  },
}
P.transport["npc:tharek-blackstone"] = {
  hash = "5090ac",
  fullHash = "5090ac",
  text = "Tharek Blackstone. Tharek Blackstone is a hardworking toolsmith residing in Kharanos, in the snowy heart of Dun Morogh. Known for supplying heavy hardware to local craftsmen, his primary patron is Beldin Steelgrill of Steelgrill's Depot. Though constantly busy at his trade, he also serves as a reliable point of contact for travelers seeking work around the settlement. Situated amidst the cold drifts of Kharanos, Tharek Blackstone keeps busy turning out reliable dwarven tools. Between repairing gear for the locals and supplying larger operations, he rarely finds a moment to rest. His biggest headache—and most reliable customer—is Beldin Steelgrill, whose mechanostrider depot just outside town demands a steady stream of heavy wrenches, gears, and replacement implements. To keep his forge running without falling behind on deliveries, Tharek often hires wandering travelers to haul newly finished tool crates over to the depot for him. Beyond his trade at the anvil, Tharek carries considerable respect among the folk of Dun Morogh. While he holds no formal military title, his standing in town makes him an approachable liaison for odd jobs, supply runs, and coordinating local efforts.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tharek-blackstone-e909135bebae64d30043/1-0000.mp3", duration = 71.5755102, start = 0},
  },
}
P.transport["npc:tharnariun-treetender"] = {
  hash = "65accf",
  fullHash = "65accf",
  text = "Tharnariun Treetender. In Auberdine, Tharnariun Treetender watches Darkshore’s wilds for signs of sickness. The night elf naturalist studies the corruption spreading through local plants and animals, seeking ways to protect them. In Auberdine, Tharnariun Treetender watches the woods beyond the port. Hostile satyrs and foul shoreline washaways threaten the village, but his work centers on the natural world around it. He believes neglecting nature invites ruin, so he studies the decline of the local woods and searches for ways to fight the sickness spreading across the forest floor.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tharnariun-treetender-e9431d5f861b47b13ff7/1-0000.mp3", duration = 35.4481633, start = 0},
  },
}
P.transport["npc:the-defias-traitor"] = {
  hash = "6dd107",
  fullHash = "6dd107",
  text = "The Defias Traitor. At Sentinel Hill, The Defias Traitor has given up the Brotherhood's hidden base to save his life. The captured outlaw is held beneath the watchtower after the People's Militia caught him stealing Farmer Saldean's wagon.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_the-defias-traitor-c35012694e90bdd7be2e/1-0000.mp3", duration = 12.5910204, start = 0},
  },
}
P.transport["npc:theldurin-the-lost"] = {
  hash = "40f741",
  fullHash = "40f741",
  text = "Theldurin the Lost. Theldurin the Lost is a reclusive, half-mad dwarf wandering the scorched expanses of the Badlands. Formerly aligned with the insidious Twilight's Hammer cult, he fled their ranks with stolen sacred relics after realizing the horror of their designs. Perched in the barren hills of the Badlands, clutching bags of explosives in wild paranoia, Theldurin is far more than a simple mad hermit. He was once an initiate of the Twilight's Hammer cult. When the sinister cabal sought to awaken a primordial elemental power trapped beneath the earth, Theldurin recoiled in terror, rejected their mad teachings, and fled into the desert. He carried with him the Scroll of Myzrael, desperate to prevent his former masters from unleashing an ancient horror upon the world. Though the escape cost him his sanity, his defiance dealt a serious blow to the cult's plans.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_theldurin-the-lost-55c6c9b7abc9ebdb0d69/1-0000.mp3", duration = 51.6440816, start = 0},
  },
}
P.transport["npc:therylune"] = {
  hash = "b2618a",
  fullHash = "b2618a",
  text = "Therylune. Therylune is a dryad found held captive at the Master's Glaive in southern Darkshore. Entrapped by the insidious Twilight's Hammer cultists who have occupied the ancient site, she relies on bold travelers to help her break free and escape their clutches. Dryads are guardians of nature and daughters of Cenarius, normally roaming the tranquil woodlands of northern Kalimdor. However, Therylune ventured too close to the ominous excavation at the Master's Glaive in southern Darkshore, where Twilight's Hammer cultists have gathered. Ambushed and trapped by the dark cult, she is unable to fight her way out alone through the swarms of cultists and requires an escort to flee to safety.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_therylune-bc91d42d24adbe7f6797/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["npc:therysil"] = {
  hash = "3387d5",
  fullHash = "3387d5",
  text = "Therysil. Therysil is a dryad dwelling at the Shrine of Aessina in central Ashenvale. Deeply devoted to the preservation of nature, she waits anxiously for word of her sister, Therylune, who fell into the hands of sinister cultists. Therysil makes her home near the tranquil waters of the Shrine of Aessina, a sacred glade within the ancient woods of Ashenvale. Like all dryads, the daughters of Cenarius, she is bound to the defense of the wild and the spirits dwelling within it. Yet her focus has been torn from quiet stewardship to gnawing worry. Her sister, Therylune, was captured nearby by the deranged Twilight's Hammer cult, leaving Therysil desperate for any wandering ally willing to aid in her sister's rescue.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_therysil-c22cfad33f49dabf7a36/1-0000.mp3", duration = 45.9232653, start = 0},
  },
}
P.transport["npc:thor"] = {
  hash = "0e7c45",
  fullHash = "0e7c45",
  text = "Thor. At Sentinel Hill, Thor keeps Westfall linked to Stormwind by gryphon flight. His trained mounts carry travelers and urgent messages above the dangerous roads. Thor tends the gryphon roost at Sentinel Hill, linking Westfall's defenders with the rest of the kingdom. The People's Militia faces bandits, gnolls, and malfunctioning harvest golems on the ground. Thor's gryphons carry travelers and military dispatches above the perilous roads. Reports from Gryan Stoutmantle and urgent requests for aid can reach the court in Stormwind far faster than a ground messenger.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_thor-5103ec920dafebc96cc5/1-0000.mp3", duration = 34.7167347, start = 0},
  },
}
P.transport["npc:thorgas-grimson"] = {
  hash = "9e30b8",
  fullHash = "9e30b8",
  text = "Thorgas Grimson. Thorgas Grimson is the resident dwarf hunter trainer stationed inside Anvilmar in Coldridge Valley. A seasoned outdoorsman of Dun Morogh, he firmly believes that hands-on survival in the freezing wilds is the finest teacher any fledgling marksman can have. Perched inside the stone halls of Anvilmar, Thorgas Grimson welcomes novice mountaineers and scouts taking their very first steps into the harsh snowdrifts of Coldridge Valley. Rather than bogging young hunters down with dry lectures, Grimson espouses a practical philosophy: real skill is forged out in the freezing winds, bow or gun in hand, tracking Dun Morogh's rugged beasts firsthand.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_thorgas-grimson-cfccc2ac25afd4988a16/1-0000.mp3", duration = 40.5681633, start = 0},
  },
}
P.transport["npc:thorgrum-borrelson"] = {
  hash = "993ffb",
  fullHash = "993ffb",
  text = "Thorgrum Borrelson. Thorgrum Borrelson is the dwarven gryphon master stationed above Thelsamar in Loch Modan. From his roost overlooking the settlement, he tends the aerial mounts that connect the valley to Ironforge and the surrounding mountain passes. Perched on the bluff rising immediately above Thelsamar, Thorgrum Borrelson handles aerial transport for the Alliance across Loch Modan. With trogg incursions and gnoll packs threatening overland paths, his trained gryphons provide vital transit over the jagged ridges. He maintains frequent connections back through the South Gate Pass to the Great Forge in Dun Morogh, as well as routes onward toward the Wetlands and beyond.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_thorgrum-borrelson-714a3f5807b5d64f9f0e/1-0000.mp3", duration = 38.3477551, start = 0},
  },
}
P.transport["npc:thorvald-deepforge"] = {
  hash = "14eff5",
  fullHash = "14eff5",
  text = "Thorvald Deepforge. Thorvald Deepforge is a dwarven weapon merchant stationed near the border pass in the Valley of Kings. He helps arm travelers and defenders securing the critical pathway between Dun Morogh and Loch Modan. Positioned within the towering monument of the Valley of Kings, Thorvald Deepforge serves the Alliance as a reliable arms dealer. The mountain passes connecting Khaz Modan's interior to the outlying territories are plagued by trogg incursions and roving wildlife, making well-forged steel essential for any Mountaineer or recruit on the road. Thorvald ensures that those arriving from Dun Morogh or heading deeper into Loch Modan carry the blades and axes needed to defend dwarven lands.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_thorvald-deepforge-8bc888490bfdb3845d63/1-0000.mp3", duration = 40.9861224, start = 0},
  },
}
P.transport["npc:thran-khorman"] = {
  hash = "11d048",
  fullHash = "11d048",
  text = "Thran Khorman. Thran Khorman is the resident dwarven warrior trainer stationed in Anvilmar, nestled within the snowy Coldridge Valley. He oversees the basic combat drilling for newly minted warriors stepping out into Dun Morogh. Standing near the training grounds of Anvilmar, Thran Khorman is tasked with turning raw dwarven recruits and visiting gnomes into disciplined combatants. He maintains a gruff, uncompromising demeanor toward anyone who lacks the grit for front-line fighting. In his eyes, even though the Third War has concluded, peace is merely an illusion: troggs encroach upon Coldridge Pass, and the mountains remain fraught with peril. He demands relentless practice with axe, mace, and shield so that Ironforge's defenders never grow dull.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_thran-khorman-12136a68e6b9dd6330ff/1-0000.mp3", duration = 46.4457143, start = 0},
  },
}
P.transport["npc:thunderaan"] = {
  hash = "170a23",
  fullHash = "170a23",
  text = "Thunderaan. Prince Thunderaan is the ancient Prince of Air, a colossal elemental struck down and betrayed during the ancient wars between fire and wind. Consumed in part by Ragnaros the Firelord, his remnant essence was sealed into shattered bindings entrusted to the Firelord's lieutenants. Adventurers who recover these relics can seek out Highlord Demitrian in Silithus to unleash him once more. Long ago, during the Elemental Sundering—a five-thousand-year clash fought between the forces of fire and air deep within Azeroth—Ragnaros sought to destroy and consume Thunderaan. The Prince was ambushed and betrayed by Ragnaros's powerful lieutenants, Baron Geddon and Garr, before being struck down by the Firelord's hammer, Sulfuras. Although defeated, Thunderaan's essence proved too mighty for Ragnaros to fully absorb. Unable to entirely devour the Prince of Air, Ragnaros sealed what little remained of Thunderaan's essence inside a talisman of elemental binding. To prevent the Prince from ever reforming, the Firelord shattered the talisman into two flawless halves. He entrusted one piece to Baron Geddon and the other to Garr, hiding both within the volcanic depths of the Molten Core beneath Blackrock Mountain.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_thunderaan-b30c366a3e621267379a/1-0000.mp3", duration = 73.6653061, start = 0},
  },
}
P.transport["npc:tommy-joe-stonefield"] = {
  hash = "78c54a",
  fullHash = "78c54a",
  text = "Tommy Joe Stonefield. At the river west of Stonefield Farm, Tommy Joe Stonefield longs for Maybell Maclure. Their families have feuded for years, so he relies on secret notes and quiet banks to keep their love hidden. Tommy Joe Stonefield waits by the river west of Stonefield Farm, looking toward the Maclure homestead across the water. The Stonefields and Maclures have clashed for years over land, pride, and farmyard squabbles. Their elders keep the feud alive, but Tommy Joe has fallen in love with Maybell Maclure. The two cannot meet openly without angering both households. Gramma Stonefield, Tommy Joe’s sympathetic grandmother, helps them exchange secret notes and tokens of affection.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tommy-joe-stonefield-fe1f0454b3a78703ae19/1-0000.mp3", duration = 42.3444898, start = 0},
  },
}
P.transport["npc:tormus-deepforge"] = {
  hash = "cea47e",
  fullHash = "cea47e",
  text = "Tormus Deepforge. Tormus Deepforge is a dwarven smith working at the center of the Great Forge in Ironforge. A dependable craftsman, he coordinates iron deliveries and supplies armaments for Alliance defense efforts across Khaz Modan and beyond. Positioned right beside the roaring fires of the Great Forge, Tormus Deepforge oversees substantial metalworking tasks on behalf of the Bronzebeard clan. Beyond hammering steel himself, Tormus mourns his mentor, Sturgy Ironband, whose smithing compound south of Helm's Bed Lake in eastern Dun Morogh was overrun by Dark Iron dwarves after a load of strange umbral ore arrived there.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tormus-deepforge-e0fa290343ba0898dc41/1-0000.mp3", duration = 37.9297959, start = 0},
  },
}
P.transport["npc:torwa-pathfinder"] = {
  hash = "a47114",
  fullHash = "a47114",
  text = "Torwa Pathfinder. Torwa Pathfinder is a lone tauren hunter and tracker camped at the entrance to Un'Goro Crater, just below the ramp descending from Tanaris. He observes the basin's primordial wildlife, studying the dangerous predators that rule the jungle floor. Adventurers seeking to test their mettle against the crater's legendary beasts often seek his guidance. Perched at the eastern base of the crater where the desert sands of Tanaris give way to humid jungle steam, Torwa Pathfinder serves as an informal warden for newcomers. He respects the wild forces of Un'Goro, understanding that careless wanderers quickly become fodder for the local fauna. His campsite provides a rare moment of respite before travelers dive into the sweltering depths. Much of Torwa's attention is consumed by Lar'korwi, a notoriously cunning and fierce raptor roaming the northern reaches of the crater. Torwa understands that brute strength alone cannot bring down such an apex predator. Instead, he instructs hunters to study its feeding habits, using fresh carcase meat and glands to craft a bait potent enough to lure the beast out into the open. Beyond hunting the crater's apex raptors, Torwa maintains a deep curiosity regarding the toxic flora and aggressive ape colonies that inhabit the basin. He directs travelers to harvest venom from volatile bloodpetals and observe the strength of dominant beasts like the mighty gorilla U'cha, constantly analyzing how nature's deadliest adaptations function in isolation.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_torwa-pathfinder-4b18cdce528d7ac58e95/1-0000.mp3", duration = 90.4097959, start = 0},
  },
}
P.transport["npc:treshala-fallowbrook"] = {
  hash = "ae05c6",
  fullHash = "ae05c6",
  text = "Treshala Fallowbrook. Treshala Fallowbrook is a night elf residing quietly on the upper level of the Tradesmen's Terrace in Darnassus. She is the wife of Heralath Fallowbrook, whose work has taken him far from home into the thorny depths of Razorfen Kraul in the Barrens. Treshala Fallowbrook keeps a modest vigil on the second floor of a workshop in Darnassus's Tradesmen's Terrace. Her husband, Heralath, journeyed to the brambled depths of Razorfen Kraul in the Barrens, and she waits at home for word of him. The two are joined by a pendant of bonding, a keepsake of their marriage that Heralath carried with him into the quilboar's warrens.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_treshala-fallowbrook-7616cdcf8f1515176c3f/1-0000.mp3", duration = 37.4595918, start = 0},
  },
}
P.transport["npc:tsunaman"] = {
  hash = "80ec60",
  fullHash = "80ec60",
  text = "Tsunaman. Tsunaman is a sentient water elemental stationed at Sun Rock Retreat in the Stonetalon Mountains. Acting as an agent of the Tribunal of the Tides, he watches over the elemental currents of Kalimdor and rallies Horde adventurers to confront corrupting forces. Dwelling near the path leading from Sun Rock Retreat down into the Charred Vale, Tsunaman serves the Tribunal of the Tides, high-ranking servants aligned with the Tidehunter, Neptulon. Rather than showing mindless hostility to mortal travelers, he cooperates with the Horde to monitor elemental unrest throughout Kalimdor, particularly the disturbances rippling out of the submerged caverns of Blackfathom Deeps. True to his elemental nature, Tsunaman harbors an instinctive, visceral hatred for fire in all forms. He constantly fumes over the nearby burning landscapes of the Charred Vale and elemental fire incursions. In camp, his animosity is so petty and unyielding that he regularly marches over to nearby cooking fires and campfires just to smack them out with a heavy fist of water.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tsunaman-fd3aaa60d7c9221631fe/1-0000.mp3", duration = 63.242449, start = 0},
  },
}
P.transport["npc:tyrion"] = {
  hash = "731cab",
  fullHash = "731cab",
  text = "Tyrion. Inside Stormwind Keep, Tyrion watches the court and aids covert work. The gnome works with Elling Trias to gather intelligence and counter plots against the kingdom. Tyrion keeps to the halls of Stormwind Keep, watching the palace and staying in touch with contacts beyond official oversight. Elling Trias, a cheese merchant in the Trade District, trusts Tyrion with sensitive matters. Trias runs a discreet information network and sends reliable operatives to Tyrion when the House of Nobles' bureaucracy must be bypassed.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_tyrion-3b25119879f40c3d704d/1-0000.mp3", duration = 34.1681633, start = 0},
  },
}
P.transport["npc:ukor"] = {
  hash = "710b85",
  fullHash = "710b85",
  text = "Ukor. Near the eastern path outside the Valley of Trials, Ukor rests after carrying supplies from Razor Hill. The training grounds already had plenty, and he hopes the provisions can still help his people. Ukor rests by the eastern road outside the Valley of Trials, tired from carrying food south from Razor Hill. Orc peons often spend their days cutting lumber or hauling rocks under harsh taskmasters. Ukor chose to bring provisions to the recruits on his own initiative. He crossed Durotar's red plains, where scorpids and boars prowl, only to find the training grounds already well-stocked. His bundle was not needed. Now he asks passing young adventurers to carry the provisions back north to Innkeeper Grosk.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ukor-4f2239349fa9f544ae1a/1-0000.mp3", duration = 43.3632653, start = 0},
  },
}
P.transport["npc:ula-elek"] = {
  hash = "004be5",
  fullHash = "004be5",
  text = "Ula'elek. In Sen'jin Village, Ula'elek works armor for warriors across the Horde. The Darkspear smith joins forces with Thun'grim Firegaze, shaping specialized gear from traditional troll craft and trophies gathered across Kalimdor. Ula'elek is a skilled armorsmith serving the Darkspear in Sen'jin Village. Nearby quilboar and sea crawlers threaten the coastal settlement, so the tribe needs sturdy armor and working blades. Ula'elek's skill also draws seasoned warriors from across the Horde. Young warriors who visit Thun'grim Firegaze at his overlook in the Barrens are sent south to Sen'jin Village. The veteran trusts Ula'elek to forge Brutal Gauntlets for battle-hardened fighters. To make them, Ula'elek calls for rare materials, especially swollen, uncloven hooves from the satyrs draining the forest's magic in northeastern Ashenvale.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ula-elek-2d5d2b19f0ea8f4e4cc1/1-0000.mp3", duration = 53.2114286, start = 0},
  },
}
P.transport["npc:umpi"] = {
  hash = "ad0fd6",
  fullHash = "ad0fd6",
  text = "Umpi. Umpi is a frog residing in Tarren Mill as the unwitting laboratory assistant of Apothecary Lydon. Kept inside the Royal Apothecary Society's workshop, she serves as a recurring test subject for experimental toxins and plague concoctions. Within the dark laboratories of Tarren Mill, the Forsaken work tirelessly to brew concoctions of death and torment. For Apothecary Lydon, scientific rigor requires living flesh to test his formulas, and Umpi bears the brunt of these trials. Lydon regularly tests lethal brews—such as the Elixir of Suffering and the Elixir of Agony—directly on her. Once the poisons take their inevitable toll and kill her, the apothecary re-animates the amphibian, ensuring she is ready to endure the next lethal dose for the glory of the Royal Apothecary Society.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_umpi-6a8293fc535471034d8e/1-0000.mp3", duration = 49.9983673, start = 0},
  },
}
P.transport["npc:undertaker-mordo"] = {
  hash = "8748a6",
  fullHash = "8748a6",
  text = "Undertaker Mordo. Undertaker Mordo is the caretaker of the crypt of Deathknell, serving as the very first face newly awakened Forsaken see when they open their eyes. He tells those who wake that they are the Lich King's slaves no more and sends them on toward the Forsaken cause; the bodies that never stir go to the fire. Keeping the crypt of Deathknell in Tirisfal Glades, Undertaker Mordo watches over the dead as corpses break free from the Scourge's shattered grip. For every newly liberated Forsaken who wakes in the cold of the crypt, Mordo provides their initial bearing in an unrecognizable second life. He assesses their sanity, introduces them to the reality of their condition, and immediately directs them toward duty under Queen Sylvanas Windrunner. Not every body brought to the crypt wakes. Mordo does not wait long: the corpses that stay still are tossed into the fire, and those who do stir are greeted with dry impatience and little ceremony. Anyone who rises with their wits intact is sent up the steps and down the road to Shadow Priest Sarvis in the chapel, who explains their new existence. The mindless zombies that overrun the north of the village are Sarvis's concern, not Mordo's; the shadow priest sends the newly risen out to destroy them.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_undertaker-mordo-4d5bb853d901194d7020/1-0000.mp3", duration = 73.4563265, start = 0},
  },
}
P.transport["npc:ur-kyo"] = {
  hash = "90813b",
  fullHash = "90813b",
  text = "Ur'kyo. In Orgrimmar's Valley of Spirits, Ur'kyo guides priests in the ways of shadow and light. The Darkspear regard him as their spiritual leader and greatest priest, and he teaches their traditions in the Horde capital. Ur'kyo guides Darkspear mystics and visiting practitioners from the Valley of Spirits in Orgrimmar. After fleeing the Echo Isles, the Darkspear made a home in Durotar alongside Thrall's Horde. Their sacred traditions remain vital to the tribe, and Ur'kyo keeps those ancestral practices alive through his teaching. Priests who come to Ur'kyo find a patient instructor in faith and old rites. He teaches the Hex of Weakness and the defensive ward called Shadowguard. Horde priests also turn to him to learn about the coalition's varied spiritual ways, from troll voodoo and ancestral customs to foreign disciplines.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ur-kyo-37a5e745ada916389cfc/1-0000.mp3", duration = 49.684898, start = 0},
  },
}
P.transport["npc:uzzek"] = {
  hash = "460e8b",
  fullHash = "460e8b",
  text = "Uzzek. Uzzek watches the eastern Barrens from southwest of Far Watch Post. The battle-hardened orc survived many skirmishes across Kalimdor and now tests and trains promising Horde warriors crossing the plains. Uzzek trains young warriors southwest of Far Watch Post, near the eastern edge of the Barrens. He endured brutal combat in the recent wars and now tests those learning to defend themselves. To prove their skill, they face the savage wildlife and raiders that trouble the crossing.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_uzzek-98b3cbda301cc520b80b/1-0000.mp3", duration = 26.7493878, start = 0},
  },
}
P.transport["npc:valstag-ironjaw"] = {
  hash = "830ba3",
  fullHash = "830ba3",
  text = "Valstag Ironjaw. Valstag Ironjaw is an Ironforge dwarven soldier stationed within Menethil Keep in the coastal marshlands of the Wetlands. Facing the pressing dangers that plague the trade passages connecting Loch Modan and the coast, he assists in securing regional routes and keeping the harbor's garrison informed of local threats. Found inside Menethil Keep in Menethil Harbor, Valstag Ironjaw serves as part of the dwarven garrison keeping watch over the lowlands. The surrounding marsh is rife with danger, from hostile Dragonmaw orcs to ravenous wildlife, making communications and supply lines difficult to maintain. Valstag helps coordinate defense efforts along the primary thoroughfares, particularly the treacherous passage cutting through Dun Algaz toward Loch Modan. With the treacherous Algaz Gauntlet choked by hostile forces, travelers and supply convoys heading between Menethil Harbor and Loch Modan are under constant threat. Valstag directs capable adventurers to confront the brigands and orcs lurking in the passes, relaying crucial military intelligence back and forth between forward scouts and commanders like Captain Stoutfist.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_valstag-ironjaw-bd26ba36d9e82ec29a32/1-0000.mp3", duration = 69.2767347, start = 0},
  },
}
P.transport["npc:vanndar-stormpike"] = {
  hash = "fef05e",
  fullHash = "fef05e",
  text = "Vanndar Stormpike. Vanndar Stormpike is a fierce dwarf mountain king who commands the Stormpike Expedition from the northern fortress of Dun Baldar. Searching the frozen peaks of Alterac Valley for ancient relics and raw resources, he leads the Alliance's unyielding war against the Frostwolf orcs. A veteran mountain king of Ironforge, Vanndar Stormpike spearheads the dwarven excavation into Alterac Valley. Following the Third War, he marched the Stormpike Guard into the northern mountains seeking hidden mineral riches and long-lost titan artifacts. Settling into the fortified redoubt of Dun Baldar, Vanndar views the valley as an ancestral right and rightful Alliance territory. He directs military outposts, defensive bunkers, and frontline pushes with grim dwarven resolve, determined that no retreat will ever be sounded under his watch. Vanndar's relentless mining and prospecting encroached directly onto the home of the Frostwolf clan, sparking brutal mountain warfare. Despite orcish demands to withdraw, Vanndar refuses to yield an inch of ground, vowing that Alterac Valley will belong to the dwarves. From his throne room deep within Dun Baldar, flanked by his marshals and bodyguards, he personally oversees the defense against Frostwolf incursions while dispatching Alliance champions to break the enemy lines and claim the valley once and for all.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_vanndar-stormpike-6551e5321dca5999abe8/1-0000.mp3", duration = 83.3567347, start = 0},
  },
}
P.transport["npc:varok-saurfang"] = {
  hash = "31e000",
  fullHash = "31e000",
  text = "Varok Saurfang. High Overlord Saurfang is a legendary orc warrior and a veteran of the Old Horde's wars. Serving as Warchief Thrall's trusted military commander in Orgrimmar, he represents the proud martial spine of the modern Horde. Few living warriors possess a martial pedigree to rival Saurfang. A veteran of the Old Horde's wars, he is considered an unstoppable force on the battlefield. Today he stands in Orgrimmar as High Overlord, a bulwark of Thrall's newborn Horde. Though he stands as an unmatched champion of the Horde, Saurfang is not driven by reckless battle-lust. While he will relentlessly defend the Horde and enforce Thrall's rule against any threat, Saurfang harbors a profound disdain for warmongering and fights strictly for honor and preservation.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_varok-saurfang-8b42c875d7ee28694b05/1-0000.mp3", duration = 45.8971429, start = 0},
  },
}
P.transport["npc:velarok"] = {
  hash = "bc80cd",
  fullHash = "bc80cd",
  text = "Velarok. Velarok Windblade is a lone human swordsman camped amid the ash and cinder of Searing Gorge, flanked by the mutilated corpses of Dark Iron dwarves. He seeks vengeance against the local Dark Irons for the brutal murder of his father, recruiting passing travelers to forge a weapon of retribution. His single-minded hunger for vengeance drives everything he asks of those who help him. Found southeast of Thorium Point, Velarok Windblade presents himself as a grieving human warrior stranded in the perilous wastes of the Searing Gorge. Surrounding his camp are the bloody, battered corpses of Dark Iron dwarves who crossed his blade. According to Velarok, these clan dwarves slaughtered his father in cold blood. Consumed by hatred, he enlists travelers to gather materials to assemble the Torch of Retribution, an enchanted weapon of vengeance against the Dark Irons and the minions of Ragnaros.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_velarok-21128e5f394479735dce/1-0000.mp3", duration = 52.5844898, start = 0},
  },
}
P.transport["npc:velora-nitely"] = {
  hash = "689a96",
  fullHash = "689a96",
  text = "Velora Nitely. In the Undercity's Trade Quarter, Velora Nitely works the forge for the Forsaken and the Horde. Once among Lordaeron's finest armorsmiths, she now makes dry jokes that rarely land. Velora Nitely works near the anvils in the Undercity's Trade Quarter, where she makes armor for the Horde. Before the Third War devastated the north, Lordaeron celebrated her as an exceptional armorsmith. Undeath took her life and warmth, but left her technical skill untouched. She works with Horde crafters across continents, including Thun'grim Firegaze in the Barrens. Her craft includes reinforcing heavy battle plate and forging the formidable Brutal Legguards from hardened materials such as Dragonmaw shinbones. Velora Nitely keeps trying to make jokes at the forge, though her humor rarely lands. Many of her somber Forsaken kin brood over their cursed fate, but she still makes room for levity. Death seems to have ruined her comedic timing: her quips sound flat, morbid, and thoroughly unfunny to the living and the dead alike. She keeps cracking them undeterred.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_velora-nitely-0ab08e0f319ed653a47c/1-0000.mp3", duration = 68.075102, start = 0},
  },
}
P.transport["npc:ventaari-brightwish"] = {
  hash = "088cda",
  fullHash = "088cda",
  text = "Ventaari Brightwish. Ventaari Brightwish is a Skyborne resident of Thendal Village on Zephras Isle. She greets travelers from across Azeroth and offers the quest The Gift of Skysight. Residing in Thendal Village upon the soaring cliffs of Zephras Isle, Ventaari Brightwish is one of the local Skyborne. While she shares a surname with Belathaan Brightwish, her own duties center around aiding newcomers who find their way to the village, extending hospitality to both the Alliance and the Horde as she initiates visitors into the traditions of her people through tasks like The Gift of Skysight.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_ventaari-brightwish-b978f97517b3ea23907d/1-0000.mp3", duration = 34.5338776, start = 0},
  },
}
P.transport["npc:verna-furlbrow"] = {
  hash = "79ff05",
  fullHash = "79ff05",
  text = "Verna Furlbrow. Verna Furlbrow waits beside her broken wagon near Westfall’s northern border. Bandits drove her from her family’s pumpkin patch, and the road to Elwynn Forest has left her stranded. Verna and her husband farmed pumpkins in northern Westfall until lawlessness drove them from their land. After outlaws took the farm, they loaded what they could onto their cart and set out for Elwynn Forest with their horse, Old Blanchy. Their wagon broke down just down the road from the abandoned Jansen Stead. Unable to repair the axle or continue, Verna now faces the elements, bandit raids, and scavengers. She depends on travelers to keep her household fed and guarded. Verna still welcomes those who have been driven to the roadside. Known for creating Westfall Stew, she shares meals and warm fires with wandering transients and refugees who have suffered similar fates. To fill her cooking pot, she needs ingredients gathered from the fields, including boar snouts, murloc eyes, okra, and stringy vulture meat. She makes hearty meals for the destitute from what the harsh frontier provides.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_verna-furlbrow-3044e7b581b70e737a19/1-0000.mp3", duration = 65.5412245, start = 0},
  },
}
P.transport["npc:veron-amberstill"] = {
  hash = "9cfe1c",
  fullHash = "9cfe1c",
  text = "Veron Amberstill. Veron Amberstill is a dwarven ram breeder residing at Amberstill Ranch in eastern Dun Morogh. He tends to the rugged mountain rams that serve as the traditional mounts of Ironforge and offers them to skilled riders who have earned his trust. Tucked away in the snow-dusted hills of eastern Dun Morogh, Veron Amberstill oversees the celebrated stock of Amberstill Ranch. Mountain rams are perfectly suited for Khaz Modan's treacherous slopes, sure-footed and thick-coated against the bite of mountain blizzards. Veron breeds and trains these beasts to carry dwarven scouts, mountaineers, and traveling adventurers. While he gladly provides standard and swift mounts to fellow dwarves, outsiders must prove their unwavering loyalty to the throne of Ironforge before he will part with any of his prized herd.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_veron-amberstill-7ec3aba71ab1df534d06/1-0000.mp3", duration = 47.0726531, start = 0},
  },
}
P.transport["npc:veronica-nials"] = {
  hash = "d35954",
  fullHash = "d35954",
  text = "Veronica Nials. Captain Veronica Nials is an officer of the Stromgarde military stationed at Refuge Pointe in the Arathi Highlands. Amid the kingdom's collapse, she coordinates defensive operations against the Syndicate and ogres that overrun the fallen capital. Following the Third War, the human kingdom of Stromgarde shattered, leaving its remnants struggling to survive against invading Boulderfist ogres and the treachery of the Syndicate. Captain Veronica Nials stands as one of the central commanders of the surviving Stromgarde defenders at Refuge Pointe. Tasked with holding the line, she directs Alliance champions against key Syndicate leadership, such as Lord Falconcrest and the warlock Marez Cowl, while striving to recover fallen soldiers' badges so their grieving families can find closure. Captain Nials's loyalties are strictly tied to her battered homeland. When Rhag Garmason and the dwarven defenders of Dun Modr begged for Stromgarde's assistance after Dark Iron saboteurs devastated the Thandol Span, Nials was forced to turn them away. Bound by honor and duty, her troops cannot spare a single blade beyond the Arathi Highlands while their own ancestral kingdom remains occupied.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_veronica-nials-14d24b06b877518905d4/1-0000.mp3", duration = 74.5795918, start = 0},
  },
}
P.transport["npc:vesprystus"] = {
  hash = "d4fee5",
  fullHash = "d4fee5",
  text = "Vesprystus. At Rut'theran Village, Vesprystus sends travelers between Teldrassil and mainland Kalimdor. He tends the hippogryph roost at the great World Tree's base. At Teldrassil's southern base, Vesprystus tends the Rut'theran roost. Trained hippogryphs carry travelers from the isolated elven boughs toward Darkshore and the mainland. A magical portal also links Rut'theran to Darnassus in the canopy above. Across the strait, Vesprystus works with the flight master at Auberdine to carry sentinels, emissaries, and adventurers into Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_vesprystus-bf0f41515bf79a188097/1-0000.mp3", duration = 34.8995918, start = 0},
  },
}
P.transport["npc:vidra-hearthstove"] = {
  hash = "cb6441",
  fullHash = "cb6441",
  text = "Vidra Hearthstove. Vidra Hearthstove is a dwarven cook residing in the Stoutlager Inn in Thelsamar. Known for preparing local specialties, she frequently relies on traveling adventurers to gather regional ingredients for her famous blood sausages. Within the bustling warmth of the Stoutlager Inn, Vidra Hearthstove tends the kitchen and helps feed the locals and travelers passing through Loch Modan. Sharing a surname with the innkeeper, she keeps Thelsamar well-provisioned. Her signature dish, Thelsamar blood sausages, is a hearty dwarven staple that requires fresh game meats gathered from the surrounding wilderness, including boar entrails, spider ichor, and bear meat.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_vidra-hearthstove-e0bde8d24c1173f09a89/1-0000.mp3", duration = 41.6914286, start = 0},
  },
}
P.transport["npc:volcor"] = {
  hash = "c0a9e0",
  fullHash = "c0a9e0",
  text = "Volcor. Volcor lies wounded in Blackwood Den, deep in southern Darkshore. The night elf scout depends on his bear Grimclaw and Auberdine's defenders to escape the hostile furbolgs. Volcor is a night elf scout wounded inside Blackwood Den. While tracking the corrupted Blackwood tribe through its underground lair, he was ambushed and badly hurt. He could not fight past the hostile furbolgs alone, so he sent Grimclaw, his loyal bear companion, into the wilds of Darkshore to seek help in Auberdine.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_volcor-3499e28e5e468aacb5ec/1-0000.mp3", duration = 30.1191837, start = 0},
  },
}
P.transport["npc:vorn-skyseer"] = {
  hash = "5ee441",
  fullHash = "5ee441",
  text = "Vorn Skyseer. Vorn Skyseer is a peaceful tauren resident of Camp Narache atop Red Cloud Mesa in Mulgore. Resting among the camp's tents, he greets young adventurers beginning their journeys and introduces them to local life. Situated in Camp Narache on Red Cloud Mesa, Vorn Skyseer serves as an informal welcoming presence for young tauren. As they undertake their rites of passage before venturing into the wider valleys of Mulgore, Vorn offers kind words and hospitality, helping new arrivals settle into the camp. Vorn is no warrior. He leaves the camp's defense to its braves and keeps to a quiet, unhurried life, content to watch over the tranquil plains of his homeland.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_vorn-skyseer-57b6bacd7be82cc4aa8f/1-0000.mp3", duration = 42.2922449, start = 0},
  },
}
P.transport["npc:warcaller-gorlach"] = {
  hash = "f6244d",
  fullHash = "f6244d",
  text = "Warcaller Gorlach. Warcaller Gorlach patrols Orgrimmar, calling Horde champions to distant battlefronts. He rallies travelers and seasoned warriors to answer commands at outposts across Kalimdor and beyond. Warcaller Gorlach walks Orgrimmar's thoroughfares, carrying the Horde's calls for expansion and defense. He gives orders among the city's people, seeking volunteers ready to test their mettle. Some he sends to the contested canopy of Ashenvale. Others he directs toward Camp Mojache in Feralas, where scouts face the wilderness. He also calls warriors to distant campaigns in the Plaguelands. As threats rise abroad, Gorlach calls on those in the capital to take up arms.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_warcaller-gorlach-6a32ec5b28caf6a63877/1-0000.mp3", duration = 41.3518367, start = 0},
  },
}
P.transport["npc:warlord-goretooth"] = {
  hash = "5253e3",
  fullHash = "5253e3",
  text = "Warlord Goretooth. Warlord Goretooth is the commanding orc officer stationed at Kargath in the dusty wastes of the Badlands. From his watchtower, he coordinates the Horde's frontier campaigns against the neighboring Dark Iron dwarves and monitors the volcanic menace of Blackrock Mountain. Though strict in military matters, he can occasionally be found relaxing around the camp's bonfire. Perched atop the watchtower of Kargath, Warlord Lunk Goretooth directs Horde operations on the hostile eastern frontier. Kargath serves as Orgrimmar's primary staging ground against the threats lurking within Blackrock Mountain and the surrounding ravines. Goretooth oversees patrols, coordinates scout forces like the Kargath Expeditionary Force, and issues direct kill orders targeting the Dark Iron clan's ranks and leadership. When he descends from his lookout, the stern commander shows a lighter side, frequently warming himself by the camp bonfire and trading quips with the camp's Forsaken casters before returning to duty. Goretooth views the Dark Iron dwarves as a clear and present threat to Horde interests in the Eastern Kingdoms. Rather than engaging in defensive posturing, he pursues aggressive war plans against General Angerforge and Emperor Dagran Thaurissan's forces entrenched within Blackrock Depths. Recognizing the gravity of assaulting such an ancient subterranean stronghold, he frequently defers strategic matters to veteran orcs like Eitrigg in Orgrimmar, seeking seasoned wisdom before sanctioning further pushes into the mountain.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_warlord-goretooth-a39d4c7b75abe9914b83/1-0000.mp3", duration = 90.5404082, start = 0},
  },
}
P.transport["npc:warmaster-laggrond"] = {
  hash = "fb0f4e",
  fullHash = "fb0f4e",
  text = "Warmaster Laggrond. Warmaster Laggrond is a seasoned orc commander stationed outside the Horde entrance to Alterac Valley in the Alterac Mountains. He oversees recruitment and frontline recognition for warriors answering the call to aid the Frostwolf clan. Through his trials, fighters prove their mettle and earn the respect of the Horde vanguard. Standing watch in the bitter cold at the threshold of Alterac Valley, Warmaster Laggrond organizes the Horde's war effort against the Stormpike Expedition. He ensures that only capable fighters enter the valley to represent the Frostwolf clan and the wider Horde. Laggrond tests arriving combatants through the Proving Grounds before directing them into the thick of battle. As warriors spill blood across the frozen peaks, it is Laggrond who measures their standing, bestowing honors upon those who earn renown among the Frostwolves.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_warmaster-laggrond-29fee9109f47239da917/1-0000.mp3", duration = 49.6587755, start = 0},
  },
}
P.transport["npc:warsong-outrider"] = {
  hash = "49b717",
  fullHash = "49b717",
  text = "Warsong Outrider. Stationed along the contested road leading east from Ashenvale into Azshara, the Warsong Outrider keeps watch over the Horde's frontier. She serves as an advanced scout for the Warsong clan, monitoring travelers and relaying crucial intelligence back to their forward encampments. Although armed and vigilant against night elf incursions, she maintains a passive watch unless directly provoked. The borderlands between Ashenvale and the shattered ruins of Azshara are fraught with danger. Operating far from the fortified safety of Splintertree Post or the lumber camps, the Warsong Outrider observes troop movements and patrols the transit corridor. Armed with a bow and toxic stingers, she stands ready to defend the Horde's claim over the region, though she conserves her strength by only firing upon Alliance trespassers who actively attack her.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_warsong-outrider-298478a768b9acbbe4fb/1-0000.mp3", duration = 50.3640816, start = 0},
  },
}
P.transport["npc:watch-captain-parker"] = {
  hash = "821aef",
  fullHash = "821aef",
  text = "Watch Captain Parker. Guard Parker is a vigilant town guardsman stationed at the Three Corners outpost in the Redridge Mountains. Tasked with patrolling the roads and monitoring aggressive gnoll packs, he serves as an early line of defense for travelers heading into Lakeshire. Positioned at the vital junction known as Three Corners, Parker keeps watch over the roads connecting Elwynn Forest, Duskwood, and Redridge. With Stormwind's military resources stretched thin and little official reinforcement reaching the region, solo watchmen like Parker carry the burden of keeping the crossroads clear of bandits, prowling predators, and raiding gnolls. Parker's immediate concern is the gnoll encampments gathering to the north and east of his post. As packs encroach closer toward the roadway, he sends able-bodied travelers to carry word of the gathering gnoll force to Deputy Feldon in Lakeshire. The Redridge pack's growing boldness poses an immediate danger to supply convoys and refugees seeking shelter in Lakeshire. Life on a lonely roadside post can be grim, but small kindnesses still find their way to Three Corners. Darcy, the server from the Lakeshire Inn, sends Parker a warm lunch while he is out on patrol. Touched by the gesture, Parker asks the adventurer who delivered it to fetch a bouquet from Lakeshire's herbalist and bring it back to her as a token of his appreciation, without telling the herbalist whom the flowers are from or for.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_watch-captain-parker-490a0c117b616a66c5e1/1-0000.mp3", duration = 84.0097959, start = 0},
  },
}
P.transport["npc:watcher-backus"] = {
  hash = "fcbc53",
  fullHash = "fcbc53",
  text = "Watcher Backus. Along Duskwood's road, Watcher Backus keeps watch for danger and suspicious traffic tied to Stormwind's political intrigues. He patrols between Darkshire and Manor Mistmantle, watching for undead and strange travelers. Watcher Backus walks a solitary beat north of Darkshire, passing near Manor Mistmantle. Like the rest of the Night Watch, he struggles against Duskwood's curse. Stormwind's garrison gives the region little support, so local volunteers guard its misty paths on their own. Backus keeps beast and ghoul at bay along the road.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_watcher-backus-f9d3b89db18038d0b222/1-0000.mp3", duration = 35.1346939, start = 0},
  },
}
P.transport["npc:watcher-dodds"] = {
  hash = "577c04",
  fullHash = "577c04",
  text = "Watcher Dodds. Watcher Dodds is a human scout of the Night Watch stationed at the central crossroads of Duskwood. Manning a lonely roadside outpost far from Darkshire's town walls, he monitors the encroaching horrors and tasks travelers with culling the local giant spider population. Watcher Dodds serves the Night Watch under Commander Althea Ebonlocke, holding down an exposed post at the intersection connecting Darkshire to Raven Hill and Deadwind Pass. While Darkshire huddles within its palisades, forward sentries like Dodds live on the knife's edge between wolf packs, ravenous ghouls, and oversized arachnids. From his roadside camp, he keeps an eye on approaching threats and enlists wandering mercenaries to thin out the spiders crawling out from the undergrowth before they completely overrun the overgrown thoroughfares.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_watcher-dodds-7e018eb8ace428117f22/1-0000.mp3", duration = 50.3118367, start = 0},
  },
}
P.transport["npc:wilder-thistlenettle"] = {
  hash = "5c785d",
  fullHash = "5c785d",
  text = "Wilder Thistlenettle. Wilder Thistlenettle is a dwarven miner brooding in a tavern within Stormwind's Dwarven District. The sole survivor of a tragic cave-in deep within the Deadmines, he is haunted by the gruesome fate of his mining company and his brother. Wilder Thistlenettle can be found drowning his sorrows in an alehouse near the southeastern gates of the Dwarven District. Years ago, he joined an expedition into the deep lodes of Moonbrook's Deadmines alongside his brother and their companions. A catastrophic cave-in sealed the rest of the crew in the dark while Wilder barely made it to the surface alive.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_wilder-thistlenettle-b67b56a3e4fd71fa8aab/1-0000.mp3", duration = 35.1869388, start = 0},
  },
}
P.transport["npc:wiley-the-black"] = {
  hash = "1dfdaa",
  fullHash = "1dfdaa",
  text = "Wiley the Black. At the Lakeshire Inn, Wiley the Black keeps out of sight. He owes his life to Gryan Stoutmantle and shares what he knows of the Defias Brotherhood. Wiley the Black keeps to the Lakeshire Inn, away from Westfall's turmoil and Redridge's gnoll-infested borders. He owes his life to Gryan Stoutmantle, commander of the People's Militia, who once saved him. Stoutmantle grumbles that he should have let Wiley rot. When the militia needs insight into the Defias conspiracy, it turns to Wiley. He reluctantly shares covert intelligence to repay his debt.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_wiley-the-black-64170ce554d24cbeded7/1-0000.mp3", duration = 35.84, start = 0},
  },
}
P.transport["npc:willem"] = {
  hash = "9de77a",
  fullHash = "9de77a",
  text = "Willem. Outside Northshire Abbey, Willem sends recruits to meet the valley's threats. He serves under Marshal McBride in the Stormwind Army, with the Defias Brotherhood pressing into Northshire. Deputy Willem watches the gates of Northshire Abbey, where the Stormwind Army keeps a foothold in the valley. The kingdom's soldiers are spread across many territories, leaving local defense to small groups like Marshal McBride's garrison. Willem meets incoming volunteers and sends them to aid residents and guard the valley's edges. The Defias Brotherhood is Willem's most pressing concern. Red-bandana bandits have entered Northshire, stolen supplies, threatened farmer Milly Osworth, and taken footholds among nearby vineyards and hills. Willem offers bounties on known cutthroats such as Garrick Padfoot, hoping to break their leadership before they can take the abbey grounds.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_willem-807de889bb1b7ee6d525/1-0000.mp3", duration = 50.6514286, start = 0},
  },
}
P.transport["npc:williden-marshal"] = {
  hash = "748b57",
  fullHash = "748b57",
  text = "Williden Marshal. Williden Marshal is the ambitious human leader of Marshal's Expedition, based out of Marshal's Refuge in northern Un'Goro Crater. Driven by the lure of rare flora, mysterious crystals, and profitable scientific research, he brought his team into the crater only to watch their lower camps overrun by the basin's colossal beasts. Williden Marshal brought an entire scientific expedition deep into Un'Goro Crater seeking fortune and discovery. Intrigued by accounts of alien crystals, uncataloged plants, and untapped resources, he established multiple forward camps across the valley floor. However, the primeval wilderness quickly turned against them. The savage beasts of the crater dismantled their research posts, forcing Williden and his survivors to retreat up into the northern cliffs to establish Marshal's Refuge. Despite being driven to the crater's mountainous edge, Williden refuses to pack up and abandon his investment. From the relative safety of the refuge, he hires passing adventurers to delve back into the savage lowlands to recover lost food crates, expensive scientific instruments, and his personal expedition journal. Though often known simply as 'Wil' to close comrades like Spark Nilminer, he takes the venture seriously—insisting on recovering their work even as titanic predators stalk the valley beneath them. Williden is not the only Marshal in the crater: Hol'anyee Marshal shares his name and works alongside him at Marshal's Refuge. Together they chose the untamed primeval crater of southern Kalimdor, and Williden remains entirely convinced that Un'Goro's crystal deposits and ancient mysteries hold the true fortune.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_williden-marshal-ab884cf288e21e33c595/1-0000.mp3", duration = 98.6383673, start = 0},
  },
}
P.transport["npc:winna-hazzard"] = {
  hash = "0904e9",
  fullHash = "0904e9",
  text = "Winna Hazzard. Winna Hazzard is an eccentric Forsaken researcher stationed at Bloodvenom Post in Felwood. Accompanied by a feline companion and known for bouts of maniacal laughter, she studies the blighted ecosystem and conducts unsettling experiments with the zone's corrupted fauna. Winna Hazzard represents the Forsaken interest in Felwood's unnatural decay. Stationed in the Horde enclave of Bloodvenom Post, she spends her time observing the local wildlife and formulating experiments utilizing tainted waters and venomous samples. Her jovial, manic demeanor often masks callous motives, evident when she uses tainted liquids drawn from the land to corrupt the small kitten that stays by her side.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_winna-hazzard-b78bbca17a91a31d2080/1-0000.mp3", duration = 40.9338776, start = 0},
  },
}
P.transport["npc:winstone-wolfe"] = {
  hash = "68a076",
  fullHash = "68a076",
  text = "Winstone Wolfe. Winstone Wolfe is a human operative affiliated with the secretive Ravenholdt organization, stationed at their secluded estate nestled between Hillsbrad and the Alterac Mountains. He keeps watch over the estate's grounds and groundskeepers, serving as one of the trusted contacts within the hidden league of thieves and assassins. Tucked away in the hidden valley of Ravenholdt Manor, Winstone Wolfe operates among the ranks of Lord Jorach Ravenholdt's syndicate. Quiet, watchful, and practical, Wolfe is one of the capable hands who handles business around the manor, ensuring that only those with proper discretion and talent walk the grounds undisturbed.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_winstone-wolfe-c477b529796cc959951a/1-0000.mp3", duration = 37.7208163, start = 0},
  },
}
P.transport["npc:witch-doctor-jin-zil"] = {
  hash = "760f67",
  fullHash = "760f67",
  text = "Witch Doctor Jin'Zil. Witch Doctor Jin'Zil is a Darkspear troll mystic dwelling in a cave at Malaka'jin in the southern Stonetalon Mountains. A longtime comrade of Darsok Swiftdagger and the shadow hunter Rokhan, he turns dark voodoo and ritual sorcery against the Horde's local enemies. Secluded inside an eastern cavern above the camp of Malaka'jin, Jin'Zil practices ancient jungle troll arts away from the coastal home of his tribe. Surrounded by bubbling cauldrons and captive prisoners, he gathers exotic reagents from the crags of the Stonetalon Mountains to weave potent blessings and curses in defense of the Horde's mountain encampment. Jin'Zil is no ordinary hedge wizard; he shares a storied history with senior Horde scouts, counting both Darsok Swiftdagger and the renowned shadow hunter Rokhan among his old friends. While Darsok coordinates frontline skirmishes against night elves and harpies, Jin'Zil fights the war spiritually and alchemically, using his forest magic and volatile voodoo to undermine threats before they ever reach the camp gates.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_witch-doctor-jin-zil-c0c67ea1e572f9a28eb3/1-0000.mp3", duration = 62.6155102, start = 0},
  },
}
P.transport["npc:witch-doctor-uzer-i"] = {
  hash = "027e42",
  fullHash = "027e42",
  text = "Witch Doctor Uzer'i. Witch Doctor Uzer'i is a jungle troll mystic residing at Camp Mojache in the primordial forests of Feralas. Dedicated to advancing the magical capabilities of the Horde, he researches techniques to trap and harness the muisek—the spiritual essence of powerful natural creatures. By capturing these ancient forest spirits, Uzer'i seeks to channel the raw primal energies traditionally favored by night elves directly into enchanted weapons. Rooted in traditional troll spiritualism, Witch Doctor Uzer'i has spent considerable effort studying the natural magic inherent to the untamed wilderness of Feralas. He argues that night elves have drawn upon the spirits of forest beasts for millennia, and believes the time has come for the Horde to seize those same primal forces. Central to his study is the concept of muisek: the vibrant spiritual essence that remains within a creature. To harness it, Uzer'i crafts specialized vessels capable of rapidly shrinking fallen beings before their escaping spirit disperses, allowing the essence to be stored and studied. Extracting muisek was merely the first phase of Uzer'i's broader ambition. Gathering resilient sinew, enchanted minerals, and petrified splintered logs from the very creatures whose spirits he trapped, the witch doctor fused physical materials with bound muisek. Through these rites, he learned to permanently bind ancient forest spirits into arms and armaments, providing the Horde with magically charged weapons. Beyond his ritual craftsmanship, Uzer'i maintains a deep curiosity regarding hidden places of power throughout Azeroth, actively tracking rumors of the ancient, submerged Sunken Temple.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_witch-doctor-uzer-i-19ab2e74e4ecb35a687b/1-0000.mp3", duration = 101.067755, start = 0},
  },
}
P.transport["npc:wizlo-bearingshiner"] = {
  hash = "af0e04",
  fullHash = "af0e04",
  text = "Wizlo Bearingshiner. Wizlo Bearingshiner is a goblin tinkerer stranded at Whitereach Post in Thousand Needles. The sole survivor of a centaur attack on his caravan, he recruits travelers to recover a valuable Hypercapacitor Gizmo from the wreckage. Staying alongside the tauren at Whitereach Post along the canyon road, Wizlo Bearingshiner faces an unwelcome delay. Centaur attacked his caravan, leaving him as its only survivor. His clients are waiting for their wares, and he worries that he will not deliver them in time. Wizlo's best gizmo hangs around the neck of a fierce panther caged beside his ruined caravan north of Whitereach Post. Even the centaur avoid the beast. Wizlo offers travelers the cage key and a reward for recovering the hypercapacitor, though he admits he has yet to work out what the device actually does.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_wizlo-bearingshiner-db42fd58da7683c94f8e/1-0000.mp3", duration = 52.0359184, start = 0},
  },
}
P.transport["npc:wizzle-brassbolts"] = {
  hash = "7134fc",
  fullHash = "7134fc",
  text = "Wizzle Brassbolts. Wizzle Brassbolts is a gnome engineer stationed alongside his fellow tinkerers out on the salt flats of Thousand Needles. Working with the gnomish racing team at the Mirage Raceway, he seeks durable local materials to reinforce their experimental rocket cars. Out in the shimmering heat of the Shimmering Flats, the rivalry between gnomish and goblin engineering takes the form of high-speed rocket car races. Wizzle Brassbolts works as part of the gnomish raceway crew, striving to keep their vehicles intact against blistering speeds and abrasive salt. To bolster their machines, he recruits adventurers to hunt the local wildlife—such as the sturdy turtles wandering the basin—harvesting their hard shells to build new fuel tanks strong enough to hold his brother's corrosive new rocket fuel. Wizzle maintains close ties with friends across the continents, including Pilot Longbeard, who sends couriers out with racing helmets for the brothers. With help like that, Wizzle keeps the gnomish team supplied despite their remote, inhospitable testing ground on the Shimmering Flats.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_wizzle-brassbolts-1a9ca5f0819b80552b7c/1-0000.mp3", duration = 64.5746939, start = 0},
  },
}
P.transport["npc:wizzlecrank-s-shredder"] = {
  hash = "358680",
  fullHash = "358680",
  text = "Wizzlecrank's Shredder. In Sludge Fen, Wizzlecrank's Shredder sits trapped among Venture Company operators. Pilot Wizzlecrank climbed inside the machine to steal it, but it will not move without a key. Its engine must be started before the goblin can try to escape. Deep in Sludge Fen, Wizzlecrank waits inside a motionless shredder. The Venture Company machine is surrounded by hostile mercenaries in the polluted basin. Wizzlecrank climbed aboard to steal it, then learned he needed a key to unlock its movement column. When another shredder operator asked if all was well, he panicked and blamed a mechanical problem. Now he remains sealed inside, with guards and overseers nearby, hoping someone will fetch the key before the Venture Company grows suspicious.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_wizzlecrank-s-shredder-cdc4cd7abf98a0c7fb28/1-0000.mp3", duration = 45.2963265, start = 0},
  },
}
P.transport["npc:wrenix-the-wretched"] = {
  hash = "c9be36",
  fullHash = "c9be36",
  text = "Wrenix the Wretched. Beside his strange apparatus in Ratchet, Wrenix the Wretched helps crack tough locks. The goblin tinker offers tools to open secure caches. Wrenix the Wretched works beside his machinery in Ratchet, the goblin port on the Barrens coast. As a tinker of the Steamwheedle Cartel, he knows mechanisms and contraptions, and how to bypass locks and salvage what lies beyond them. Rogues and scouts working the coast can turn to him for help. Wrenix keeps his gizmotronic apparatus close at hand. He uses it and his mechanical skill to supply thieves' tools and lock-picking instruments. Those seeking to recover stolen Southsea pirate contraband along the Merchant Coast can put them to use.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_wrenix-the-wretched-6207397b7acf215bf177/1-0000.mp3", duration = 42.8146939, start = 0},
  },
}
P.transport["npc:wynne-larson"] = {
  hash = "dc89bb",
  fullHash = "dc89bb",
  text = "Wynne Larson. In Stormwind's Mage Quarter, Wynne Larson supplies mages across the kingdom with robes. Human clothier Wynne relies on local craftsmen since Dalaran and Quel'Thalas fell in the Third War, and points spellcasters toward rare materials for enchanted garments. Before the Third War, Dalaran and Quel'Thalas supplied the finest woven fabrics and enchanted vestments. Their destruction crippled the old trade routes and arcane textile production. In Stormwind's Mage Quarter, Wynne Larson now works with local tailors and enchanters such as Lucan Cordell. Together, they meet the city's growing demand for robes and spellwoven gear. Novice and journeyman mages seeking arcane garments come to Wynne's shop. She knows what materials are needed for vestments such as Manaweave Robes and Astral Knot Garments. To find those materials, she sends arcane practitioners into dangerous places to recover rare reagents like pristine spider silk. Her work helps keep Stormwind's mages outfitted despite shortages from the north.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_wynne-larson-572ad009454d6a940892/1-0000.mp3", duration = 62.2497959, start = 0},
  },
}
P.transport["npc:xavathras"] = {
  hash = "ac95a5",
  fullHash = "ac95a5",
  text = "Xavathras. Xavathras is a vicious satyr commander residing among the tents at the Ruins of Constellas in Felwood. Leading a band of Jadefire satyrs, he oversees the corruption of an ancient moonwell in service to his master, Xavaric. Within the tainted glades of Felwood, the Ruins of Constellas have fallen into the clutches of the Jadefire satyrs. Stationed in an encampment pitched amidst the elven stonework, Xavathras directs the defilement of a nearby moonwell on behalf of another cruel satyr, Xavaric. By poisoning the pure waters with demonic energy, Xavathras deepens the corruption that grips the forest. His presence poses a direct threat to any attempts to restore the woodland, earning the ire of night elves like Eridan Bluewind who mark him for death.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_xavathras-ca3df3c6f2b94fd3fd5b/1-0000.mp3", duration = 46.0277551, start = 0},
  },
}
P.transport["npc:yeh-kinya"] = {
  hash = "8c016e",
  fullHash = "8c016e",
  text = "Yeh'kinya. Yeh'kinya is a jungle troll scholar residing at Steamwheedle Port on the desert coast of Tanaris. Claiming to seek ancient lore and artifacts to understand dark powers, he dispatches willing adventurers across Azeroth on missions to gather lost troll relics. Lounging among the goblins and dockworkers of Steamwheedle Port, Yeh'kinya presents himself as a quiet student of history and spirits. He recruits travelers to track down obscure magical items across Kalimdor and the Eastern Kingdoms, from ancient eggs in the Hinterlands to stone prophecy tablets buried in the ruins of Zul'Farrak. While he claims these errands serve peaceful academic inquiry into ancient troll history, his specific focus on the blood god Hakkar draws suspicion from watchful onlookers.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_yeh-kinya-e7c5c7813b972b5d9c0e/1-0000.mp3", duration = 47.6995918, start = 0},
  },
}
P.transport["npc:yvette-farthing"] = {
  hash = "090386",
  fullHash = "090386",
  text = "Yvette Farthing. Yvette Farthing is a Forsaken resident of Brill in Tirisfal Glades, dwelling in the Gallows' End Tavern alongside her father, Coleman. Though she appears as hardened and detached as any of Sylvanas's people, she carries the lingering ghost of a mortal romance cut short by the Scourge. Before the Third War swept Lordaeron into ruin, Yvette was in love with Thurman Agamand, one of the heirs of the prosperous Agamand Mills. When the Scourge plague approached, Yvette and her father, Coleman, begged Thurman to abandon the estate and flee with them. Thurman refused out of devotion to his family's legacy. Both would eventually perish and rise into undeath, but while Yvette found a place among the free-willed Forsaken in Brill, Thurman's tragic final fate remained unknown to her.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_yvette-farthing-6476b70fe328f986c53e/1-0000.mp3", duration = 48.4832653, start = 0},
  },
}
P.transport["npc:zaldimar-wefhellt"] = {
  hash = "c073f3",
  fullHash = "c073f3",
  text = "Zaldimar Wefhellt. On Goldshire's upper floor, Zaldimar Wefhellt teaches young mages their first spells. When they outgrow his lessons, he sends them to Stormwind City for further training. Upstairs at the Lion's Pride Inn, Zaldimar Wefhellt teaches novice mages the first arts of arcane, fire, and frost. When an apprentice outgrows those lessons, he sends them north to the Mage Quarter in Stormwind, where Jennea Cannon can teach them more.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_zaldimar-wefhellt-276a15b3d9c34a9be742/1-0000.mp3", duration = 26.6710204, start = 0},
  },
}
P.transport["npc:zamja"] = {
  hash = "0159f0",
  fullHash = "0159f0",
  text = "Zamja. In Orgrimmar’s Drag, Zamja teaches Horde travelers to cook. The Darkspear troll trains cooks to make meals from beasts of Kalimdor. Zamja works in the Drag, where she cuts meat and teaches Horde travelers to cook. Cooking helps travelers in the rugged lands of Durotar and the Barrens turn raw game into rations. Cooks who have mastered basic recipes can seek further training in Gadgetzan, to the south.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_zamja-3afd325c92421d6c9f69/1-0000.mp3", duration = 25.8873469, start = 0},
  },
}
P.transport["npc:zangen-stonehoof"] = {
  hash = "a45ac3",
  fullHash = "a45ac3",
  text = "Zangen Stonehoof. Zangen Stonehoof is a tauren keeper situated at the High Rise bonfire in the heart of Thunder Bluff. Dutiful and revered among his peers, he faithfully tends to the central flames each evening while coordinating efforts to aid his distant kin across Kalimdor. Perched on the High Rise of Thunder Bluff, Zangen Stonehoof maintains the central communal bonfire that overlooks the city's highest bluffs. As twilight falls over Mulgore, Zangen kindles the fire, providing warmth and an enduring beacon for the tribes assembled beneath High Chieftain Cairne Bloodhoof. Beyond keeping the flames alight, he maintains ties with allies beyond Mulgore's mesa, acting as a liaison for spiritual and ritual endeavors taking place across the continent. Zangen acts as an intermediary for Rau Cliffrunner, an associate stationed south in Thousand Needles. When Rau required the mystical waters of a night elf moonwell for sacred rituals, Zangen enlisted dependable Horde adventurers to brave the contested forests of Ashenvale. By securing the filled phial from the ancient groves and dispatching it south to Freewind Post, Zangen plays a quiet but pivotal part in preserving ancient rites and assisting scattered tauren posts.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_zangen-stonehoof-b14a311d2007f005d53f/1-0000.mp3", duration = 75.3632653, start = 0},
  },
}
P.transport["npc:zankaja"] = {
  hash = "e7c5a4",
  fullHash = "e7c5a4",
  text = "Zankaja. In Orgrimmar, young orc woman Zankaja waits anxiously for word of her mate, Dogran. He was assigned to duty at the Crossroads, along the dangerous frontier of the Barrens. Zankaja waits for news of Dogran, her mate, in Orgrimmar. Dogran earned a promotion and went south to bolster the outpost at the Crossroads in the Barrens. The assignment honors a warrior, but the frontier is harsh, with quilboar, centaur, and aggressive beasts. When Dogran failed to send word or return as expected, Zankaja began asking travelers to seek news of him.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_zankaja-91eb77a5d3fd05ed37ce/1-0000.mp3", duration = 36.7281633, start = 0},
  },
}
P.transport["npc:zardeth-of-the-black-claw"] = {
  hash = "5a11b2",
  fullHash = "5a11b2",
  text = "Zardeth of the Black Claw. In Stormwind's Mage Quarter, Zardeth of the Black Claw protects a hidden warlock cabal from scrutiny. He dwells in the chambers beneath the Slaughtered Lamb and poses as an ordinary patron. When curious nobles look too closely, he makes sure their inquiries end for good. Beneath the Slaughtered Lamb, tunnels shelter those who practice darker arts while the Mage Quarter's spires study arcane discipline in the open. Zardeth of the Black Claw works from these crypts, guarding warlocks who hide right beneath the city guard's nose. The Alliance condemns fel magic, so the cabal survives by keeping its presence secret and removing threats before royal investigators arrive.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_zardeth-of-the-black-claw-3405ed55c463490c4df0/1-0000.mp3", duration = 44.6693878, start = 0},
  },
}
P.transport["npc:zargh"] = {
  hash = "046b1e",
  fullHash = "046b1e",
  text = "Zargh. At the Crossroads in the Barrens, Zargh sells meat and sends choice cuts to Orgrimmar. At the Crossroads, Zargh sells cured meat, shank, and game from the surrounding plains. Travelers heading into the wilderness can find provisions at his shop. He also sends choice cuts across Durotar to Innkeeper Gryshka in the Valley of Strength in Orgrimmar.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_zargh-d58082aa333061272a2c/1-0000.mp3", duration = 22.0212245, start = 0},
  },
}
P.transport["npc:zarlman-two-moons"] = {
  hash = "50597d",
  fullHash = "50597d",
  text = "Zarlman Two-Moons. Zarlman Two-Moons is a revered tauren mystic residing in Bloodhoof Village in central Mulgore. While Baine Bloodhoof oversees the village's daily earthly affairs, Zarlman guides its spiritual life and communions with the spirits. He plays a vital role in initiating young tauren into adulthood through the sacred Rite of Vision. Within Bloodhoof Village, leadership is divided between the physical and the mystical. Baine Bloodhoof commands the settlement's defense and temporal needs, but it is Zarlman Two-Moons who maintains the harmony of the spirit world. In a culture deeply rooted in reverence for the Earth Mother and ancestral wisdom, Zarlman serves as a conduit between the everyday struggles of the plains and the timeless voices of the past. Zarlman's most crucial duty to his people is administering the Rite of Vision, a traditional trial every maturing tauren must undertake. By guiding initiates to prepare sacred draughts and listen closely to ancestral portents, he helps young hunters, shamans, and warriors discover their destined path and spirit guides. Under his instruction, initiates learn that physical strength on the plains means little without spiritual clarity.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_zarlman-two-moons-df852cfa162758611372/1-0000.mp3", duration = 73.7436735, start = 0},
  },
}
P.transport["npc:zarrin"] = {
  hash = "581465",
  fullHash = "581465",
  text = "Zarrin. Behind Dolanaar's inn, Zarrin teaches the ways of Kaldorei cooking. He tends an open hearth on Teldrassil, where young night elves and visitors learn to prepare meals from the tree's native flora and fauna. Behind Dolanaar's inn, Zarrin tends an open cooking fire and teaches Kaldorei culinary arts. Teldrassil's native plants and animals provide food for those who live here. Zarrin shows visitors how to forage and prepare meals at home.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_zarrin-44b8e6f29e51d2d374cd/1-0000.mp3", duration = 26.9061224, start = 0},
  },
}
P.transport["npc:zenn-foulhoof"] = {
  hash = "2d2abe",
  fullHash = "2d2abe",
  text = "Zenn Foulhoof. East of Dolanaar, Zenn Foulhoof asks travelers for forest reagents. The night elves watch him closely.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_zenn-foulhoof-e5d70118d698897c10e9/1-0000.mp3", duration = 8.67265306, start = 0},
  },
}
P.transport["npc:zevrost"] = {
  hash = "40e8c1",
  fullHash = "40e8c1",
  text = "Zevrost. In Orgrimmar’s Cleft of Shadow, Zevrost trains warlocks in fel magic. He guides Horde initiates through summoning rites and the handling of dark artifacts. In the Cleft of Shadow beneath Orgrimmar, Zevrost is one of the chief mentors for Horde warlocks in Thrall’s capital. Orcs remain wary of fel magic after their past demonic corruption, so practitioners work under strict watch. Zevrost teaches the discipline needed to command demons without yielding to their corruption. He says fel ruins only those who lack inner strength. Zevrost guides warlocks beyond spells and curses, opening the way to greater dark undertakings. Initiates seeking advanced implements such as the Orb of Orahil, or the means to summon a fiery Felsteed, often come through his hands. He sends ambitious practitioners to other masters, including Menara Voidrender in the Barrens, so they can push their command of shadow magic to its limits.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_zevrost-24563be72555932baede/1-0000.mp3", duration = 59.6897959, start = 0},
  },
}
P.transport["npc:zjolnir"] = {
  hash = "8f3398",
  fullHash = "8f3398",
  text = "Zjolnir. In Sen'jin Village, Zjolnir raises raptors for Darkspear riders and trusted Horde champions. His trained mounts carry deep cultural pride for troll riders. Near Sen'jin Village's pens, Zjolnir raises the fierce raptors the Darkspear favor as mounts. Predatory and temperamental, they need an expert hand before they can be raised and saddled for war. Zjolnir freely gives these prized mounts to fellow trolls who have learned the riding arts. Other Horde members must first earn the Darkspear tribe's exalted trust before he will entrust them with one of his raptors.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_zjolnir-69599c2398d10c856fbd/1-0000.mp3", duration = 36.2579592, start = 0},
  },
}
P.transport["npc:zor-lonetree"] = {
  hash = "8dfd17",
  fullHash = "8dfd17",
  text = "Zor Lonetree. At Grommash Hold, Zor Lonetree studies the Horde’s concerns beyond Durotar. His knowledge of Alliance politics helps the court judge foreign affairs across Kalimdor. Zor Lonetree watches beyond Durotar from Grommash Hold. A shrewd advisor to the Horde’s high leadership, he has an unusually keen understanding of human and Alliance politics. When foreign curiosities reach Orgrimmar, he studies them; when trouble stirs among the land’s spirits, he directs travelers toward it. He has examined noble jewelry recovered from human settlements and followed disturbances among the spirits of the Stonetalon Mountains, keeping the warchief’s court informed on both political and spiritual matters.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_zor-lonetree-69a615e8e3bcf041ad33/1-0000.mp3", duration = 44.8261224, start = 0},
  },
}
P.transport["npc:zureetha-fargaze"] = {
  hash = "08d8ae",
  fullHash = "08d8ae",
  text = "Zureetha Fargaze. In the Valley of Trials, Zureetha Fargaze watches for threats to young Horde recruits. Alongside Foreman Thazz'ril in Durotar, she sends them to uncover and root out the Burning Blade cult hidden in the valley. Zureetha Fargaze watches for dangers beyond the work and discipline Foreman Thazz'ril oversees. The Burning Blade cult has secretly entered the Valley of Trials, corrupted lesser demons, and gathered strength in the nearby Burning Blade Coven. She sends untested adventurers to recover medallions from the cultists, confirm their presence, and disrupt their early efforts. Then she directs seasoned recruits farther into Durotar.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_zureetha-fargaze-caec5148c9b696a52eb6/1-0000.mp3", duration = 39.7844898, start = 0},
  },
}
P.transport["topic:agamaggan"] = {
  hash = "2a50a2",
  fullHash = "2a50a2",
  text = "Agamaggan. Agamaggan the Great Boar was one of the colossal Ancient Guardians who walked Azeroth in its earliest days. He fell ten thousand years ago fighting the Burning Legion in the War of the Ancients, and his sacrifice helped save Azeroth from ruin. Where his blood and body crashed into the earth, vast networks of thorny vines arose, creating the Razorfen and granting life and purpose to his descendants, the quilboar. Ten thousand years ago, during the War of the Ancients, the mighty demigod Agamaggan came forth to battle the Burning Legion. The colossal boar fought with terrifying ferocity, and though he ultimately fell in combat, his actions helped save Azeroth from ruin. Where Agamaggan collapsed in the southern Barrens, his colossal corpse reshaped the land. His spilled blood soaked into the soil, causing enormous, impenetrable brambles and thorny vines to burst upward from the dry earth. These tangled thickets became known as the Razorfen. The quilboar revere the site as their holiest ground, viewing the labyrinth of Razorfen Kraul as his resting body and Razorfen Downs as his gaping skull. Scattered throughout the Barrens are crystallized Blood Shards, believed to be the physical remnants of the demigod's spilled blood, pulsing with lingering primal energy that quilboar geomancers and shamans harness for power. Agamaggan is revered as the divine progenitor of all quilboar. They view the surrounding brambles not merely as homes, but as the living armor left behind by their creator to shelter them from hostile neighbors. Quilboar tribes believe their god's spirit watches over them, granting martial vigor to their warriors and earth magic to their geomancers. In turn, they aggressively defend the thorns against encroaching tauren, orcs, and centaur, convinced that their sacred duty is to guard the fallen body of the boar god who birthed them.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_agamaggan-76ee73613aa3880a28cd/1-0000.mp3", duration = 111.725714, start = 0},
  },
}
P.transport["topic:alliance"] = {
  hash = "74ab08",
  fullHash = "74ab08",
  text = "Alliance. The Alliance is a grand coalition of mortal races bound by shared ideals of honor, duty, and the defense of order across Azeroth. Born out of the ashes of the northern kingdom of Lordaeron, its current heart beats in Stormwind City, united alongside the dwarves of Ironforge, the exiled gnomes, and the night elves of Kalimdor. The modern Alliance descends from the original Alliance of Lordaeron, founded when Sir Anduin Lothar led Stormwind refugees north during the Second War to unite the Seven Kingdoms, dwarves, and high elves against the Old Horde. While the Scourge and the Third War decimated the north—leaving Lordaeron in ruins and driving the survivors into scattered resistance—the restored Kingdom of Stormwind rose to fill the void. Today, Stormwind stands as the preeminent seat of human leadership, carrying the banners of honor and faith into a fractured world. The faction's backbone in the Eastern Kingdoms relies on the steadfast bond between humans and the dwarves of Ironforge under King Magni Bronzebeard. Alongside the dwarves reside the gnomes, driven from Gnomeregan by a devastating trogg uprising. Guided by High Tinker Gelbin Mekkatorque, the exiled gnomes lend their brilliant engineering to the Alliance war effort, believing the coalition's survival is paramount to ever reclaiming their irradiated home. Across the Great Sea, the reclusive night elves abandoned millennia of isolation after the Battle of Mount Hyjal. Reeling from the loss of their immortality and engaged in bitter territorial clashes against the Horde over logging in Ashenvale, the kaldorei allied with their newfound mortal companions. Though cultural friction remains—and some traditionalists decry the presence of humans and dwarves in ancient forests—the Alliance provides vital military and diplomatic cooperation to safeguard Kalimdor against demonic remnants and Horde expansion. Despite its outward strength, the Alliance is beset by internal strain. King Varian Wrynn vanished under mysterious circumstances en route to a diplomatic summit, leaving his young son Anduin on the throne under Highlord Bolvar Fordragon's regency. Relations with former human allies are fractured: the maritime kingdom of Kul Tiras keeps its distance, while Sylvanas Windrunner's undead Forsaken now hold the ruins of Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_alliance-13eb0ffaaeb73dd12c41/1-0000.mp3", duration = 143.412245, start = 0},
  },
}
P.transport["topic:brotherhood-of-northshire"] = {
  hash = "fa3c28",
  fullHash = "fa3c28",
  text = "Brotherhood of Northshire. The Brotherhood of Northshire is a holy human clerical order dedicated to the Church of the Holy Light, based out of Northshire Abbey in Elwynn Forest. Originally known as the Clerics of Northshire, the order suffered catastrophic losses during the First War before being reformed under Archbishop Alonsus Faol. Today, the Brotherhood serves as both a spiritual sanctuary and the primary training ground for fledgling Alliance defenders. Centuries ago, pious missionaries traveled south from Lordaeron into the kingdom of Stormwind, establishing Northshire Abbey to minister to the people and soothe the realm through the Holy Light. Originally known as the Holy Order of Northshire Clerics, their compassion was legendary—they even tended to injured gnolls and jungle trolls during past border wars. When the Orcish Horde crossed through the Dark Portal, the clerics marched bravely to the front lines without armor or weapons to heal fallen soldiers. Because their healing sustained the Stormwind Army, the orcs ruthlessly targeted them. The order was decimated, the abbey was ransacked and burned, and the surviving clerics were forced to flee north across the sea to Southshore with Sir Anduin Lothar. The slaughter of the Northshire clerics sent shockwaves through the human kingdoms. Realizing that faith alone could not withstand an axe without armor and martial discipline, Archbishop Alonsus Faol resolved to create warriors who possessed both the sacred powers of the Light and the martial mastery of a knight. Drawing upon the surviving clerics and devout knights, Faol formed the Knights of the Silver Hand, giving rise to humanity's first paladins. In this way, the sacrifice of Northshire's fallen healers became the very foundation for the holy warriors who broke the Horde in the Second War. Following the reclamation of Stormwind and the destruction of the Dark Portal, Archbishop Faol oversaw the rebuilding of Northshire Abbey and reorganized the order as the Brotherhood of Northshire. Now in 25 ADP, Northshire Abbey stands as a quiet yet vital center where new recruits gather to begin their service to the realm. Under figures like Priestess Anetta, Brother Sammuel, and Brother Paxton, the Brotherhood attends to the spiritual health of the valley, preserves ancient texts in their library, and trains the next generation of defenders to confront brigands, wolves, and the gathering shadows across Elwynn Forest.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_brotherhood-of-northshire-b2c9eeb2fbe1b68e94bd/1-0000.mp3", duration = 146.494694, start = 0},
  },
}
P.transport["topic:centaur"] = {
  hash = "39eea6",
  fullHash = "39eea6",
  text = "Centaur. Centaur are a violent, horse-bodied humanoid race whose nomadic clans dominate the arid plains of central Kalimdor. Born from the tragic union between the demigod Zaetar and the earth princess Theradras, they spent centuries driving the tauren toward extinction before the newly arrived orcish Horde intervened. Centaur legend traces the race to the caverns of Maraudon beneath Desolace. There, Zaetar, one of the immortal sons of the demigod Cenarius, and Princess Theradras, daughter of the elemental lord Therazane, sired the first centaur. Upon their emergence, the barbaric offspring turned on their father and killed him. Grief-stricken, Theradras trapped Zaetar's spirit within the winding caverns of Maraudon, yet she shielded her vicious children, who swiftly multiplied across Kalimdor. Following their emergence, the centaur expanded outward from Desolace, waging a brutal war of attrition against Kalimdor's native populations. The nomadic tauren suffered the most: driven from their fertile ancestral homeland of Mulgore, they were chased relentlessly across the Barrens. Centaur warbands treated the tauren as prey, burning settlements and hunting them for sport. By the time of the Third War, centuries of relentless pursuit had brought the tauren to the precipice of extinction, leaving them desperately fleeing endless marauders across the savannah. Everything shifted when Warchief Thrall and the newly arrived orcish Horde landed upon Kalimdor. Thrall formed a pact with Cairne Bloodhoof, uniting orcish steel with tauren might. Together, they crushed the aggressive Kolkar warbands, broke their grip on the plains, and enabled the tauren to safely establish Thunder Bluff and reclaim Mulgore. This alliance ended the nomadic exile of the tauren and established a debt of blood and honor that permanently bound them into the Horde. Despite their staggering defeats, centaur remain an active threat across central Kalimdor. Their society is divided into warring clans—primarily the Kolkar, Gelkis, Magram, and Maraudine—each led by a khan and locked in perpetual blood feuds over territory and water. While their internal squabbles keep them from uniting into an unstoppable horde, aggressive raiding parties continue to strike at trade caravans and settlements across Durotar, the Barrens, Thousand Needles, and the borders of Mulgore.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_centaur-95c1f816fc8e86af3a2c/1-0000.mp3", duration = 144.718367, start = 0},
  },
}
P.transport["topic:defias-brotherhood"] = {
  hash = "94cf35",
  fullHash = "94cf35",
  text = "Defias Brotherhood. The Defias Brotherhood is a widespread criminal network of bandits, brigands, and assassins waging an underground insurgency against the Kingdom of Stormwind. Originally formed by the artisans of the Stonemasons Guild who were cheated of their pay for rebuilding the capital, they have devolved into violent outlaws terrorizing the southern farmlands. From their hidden redoubt deep beneath Westfall, they aim to overthrow the corrupt House of Nobles and lay waste to the kingdom. Following the Second War, the Stonemasons Guild was hired to rebuild Stormwind from smoldering ruins into a grand stone capital. When their masterwork was finished, the House of Nobles refused to deliver the promised payment, citing crushing wartime debt. Guildmaster Edwin VanCleef spoke out on behalf of his workers, demanding fair restitution, but the nobles responded by ordering the Stonemasons Guild disbanded. The ensuing riots in the city streets ended with the laborers driven out of Stormwind into exile. Stripped of their livelihood and outlawed, VanCleef and the desperate workers banded together, binding their faces in red silk to represent the blood of the wronged, and turned to highway robbery to claim what they believed they were owed. With the royal army overextended, VanCleef turned the neglected farmlands of Westfall into the Brotherhood's base of operations. The bandits overran the hamlet of Moonbrook and commandeered the abandoned subterranean tunnels of the Deadmines. Defias agents seized local mines, driven farmers from their homesteads with reprogrammed harvest golems, and salted the earth to starve the region. With the Crown unable or unwilling to send soldiers to protect rural citizens, local farmers formed The People's Militia out of Sentinel Hill to fight a desperate war of attrition against an enemy that now outmans and outguns them.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_defias-brotherhood-89175c0aa6d01297f71b/1-0000.mp3", duration = 110.027755, start = 0},
  },
}
P.transport["topic:druid"] = {
  hash = "e551c8",
  fullHash = "e551c8",
  text = "Druid. Druids are guardians of the natural world who draw power directly from the wild spirits, the celestial bodies, and the Emerald Dream. Master shapeshifters, they adopt the forms of primal beasts to protect the land or mend grievous wounds. Practiced primarily by the night elves, newly revived among the tauren and kept alive by the Skyborne, druids place the preservation of nature above all mortal allegiance. Druidism is far more than a martial art; it is an ancient way of life rooted in deep communion with nature and the demigod Cenarius. Druids wield raw natural energies, commanding roots to entangle their foes, directing the celestial brilliance of the moon and stars, and invoking restorative flora to knit bone and flesh. Their duty is to preserve the cosmic balance and protect the unfettered wild from exploitation and corruption. The defining hallmark of the druid is the supernatural art of shapeshifting. Through spiritual devotion, practitioners channel the primal aspects of Azeroth's beasts. They take on the thick hide of the bear to withstand crushing assaults, slip into the lithe form of the feline predator to strike from the shadows, or adopt aquatic and avian shapes to traverse sea and sky. While transformed, their animal mouths can rarely form mortal words, yet their physical prowess rivals the apex predators of the wild. First taught to Malfurion Stormrage by Cenarius ten thousand years ago, mortal druidism was later formalized under the Cenarion Circle. Headquartered in sacred Moonglade, the Circle watches over druidic practices across Kalimdor, standing independent of mortal factions and political squabbles. While long dominated solely by night elf men who spent centuries slumbering in the Emerald Dream, the aftermath of the Third War saw both night elf women and the tauren welcomed into its fold. Druidism reached the Skyborne long ago. When the Shal'nan's rebellion rose against Prince Tortheldrin in Eldre'Thalas, the common folk who joined it took up nature magic, influenced by the Cenarion Circle to the north, while Tortheldrin scorned it as beneath the Highborne. Their descendants still practice it: the Nightclaw Druids of Shadowgale Forest on Zephras Isle keep largely to themselves, apart from the other Skyborne factions.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_druid-12eca46913247d89392f/1-0000.mp3", duration = 145.737143, start = 0},
  },
}
P.transport["topic:druids-of-the-fang"] = {
  hash = "55b017",
  fullHash = "55b017",
  text = "Druids of the Fang. The Druids of the Fang are a splinter sect of night elf druids who succumbed to corruption deep within the Wailing Caverns. Originally disciples of the visionary Naralex, they abandoned the Cenarion Circle after their master's connection to the Emerald Dream turned into a foul nightmare. Under the self-proclaimed Lord Serpentis, they now wield serpent-like forms and seek to remake the Barrens into their own twisted paradise. The Barrens was not always an arid wasteland, and Naralex sought to return it to the lush, verdant sanctuary it once was. Naralex led a dedicated order of young druids into the subterranean depths of the Wailing Caverns, tapping into the natural underground fissures and subterranean springs. By entering an induced slumber, Naralex hoped to channel the living energies of the Emerald Dream into the waterways, nursing the scorched savannah above back to vibrant life.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_druids-of-the-fang-0294365caafe0bfa303d/1-0000.mp3", duration = 54.9877551, start = 0},
  },
}
P.transport["topic:dwarf"] = {
  hash = "ba1e23",
  fullHash = "ba1e23",
  text = "Dwarf. Dwarves are a stout, resilient race carved from the living stone of ancient titan-forged earthen, now inhabiting the snow-capped mountain kingdoms of Khaz Modan and beyond. Known for their mastery of stonework, metallurgy, and devastating frontline combat, they stand as one of the Alliance's fiercest and most dependable pillars. Under the reign of King Magni Bronzebeard, their sprawling subterranean capital of Ironforge serves as the beating heart of dwarven society. Long ago, the subterranean titan-forged known as earthen awoke from an eons-long slumber within the vaults of Uldaman, transformed by the Curse of Flesh into beings of blood and bone. Taking the name dwarves, they reclaimed the high crags of Khaz Modan—named in honor of the titan Khaz'goroth—and carved the majestic subterranean stronghold of Ironforge beneath the peaks of Dun Morogh. Endowed with incredible natural fortitude, a sharp eye for stone and ore, and a penchant for roaring hearths and heady ale, dwarves approach craftsmanship and warfare with identical tenacity. Dwarven unity shattered centuries ago following the death of High King Modimus Anvilmar. Civil war erupted across Ironforge among three rival factions: the Bronzebeard clan, the Wildhammer clan, and the Dark Iron clan. After the Bronzebeards secured the mountain and drove out their kin, Sorcerer-Thane Thaurissan of the Dark Irons launched a disastrous war of vengeance against both rivals. Driven to desperation beneath the Redridge Mountains, Thaurissan accidentally summoned Ragnaros the Firelord, immolating his own realm into the volcanic wastes of Searing Gorge and the Burning Steppes. The surviving Dark Irons were enslaved beneath Blackrock Mountain, while the devastated Wildhammers migrated north to Aerie Peak in the Hinterlands. When the orcish Horde surged across the continent during the Second War, King Magni Bronzebeard sealed Ironforge's gates against brutal sieges while dwarven forces took up arms alongside the Alliance of Lordaeron. Renowned for heavy plate armor, deadly muskets, and fearless gryphon riders, dwarven warriors played a vital role in shattering the Horde. Today, the Kingdom of Ironforge remains one of the Alliance's most stalwart defenders, welcoming their displaced gnome cousins into their halls while actively unearthing the titan ruins of Khaz Modan to unravel the mysteries of their ancient origins.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_dwarf-d6764a6d713ef08aa390/1-0000.mp3", duration = 148.166531, start = 0},
  },
}
P.transport["topic:earth-mother"] = {
  hash = "87ad78",
  fullHash = "87ad78",
  text = "Earth Mother. The Earth Mother is the supreme, benevolent creator deity worshipped by the tauren, revered as the living embodiment and architect of Azeroth's land and elements. In tauren myth, she shaped the mountains, plains, and seasons and set the sun and moon in the sky as her watchful eyes. Her presence permeates everyday tauren culture, guiding their reverence for nature, duty to the elements, and hopes for the afterlife. Tauren creation myths tell that before day and night existed, the Earth Mother set about shaping Azeroth as a haven for her coming children. Scraping her nails across newly raised mountains sparked the world's first fires, while her hands carved rivers and ocean beds. Her laughter gave breath to the wind, and by lifting the primordial fogs into the sky, she brought the first rains, which coaxed grass, forests, and grain from the soil. Aided by the friendly elements, the Earth Mother brought forth twins: An'she, the sun, and Mu'sha, the moon. To rest while keeping them safe, she placed the radiant twins into her eyes, creating day, night, and the cycle of the seasons as she opened and closed each lid. Later, she pressed her heart against the fertile earth, breathing the song of life into the land to create the shu'halo, the first tauren. She charged the twins and the elements with teaching the young mortals how to hunt, build, dance, and live in harmony with the wilds. In time, the Earth Mother set An'she and Mu'sha in the sky, where the sun and moon keep watch over the land by day and by night. Tauren say that her spirit now dwells in the rivers, trees, plains, and mountains of the world, and that every lesser nature spirit springs from her and returns to her in the end. Tauren believe her spirit cradles Azeroth still. Her ear is attuned to the winds, hearing the prayers of her children, and her heart beats within the deep stone. Tauren hunters, shamans, and druids direct their thanks to her for every kill and harvest, believing that all life originates from her embrace and that every tauren's spirit returns to her soil upon death.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_earth-mother-766f12899d03b4ac0c98/1-0000.mp3", duration = 128.600816, start = 0},
  },
}
P.transport["topic:elemental-plane"] = {
  hash = "6da85d",
  fullHash = "6da85d",
  text = "Elemental Plane. The Elemental Plane is an interconnected pocket dimension forged by the titans to imprison Azeroth's chaotic elementals. Divided into four distinct realms—Skywall, Deepholm, the Abyssal Maw, and the Firelands—it confines the primordial spirits away from the mortal world. Though sealed long ago, cracks in its barriers allow violent elemental incursions and catastrophic summonings into Azeroth. In the ancient days, the elementals served as lieutenants of the Old Gods. When the titans triumphed, they banished the elemental lords and their myriad servants into an isolated realm known as the Elemental Plane, divided into four domains tailored to each primal force: Skywall for air, Deepholm for earth, the Abyssal Maw for water, and the Firelands for fire. With the elementals' departure, nature calmed, and Azeroth's surface finally knew peace. Banishment did not temper the fury of the elementals. Confined within their prison, the primordial powers wage endless wars against one another across the boundaries of their domains. The barriers separating Azeroth from the Elemental Plane are formidable, but not unbreakable. Two centuries ago, during the desperate climax of the War of the Three Hammers, Sorcerer-Thane Thaurissan pierced the veil to summon Ragnaros the Firelord from the Firelands, an apocalyptic event that ruptured the Redridge Mountains and forged Blackrock Mountain. In recent days, volatile cracks have opened across Kalimdor. Dimensional rifts repeatedly manifest in Silithus, Un'Goro Crater, Azshara, and Winterspring, disgorging waves of hostile elementals eager to test the defenses of the mortal world.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_elemental-plane-4ca8c284f8ca6557228d/1-0000.mp3", duration = 105.534694, start = 0},
  },
}
P.transport["topic:furbolg"] = {
  hash = "8277ea",
  fullHash = "8277ea",
  text = "Furbolg. Furbolgs are a hulking, reclusive race of bear-men native to northern Kalimdor who lived in harmony with nature and the night elves for millennia. In the wake of the Third War, demonic corruption and lingering fel magic have driven nearly every tribe into a frenzied madness. Today, former friends have become vicious territorial predators, with only a tiny handful of tribes clinging to their sanity. Furbolgs are an ancient people of Kalimdor who have long revered the wild god Ursoc. During the War of the Ancients ten thousand years ago, tribal packs united under chieftain Unng Ak to fight alongside night elves and tauren against the first demonic invasion. Following the Great Sundering, they chose seclusion deep in the northern woodlands, maintaining peaceful ties with night elf druids and forest wardens while living in simple harmony with the wild. The Third War shattered the furbolgs' tranquil existence. The passage of the Burning Legion through Kalimdor left lingering fel taint across the soil and canopy of Ashenvale and Felwood. Simple-minded and deeply attuned to the land, the bear-men absorbed this corruption directly. Their wizened shamans were overthrown or silenced by bloodthirsty firebrands who channeled fel moss, dark talismans, and corrupt alchemy, transforming peaceful gatherers into rabid raiders who now attack travelers and night elf settlements on sight. Across northern Kalimdor, nearly every major tribe has succumbed: the Gnarlpine across Teldrassil, the Blackwood of Darkshore, the Thistlefur and Foulweald in Ashenvale, and the Deadwood and Winterfall of the northern highlands. Yet a few hold the line. Deep within the fortified tunnels connecting Felwood, Winterspring, and Moonglade, the Timbermaw tribe fiercely guards its sanity. Wary and isolated, the Timbermaw defend their hold against their crazed northern kin, desperate to preserve what remains of their uncorrupted culture.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_furbolg-c4f0887329c1d1ba2749/1-0000.mp3", duration = 119.771429, start = 0},
  },
}
P.transport["topic:house-of-nobles"] = {
  hash = "3a8fa3",
  fullHash = "3a8fa3",
  text = "House of Nobles. The House of Nobles is the hereditary aristocratic council that helps administer the kingdom of Stormwind from Stormwind Keep. Holding immense leverage over regional land, taxation, and trade, their refusal to pay the rebuilt city's laborers ignited the bloody riots that gave birth to the Defias Brotherhood. Composed of Stormwind's most powerful patrician bloodlines, the House of Nobles serves as the primary advisory body to the Crown. Because the aristocracy owns the majority of the arable land throughout Elwynn, Westfall, and Duskwood, they wield outsized authority over commerce, regional magistrates, and royal decrees. While the boy-king Anduin Wrynn and Highlord Bolvar Fordragon officially rule the kingdom, the council routinely ties the throne's hands in red tape, asserting the power to stall trials, block executions, and meddle in provincial administration. Following the Second War, the House of Nobles contracted Guildmaster Edwin VanCleef and the Stonemasons Guild to rebuild Stormwind City from its ashes. However, the nobility simultaneously incurred staggering debts while expanding the kingdom's military frontier south into Stranglethorn. When the gleaming capital was finished, the nobles balked at the invoice and refused to pay the workers their full wages. Enraged by the betrayal, the masons rioted in the streets, prompting the nobility to banish the guild, driving the ruined workers into Westfall to form the Defias Brotherhood.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_house-of-nobles-226cf124e022fbcafe51/1-0000.mp3", duration = 88.555102, start = 0},
  },
}
P.transport["topic:human"] = {
  hash = "dd96b9",
  fullHash = "dd96b9",
  text = "Human. Humans are an adaptable and resilient mortal race who have shaped much of the Eastern Kingdoms' history. Once unified under the ancient Empire of Arathor, their civilization fractured into the Seven Kingdoms, with Stormwind now standing as humanity's primary surviving bastion within the Alliance. Millennia ago, early humans lived as scattered, nomadic tribes constantly threatened by the Amani forest trolls. Recognizing that disunity would mean extinction, Warlord Thoradin of the Arathi tribe united the disparate clans through diplomacy and conquest, establishing the Empire of Arathor with its fortress capital at Strom. During the Troll Wars, the beleaguered high elves of Quel'Thalas allied with Arathor, teaching one hundred humans the arts of arcane magic. Together, they broke the troll armies, securing humanity's dominion over the central continents and laying the foundation for future mortal alliances. As Arathor grew secure and prosperous, its outlying settlements became powerful, self-sufficient city-states. Over time, the centralized empire splintered into seven distinct realms: Gilneas, Alterac, Dalaran, Lordaeron, Kul Tiras, Stormwind, and Stromgarde (the original home of Strom). While these nations traded vigorously with dwarves, gnomes, and elves, peace was fragile. Territorial disputes, border skirmishes—such as the perennial mountain feuds between Alterac and Stromgarde—and courtly intrigue consumed the kingdoms, creating deep rivalries that persisted until external catastrophes forced their hand. The arrival of the orcish Horde through the Dark Portal shattered humanity's internal squabbles. Stormwind was razed during the First War, its refugees fleeing north to warn the other realms. In response, King Terenas Menethil II helped forge the Alliance of Lordaeron, combining the strength of mankind, dwarves, gnomes, and high elves to defeat the Horde in the Second War. Though Stormwind was painstakingly rebuilt, tragedy struck again when the Scourge plague ravaged Lordaeron and Dalaran fell during the Third War, leaving the northern human realms in smoking ruin. Today, Stormwind stands as the strongest remaining human kingdom and the linchpin of the grand Alliance. However, peace remains elusive. King Varian Wrynn has mysteriously vanished while en route to a diplomatic summit, leaving his ten-year-old son, Anduin Wrynn, crowned king while Highlord Bolvar Fordragon serves as regent. To the north, the survivors of Lordaeron are scattered or dead, while Gilneas hides behind its colossal Greymane Wall, leaving Stormwind to bear the weight of mankind's defense.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_human-d42d72e55f890f1d423e/1-0000.mp3", duration = 163.709388, start = 0},
  },
}
P.transport["topic:hunter"] = {
  hash = "d40218",
  fullHash = "d40218",
  text = "Hunter. Masters of wilderness survival and deadly marksmanship, hunters roam the untamed reaches of Azeroth alongside fierce beast companions. Armed with bows, rifles, or crossbows, they excel at harassing enemies from a distance while relying on clever traps and primal aspects to control the flow of battle. Whether tracking elusive quarry across snowcapped peaks or stalking prey through dense forests, they live by their wits and connection to nature. At the heart of every hunter lies an instinctual empathy for the primal world. Unlike those who exploit nature or isolate themselves within stone bastions, hunters immerse themselves entirely in untamed lands. They study the habits, movements, and strengths of predatory beasts, earning their respect rather than breaking their spirits. Through patient bonding, a hunter tames dangerous creatures—such as fierce prowling cats, stubborn mountain bears, and sharp-eyed raptors—turning wild animals into steadfast allies that defend them to the death. On the battlefield, hunters dictate the terms of engagement from a safe distance. Armed with bows, heavy crossbows, or calibrated rifles, they unleash deadly volleys that pierce through heavy armor before an attacker can even draw near. Their finely honed senses make them peerless trackers, capable of tracing the faintest footsteps, scents, and disturbances left by quarry. When foes attempt to close the distance, hunters deploy frost and flame traps, disorienting ambushes, or agile evasive maneuvers to keep enemies right where they want them. The path of the hunter manifests differently among the various cultures of Azeroth. Night elf Sentinels embody ancient marksmanship and stealth beneath the canopy of Ashenvale, utilizing bows and shadowcraft in quiet harmony with the wilderness. Dwarven riflemen brave the freezing crags of Dun Morogh alongside hardy bears, mastering the engineering of gunpowder. Across Kalimdor, Tauren and Orc trackers honor ancient nomadic customs, running down their prey with sacred respect and calling upon bestial spirits to guide their shots. In Elwynn Forest, young humans learn the trade from seasoned trackers like the dwarf Tordrin Sternblade in Northshire Valley and Josephine Carson in Goldshire, and the Skyborne learn to track and tame the beasts of Zephras Isle.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_hunter-032644642d93b7fe6143/1-0000.mp3", duration = 141.244082, start = 0},
  },
}
P.transport["topic:leper-gnome"] = {
  hash = "68c181",
  fullHash = "68c181",
  text = "Leper gnome. Leper gnomes are the tragic, mutated survivors of Gnomeregan's catastrophic irradiation during the Third War. Maddened by toxic fallout and lingering fumes, most have sworn fealty to the usurper Mekgineer Thermaplugg, fiercely defending their ruined city against all outsiders. When trogg invaders breached Gnomeregan during the Third War, Mekgineer Thermaplugg advised High Tinker Gelbin Mekkatorque to flood the city with radioactive toxins. Thermaplugg claimed the poison would exterminate the troggs while sparing the gnomish population. Instead, the catastrophe wiped out eighty percent of the city's inhabitants. Those who survived within the sealed lower levels were warped in mind and flesh by toxic fallout, mutating into pale, pustulant wretches dubbed leper gnomes. Thermaplugg himself succumbed to the poisonous fallout, losing both his complexion and his sanity. Naming himself techno-overlord and King of Gnomeregan, he gathered the crazed survivors in the Tinkers' Court. In their fractured mental state, many leper gnomes perceive all surface dwellers as trogg intruders, driving them to attack returning rescue parties with frantic savagery. They pilot salvaged mechanical constructs and assemble volatile ordnance, guarding Thermaplugg's twisted kingdom with fanatical devotion. While the majority remain trapped within Gnomeregan's contaminated corridors, a handful of leper gnomes have found their way into the wider world. Driven by desperation or dark ambition, individuals have turned up among the Dark Iron dwarves in Blackrock Depths, operated machinery for the Venture Company in Stonetalon, or taken up service as lab assistants under the Forsaken's Royal Apothecary Society in the bowels of the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_leper-gnome-944b85b204ad8ae3bf0a/1-0000.mp3", duration = 104.254694, start = 0},
  },
}
P.transport["topic:lich-king"] = {
  hash = "6bf416",
  fullHash = "6bf416",
  text = "Lich King. The Lich King is the lord and psychic master of the undead Scourge, ruling from the Frozen Throne far to the north in Icecrown. Originally forged by the demon Kil'jaeden from the spirit of the orc shaman Ner'zhul, the entity eventually lured Prince Arthas Menethil into corruption, culminating in their fateful union atop Northrend's icy peaks. When the orc shaman Ner'zhul attempted to flee the dying world of Draenor, he fell directly into the clutches of Kil'jaeden the Deceiver. The demon lord tore Ner'zhul's body to shreds but bound his tormented soul into a block of diamond-hard ice cast out of the Twisting Nether. Flung into Azeroth, the glacial monolith struck the northern wastes of Northrend, forming the Frozen Throne. Kil'jaeden intended the Lich King to forge an unstoppable undead vanguard that would dismantle the mortal kingdoms without succumbing to the infighting that ruined the Orcish Horde. Instead, armed with immense telepathic power, Ner'zhul immediately began plotting his own bid for freedom. Watching dreadlords kept close vigil over the entity, forcing Ner'zhul to act in secret. Reaching out with his mind, he ensnared the exiled Kirin Tor archmage Kel'Thuzad, who established the Cult of the Damned in Lordaeron. Through cauldrons of tainted grain, the Scourge unleashed the Plague of Undeath across the northern kingdoms. The crisis drew in Prince Arthas Menethil, whose desperation to save his people led him into ruthless brutality, culminating in the infamous slaughter of Stratholme. Blinded by vengeance against the dreadlord Mal'Ganis, Arthas pursued his quarry into Northrend, where the cursed runeblade Frostmourne waited to steal his soul and turn him into the Scourge's premier death knight. Though forced to summon Archimonde and hand temporary command to the Burning Legion, the Lich King anticipated the demons' hubris. Arthas manipulated the demon hunter Illidan Stormrage into claiming the Skull of Gul'dan and slaying Tichondrius, ultimately contributing to Archimonde's ruin at Mount Hyjal. In the aftermath, a desperate Kil'jaeden tasked Illidan with destroying the Frozen Throne. As cracks in the icy spire weakened Ner'zhul's power—allowing Sylvanas Windrunner and her Forsaken to break free—the Lich King summoned his champion home. Arthas returned to Northrend, defeated Illidan at the foot of Icecrown, ascended the spire, and shattered the ice to merge with Ner'zhul into a single terrible consciousness.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_lich-king-8af96873d89fc5aaae60/1-0000.mp3", duration = 151.614694, start = 0},
  },
}
P.transport["topic:light"] = {
  hash = "e0a88a",
  fullHash = "e0a88a",
  text = "Light. The Light is a boundless primal cosmic force whose energy connects and suffuses all living things across creation. Manifested in the mortal realm as Holy magic, it responds to willpower, meditation, and unyielding faith to mend flesh, shield allies, and purge darkness. The Light is an omnipresent force of living energy. When brought into Azeroth, it manifests as Holy magic. Its power flows through living souls as a connective tissue, binding mortal hearts together. While mortals often personify it as a conscious protector, the Light fundamentally answers the absolute conviction of the soul calling upon it. To channel the Light requires intense self-abnegation, disciplined meditation, and unshakable willpower. Practitioners—most famously the priests of the Church of the Holy Light and the holy paladins—train for years to become clear, empty vessels for its radiance. Through their devotion, the Light manifests as restorative warmth to mend mortal wounds, brilliant wards to shelter the innocent, or searing fire to strike down demons and the risen undead. While humanity and the dwarves revere the Light through formal scripture, other cultures access its brilliance through different spiritual traditions. The night elves channel sacred moonlight through devotion to the goddess Elune, weaving holy magic that cleanses and protects. The tauren honor the sun deity An'she in their own spiritual traditions.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_light-6b888a04e7b774c18e82/1-0000.mp3", duration = 91.2457143, start = 0},
  },
}
P.transport["topic:llane-wrynn-i"] = {
  hash = "c3e4fd",
  fullHash = "c3e4fd",
  text = "Llane Wrynn I. King Llane Wrynn I was the ruler of Stormwind during the catastrophic First War, whose reign ended with the fall of the kingdom and his own tragic murder. A beloved and proud monarch, his steadfast refusal to believe his friend Medivh had betrayed humanity ultimately doomed his defense of the capital. Born to King Barathen Wrynn, young Prince Llane grew up alongside Anduin Lothar and Medivh. In their youth, the three companions ventured into the jungles of Stranglethorn Vale and clashed with the Gurubashi trolls there. In time, Llane ascended to the throne as Stormwind's king. When mysterious, green-skinned creatures emerged from the southern swamps, King Llane dispatched Lothar to investigate the Black Morass. What began as minor skirmishes erupted into the First War as the Horde overran the forests of Duskwood, Westfall, and Redridge. Messengers sent to Lordaeron and other northern human kingdoms were dismissed, their pleas undermined by Stormwind's historic isolationism and aristocratic intrigue. Despite these disadvantages, Llane organized an audacious counterattack alongside Lothar that broke the Horde's initial siege of Stormwind, dealing the invaders their first major defeat.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_llane-wrynn-i-3e2a9f710918693e1d66/1-0000.mp3", duration = 73.9787755, start = 0},
  },
}
P.transport["topic:mage"] = {
  hash = "b1a80a",
  fullHash = "b1a80a",
  text = "Mage. Mages are scholarly spellcasters who bend the fabric of reality through arcane study, hurling destructive fire, controlling frost, and raw arcane energy. While physically fragile and cloaked only in cloth, their mastery over teleportation, conjuration, and battlefield crowd control makes them formidable allies and terrifying foes. Their discipline requires immense mental dedication, balancing immense destructive potential against the perilous history of arcane misuse. The path of the mage demands intellect, focus, and years of rigorous study. Rather than communing with spirits or relying on divine faith, magi treat magic as a precise cosmic science. By drawing upon arcane energies, a practitioner can weave raw destructive power, summon searing bursts of flame, or chill the surrounding air into solid ice and howling blizzards. Because heavy armor disrupts the delicate somatic gestures and mental focus required for incantations, mages wear light cloth, relying instead on wards, mana barriers, and evasive spells to protect themselves. Human magical heritage began nearly three millennia ago during the Troll Wars, when high elven sorcerers instructed one hundred humans of the Empire of Arathor to turn the tide against the Amani. As the number of human practitioners multiplied, fearful mundane citizens drove many magi to establish the magocracy of Dalaran. Under the governance of the Kirin Tor, Dalaran became the central archive of magical study for the northern kingdoms, formalizing the traditions of combat magic that later supported the Alliance of Lordaeron through the First and Second Wars. Arcane practitioners have never enjoyed uncomplicated trust. From the ancient cataclysm wrought by the Highborne to the catastrophic fall of Dalaran during the Third War, magic's volatile nature evokes widespread wariness. The Church of the Holy Light has historically treated wizardry with skepticism, and conservative knights have often viewed arcane spellcrafters as damned souls or a necessary evil on the battlefield. Despite this suspicion, civil and military leaders recognize that a capable magus offers invaluable battlefield supremacy, swift mass transportation, and essential countermeasures against supernatural threats. The arcane is not the Alliance's alone. Troll and Forsaken mages serve the Horde, and orcs who take up the art begin under the Darkspear mage Mai'ah in the Valley of Trials, who teaches that patience and careful judgment matter more than raw power. Among the Skyborne, the High Order descends from the Highborne of Eldre'Thalas. Their ages in Skywall cost them much of their ancestors' arcane knowledge, and with the wind spirits gone from Zephras Isle they seek to recover it. Skyborne mages fight for the Alliance.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_mage-098bd059284312ef5181/1-0000.mp3", duration = 175.856327, start = 0},
  },
}
P.transport["topic:muradin-bronzebeard"] = {
  hash = "ae5cfa",
  fullHash = "ae5cfa",
  text = "Muradin Bronzebeard. Muradin Bronzebeard was the brother of King Magni Bronzebeard and Brann Bronzebeard, as well as a renowned warrior, diplomat, and co-founder of the Explorers' League. Revered across Khaz Modan and Lordaeron alike, he is believed to have died in the frozen wastes of Northrend when Prince Arthas Menethil claimed the cursed runeblade Frostmourne. Muradin fought with distinction during the Second War, acting as the vital liaison between the mountain halls of Khaz Modan and the Alliance of Lordaeron. He helped hold Ironforge during the Horde's siege and marched alongside Alliance forces all the way through Blackrock Spire to the Dark Portal. In the peaceful years that followed, Muradin settled into Capital City as Ironforge’s official ambassador. Jovial yet formidable, he became a fixture in the palace, growing close to King Terenas Menethil and taking it upon himself to tutor young Prince Arthas in the arts of swordplay and combat. Beyond politics and war, Muradin possessed a restless curiosity. Alongside his brothers, he helped establish the dwarven Explorers' League, dedicated to uncovering lost titan relics and chronicling the distant corners of the world. He fell in love with the desolate, windswept continent of Northrend, making frequent journeys north to sketch ancient architecture and document its fierce inhabitants. It was Northrend's rugged mysteries that ultimately drew him on his final expedition, seeking out lore, relics, and the whispered legend of a forgotten runeblade.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_muradin-bronzebeard-807fba55ce7c6fb792f9/1-0000.mp3", duration = 90.1746939, start = 0},
  },
}
P.transport["topic:old-god"] = {
  hash = "d46f42",
  fullHash = "d46f42",
  text = "Old God. The Old Gods are colossal, malevolent horrors of flesh and madness who ruled Azeroth in its primordial dawn. Though vanquished and bound deep beneath the crust by the Titans, their ancient whispers still corrode mortal minds, twist nature, and drive doomsday cults to unearth their prisons. Long before mortal records began, Azeroth was dominated by the Old Gods, colossal entities of chaotic flesh such as C'Thun. They embedded themselves into the planet's crust, commanding elemental armies and insectoid swarms. When the Titans arrived, their armies fought an apocalyptic war against them. Rather than destroying them, the Titans bound the Old Gods in vast, subterranean prisons to keep them dormant forever. Even chained beneath miles of stone and enchanted wards, the Old Gods have never truly slept. Their psychic malice seeps continually into the world, corrupting the vulnerable. It was their collective malice that slowly drove Neltharion the Earth-Warder mad during the War of the Ancients, twisting the noble dragon into Deathwing. When Queen Azshara and her Highborne drowned beneath the raging waters of the Great Sundering, an Old God answered their desperation, transforming them into the serpentine naga.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_old-god-432ca28ec10615fb536a/1-0000.mp3", duration = 79.3338776, start = 0},
  },
}
P.transport["topic:paladin"] = {
  hash = "410867",
  fullHash = "410867",
  text = "Paladin. Paladins are holy warriors who blend martial prowess with the power of the Holy Light. Clad in heavy plate, they protect the innocent, heal the wounded and strike down wicked foes. Humans and dwarves carry the Silver Hand's legacy for the Alliance, and among the Horde, Forsaken who served the Light in life still answer its call, though it burns them. The paladins were originally established during the Second War by Archbishop Alonsus Faol. Having witnessed the devastation wrought upon the pious Clerics of Northshire during the First War, Faol recognized that healers alone could not survive the brutality of orcish warfare. He gathered virtuous knights of Lordaeron and trained surviving clerics in the ways of martial combat and divine magic. Baptized as the Knights of the Silver Hand and led by Uther the Lightbringer, these champions provided both physical defense and spiritual renewal to the kingdoms of humanity. Where priests act as the voice of the Holy Light—preaching faith and tending the spirits of the common folk—paladins serve as its martial arm. Their profound conviction grants them miraculous powers: they project emboldening auras, seal sanctified blessings upon their allies, and mend fatal injuries. In combat against unholy horrors, the Light burns through their strikes, allowing paladins to incinerate undead and demonic entities with righteous fury. The fall of Lordaeron during the Third War scattered the original order, yet the ideals of the Silver Hand endure. In the south, the humans of Stormwind and the stalwart dwarves of Ironforge have taken up the mantle. Training in sanctuaries like the Cathedral of Light and the Hall of Mysteries, these paladins pledge their swords and shields to uphold justice and defend the Alliance from the gathering shadows. Not every knight of Lordaeron stayed in the grave. Some Forsaken who served the Light in life still hold to their vows, and the Light still answers them, though it sears their dead flesh with every prayer. Aramis Hammerhand trains these risen paladins in the chapel at Deathknell, Shari Stilwell continues their instruction in Brill, and an order of Forsaken paladins, Tyr's Watch, holds Bandarion Keep in western Tirisfal. Theirs is a lonely road: they wield the very power that burned their people, and Sylvanas Windrunner tolerates their order while watching it closely.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_paladin-46f1c5b0ff947d7cace8/1-0000.mp3", duration = 144.53551, start = 0},
  },
}
P.transport["topic:priest"] = {
  hash = "e826f2",
  fullHash = "e826f2",
  text = "Priest. Priests are spiritual guides and conduits of immense unseen power who shape belief, mend flesh, and guard souls. Channeling the radiant energies of faith or plumbing the terrifying depths of the Void, they serve as the vital heart of any war party. Across Azeroth, their traditions range from the Church of the Holy Light to the Moon Goddess's Sisterhood and shadowy Forsaken cults. Priests guide the spiritual destiny of their communities. While physical combatants test their mettle with steel, priests draw power directly from conviction. Through divine connection, they soothe grievous wounds, raise fallen companions from death's threshold, and weave mystic barriers to repel incoming harm. Their presence on the field often marks the difference between survival and annihilation. The priesthood is not solely an instrument of benevolence. Just as life holds both illumination and darkness, the priest walks a perilous line between divine restoration and mental devastation. Those who master the holy arts call down searing righteous vengeance to smite enemies, while practitioners of Shadow magic delve into the Void to dominate minds, twist willpower, and inflict agonizing pain from afar. No single faith defines Azeroth's priests. Among humans, dwarves and gnomes, the Church of the Holy Light codifies a philosophy of virtue, having adapted its fragile Clerics of Northshire into a hardened order after the First War. In Kalimdor, the night elven Sisterhood of Elune honors the Mother Moon with starlight and grace, while troll witch doctors beseech the primal Loa. Among the newly risen Forsaken, many have turned from former dogmas toward the Cult of the Forgotten Shadow, preaching that darkness and light must exist in delicate equilibrium.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_priest-84e0c6cc5904487915a2/1-0000.mp3", duration = 107.467755, start = 0},
  },
}
P.transport["topic:rogue"] = {
  hash = "b4ce5c",
  fullHash = "b4ce5c",
  text = "Rogue. Rogues are masters of stealth, espionage, and sudden, lethal combat who dictate the terms of engagement from the shadows. Relying on light leather armor, dual-wielded blades, and brewed toxins, they strike unawares before vanishing back into the dark. Across Azeroth, they serve as scouts, assassins, pickpockets, and agents for factions and hidden syndicates alike. Rogues eschew the heavy plate and open confrontation of traditional frontline warriors. Clad in lightweight leather to remain completely silent and mobile, they stalk their quarry unseen. When they engage, they seize the opening moments through precision and surprise, aiming for vital organs or exposed joints. Utilizing an ever-flowing pool of energy and rapid weapon combinations, a rogue softens up an enemy with carefully chained strikes before unleashing a catastrophic finishing blow. A blade alone is rarely enough for a professional cutpurse or killer. Rogues are skilled alchemists of lethal concoctions, hand-crafting venomous coatings to numb limbs, slow escapes, or rapidly sap the vitality of their targets. Coupled with lockpicking tools, thrown weapons, and distracting trickery, they excel at slipping past fortified perimeters, disarming traps, and infiltrating vaults that would stump a company of soldiers. While many rogues operate as lone wolves, highwaymen, or street-level thugs, the finest operatives belong to organized intelligence networks and assassin guilds. Stormwind relies on the clandestine operatives of SI:7, and the Forsaken utilize the relentless Deathstalkers. In Orgrimmar, the shadowy remnants of the Shattered Hand serve the Warchief, while the elite, neutral League of Assassins answers to Lord Jorach Ravenholdt.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_rogue-a28ef22ab6d839ea482c/1-0000.mp3", duration = 107.154286, start = 0},
  },
}
P.transport["topic:scarlet-crusade"] = {
  hash = "ca1dc9",
  fullHash = "ca1dc9",
  text = "Scarlet Crusade. Born from the shattered remnants of the Knights of the Silver Hand, the Scarlet Crusade is a fanatical holy order obsessed with purging the undead from Lordaeron. Blighted by paranoia and radical zealotry, they view anyone outside their ranks as carriers of the plague and shoot outsiders on sight. From strongholds across Tirisfal Glades and the Plaguelands, their crimson banners wage a ruthless war against Scourge and living alike. When Prince Arthas betrayed Lordaeron and murdered King Terenas Menethil II, the Order of the Silver Hand was broken. Surviving paladins and priests rallied under leaders like Alexandros Mograine, Saidan Dathrohan, and General Abbendis to reclaim their ruined homeland. Reorganizing their forces at Hearthglen and Tyr's Hand, they swore to cleanse the undead scourge with holy fire. Yet as the war dragged on, tragedy and suspicion festered within their ranks. What began as a desperate resistance soon devolved into an unyielding, xenophobic crusade. As the Crusade's dogma hardened into religious madness, moderate commanders recoiled. Lord Maxwell Tyrosus and his followers argued that retaking the north required alliances across Azeroth, seeking aid from the dwarves, gnomes, and night elves. Rejected by the zealots, Tyrosus and other disillusioned knights abandoned the order to form the Argent Dawn, remaining faithful to the pure, inclusive tenets of the Holy Light. Meanwhile, the Scarlet Crusade seized the Scarlet Monastery in Tirisfal Glades as their heart of power, slaughtering travelers and refugees under the hysterical belief that all who walk the Plaguelands carry the Scourge's contagion.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_scarlet-crusade-b6c855fa6076737f5d3c/1-0000.mp3", duration = 100.231837, start = 0},
  },
}
P.transport["topic:shadow-council"] = {
  hash = "4955bc",
  fullHash = "4955bc",
  text = "Shadow Council. The Shadow Council was the secret cabal of warlocks and necrolytes that orchestrated the corruption of the Old Horde on Draenor and guided its invasion of Azeroth. Founded by Gul'dan under the direction of the Burning Legion, the cult manipulated clan chieftains from behind the scenes until Warchief Orgrim Doomhammer purged their stronghold in Blackrock Mountain. Before the crossing into Azeroth, Gul'dan brought together a clandestine assembly of warlocks, necrolytes, and opportunistic chieftains to manipulate the orcish clans. By elevating Blackhand the Destroyer as a malleable figurehead, the Shadow Council ruled the Old Horde from the dark. They disseminated fel magic across Draenor and fed the blood of the demon Mannoroth to the clans, binding the orcs to the will of the Burning Legion. The Shadow Council entered a pact with Medivh—the Guardian possessed by Sargeras—to breach the barrier between worlds. Through the Dark Portal, the Council guided the Horde into the Kingdom of Stormwind. From their sanctum in Blackrock Spire, the warlocks oversaw the war effort.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_shadow-council-d16a71893e1f581b0a0f/1-0000.mp3", duration = 67.9706122, start = 0},
  },
}
P.transport["topic:shaman"] = {
  hash = "0da4ea",
  fullHash = "0da4ea",
  text = "Shaman. Shaman are spiritual mediators who commune with the primordial forces of earth, air, fire and water. Balancing raw nature through totems, lightning and ancestral healing, they are the spiritual core of orc, tauren and troll culture under Warchief Thrall. Dwarves walk the path too, as the Wildhammer long have, and the Skyborne Windshapers seek to restore their people's bond with the winds. Unlike priests who revere the divine or mages who bend the arcane, shaman interact directly with the primal forces of nature. The elements of earth, air, fire, and water are inherently chaotic and locked in perpetual conflict. A shaman does not enslave these forces, but petitions and negotiates with them, serving as a balance keeper between primal fury and the mortal world. Through wooden and stone totems planted into the soil, shaman channel these elemental bargains to protect allies, hinder foes, or mend the wounded with cleansing water. Shamanism was once the ancient foundation of orcish clan life on Draenor. However, Kil'jaeden and the Shadow Council deceived the shamans into war against the draenei, causing the elemental spirits to withdraw their favor. Stripped of their gifts, many former shaman succumbed to demonic corruption and became warlocks, nearly extinguishing the tradition entirely. Only after the Second War did Thrall, guided by Drek'Thar of the Frostwolf clan, rediscover the ancient rites. Thrall's ascension as Warchief revitalized shamanism, elevating it into the moral compass of the New Horde. Across Kalimdor, shamanic traditions vary widely among the Horde's allied peoples. Tauren mystics treat communion with the earth and the spirits as a sacred cultural anchor. Darkspear trolls approach the discipline through reverence for the loa and ancestral wild spirits, weaving voodoo and nature rites together. Across all these tribal borders, shaman stand as essential community elders, advisers, and fearsome front-line defenders. The shaman's path does not belong to the Horde alone. Among the dwarves, the Wildhammer of Aerie Peak have long called on storm and stone, and Wildhammer earthseers such as Earthseer Farsen bring that far-seeing craft to Dun Morogh. Dwarves of Ironforge take up the totem as well and fight for the Alliance. Far above the world, the Windshapers are the spiritual leaders of the Skyborne. The wind spirits of Zephras Isle have fallen silent, and the Windshapers train new shaman in the hope of restoring that lost bond; Skyborne who join the Horde follow their path.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_shaman-92e631ec63e2a52bce6d/1-0000.mp3", duration = 161.17551, start = 0},
  },
}
P.transport["topic:shan-do"] = {
  hash = "e8e982",
  fullHash = "e8e982",
  text = "Shan'do. Shan'do is a revered Darnassian honorific meaning \"honored teacher\" or \"honored instructor.\" Traditionally used within night elven society and druidic circles, it denotes deep reverence toward a mentor who guides another along the path of wisdom and natural magic. Its direct counterpart is thero'shan, meaning \"honored student.\" In the Darnassian language, shan'do translates directly to \"honored teacher\" or \"honored instructor.\" It is far more than an occupational label: addressing an elder or mentor as shan'do expresses solemn humility, filial devotion, and enduring respect for their guidance. The title is most famously intertwined with the history of the Cenarion Circle. The demigod Cenarius was the original shan'do to Malfurion Stormrage, instructing him in the ways of nature before the War of the Ancients. In turn, Malfurion became shan'do to generations of mortal druids, to the point where \"Shan'do Stormrage\" is his standard styling among night elves, forest keepers, and reverent allies across Kalimdor. While most common among Cenarion druids—such as disciples addressing Naralex or the slumbering Malfurion—the honorific is fundamentally Darnassian, not exclusively religious. The title represents the bond of transmission between master and pupil, irrespective of the school of thought.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_shan-do-331faf1d08e215bf160c/1-0000.mp3", duration = 81.9983673, start = 0},
  },
}
P.transport["topic:stonemasons-guild"] = {
  hash = "b0541b",
  fullHash = "b0541b",
  text = "Stonemasons Guild. The Stonemasons Guild was the collective of master builders and artisans responsible for reconstructing Stormwind City after the Second War. Following a bitter dispute over payment with the House of Nobles that ended in deadly riots, the guild was forcibly dissolved, driving its members into exile and giving rise to the Defias Brotherhood. Led by elected Guildmaster Edwin VanCleef, the artisans of the Stonemasons Guild demonstrated a mastery of masonry that rivaled the Royal Stonecutters Union of the dwarves. Following the devastation of the First and Second Wars, the House of Nobles hired the guild to embark upon the monumental task of rebuilding Stormwind City from ruins, trusting them to restore the capital to its ancient grandeur. For years, VanCleef and an army of craftsmen toiled through Elwynn, raising the soaring spires of Stormwind Keep and the massive arches of the Cathedral of Light. However, royal finances collapsed under heavy military debts incurred in southern campaigns. Influenced by aristocratic politics, the House of Nobles refused to pay the guild their agreed salaries and fees. When VanCleef petitioned for restitution, the nobles answered by unilaterally disbanding the guild, sparking immense fury among the laborers who had bled to rebuild the city.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_stonemasons-guild-9cdfd1c638cc22b868fc/1-0000.mp3", duration = 80.8228571, start = 0},
  },
}
P.transport["topic:stormwind-kingdom"] = {
  hash = "944d68",
  fullHash = "944d68",
  text = "Stormwind (kingdom). The Kingdom of Stormwind is the southernmost and currently foremost human realm on Azeroth, holding dominion over Elwynn Forest, Westfall, Duskwood, and the Redridge Mountains. Sacked and shattered during the First War, it was rebuilt through blood and labor after the Second, rising to become the military and cultural center of the Alliance following the tragic collapse of Lordaeron in the north. Today, the kingdom stands beset from within and without, ruled by the ten-year-old King Anduin Wrynn under the watchful guidance of Highlord Bolvar Fordragon while its crowned monarch remains missing. Stormwind was established over a thousand years ago by descendants of the ancient Arathi empire who ventured south beyond the crags of Khaz Modan into fertile, forested valleys. Far from the northern kingdoms, the realm grew into a culture fiercely proud of its self-reliance and the Light. That independence was nearly extinguished when the Orcish Horde poured through the Dark Portal. Stormwind City burned to ash in the First War, its King Llane slain. The surviving populace fled north across the Great Sea led by Sir Anduin Lothar, rallying the northern realms into the Alliance of Lordaeron. Once the Orcish threat was crushed in the Second War, refugees returned home, hiring the Stonemasons Guild to rebuild their magnificent capital of white stone and blue banners. When the Scourge wiped out Lordaeron during the Third War, Stormwind became humanity's greatest remaining bastion.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_stormwind-kingdom-aac903f37634ddc6c849/1-0000.mp3", duration = 88.7379592, start = 0},
  },
}
P.transport["topic:syndicate"] = {
  hash = "3c279e",
  fullHash = "3c279e",
  text = "Syndicate. The Syndicate is a widespread human criminal organization founded and led by dispossessed nobles of the fallen kingdom of Alterac. Operating out of fortified strongholds across the Alterac Mountains, Hillsbrad Foothills, and the ruins of Stromgarde Keep, they wage an uncompromising war against both the Alliance and the Horde to restore their lost aristocracy. When the kingdom of Alterac collapsed in dishonor following King Aiden Perenolde's treachery during the Second War, its aristocracy was stripped of land and title. Refusing to accept their exile, the remaining Alteraci nobility banded together under the late king's son, Prince Aliden Perenolde. Adopting distinctive orange bandanas and standardizing their ranks with hired thugs, highwaymen, and hedge wizards, they forged the Syndicate. To the outside world, they behave like common brigands, raiding caravans, ambushing travelers, and running extortion rings. In truth, their criminal enterprises exist solely to fund an organized effort to reconquer their ancestral domains and subjugate surrounding lands. The Syndicate maintains entrenched footholds across northern Lordaeron. In the snowy Alterac Mountains, they fortified the ruined town of Strahnbrad and established encampments throughout the Uplands and Dandred's Fold. To the south, they hold the crumbling remnants of Durnholde Keep in the Hillsbrad Foothills, using it as a springboard to harass Southshore and raid supply routes. Further east across the Thoradin's Wall, Lord Falconcrest marshals an occupying Syndicate army inside the historic ruins of Stromgarde Keep in Arathi, actively battling the battered Stromgarde Militia for mastery over the Arathi Highlands. Unlike ordinary outlaws, the Syndicate harbors grand ideological ambitions that earn them the hatred of almost every regional faction. They view the Alliance as mortal enemies who stole their rightful heritage, frequently targeting Southshore officials such as Magistrate Henry Maleb. Towards the Horde, their stance is openly supremacist: following the philosophies of Aedelas Blackmoore, they view orcs merely as beasts fit for slave labor and seek to rebuild the internment camp system. Sylvanas Windrunner's Forsaken execute captured Syndicate members on sight, while the clandestine thieves' guild of Ravenholdt wages a constant shadow war against their sloppy, arrogant operatives.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_syndicate-d6d8dc58a64e0dda167f/1-0000.mp3", duration = 143.516735, start = 0},
  },
}
P.transport["topic:varian-wrynn"] = {
  hash = "929bb1",
  fullHash = "929bb1",
  text = "Varian Wrynn. King Varian Wrynn is the rightful ruler of the Kingdom of Stormwind, currently missing after vanishing en route to a diplomatic summit in Theramore. In his absence, his ten-year-old son Anduin wears the crown, guided by Highlord Bolvar Fordragon and Lady Katrana Prestor. Varian was just a boy when the First War shattered his life. He watched his father, King Llane Wrynn, die by the hand of the assassin Garona Halforcen as the Old Horde stormed the capital. Rescued by Anduin Lothar, the orphaned prince fled north with the kingdom's survivors to Southshore. In Capital City, King Terenas Menethil II took Varian in like a second son. The young prince grew up in exile alongside Prince Arthas Menethil, bearing the memory of a burned home until the Alliance of Lordaeron broke the Horde and reclaimed Stormwind. Crowned at eighteen, Varian took on the immense task of resurrecting his ruined kingdom. To restore the capital, he commissioned the Stonemasons Guild under Edwin VanCleef. But when the grand work was finished, the corrupt House of Nobles refused to pay the promised wages, and the stonemasons refused to back down. Varian found himself paralyzed between the entrenched nobility and the furious artisans. The dispute erupted into violent riots in the streets of Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_varian-wrynn-7a78eeec171bc88ec288/1-0000.mp3", duration = 80.4571429, start = 0},
  },
}
P.transport["topic:war-of-the-ancients"] = {
  hash = "782b64",
  fullHash = "782b64",
  text = "War of the Ancients. Ten thousand years ago, the reckless sorcery of Queen Azshara and her Highborne tore a portal through the Well of Eternity, unleashing the demonic Burning Legion onto Azeroth. Led by the young druid Malfurion Stormrage, his brother Illidan, and Priestess Tyrande Whisperwind, a desperate coalition of night elves, dragons, and ancient forest demigods repelled the invaders. The resulting destruction of the Well triggered the Great Sundering, violently shattering the ancient continent of Kalimdor and permanently altering the face of the world. At the height of the ancient Kaldorei Empire, Queen Azshara and her elite caste of sorcerers, the Highborne, relentlessly drew upon the vast arcane depths of the Well of Eternity. Their reckless manipulation sent massive ripples into the Great Dark Beyond, attracting Sargeras, the master of the Burning Legion. Entranced by promises of ultimate power and perfection, Azshara and her advisor Xavius opened a trans-dimensional rift within the Well. Legions of felhounds, felguard, doomguard, and monstrous commanders poured into the capital city of Zin-Azshari, slaughtering all non-Highborne and beginning their crusade to purge the world of life. Horrified by the slaughter, night elves outside the Highborne caste rallied to resist. The resistance was led by remarkable heroes: the first mortal druid Malfurion Stormrage, the devout priestess of Elune Tyrande Whisperwind, and Malfurion's gifted brother Illidan. Together they gathered the common night elves into a desperate frontline against the Legion's onslaught. The war escalated to world-shattering proportions when the demigod Cenarius rallied the ancient Wild Gods and dragonflights into the fray. Determined to stop Sargeras himself from stepping foot onto Azeroth, Malfurion and the resistance made a desperate push to collapse the portal over the Well of Eternity. Their desperate gambit succeeded in casting the demonic host back into the Twisting Nether, but the strain proved too great. The Well violently imploded, triggering the Great Sundering that shattered Kalimdor into separate continents and flooded the center of the world, birthing the Great Sea and forever marking Kaldorei culture.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_war-of-the-ancients-b9d789cc37a695792b65/1-0000.mp3", duration = 135.053061, start = 0},
  },
}
P.transport["topic:warrior"] = {
  hash = "0cc233",
  fullHash = "0cc233",
  text = "Warrior. Warriors are the quintessential frontline combatants of Azeroth, mastering heavy plate armor, shields, and nearly every form of martial weaponry. Fueling their most devastating strikes with pure combat rage, they charge into the thick of battle to defend weaker allies or carve through enemy ranks. They are found across every race and civilization, serving as everything from stalwart city guards and royal champions to wandering mercenaries. Warriors rely neither on divine prayers nor arcane incantations. Their power stems entirely from physical endurance, battlefield discipline, and an exhaustive mastery of weaponry. Clad in the heaviest plate mail, they dictate the frontline. Some fight behind towering shields to withstand punishing assaults and draw peril away from spellcasters and archers. Others step forward with two-handed polearms, axes, and greatswords, or wade into melee wielding a blade in each hand to cleave through whole formations. In the furnace of battle, pain and blood ignite a warrior's inner fire. Known simply as rage, this resource swells as warriors inflict and absorb punishment. Rather than yielding to exhaustion or bleeding wounds, seasoned fighters channel this combat fury directly into bone-shattering strikes, sweeping whirlwinds of steel, and deafening battle cries that bolster nearby comrades while shattering enemy morale. Unlike classes tied to specific creeds or elemental patrons, the warrior tradition is universal to every race on Azeroth. Stormwind relies on its disciplined knights and footmen, Ironforge marshals its stout mountain guard, and the Horde rallies around orcish blademasters, tauren braves, and Forsaken Deathguards. Whether driven by honor, territorial defense, or cold coin, those who answer the call of arms form the unbroken backbone of every standing army.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_warrior-e9be0ffae13a0388cff1/1-0000.mp3", duration = 116.767347, start = 0},
  },
}
P.transport["topic:warsong-clan"] = {
  hash = "27499d",
  fullHash = "27499d",
  text = "Warsong clan. The Warsong clan is one of the most ferocious and legendary fighting forces among the orcs, formerly led by the revered chieftain Grommash Hellscream. Having survived exile, the internment camps, and demonic corruption, the clan now operates primarily in Ashenvale as the Warsong Outriders, fiercely securing lumber for the fledgling Horde while clashing ceaselessly with the night elves. Long before crossing into Azeroth, the Warsong forged their reputation across the open plains of Draenor through mobile wolf-rider tactics. After the Horde's defeat, while other orcs languished in Alliance internment camps, the Warsong evaded capture, wandering the wilderness and clinging to their warlike spirit until Thrall united with Hellscream to forge the New Horde. Upon arriving in Kalimdor during the Third War, Thrall ordered Hellscream and his clan into Ashenvale to harvest timber and establish an outpost. The intrusion enraged the night elves and the forest demigod Cenarius. Pushed to the brink of slaughter, the Warsong succumbed once more to the pit lord Mannoroth's demonic blood to prevail, slaying Cenarius in a frenzy of fel corruption. Thrall and his allies managed to purge Hellscream of the curse, culminating in a fateful showdown where Grom gave his life to destroy Mannoroth. His heroic sacrifice broke the demon blood curse forever, cementing the Warsong clan's place in Horde history. In the present day, the clan continues Grommash's mission under the banner of the Warsong Outriders. From strongholds like Splintertree Post and active logging encampments, they harvest timber crucial for building the young Horde nation in the arid wastes of Durotar. Their presence has sparked a bitter territorial war with the night elven Silverwing Sentinels. Driven by their ancestral zeal, the Warsong show no sign of relinquishing Warsong Gulch, cutting deep into the ancient forest despite endless ambushes.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_warsong-clan-52f1a89291748e12196e/1-0000.mp3", duration = 120.032653, start = 0},
  },
}
P.transport["topic:wildhammer-clan"] = {
  hash = "df7e97",
  fullHash = "df7e97",
  text = "Wildhammer clan. The Wildhammer clan is a rugged, nature-dwelling branch of the dwarven race famed for taming wild gryphons and wielding storm-charged hammers. Driven from their ancestral fortress of Grim Batol centuries ago, they carved a fiercely independent home across the wooded peaks of the Hinterlands. Though reclusive by nature, they remain stalwart friends of the Alliance, defending the skies whenever called upon. Before the War of the Three Hammers, the Wildhammers lived in the foothills around Ironforge. When High King Modimus Anvilmar died, civil war fractured the dwarven kingdom, and the victorious Bronzebeards claimed Ironforge for themselves. Thane Khardros led his clan north to establish a magnificent hold inside the peak of Grim Batol. Yet peace was short-lived: the defeated Dark Irons soon laid siege to the fortress. While Khardros personally slew the Dark Iron sorceress Modgud, her dying curse blighted the mountain so deeply that the halls became uninhabitable. Refusing an invitation to move back under Bronzebeard rule, the Wildhammers chose self-reliance, marching north into the forests and rocky crags of the Hinterlands. In the lush highlands of their new realm, the Wildhammers built Aerie Peak. Unlike their subterranean cousins, these dwarves embraced the open sky and living rock, developing a deep, spiritual kinship with the native gryphons. Forging enchanted stormhammers in secluded aviaries, the Wildhammers became the finest aerial cavalry in Azeroth. During the Second War, when Warchief Orgrim Doomhammer pushed his forces toward Quel'Thalas and assaulted Aerie Peak, Supreme Commander Anduin Lothar and the Alliance came to their aid. In gratitude, High Thane Kurdran Wildhammer pledged his gryphon riders to the coalition, dogfighting the Horde's enslaved red dragons across the skies of Lordaeron and the Great Sea. When the Dark Portal reopened, Kurdran Wildhammer led his riders into Draenor with the Alliance Expedition, sacrificing his return to seal the rift—an act commemorated by a colossal statue in Stormwind's Valley of Heroes. Back in Aerie Peak, High Thane Falstad stepped up to lead the clan. Even as the human kingdoms squabbled and fractured in later years, the Wildhammers remained steadfast partners of King Terenas Menethil II. When the Scourge swept across Lordaeron in the Third War, Wildhammer flyers took to the air once more, fighting desperately to protect allied lands and innocent refugees from the walking dead.",
  ["1"] = {
    {file = "Audio/Transport/full_topic_wildhammer-clan-a9b2fd77674253864e7c/1-0000.mp3", duration = 155.663673, start = 0},
  },
}
